#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0

#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11

#define ADC_CHANNEL 0
#define ADC_RESOLUTION 10

#define SAMPLE_RATE 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void setup_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, GPIO_CE0);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for CE0\n");
        exit(1);
    }

    gpiod_line_request_output(line, "ce0", 0);
    gpiod_line_set_value(line, 0);

    line = gpiod_chip_get_line(chip, GPIO_MOSI);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for MOSI\n");
        exit(1);
    }

    gpiod_line_request_output(line, "mosi", 0);
    gpiod_line_set_value(line, 0);

    line = gpiod_chip_get_line(chip, GPIO_MISO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for MISO\n");
        exit(1);
    }

    gpiod_line_request_input(line, "miso");

    line = gpiod_chip_get_line(chip, GPIO_SCLK);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for SCLK\n");
        exit(1);
    }

    gpiod_line_request_output(line, "sclk", 0);
    gpiod_line_set_value(line, 0);

    gpiod_chip_close(chip);
}

static void setup_spi(void) {
    int fd;
    struct spi_ioc_transfer xfer;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(1);
    }

    xfer.tx_buf = (unsigned long)NULL;
    xfer.rx_buf = (unsigned long)NULL;
    xfer.len = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.delay_usecs = SPI_DELAY;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Failed to configure SPI device\n");
        exit(1);
    }

    close(fd);
}

static void read_adc(void) {
    int fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    uint16_t adc_value;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(1);
    }

    tx_buf[0] = 0x06 | (ADC_CHANNEL << 4);
    tx_buf[1] = 0x00;

    xfer.tx_buf = (unsigned long)tx_buf;
    xfer.rx_buf = (unsigned long)rx_buf;
    xfer.len = 2;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.delay_usecs = SPI_DELAY;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        exit(1);
    }

    adc_value = (rx_buf[0] << 8) | rx_buf[1];
    printf("ADC value: %d\n", adc_value);

    close(fd);
}

int main(void) {
    struct sigaction sa;
    struct timespec ts;

    setup_gpio();
    setup_spi();

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        read_adc();
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_RATE * 1000000;
        nanosleep(&ts, NULL);
    }

    return 0;
}

