#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <ads1115.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x48
#define AIN0 0
#define GAIN 4096
#define DATA_RATE 128
#define CONVERSION_TIME 500

static int i2c_fd;
static int ads1115_fd;

static void sigint_handler(int signum) {
    if (signum == SIGINT) {
        close(i2c_fd);
        close(ads1115_fd);
        ads1115_cleanup();
        exit(0);
    }
}

int main(int argc, char **argv) {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Open ADS1115 device
    ads1115_fd = ads1115_open(i2c_fd, I2C_ADDR);
    if (ads1115_fd < 0) {
        perror("Failed to open ADS1115 device");
        exit(1);
    }

    // Configure ADS1115 for single-shot mode, single-ended input on AIN0, programmable gain of ±4.096 V, and data rate of 128 SPS
    if (ads1115_config(ads1115_fd, AIN0, GAIN, DATA_RATE) < 0) {
        perror("Failed to configure ADS1115");
        exit(1);
    }

    // Read current value every 500 ms
    while (1) {
        // Read 16-bit conversion result
        uint16_t conversion_result;
        if (ads1115_read(ads1115_fd, &conversion_result) < 0) {
            perror("Failed to read conversion result");
            exit(1);
        }

        // Convert to amperes
        float current = (float)conversion_result / GAIN;

        // Log current value to console
        printf("Current: %f A\n", current);

        // Sleep for 500 ms
        usleep(CONVERSION_TIME * 1000);
    }

    // Close I2C device
    close(i2c_fd);

    // Close ADS1115 device
    ads1115_close(ads1115_fd);

    // Clean up library
    ads1115_cleanup();

    return 0;
}

