#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE0_GPIO 8
#define D0_GPIO 4
#define A0_CHANNEL 0

int main(void) {
    // Initialize the SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize the GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    struct gpiod_line *ce0_line = gpiod_chip_get_line(chip, CE0_GPIO);
    if (!ce0_line) {
        perror("Failed to get CE0 GPIO line");
        return 1;
    }

    struct gpiod_line *d0_line = gpiod_chip_get_line(chip, D0_GPIO);
    if (!d0_line) {
        perror("Failed to get D0 GPIO line");
        return 1;
    }

    // Set the SPI mode and clock speed
    struct spi_ioc_transfer spi_xfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .word_delay_usecs = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
        perror("Failed to set SPI mode and clock speed");
        return 1;
    }

    // Set the CE0 line to high
    if (gpiod_line_set_value(ce0_line, 1) < 0) {
        perror("Failed to set CE0 line to high");
        return 1;
    }

    // Open the output file
    FILE *fp = fopen("flame_data.csv", "w");
    if (!fp) {
        perror("Failed to open output file");
        return 1;
    }

    // Main loop
    while (true) {
        // Read the digital output D0
        bool flame_detected = gpiod_line_get_value(d0_line);

        // Read the analog output A0
        uint16_t adc_value = 0;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            perror("Failed to read ADC value");
            continue;
        }

        // Calculate the temperature
        float temperature = (adc_value / 1023.0) * 3.3;

        // Write the data to the output file
        fprintf(fp, "%ld, %d, %f\n", time(NULL), flame_detected, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(ce0_line);
    gpiod_line_release(d0_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(fp);

    return 0;
}

