#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <ads1115/ads1115.h>

#define BUZZER_PIN 27
#define FLAME_PIN 4
#define TEMP_PIN AIN0
#define DEBOUNCE_TIME 50
#define FIRE_THRESHOLD 60

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize the GPIO library
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the ADC
    ads1115_t adc;
    if (ads1115_init(&adc, i2c_fd, ADS1115_ADDRESS_GND) != 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        return 1;
    }

    // Configure the ADC for single-ended input on channel AIN0
    if (ads1115_set_mode(&adc, ADS1115_MODE_SINGLE) != 0) {
        fprintf(stderr, "Failed to set ADC mode\n");
        return 1;
    }
    if (ads1115_set_input_mux(&adc, ADS1115_INPUT_AIN0) != 0) {
        fprintf(stderr, "Failed to set ADC input mux\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the flame sensor
        bool flame_detected = gpiod_get_value(FLAME_PIN);

        // Read the temperature sensor
        int16_t temp = ads1115_read_value(&adc);

        // Check if both sensors are active
        if (flame_detected && temp >= FIRE_THRESHOLD) {
            // Log the fire event
            time_t now = time(NULL);
            fprintf(log_file, "%s: Fire detected!\n", ctime(&now));

            // Activate the buzzer
            gpiod_set_value(BUZZER_PIN, 1);

            // Wait for 2 seconds
            usleep(2000000);

            // Deactivate the buzzer
            gpiod_set_value(BUZZER_PIN, 0);
        } else if (flame_detected) {
            // Log the flame detection
            time_t now = time(NULL);
            fprintf(log_file, "%s: Flame detected!\n", ctime(&now));
        } else if (temp >= FIRE_THRESHOLD) {
            // Log the temperature reading
            time_t now = time(NULL);
            fprintf(log_file, "%s: Temperature: %d°C\n", ctime(&now), temp);
        }

        // Wait for the debounce time
        usleep(DEBOUNCE_TIME * 1000);
    }

    // Clean up
    gpiod_cleanup();
    ads1115_cleanup(&adc);
    fclose(log_file);

    return 0;
}

