#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_FAN "/sys/class/gpio/gpio18"
#define GPIO_FAN_ON 1
#define GPIO_FAN_OFF 0
#define THRESHOLD 1000

int main(void) {
    int spi_fd, gpio_fd, ret;
    struct spi_ioc_transfer spi_xfer;
    struct gpio_chip_info gpio_info;
    struct gpio_chip_config gpio_config;
    struct timespec ts;
    uint8_t spi_buf[4];
    uint16_t adc_value;
    int fan_state = GPIO_FAN_OFF;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_xfer.mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_xfer.bits_per_word);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_xfer.speed_hz);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_fd = open(GPIO_FAN, O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Set GPIO direction
    gpio_info.line_offset = 18;
    gpio_info.direction = GPIO_DIR_OUT;
    ret = ioctl(gpio_fd, GPIO_IOC_SET_LINE_DIRECTION, &gpio_info);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set GPIO value
    gpio_config.line_offset = 18;
    gpio_config.value = fan_state;
    ret = ioctl(gpio_fd, GPIO_IOC_SET_LINE_VALUE, &gpio_config);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Read current sensor data
    while (1) {
        // Read SPI data
        spi_xfer.tx_buf = spi_buf;
        spi_xfer.rx_buf = spi_buf;
        spi_xfer.len = 4;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);
        if (ret < 0) {
            perror("Failed to read SPI data");
            close(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Convert SPI data to ADC value
        adc_value = (spi_buf[1] << 8) | spi_buf[2];

        // Check for sensor absence
        if (adc_value == 0 || adc_value == 0xFFFF) {
            printf("Sensor is absent\n");
            continue;
        }

        // Check for fan state
        if (adc_value > THRESHOLD) {
            fan_state = GPIO_FAN_ON;
        } else {
            fan_state = GPIO_FAN_OFF;
        }

        // Set GPIO value
        gpio_config.line_offset = 18;
        gpio_config.value = fan_state;
        ret = ioctl(gpio_fd, GPIO_IOC_SET_LINE_VALUE, &gpio_config);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            close(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Log data
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%ld: %d\n", ts.tv_sec, ts.tv_nsec, adc_value);
        fflush(stdout);

        // Sleep for 1 second
        sleep(1);
    }

    // Close GPIO chip
    close(gpio_fd);

    // Close SPI device
    close(spi_fd);

    return 0;
}

