#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>

#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define MCP3008_SCLK_PIN 11
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9

#define FLAME_DATA_FILE "flame_data.csv"

int main(void) {
    // Initialize the GPIO and SPI interfaces
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiInitialise() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    // Set up the MCP3008 chip select pin
    if (gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 chip select pin mode\n");
        return 1;
    }

    // Set up the MCP3008 SPI pins
    if (gpioSetMode(MCP3008_SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 SCLK pin mode\n");
        return 1;
    }

    if (gpioSetMode(MCP3008_MOSI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 MOSI pin mode\n");
        return 1;
    }

    if (gpioSetMode(MCP3008_MISO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 MISO pin mode\n");
        return 1;
    }

    // Set up the flame sensor pin
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return 1;
    }

    // Open the CSV file for writing
    int fd = open(FLAME_DATA_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read the flame sensor value
        int flame_value = gpioRead(FLAME_SENSOR_PIN);
        if (flame_value < 0) {
            fprintf(stderr, "Failed to read flame sensor value\n");
            return 1;
        }

        // Read the temperature value from the MCP3008
        int temperature = mcp3008Read(MCP3008_CS_PIN, MCP3008_SCLK_PIN, MCP3008_MOSI_PIN, MCP3008_MISO_PIN, 0);
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature value\n");
            return 1;
        }

        // Write the data to the CSV file
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "%d,%d\n", flame_value, temperature);
        if (write(fd, buffer, strlen(buffer)) < 0) {
            fprintf(stderr, "Failed to write to CSV file\n");
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(fd);
    gpioTerminate();
    spiTerminate();

    return 0;
}

