#define I2C_REG 0x00
#define I2C_LEN 2

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

#define SAMPLE_RATE 100
#define SAMPLE_COUNT 10

#define AUDIO_LOG_FILE "audio_log.txt"

int main(int argc, char **argv) {
  // Initialize GPIO pins
  struct gpiod_chip *chip = gpiod_chip_open_by_number(GPIO_PIN_2);
  if (!chip) {
    fprintf(stderr, "Error: Failed to open GPIO chip\n");
    return 1;
  }
  struct gpiod_line *line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
  if (!line_2) {
    fprintf(stderr, "Error: Failed to get GPIO line\n");
    return 1;
  }
  struct gpiod_line *line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
  if (!line_3) {
    fprintf(stderr, "Error: Failed to get GPIO line\n");
    return 1;
