#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <ads1115.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CHANNEL 0
#define RATE 10
#define THRESHOLD 50.0
#define BUFFER_SIZE 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int fd;
    int i;
    int16_t raw_value;
    float current;
    float buffer[BUFFER_SIZE];
    float average;

    // Initialize the I2C bus
    if ((fd = i2c_open(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the ADS1115 ADC
    if (ads1115_init(fd, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115 ADC: %s\n", strerror(errno));
        return 1;
    }

    // Set the channel and rate
    if (ads1115_set_channel(fd, CHANNEL) < 0) {
        fprintf(stderr, "Failed to set channel: %s\n", strerror(errno));
        return 1;
    }
    if (ads1115_set_rate(fd, RATE) < 0) {
        fprintf(stderr, "Failed to set rate: %s\n", strerror(errno));
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Set up the LED
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }
    if (gpio_set_mode(17, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Read the raw value from the ADC
        if (ads1115_read_raw(fd, &raw_value) < 0) {
            fprintf(stderr, "Failed to read raw value: %s\n", strerror(errno));
            return 1;
        }

        // Convert the raw value to current
        current = ads1115_convert_raw_to_current(raw_value);

        // Add the current to the buffer
        buffer[i] = current;
        i = (i + 1) % BUFFER_SIZE;

        // Calculate the average of the buffered currents
        average = 0;
        for (int j = 0; j < BUFFER_SIZE; j++) {
            average += buffer[j];
        }
        average /= BUFFER_SIZE;

        // Check if the average exceeds the threshold
        if (average > THRESHOLD) {
            // Turn on the LED
            gpio_write(17, 1);
        } else {
            // Turn off the LED
            gpio_write(17, 0);
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpio_close(17);
    ads1115_close(fd);
    i2c_close(fd);

    return 0;
}

