#include <tcs34725.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000
#define CSV_FILE "color_log.csv"
#define CSV_HEADER "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n"

static int i2c_fd;
static int csv_fd;
static struct tcs34725_dev dev;

static void sigint_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    tcs34725_close(&dev);
    close(csv_fd);
    pigpio_stop();
    exit(0);
}

int main(int argc, char **argv) {
    int ret;
    char line[100];
    struct timeval tv;
    struct tm *tm;
    uint16_t clear, red, green, blue;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize TCS34725 driver
    ret = tcs34725_init(&dev, i2c_fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize TCS34725 driver\n");
        return 1;
    }

    // Check ID register
    uint8_t id;
    ret = tcs34725_get_id(&dev, &id);
    if (ret < 0 || id != TCS34725_ID) {
        fprintf(stderr, "Invalid ID register value\n");
        return 1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (csv_fd < 0) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Write header row if necessary
    if (lseek(csv_fd, 0, SEEK_END) == 0) {
        write(csv_fd, CSV_HEADER, strlen(CSV_HEADER));
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Wait at least 3 ms after power-on
        usleep(3000);

        // Read color values
        ret = tcs34725_get_color(&dev, &clear, &red, &green, &blue);
        if (ret < 0) {
            fprintf(stderr, "Failed to read color values\n");
            continue;
        }

        // Get current time
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);

        // Format output line
        snprintf(line, sizeof(line), "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%d\n",
                 tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                 tm->tm_hour, tm->tm_min, tm->tm_sec,
                 clear, red, green, blue);

        // Write output line to CSV file
        write(csv_fd, line, strlen(line));

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    tcs34725_close(&dev);
    close(csv_fd);
    pigpio_stop();

    return 0;
}

