#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_DEVICE "/dev/gpiochip0"
#define GPIO_PIN_MOTOR 17
#define GPIO_PIN_ADC 0
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 12
#define ADC_REFERENCE 3.3
#define ADC_GAIN 1.0
#define ADC_OFFSET 0.0
#define ADC_SAMPLE_RATE 1.0
#define ADC_SAMPLE_TIME 1000000
#define ADC_SAMPLE_COUNT 10
#define ADC_SAMPLE_DELAY 100000
#define ADC_OVERCURRENT_THRESHOLD 10.0

int main(int argc, char *argv[]) {
  // Open SPI device
  int spi_fd = open(SPI_DEVICE, O_RDWR);
  if (spi_fd < 0) {
    perror("Failed to open SPI device");
    return 1;
  }

  // Set SPI mode
  if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
    perror("Failed to set SPI mode");
    close(spi_fd);
    return 1;
  }

  // Set SPI clock speed
  if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
    perror("Failed to set SPI clock speed");
    close(spi_fd);
    return 1;
  }

  // Open GPIO device
  int gpio_fd = open(GPIO_DEVICE, O_RDWR);
  if (gpio_fd < 0) {
    perror("Failed to open GPIO device");
    close(spi_fd);
    return 1;
  }

  // Set GPIO pin direction
  if (ioctl(gpio_fd, GPIO_IOC_WR_DIR, GPIO_PIN_MOTOR) < 0) {
    perror("Failed to set GPIO pin direction");
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set GPIO pin value
  if (ioctl(gpio_fd, GPIO_IOC_WR_VALUE, GPIO_PIN_MOTOR) < 0) {
    perror("Failed to set GPIO pin value");
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Open ADC file
  int adc_fd = open(ADC_DEVICE, O_RDWR);
  if (adc_fd < 0) {
    perror("Failed to open ADC device");
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC channel
  if (ioctl(adc_fd, ADC_IOC_WR_CHANNEL, ADC_CHANNEL) < 0) {
    perror("Failed to set ADC channel");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC resolution
  if (ioctl(adc_fd, ADC_IOC_WR_RESOLUTION, ADC_RESOLUTION) < 0) {
    perror("Failed to set ADC resolution");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC reference
  if (ioctl(adc_fd, ADC_IOC_WR_REFERENCE, ADC_REFERENCE) < 0) {
    perror("Failed to set ADC reference");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC gain
  if (ioctl(adc_fd, ADC_IOC_WR_GAIN, ADC_GAIN) < 0) {
    perror("Failed to set ADC gain");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC offset
  if (ioctl(adc_fd, ADC_IOC_WR_OFFSET, ADC_OFFSET) < 0) {
    perror("Failed to set ADC offset");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC sample rate
  if (ioctl(adc_fd, ADC_IOC_WR_SAMPLE_RATE, ADC_SAMPLE_RATE) < 0) {
    perror("Failed to set ADC sample rate");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC sample time
  if (ioctl(adc_fd, ADC_IOC_WR_SAMPLE_TIME, ADC_SAMPLE_TIME) < 0) {
    perror("Failed to set ADC sample time");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC sample count
  if (ioctl(adc_fd, ADC_IOC_WR_SAMPLE_COUNT, ADC_SAMPLE_COUNT) < 0) {
    perror("Failed to set ADC sample count");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC sample delay
  if (ioctl(adc_fd, ADC_IOC_WR_SAMPLE_DELAY, ADC_SAMPLE_DELAY) < 0) {
    perror("Failed to set ADC sample delay");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Set ADC overcurrent threshold
  if (ioctl(adc_fd, ADC_IOC_WR_OVERCURRENT_THRESHOLD, ADC_OVERCURRENT_THRESHOLD) < 0) {
    perror("Failed to set ADC overcurrent threshold");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Open file for logging
  int log_fd = open("current_log.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (log_fd < 0) {
    perror("Failed to open log file");
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Write header to log file
  char header[] = "timestamp,current\n";
  if (write(log_fd, header, strlen(header)) < 0) {
    perror("Failed to write header to log file");
    close(log_fd);
    close(adc_fd);
    close(gpio_fd);
    close(spi_fd);
    return 1;
  }

  // Main loop
  while (1) {
    // Read ADC value
    uint16_t adc_value;
    if (read(adc_fd, &adc_value, sizeof(adc_value)) < 0) {
      perror("Failed to read ADC value");
      close(log_fd);
      close(adc_fd);
      close(gpio_fd);
      close(spi_fd);
      return 1;
    }

    // Convert ADC value to current
    float current = (adc_value * ADC_GAIN) + ADC_OFFSET;

    // Check for overcurrent
    if (current > ADC_OVERCURRENT_THRESHOLD) {
      // Disable motor
      if (ioctl(gpio_fd, GPIO_IOC_WR_VALUE, GPIO_PIN_MOTOR) < 0) {
        perror("Failed to set GPIO pin value");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }

      // Log overcurrent event
      char log_message[] = "Overcurrent event detected at ";
      char timestamp[20];
      time_t now = time(NULL);
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
      strcat(log_message, timestamp);
      strcat(log_message, "\n");
      if (write(log_fd, log_message, strlen(log_message)) < 0) {
        perror("Failed to write log message");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }

      // Wait one second
      sleep(1);

      // Enable motor
      if (ioctl(gpio_fd, GPIO_IOC_WR_VALUE, GPIO_PIN_MOTOR) < 0) {
        perror("Failed to set GPIO pin value");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }
    }

    // Write current to log file
    char log_message[] = "timestamp,current\n";
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    strcat(log_message, timestamp);
    strcat(log_message, ",");
    char current_str[20];
    sprintf(current_str, "%f", current);
    strcat(log_message, current_str);
    strcat(log_message, "\n");
    if (write(log_fd, log_message, strlen(log_message)) < 0) {
      perror("Failed to write log message");
      close(log_fd);
      close(adc_fd);
      close(gpio_fd);
      close(spi_fd);
      return 1;
    }

    // Wait one second
    sleep(1);
  }

  // Close file descriptors
  close(log_fd);
  close(adc_fd);
  close(gpio_fd);
  close(spi_fd);

  return 0;
}

