      perror("Failed to read ADC value");
      close(log_fd);
      close(adc_fd);
      close(gpio_fd);
      close(spi_fd);
      return 1;
    }

    // Convert ADC value to current
    float current = (adc_value * ADC_GAIN) + ADC_OFFSET;

    // Check for overcurrent
    if (current > ADC_OVERCURRENT_THRESHOLD) {
      // Disable motor
      if (ioctl(gpio_fd, GPIO_IOC_WR_VALUE, GPIO_PIN_MOTOR) < 0) {
        perror("Failed to set GPIO pin value");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }

      // Log overcurrent event
      char log_message[] = "Overcurrent event detected at ";
      char timestamp[20];
      time_t now = time(NULL);
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
      strcat(log_message, timestamp);
      strcat(log_message, "\n");
      if (write(log_fd, log_message, strlen(log_message)) < 0) {
        perror("Failed to write log message");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }

      // Wait one second
      sleep(1);

      // Enable motor
      if (ioctl(gpio_fd, GPIO_IOC_WR_VALUE, GPIO_PIN_MOTOR) < 0) {
        perror("Failed to set GPIO pin value");
        close(log_fd);
        close(adc_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
      }
    }

    // Write current to log file
    char log_message[] = "timestamp,current\n";
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    strcat(log_message, timestamp);
    strcat(log_message, ",");
    char current_str[20];
    sprintf(current_str, "%f", current);
    strcat(log_message, current_str);
    strcat(log_message, "\n");
    if (write(log_fd, log_message, strlen(log_message)) < 0) {
      perror("Failed to write log message");
      close(log_fd);
      close(adc_fd);
      close(gpio_fd);
      close(spi_fd);
      return 1;
    }

    // Wait one second
    sleep(1);
  }

  // Close file descriptors
  close(log_fd);
  close(adc_fd);
  close(gpio_fd);
  close(spi_fd);

  return 0;
}
```
This code uses the `libgpiod` and `libspi` libraries to interface with the Raspberry Pi's GPIO and SPI peripherals, respectively. It sets up the SPI device and GPIO pin for the motor shutdown control, and configures the ADC device to read the current sensor output. The program then enters a loop that reads the ADC value, converts it to current, checks for overcurrent, and logs the current and timestamp to a file. The program also handles errors and gracefully terminates by catching SIGINT and SIGTERM signals and closing file descriptors and releasing GPIO lines cleanly.

