#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>

#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_CE 8
#define MCP3008_SPI_SCLK 11
#define MCP3008_SPI_MOSI 10
#define MCP3008_SPI_MISO 9
#define MCP3008_CHANNEL 0
#define MCP3008_SAMPLE_RATE 100
#define MCP3008_OVERCURRENT_THRESHOLD 10

#define GPIO_SHUTDOWN 27

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize the MCP3008 SPI interface
    if (mcp3008_init(MCP3008_SPI_BUS, MCP3008_SPI_CE, MCP3008_SPI_SCLK, MCP3008_SPI_MOSI, MCP3008_SPI_MISO) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008 SPI interface\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set up the GPIO pin for shutdown
    if (gpio_export(GPIO_SHUTDOWN) < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d\n", GPIO_SHUTDOWN);
        return 1;
    }
    if (gpio_set_direction(GPIO_SHUTDOWN, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set direction of GPIO pin %d\n", GPIO_SHUTDOWN);
        return 1;
    }

    // Main loop
    while (running) {
        // Read the current value from the sensor
        int16_t current = mcp3008_read_adc(MCP3008_CHANNEL);
        if (current < 0) {
            fprintf(stderr, "Failed to read current value from sensor\n");
            return 1;
        }

        // Log the current value to the log file
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(log_file, "%s, %d\n", timestamp, current);
        fflush(log_file);

        // Check if the current exceeds the overcurrent threshold
        if (current > MCP3008_OVERCURRENT_THRESHOLD) {
            // Shut down the motor
            gpio_write(GPIO_SHUTDOWN, 1);

            // Log the overcurrent event
            fprintf(log_file, "OVERCURRENT, %d\n", current);
            fflush(log_file);

            // Terminate the program
            running = 0;
        }

        // Sleep for the sample rate
        usleep(MCP3008_SAMPLE_RATE * 1000);
    }

    // Clean up
    mcp3008_close();
    gpio_unexport(GPIO_SHUTDOWN);
    fclose(log_file);
    pigpio_stop();

    return 0;
}

