#define SPI_MISO_PIN 9
#define SPI_MOSI_PIN 10

#define METHANE_LOG_FILE "methane_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Initialize the SPI interface
    int spi_fd = -1;
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set the SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set the SPI chip select pin
    if (ioctl(spi_fd, SPI_IOC_WR_CS, &SPI_CS_PIN) < 0) {
        fprintf(stderr, "Error setting SPI chip select pin: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set the SPI clock pin
    if (ioctl(spi_fd, SPI_IOC_WR_CLK, &SPI_CLK_PIN) < 0) {
        fprintf(stderr, "Error setting SPI clock pin: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set the SPI MISO pin
    if (ioctl(spi_fd, SPI_IOC_WR_MISO, &SPI_MISO_PIN) < 0) {
        fprintf(stderr, "Error setting SPI MISO pin: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set the SPI MOSI pin
    if (ioctl(spi_fd, SPI_IOC_WR_MOSI, &SPI_MOSI_PIN) < 0) {
        fprintf(stderr, "Error setting SPI MOSI pin: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Initialize the GPIO interface
    int gpio_fd = -1;
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening GPIO device: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set the GPIO pin for the MCP3008 ADC
    if (ioctl(gpio_fd, GPIO_IOC_WR_PIN, &SPI_CS_PIN) < 0) {
        fprintf(stderr, "Error setting GPIO pin: %s\n", strerror(errno));
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set the GPIO pin for the MCP3008 ADC
    if (ioctl(gpio_fd, GPIO_IOC_WR_PIN, &SPI_CLK_PIN) < 0) {
        fprintf(stderr, "Error setting GPIO pin: %s\n", strerror(errno));
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set the GPIO pin for the MCP3008 ADC
    if (ioctl(gpio_fd, GPIO_IOC_WR_PIN, &SPI_MISO_PIN) < 0) {
        fprintf(stderr, "Error setting GPIO pin: %s\n", strerror(errno));
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set the GPIO pin for the MCP3008 ADC
    if (ioctl(gpio_fd, GPIO_IOC_WR_PIN, &SPI_MOSI_PIN) < 0) {
        fprintf(stderr, "Error setting GPIO pin: %s\n", strerror(errno));
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set up the signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the log file
    FILE *log_file = fopen(METHANE_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read the sensor data
        uint16_t sensor_data = 0;
        if (ioctl(spi_fd, SPI_IOC_RD_DATA, &sensor_data) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            close(log_file);
            close(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Convert the sensor data to ppm
        float methane_ppm = (float)sensor_data * 1000.0 / 1024.0;

        // Log the data to the file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %f\n", timestamp, methane_ppm);

        // Check for a leak
        if (methane_ppm > METHANE_THRESHOLD) {
            fprintf(stderr, "Leak detected: %f ppm\n", methane_ppm);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close the log file
    fclose(log_file);

    // Close the GPIO interface
    close(gpio_fd);

    // Close the SPI interface
    close(spi_fd);

    return 0;
}
```
This code initializes the SPI interface and the GPIO interface, sets up the signal handlers, and then enters a loop that reads the sensor data, converts it to ppm, logs it to a file, and checks for a leak. The program uses the `libgpiod` and `pigpio` libraries to interact with the GPIO and SPI interfaces, respectively. The program also uses the `time` library to get the current time and the `strftime` function to format the timestamp.

Note that this code assumes that the MCP3008 ADC is connected to the Raspberry Pi's SPI bus and that the sensor is connected to the MCP3008 ADC's channel 0. You may need to modify the code to match your specific hardware configuration.

