#include <libgpiod/libgpiod.h>
#include <mcp3208/mcp3208.h>

#define HUMIDITY_THRESHOLD 80
#define HUMIDITY_FILE "humidity_log.txt"
#define HUMIDITY_ALERT_SUBJECT "Humidity Alert"
#define HUMIDITY_ALERT_BODY "Humidity exceeded threshold of 80%."

// Function prototypes
void handle_sigint(int signal);
void handle_sigterm(int signal);
void read_humidity(void);
void write_humidity_log(void);
void send_humidity_alert(void);

// Global variables
int humidity_fd;
int humidity_threshold;
int humidity_alert_sent;

int main(void) {
    // Initialize the ADC driver
    if (mcp3208_init() != 0) {
        fprintf(stderr, "Failed to initialize ADC driver\n");
        return 1;
    }

    // Initialize the GPIO chip
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return 1;
    }

    // Set up the SPI bus
    if (spi_setup() != 0) {
        fprintf(stderr, "Failed to set up SPI bus\n");
        return 1;
    }

    // Open the humidity log file
    humidity_fd = open(HUMIDITY_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (humidity_fd < 0) {
        fprintf(stderr, "Failed to open humidity log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        read_humidity();
        write_humidity_log();
        if (humidity_threshold > HUMIDITY_THRESHOLD && !humidity_alert_sent) {
            send_humidity_alert();
        }
        sleep(1);
    }

    // Clean up
    close(humidity_fd);
    gpiod_cleanup();
    mcp3208_cleanup();

    return 0;
}

void handle_sigint(int signal) {
    // Clean up
    close(humidity_fd);
    gpiod_cleanup();
    mcp3208_cleanup();

    // Exit
    exit(0);
}

void handle_sigterm(int signal) {
    // Clean up
    close(humidity_fd);
    gpiod_cleanup();
    mcp3208_cleanup();

    // Exit
    exit(0);
}

void read_humidity(void) {
    // Read the humidity value
    int humidity = mcp3208_read_adc(0);
    if (humidity < 0) {
        fprintf(stderr, "Failed to read humidity value\n");
        return;
    }

    // Convert the humidity value to a percentage
    humidity_threshold = (humidity * 100) / 4095;
}

void write_humidity_log(void) {
    // Get the current timestamp
    time_t timestamp = time(NULL);

    // Write the humidity value to the log file
    char line[100];
    snprintf(line, sizeof(line), "%ld, %d, %d\n", timestamp, humidity_threshold, humidity_threshold);
    write(humidity_fd, line, strlen(line));
}

void send_humidity_alert(void) {
    // Send the email alert
    if (ssmtp_send_mail(HUMIDITY_ALERT_SUBJECT, HUMIDITY_ALERT_BODY) != 0) {
        fprintf(stderr, "Failed to send email alert\n");
        return;
    }

    // Set the humidity alert flag
    humidity_alert_sent = 1;
}

