#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define TMP36_CHANNEL 0
#define TMP36_VREF 3.3
#define TMP36_RANGE 125
#define TMP36_MIN -40
#define TMP36_MAX 125

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000

#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9

#define LOG_FILE "temperature_log.csv"

static int spi_fd;
static int gpio_fd;
static int log_fd;

static void sigint_handler(int signum) {
    printf("Received signal %d, closing SPI device and GPIO lines\n", signum);
    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    exit(0);
}

static void init_gpio(void) {
    gpio_fd = gpio_open(GPIO_CE0);
    if (gpio_fd < 0) {
        printf("Error opening GPIO %d: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        printf("Error setting GPIO %d mode: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    if (gpio_set_value(gpio_fd, 1) < 0) {
        printf("Error setting GPIO %d value: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }
}

static void init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        printf("Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        printf("Error setting SPI mode: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        printf("Error setting SPI bits per word: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        printf("Error setting SPI speed: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_log(void) {
    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        printf("Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        exit(1);
    }

    if (write(log_fd, "timestamp,temperature_celsius\n", 25) < 0) {
        printf("Error writing to log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_temperature(void) {
    uint16_t adc_value;
    int16_t temperature;
    char timestamp[20];

    if (gpio_set_value(gpio_fd, 0) < 0) {
        printf("Error setting GPIO %d value: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
        printf("Error reading from SPI device: %s\n", strerror(errno));
        exit(1);
    }

    if (gpio_set_value(gpio_fd, 1) < 0) {
        printf("Error setting GPIO %d value: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    temperature = (adc_value * TMP36_VREF) / 4096;

    if (temperature < TMP36_MIN || temperature > TMP36_MAX) {
        printf("Temperature out of range: %d\n", temperature);
        exit(1);
    }

    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char line[50];
    snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, temperature);

    if (write(log_fd, line, strlen(line)) < 0) {
        printf("Error writing to log file: %s\n", strerror(errno));
        exit(1);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_gpio();
    init_spi();
    init_log();

    while (1) {
        read_temperature();
        sleep(1);
    }

    return 0;
}

