static void init_log(void) {
    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        printf("Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        exit(1);
    }

    if (write(log_fd, "timestamp,temperature_celsius\n", 25) < 0) {
        printf("Error writing to log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_temperature(void) {
    uint16_t adc_value;
    int16_t temperature;
    char timestamp[20];

    if (gpio_set_value(gpio_fd, 0) < 0) {
        printf("Error setting GPIO %d value: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
        printf("Error reading from SPI device: %s\n", strerror(errno));
        exit(1);
    }

    if (gpio_set_value(gpio_fd, 1) < 0) {
        printf("Error setting GPIO %d value: %s\n", GPIO_CE0, strerror(errno));
        exit(1);
    }

    temperature = (adc_value * TMP36_VREF) / 4096;

    if (temperature < TMP36_MIN || temperature > TMP36_MAX) {
        printf("Temperature out of range: %d\n", temperature);
        exit(1);
    }

    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char line[50];
    snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, temperature);

    if (write(log_fd, line, strlen(line)) < 0) {
        printf("Error writing to log file: %s\n", strerror(errno));
        exit(1);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_gpio();
    init_spi();
    init_log();

    while (1) {
        read_temperature();
        sleep(1);
    }

    return 0;
}
