#include <time.h>
#include <sys/time.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_FREQ 400000
#define I2C_TIMEOUT 1000

#define HR_ADC_CHANNEL 0
#define SPO2_ADC_CHANNEL 1

#define HR_SCALE 1000
#define SPO2_SCALE 100

#define LOG_FILE "biometric_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_FREQ, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize PPG sensor
    int ret = i2c_write(i2c_fd, 0x00, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Unix timestamp,HR (bpm),SpO2 (%),Error flag\n");

    // Main loop
    while (running) {
        // Read PPG data
        uint16_t hr_adc = 0;
        uint16_t spo2_adc = 0;
        ret = i2c_read(i2c_fd, HR_ADC_CHANNEL, &hr_adc);
        if (ret < 0) {
            fprintf(stderr, "Error reading HR ADC: %s\n", strerror(errno));
            return 1;
        }
        ret = i2c_read(i2c_fd, SPO2_ADC_CHANNEL, &spo2_adc);
        if (ret < 0) {
            fprintf(stderr, "Error reading SPO2 ADC: %s\n", strerror(errno));
            return 1;
        }

        // Convert raw ADC values to HR and SpO2
        int hr = (int)(((float)hr_adc / HR_SCALE) * 60);
        int spo2 = (int)(((float)spo2_adc / SPO2_SCALE) * 100);

        // Write data to log file
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld,%d,%d,0\n", tv.tv_sec, hr, spo2);

        // Flush log file
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus
    i2c_close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

