#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_MEASURE_CMD 0xAC
#define I2C_CONVERSION_TIME 5000
#define I2C_RETRY_TIME 5000

#define CALIBRATION_A 0.00000000624288
#define CALIBRATION_B 0.00000000000392
#define CALIBRATION_C 0.0000000000000624288

#define CSV_FILE "environmental_data.csv"

int main(void) {
    int i2c_fd;
    int ret;
    uint8_t buf[6];
    uint16_t pressure;
    uint16_t temperature;
    uint16_t crc;
    uint32_t timestamp;

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open the CSV file for logging
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Issue the high-precision measurement command
        ret = write(i2c_fd, &I2C_MEASURE_CMD, 1);
        if (ret < 0) {
            perror("Failed to write I2C command");
            close(i2c_fd);
            fclose(csv_file);
            return 1;
        }

        // Wait for the conversion to complete
        usleep(I2C_CONVERSION_TIME);

        // Read the 6-byte result
        ret = read(i2c_fd, buf, 6);
        if (ret < 0) {
            perror("Failed to read I2C result");
            close(i2c_fd);
            fclose(csv_file);
            return 1;
        }

        // Extract the pressure and temperature values
        pressure = (buf[0] << 8) | buf[1];
        temperature = (buf[2] << 8) | buf[3];
        crc = (buf[4] << 8) | buf[5];

        // Calculate the actual pressure and temperature values
        double actual_pressure = pressure * CALIBRATION_A + temperature * CALIBRATION_B + crc * CALIBRATION_C;
        double actual_temperature = temperature * CALIBRATION_A + crc * CALIBRATION_B;

        // Log the timestamped reading to the CSV file
        timestamp = time(NULL);
        fprintf(csv_file, "%ld,%.2f,%.2f\n", timestamp, actual_pressure, actual_temperature);

        // Display the values on the console for real-time monitoring
        printf("Timestamp: %ld\n", timestamp);
        printf("Pressure: %.2f Pa\n", actual_pressure);
        printf("Temperature: %.2f °C\n", actual_temperature);

        // Wait for the next measurement
        usleep(I2C_RETRY_TIME);
    }

    // Close the I2C bus and the CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

void signal_handler(int signal) {
    // Handle SIGINT and SIGTERM by closing the I2C bus and the CSV file
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

