#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 500
#define BUZZER_PIN 18
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"

int main(int argc, char *argv[]) {
    // Initialize SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize GPIO pin for buzzer
    int buzzer_fd = gpiod_export(BUZZER_PIN, GPIOD_AS_OUTPUT);
    if (buzzer_fd < 0) {
        perror("Failed to export GPIO pin for buzzer");
        return 1;
    }

    // Initialize temperature file
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (temp_file == NULL) {
        perror("Failed to open temperature file");
        return 1;
    }

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Set GPIO pin for buzzer
    if (gpiod_set_value(buzzer_fd, 0) < 0) {
        perror("Failed to set GPIO pin for buzzer");
        return 1;
    }

    // Set signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigaction(SIGINT, &sigint_handler, NULL);

    // Main loop
    while (1) {
        // Read temperature from file
        float temp;
        if (fscanf(temp_file, "%f", &temp) != 1) {
            perror("Failed to read temperature from file");
            return 1;
        }

        // Read ADC value from SPI device
        uint8_t spi_data[3];
        if (read(spi_fd, spi_data, 3) != 3) {
            perror("Failed to read ADC value from SPI device");
            return 1;
        }

        // Calculate voltage and temperature compensation
        float voltage = (spi_data[1] << 8) | spi_data[2];
        float compensated_voltage = voltage / (1 + (temp / 25));

        // Check if flame is detected
        int flame_detected = (compensated_voltage > 0.5);

        // Log data to file
        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%d\n",
            get_timestamp(),
            voltage,
            compensated_voltage,
            temp,
            flame_detected);

        // Set GPIO pin for buzzer
        if (gpiod_set_value(buzzer_fd, flame_detected) < 0) {
            perror("Failed to set GPIO pin for buzzer");
            return 1;
        }

        // Sleep for SPI_DELAY milliseconds
        usleep(SPI_DELAY * 1000);
    }

    // Clean up
    close(spi_fd);
    close(buzzer_fd);
    fclose(temp_file);
    fclose(log_file);

    return 0;
}

void sigint_handler_func(int signum) {
    // Stop sampling loop
    printf("Stopping sampling loop\n");

    // Turn off buzzer
    if (gpiod_set_value(buzzer_fd, 0) < 0) {
        perror("Failed to turn off buzzer");
    }

    // Close log file
    fclose(log_file);

    // Release driver resources
    gpiod_release(buzzer_fd);
    close(spi_fd);

    // Exit program
    exit(0);
}

char *get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);

    return timestamp;
}

