#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define LED_PIN 17
#define WATER_LEVEL_THRESHOLD 75
#define HYSTERESIS 5

static int spi_handle;
static int led_handle;
static int json_file;

static void sigint_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioTerminate();
    close(spi_handle);
    close(led_handle);
    close(json_file);
    exit(0);
}

static void write_json_entry(int level) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%T.%LZ", gmtime(&now));
    char entry[100];
    snprintf(entry, sizeof(entry), "{\"timestamp\":\"%s\",\"level\":%d}", timestamp, level);
    write(json_file, entry, strlen(entry));
    fflush(json_file);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <json_file>\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    led_handle = gpioOpen(LED_PIN, GPIO_OUTPUT);
    if (led_handle < 0) {
        fprintf(stderr, "Failed to open LED pin %d\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    json_file = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (json_file < 0) {
        fprintf(stderr, "Failed to open JSON file %s\n", argv[1]);
        gpioClose(led_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    write(json_file, "[", 1);
    fflush(json_file);

    int level = 0;
    while (1) {
        level = mcp3008Read(spi_handle, 0);
        if (level < 0) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            continue;
        }

        write_json_entry(level);

        if (level > WATER_LEVEL_THRESHOLD + HYSTERESIS) {
            gpioWrite(led_handle, 1);
        } else if (level < WATER_LEVEL_THRESHOLD - HYSTERESIS) {
            gpioWrite(led_handle, 0);
        }

        usleep(100000);
    }

    gpioClose(led_handle);
    spiClose(spi_handle);
    gpioTerminate();
    close(json_file);

    return 0;
}

