#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_BITS 10
#define SPI_DELAY 1000

#define SOIL_MOISTURE_LOG "soil_moisture.log"

static int spi_fd;
static int log_fd;

static void sigint_handler(int signum) {
    printf("Caught signal %d\n", signum);
    close(spi_fd);
    close(log_fd);
    ioctl(spi_fd, SPI_IOC_CLEANUP, NULL);
    exit(0);
}

static void init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    struct spi_ioc_transfer spi_transfer;
    memset(&spi_transfer, 0, sizeof(spi_transfer));
    spi_transfer.tx_buf = (unsigned long)NULL;
    spi_transfer.rx_buf = (unsigned long)NULL;
    spi_transfer.len = SPI_BITS;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = SPI_BITS;
    spi_transfer.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("Failed to configure SPI device");
        exit(1);
    }
}

static void init_log(void) {
    log_fd = open(SOIL_MOISTURE_LOG, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(1);
    }
}

static void read_soil_moisture(void) {
    uint16_t adc_value;
    if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
        perror("Failed to read from SPI device");
        exit(1);
    }

    int moisture_percentage = (adc_value * 100) / 1023;
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char log_line[100];
    snprintf(log_line, sizeof(log_line), "%s, %d, %d\n", timestamp, adc_value, moisture_percentage);
    if (write(log_fd, log_line, strlen(log_line)) < 0) {
        perror("Failed to write to log file");
        exit(1);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_spi();
    init_log();

    int interval = 1;
    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    while (1) {
        read_soil_moisture();
        sleep(interval);
    }

    return 0;
}

