        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(1);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(1);
    }

    // Set SPI delay
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("Failed to set SPI delay");
        close(spi_fd);
        exit(1);
    }

    // Set SPI CS high
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_HIGH) < 0) {
        perror("Failed to set SPI CS high");
        close(spi_fd);
        exit(1);
    }

    // Set SPI CS low
    if (ioctl(spi_fd, SPI_IOC_WR_CS_LOW, &SPI_CS_LOW) < 0) {
        perror("Failed to set SPI CS low");
        close(spi_fd);
        exit(1);
    }

    // Set ADC channel
    if (ioctl(spi_fd, SPI_IOC_WR_ADC_CHANNEL, &ADC_CHANNEL) < 0) {
        perror("Failed to set ADC channel");
        close(spi_fd);
        exit(1);
    }

    // Set ADC resolution
    if (ioctl(spi_fd, SPI_IOC_WR_ADC_RESOLUTION, &ADC_RESOLUTION) < 0) {
        perror("Failed to set ADC resolution");
        close(spi_fd);
        exit(1);
    }

    // Set ADC reference
    if (ioctl(spi_fd, SPI_IOC_WR_ADC_REFERENCE, &ADC_REFERENCE) < 0) {
        perror("Failed to set ADC reference");
        close(spi_fd);
        exit(1);
    }

    // Set moisture threshold
    if (ioctl(spi_fd, SPI_IOC_WR_MOISTURE_THRESHOLD, &MOISTURE_THRESHOLD) < 0) {
        perror("Failed to set moisture threshold");
        close(spi_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read ADC data
        uint16_t adc_data;
        if (read(spi_fd, &adc_data, sizeof(adc_data)) < 0) {
            perror("Failed to read ADC data");
            close(spi_fd);
            exit(1);
