        // Calculate moisture percentage
        int moisture_percentage = (adc_data * 100) / ADC_REFERENCE;

        // Print data to console
        printf("ADC reading: %d\n", adc_data);
        printf("Moisture percentage: %d%%\n", moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

