    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Set up the SPI transfer
    tx_buf[0] = MCP3008_START_BIT;
    tx_buf[1] = MCP3008_CONFIG_BYTE;
    tx_buf[2] = MCP3008_DONT_CARE_BYTE;

    // Loop forever, reading the ADC value and computing the moisture percentage
    while (1) {
        // Transfer the data to the ADC
        ret = write(spi_fd, tx_buf, 3);
        if (ret < 0) {
            perror("Failed to transfer data to ADC");
            close(spi_fd);
            return 1;
        }

        // Read the ADC value
        ret = read(spi_fd, rx_buf, 3);
        if (ret < 0) {
            perror("Failed to read ADC value");
            close(spi_fd);
            return 1;
        }

        // Compute the moisture percentage
        adc_value = (rx_buf[1] << 8) | rx_buf[2];
        moisture_percentage = (float)adc_value / 1023.0 * 100.0;

        // Clamp the moisture percentage to the 0-100% range
        if (moisture_percentage < 0.0) {
            moisture_percentage = 0.0;
        } else if (moisture_percentage > 100.0) {
            moisture_percentage = 100.0;
        }

        // Print the moisture percentage to the console
        printf("Moisture percentage: %.2f%%\n", moisture_percentage);

        // Sleep for 5 seconds before reading the ADC again
        sleep(5);
    }

    // Close the SPI device
    close(spi_fd);

    return 0;
}

