#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNELS 4
#define SPI_BITS 12
#define SPI_DELAY 1000000

#define CSV_FILE "environmental_data.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int spi_fd;
    int csv_fd;
    struct spi_ioc_transfer spi_xfer;
    struct timespec ts;
    uint8_t spi_buf[SPI_CHANNELS * SPI_BITS / 8];
    uint16_t spi_data[SPI_CHANNELS];
    uint32_t spi_timestamp;
    char csv_buf[1024];

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return 1;
    }

    // Set up SPI transfer structure
    spi_xfer.tx_buf = (unsigned long)spi_buf;
    spi_xfer.rx_buf = (unsigned long)spi_buf;
    spi_xfer.len = SPI_CHANNELS * SPI_BITS / 8;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;
    spi_xfer.delay_usecs = SPI_DELAY;

    // Main loop
    while (running) {
        // Read SPI data
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            perror("Failed to read SPI data");
            close(spi_fd);
            close(csv_fd);
            return 1;
        }

        // Convert SPI data to voltage
        for (int i = 0; i < SPI_CHANNELS; i++) {
            spi_data[i] = (spi_buf[i * 3] << 8) | (spi_buf[i * 3 + 1] << 4) | (spi_buf[i * 3 + 2] >> 4);
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        spi_timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

        // Write to CSV file
        snprintf(csv_buf, sizeof(csv_buf), "%lu,%u,%u,%u,%u\n", spi_timestamp, spi_data[0], spi_data[1], spi_data[2], spi_data[3]);
        write(csv_fd, csv_buf, strlen(csv_buf));
    }

    // Clean up
    close(spi_fd);
    close(csv_fd);

    return 0;
}

