#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define MAX30102_PART_ID_REG 0x0A
#define MAX30102_SPO2_REG 0x0F
#define MAX30102_HEART_RATE_REG 0x10

#define SPO2_THRESHOLD 95
#define HEART_RATE_THRESHOLD 100

#define LOG_FILE "health_log.txt"

static bool initialized = false;
static int i2c_handle;
static int gpio_handle;

static void init_i2c(void) {
    i2c_handle = i2c_open(I2C_BUS, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        exit(1);
    }
}

static void init_gpio(void) {
    gpio_handle = gpio_open(0, 0);
    if (gpio_handle < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_max30102(void) {
    uint8_t part_id;
    if (i2c_read(i2c_handle, MAX30102_ADDR, MAX30102_PART_ID_REG, &part_id, 1) != 1) {
        fprintf(stderr, "Error reading MAX30102 Part ID register: %s\n", strerror(errno));
        exit(1);
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Invalid MAX30102 Part ID: 0x%02X\n", part_id);
        exit(1);
    }
}

static void read_max30102(void) {
    uint8_t spo2_reg[2];
    uint8_t heart_rate_reg[2];
    if (i2c_read(i2c_handle, MAX30102_ADDR, MAX30102_SPO2_REG, spo2_reg, 2) != 2) {
        fprintf(stderr, "Error reading MAX30102 SpO2 register: %s\n", strerror(errno));
        exit(1);
    }
    if (i2c_read(i2c_handle, MAX30102_ADDR, MAX30102_HEART_RATE_REG, heart_rate_reg, 2) != 2) {
        fprintf(stderr, "Error reading MAX30102 Heart Rate register: %s\n", strerror(errno));
        exit(1);
    }
    uint16_t spo2 = (spo2_reg[0] << 8) | spo2_reg[1];
    uint16_t heart_rate = (heart_rate_reg[0] << 8) | heart_rate_reg[1];
    if (spo2 < SPO2_THRESHOLD || heart_rate > HEART_RATE_THRESHOLD) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            exit(1);
        }
        fprintf(log_file, "%s: SpO2=%d%%, Heart Rate=%dBPM\n", timestamp, spo2, heart_rate);
        fclose(log_file);
    }
}

static void sigint_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "Received SIGINT, exiting...\n");
        exit(0);
    }
}

int main(void) {
    init_i2c();
    init_gpio();
    init_max30102();
    signal(SIGINT, sigint_handler);
    while (true) {
        read_max30102();
        sleep(1);
    }
    return 0;
}

