#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CSV_FILE "analog_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO and SPI
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    pigpio_t *pi = pigpio_start(NULL, NULL);
    if (!pi) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Set up SPI
    int spi_handle = pigpio_spi_open(pi, SPI_BUS, SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return 1;
    }

    // Set up CSV file
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Write header row
    fprintf(csv_file, "Timestamp,Channel,Voltage\n");

    // Main loop
    while (running) {
        // Read voltage from MCP3008
        uint16_t voltage = 0;
        int ret = pigpio_spi_xfer(pi, spi_handle, NULL, 0, (uint8_t *)&voltage, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read voltage from MCP3008\n");
            return 1;
        }

        // Convert voltage to millivolts
        voltage = (voltage >> 8) * 3300 / 1023;

        // Write to CSV file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(csv_file, "%s,%d,%d\n", timestamp, SPI_CHANNEL, voltage);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    pigpio_spi_close(pi, spi_handle);
    pigpio_stop(pi);
    gpiod_chip_close(chip);
    fclose(csv_file);

    return 0;
}

