    pigpio_cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (pigpio_start(NULL, NULL) < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    adc_fd = pigpio_spi_open(0, 0, 0, 0, 0);
    if (adc_fd < 0) {
        printf("Failed to open SPI handle\n");
        pigpio_cleanup();
        return 1;
    }

    buzzer_fd = pigpio_gpio_open(BUZZER_GPIO);
    if (buzzer_fd < 0) {
        printf("Failed to open GPIO handle\n");
        pigpio_spi_close(adc_fd);
        pigpio_cleanup();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint16_t adc_value;
        if (pigpio_spi_read(adc_fd, ADC_CHANNEL, &adc_value) < 0) {
            printf("Failed to read from ADC\n");
            continue;
        }

        if (adc_value >= ADC_THRESHOLD) {
            if (pigpio_gpio_write(buzzer_fd, 1) < 0) {
                printf("Failed to write to buzzer\n");
                continue;
            }
        } else {
            if (pigpio_gpio_write(buzzer_fd, 0) < 0) {
                printf("Failed to write to buzzer\n");
                continue;
            }
        }

        usleep(500000);
    }

    pigpio_spi_close(adc_fd);
    pigpio_gpio_close(buzzer_fd);
    pigpio_cleanup();

    return 0;
}

