#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x48
#define GPIO_RELAY 17
#define GPIO_REED 27
#define REED_PULL_UP 1
#define REED_ACTIVE_LOW 1
#define RELAY_ACTIVE_HIGH 1
#define RELAY_PULSE_MS 3000
#define SAMPLE_INTERVAL_MS 200
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL_MS 50
#define THRESHOLD 100

int i2c_fd;
int gpio_fd;
int relay_fd;
int reed_fd;

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
}

void init_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_RELAY, GPIO_OUT) < 0) {
        perror("Failed to set GPIO direction");
        exit(1);
    }

    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_REED, GPIO_IN) < 0) {
        perror("Failed to set GPIO direction");
        exit(1);
    }
}

void init_relay() {
    relay_fd = open("/dev/gpiochip0", O_RDWR);
    if (relay_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (ioctl(relay_fd, GPIO_SET_DIR, GPIO_RELAY, GPIO_OUT) < 0) {
        perror("Failed to set GPIO direction");
        exit(1);
    }
}

void init_reed() {
    reed_fd = open("/dev/gpiochip0", O_RDWR);
    if (reed_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (ioctl(reed_fd, GPIO_SET_DIR, GPIO_REED, GPIO_IN) < 0) {
        perror("Failed to set GPIO direction");
        exit(1);
    }

    if (ioctl(reed_fd, GPIO_SET_PULL, GPIO_REED, REED_PULL_UP) < 0) {
        perror("Failed to set GPIO pull-up");
        exit(1);
    }
}

void calibrate() {
    int i;
    int sum = 0;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        int val = read_distance();
        if (val < 0) {
            perror("Failed to read distance");
            exit(1);
        }
        sum += val;
        usleep(CALIBRATION_INTERVAL_MS * 1000);
    }
    int avg = sum / CALIBRATION_SAMPLES;
    printf("Calibration average: %d\n", avg);
}

int read_distance() {
    int val;
    if (ioctl(i2c_fd, I2C_RDWR, &val) < 0) {
        perror("Failed to read distance");
        return -1;
    }
    return val;
}

void release_resources() {
    close(i2c_fd);
    close(gpio_fd);
    close(relay_fd);
    close(reed_fd);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, releasing resources\n", sig);
        release_resources();
        exit(0);
    }
}

int main() {
    init_i2c();
    init_gpio();
    init_relay();
    init_reed();

    calibrate();

    while (1) {
        int val = read_distance();
        if (val < 0) {
            perror("Failed to read distance");
            exit(1);
        }
        if (val < THRESHOLD) {
            printf("Distance below threshold, releasing relay\n");
            if (ioctl(relay_fd, GPIO_SET_VAL, GPIO_RELAY, RELAY_ACTIVE_HIGH) < 0) {
                perror("Failed to set relay value");
                exit(1);
            }
            usleep(RELAY_PULSE_MS * 1000);
            if (ioctl(relay_fd, GPIO_SET_VAL, GPIO_RELAY, RELAY_ACTIVE_LOW) < 0) {
                perror("Failed to set relay value");
                exit(1);
            }
            int reed_val = read_reed();
            if (reed_val < 0) {
                perror("Failed to read reed value");
                exit(1);
            }
            if (reed_val == REED_ACTIVE_LOW) {
                printf("Door opened\n");
            } else {
                printf("Door not opened\n");
            }
            log_event(reed_val);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return 0;
}

