#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0

#define PUMP_GPIO 18
#define PUMP_ACTIVE_HIGH

#define THRESHOLD 30
#define DURATION 10
#define SLEEP_INTERVAL 60

#define LOG_FILE "irrigation.log"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void sigterm_handler(int signum) {
    running = 0;
}

static void log_moisture_reading(int moisture) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[100];
    snprintf(line, sizeof(line), "%s: Moisture level: %d%%\n", timestamp, moisture);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fputs(line, fp);
        fclose(fp);
    }
}

static void log_pump_activation(int duration) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[100];
    snprintf(line, sizeof(line), "%s: Pump activated for %d seconds\n", timestamp, duration);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fputs(line, fp);
        fclose(fp);
    }
}

static void log_pump_deactivation() {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[100];
    snprintf(line, sizeof(line), "%s: Pump deactivated\n", timestamp);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fputs(line, fp);
        fclose(fp);
    }
}

static int read_moisture_level() {
    int moisture = 0;
    int retries = 0;
    while (retries < 3) {
        int spi_fd = spi_open(SPI_BUS, SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS, SPI_DELAY);
        if (spi_fd < 0) {
            fprintf(stderr, "Error opening SPI bus: %s\n", strerror(errno));
            return -1;
        }
        uint8_t tx_buf[4] = {0x01, 0x80, 0x00, 0x00};
        uint8_t rx_buf[4];
        int ret = spi_transfer(spi_fd, tx_buf, rx_buf, 4);
        if (ret < 0) {
            fprintf(stderr, "Error reading from SPI bus: %s\n", strerror(errno));
            spi_close(spi_fd);
            return -1;
        }
        moisture = (rx_buf[1] << 8) | rx_buf[2];
        spi_close(spi_fd);
        if (moisture > 0) {
            break;
        }
        retries++;
    }
    return moisture;
}

static void activate_pump(int duration) {
    int gpio_fd = gpio_open(PUMP_GPIO, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", PUMP_GPIO, strerror(errno));
        return;
    }
    gpio_set_value(gpio_fd, PUMP_ACTIVE_HIGH);
    sleep(duration);
    gpio_set_value(gpio_fd, !PUMP_ACTIVE_HIGH);
    gpio_close(gpio_fd);
}

int main(int argc, char *argv[]) {
    int opt;
    int threshold = THRESHOLD;
    int duration = DURATION;
    int sleep_interval = SLEEP_INTERVAL;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        int moisture = read_moisture_level();
        if (moisture < 0) {
            fprintf(stderr, "Error reading moisture level: %s\n", strerror(errno));
            continue;
        }
        log_moisture_reading(moisture);
        if (moisture < threshold) {
            activate_pump(duration);
            log_pump_activation(duration);
        } else {
            log_pump_deactivation();
        }
        sleep(sleep_interval);
    }

    return 0;
}

