#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>
#include <mcp3008/mcp3008.h>

#define MCP3008_CHANNEL 0
#define MCP3008_SAMPLE_RATE 10000
#define MCP3008_THRESHOLD 1000

#define GPIO_CE0 8
#define GPIO_CLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9

#define LOG_FILE "/var/log/sound_events.log"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void log_event(int value) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s: %d\n", timestamp, value);
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (write(fd, log_entry, strlen(log_entry)) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    close(fd);
}

int main(void) {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (pigpio_init() < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    // Initialize MCP3008
    if (mcp3008_init(MCP3008_CHANNEL, MCP3008_SAMPLE_RATE) < 0) {
        perror("mcp3008_init");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    if (gpiod_set_direction(GPIO_CE0, GPIO_OUT) < 0) {
        perror("gpiod_set_direction");
        exit(EXIT_FAILURE);
    }
    if (gpiod_set_direction(GPIO_CLK, GPIO_OUT) < 0) {
        perror("gpiod_set_direction");
        exit(EXIT_FAILURE);
    }
    if (gpiod_set_direction(GPIO_MOSI, GPIO_OUT) < 0) {
        perror("gpiod_set_direction");
        exit(EXIT_FAILURE);
    }
    if (gpiod_set_direction(GPIO_MISO, GPIO_IN) < 0) {
        perror("gpiod_set_direction");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Main loop
