    int fd;
    uint8_t data;

    // Open I2C device
    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set I2C register address
    if (ioctl(fd, I2C_REG, I2C_REG) < 0) {
        perror("Failed to set I2C register address");
        close(fd);
        return 1;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Dummy read to discard previous conversion result
    if (read(fd, &data, 1) < 0) {
        perror("Failed to read from I2C device");
        close(fd);
        return 1;
    }

    // Infinite loop to read ADC values
    while (1) {
        // Read ADC value
        if (read(fd, &data, 1) < 0) {
            perror("Failed to read from I2C device");
            close(fd);
            return 1;
        }

        // Print ADC value
        printf("%d\n", data);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C device
    close(fd);

    return 0;
}

