#include <syslog.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <ads1115/ads1115.h>

#define THRESHOLD 500
#define BUFFER_SIZE 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize syslog
    openlog("Honeywell SS49E", LOG_PID, LOG_USER);

    // Initialize GPIO27 (BCM numbering) as output
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line, "Honeywell SS49E", 0);
    gpiod_line_set_value(line, 0);

    // Initialize ADS1115 ADC on I2C bus 1
    struct ads1115_dev *dev = ads1115_init(1);
    if (!dev) {
        syslog(LOG_ERR, "Failed to initialize ADS1115 ADC");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up ADS1115 ADC to read from AIN0
    ads1115_set_channel(dev, ADS1115_CHANNEL_AIN0);
    ads1115_set_mode(dev, ADS1115_MODE_SINGLE_SHOT);
    ads1115_set_rate(dev, ADS1115_RATE_1_SPS);

    // Set up circular buffer to store magnetic field strength values
    int16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read voltage from ADS1115 ADC
        int16_t voltage = ads1115_read_voltage(dev);
        if (voltage < 0) {
            syslog(LOG_ERR, "Failed to read voltage from ADS1115 ADC");
            continue;
        }

        // Convert voltage to magnetic field strength
        int16_t magnetic_field_strength = voltage * 3.3 / 4096;

        // Store magnetic field strength in circular buffer
        buffer[buffer_index] = magnetic_field_strength;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate rolling average of magnetic field strength
        int16_t average = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            average += buffer[i];
        }
        average /= BUFFER_SIZE;

        // Check if threshold is exceeded
        if (average > THRESHOLD) {
            // Drive GPIO27 HIGH to simulate motor shutdown
            gpiod_line_set_value(line, 1);
        } else {
            // Drive GPIO27 LOW
            gpiod_line_set_value(line, 0);
        }

        // Log magnetic field strength and threshold crossing
        syslog(LOG_INFO, "Magnetic field strength: %d Gauss, threshold: %d Gauss", magnetic_field_strength, THRESHOLD);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    ads1115_close(dev);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

