    running = 0;
}

int main(int argc, char **argv) {
    // Initialize the ADC and GPIO interfaces
    mcp3008_t *adc = mcp3008_init(0, 1000000, 0);
    if (adc == NULL) {
        fprintf(stderr, "Failed to initialize ADC\n");
        return 1;
    }

    gpiod_t *gpio = gpiod_init(18, GPIOD_OUTPUT);
    if (gpio == NULL) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        mcp3008_close(adc);
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the watering events file for writing
    int fd = open(WATERING_EVENTS_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open watering events file\n");
        gpiod_close(gpio);
        mcp3008_close(adc);
        return 1;
    }

