    while (running) {
        // Read the ADC value
        uint16_t adc_value = mcp3008_read(adc, ADC_CHANNEL);
        if (adc_value == 0) {
            fprintf(stderr, "Invalid ADC value\n");
            continue;
        }

        // Check if the value is below the threshold
        if (adc_value < THRESHOLD) {
            // Activate the water pump
            gpiod_set_value(gpio, 1);

            // Log the watering event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            char event[100];
            snprintf(event, sizeof(event), "%s: Watering event, moisture level = %d\n", timestamp, adc_value);
            write(fd, event, strlen(event));

            // Wait for the watering duration
            sleep(WATERING_DURATION);

            // Deactivate the water pump
            gpiod_set_value(gpio, 0);
        }

        // Wait for the next iteration
        sleep(60);
    }

    // Clean up
    close(fd);
    gpiod_close(gpio);
    mcp3008_close(adc);

    return 0;
}

