#define INTENSITY_LEVEL_0 0
#define INTENSITY_LEVEL_1 25
#define INTENSITY_LEVEL_2 50
#define INTENSITY_LEVEL_3 75
#define INTENSITY_LEVEL_4 100

#define SIGINT_HANDLER_FUNC void sigint_handler(int signum)

static int spi_fd;
static int adc_fd;
static int intensity_level;

static void init_spi(void) {
    spi_fd = pigpio_spi_open(SPI_BUS, SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS, SPI_DELAY, SPI_CS_HIGH, SPI_CS_LOW);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_adc(void) {
    adc_fd = pigpio_adc_open(ADC_CHANNEL, ADC_FULL_SCALE, ADC_VDD);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC device: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_adc(void) {
    uint16_t adc_value;
    if (pigpio_adc_read(adc_fd, &adc_value) < 0) {
        fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
        return;
    }
    intensity_level = map_adc_value_to_intensity_level(adc_value);
}

static int map_adc_value_to_intensity_level(uint16_t adc_value) {
    if (adc_value <= INTENSITY_LEVEL_0) {
        return INTENSITY_LEVEL_0;
    } else if (adc_value <= INTENSITY_LEVEL_1) {
        return INTENSITY_LEVEL_1;
    } else if (adc_value <= INTENSITY_LEVEL_2) {
        return INTENSITY_LEVEL_2;
    } else if (adc_value <= INTENSITY_LEVEL_3) {
