#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1023
#define PWM_GPIO 18
#define ADC_GPIO 8

int spi_fd;
int pwm_fd;

void sigint_handler(int signum) {
    printf("Stopping PWM output and releasing resources...\n");
    pigpio_stop(pwm_fd);
    close(spi_fd);
    exit(0);
}

int main(void) {
    // Initialize SPI interface
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        exit(1);
    }

    // Initialize PWM interface
    pwm_fd = pigpio_start(PWM_FREQ, PWM_DUTY_MIN, PWM_DUTY_MAX);
    if (pwm_fd < 0) {
        perror("Failed to start PWM");
        exit(1);
    }

    // Set up SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value;
        if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
            perror("Failed to read ADC value");
            exit(1);
        }

        // Set PWM duty cycle
        uint16_t pwm_value = (adc_value * (PWM_DUTY_MAX - PWM_DUTY_MIN)) / 1023 + PWM_DUTY_MIN;
        if (pigpio_set_dutycycle(pwm_fd, pwm_value) < 0) {
            perror("Failed to set PWM duty cycle");
            exit(1);
        }

        // Print values
        printf("ADC value: %d\n", adc_value);
        printf("PWM value: %d\n", pwm_value);

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

