#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_SPEED 1000000
#define SPI_DELAY 500

int main(void) {
    int spi_fd;
    uint16_t raw_value;
    float voltage;

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set up SPI transfer
    struct spi_ioc_transfer spi_xfer;
    spi_xfer.tx_buf = NULL;
    spi_xfer.rx_buf = (unsigned long)&raw_value;
    spi_xfer.len = SPI_BITS / 8;
    spi_xfer.delay_usecs = SPI_DELAY;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;

    // Read raw value from channel 0
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
        fprintf(stderr, "Error reading from SPI device: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Compute voltage
    voltage = (float)raw_value * 3.3 / 1023.0;

    // Print raw value and voltage
    printf("Raw value: %u\n", raw_value);
    printf("Voltage: %.2f\n", voltage);

    // Clean up
    close(spi_fd);

    return 0;
}

