        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    // Initialize the CSV file
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

    struct sigaction sigterm_action;
    sigterm_action.sa_handler = sigterm_handler;
    sigemptyset(&sigterm_action.sa_mask);
    sigterm_action.sa_flags = 0;
    sigaction(SIGTERM, &sigterm_action, NULL);

    // Main loop
    while (running) {
        // Read the analog voltage on channels 0, 1, and 2
        uint16_t channel_0 = 0;
        uint16_t channel_1 = 0;
        uint16_t channel_2 = 0;

        // Set the chip select to 0
        if (ioctl(spi_fd, SPI_IOC_WR_CHIP_SELECT, &CHANNEL_0) < 0) {
            perror("Failed to set chip select");
            return 1;
        }

        // Read the analog voltage on channel 0
        if (ioctl(spi_fd, SPI_IOC_RD_MESSAGE, &channel_0) < 0) {
            perror("Failed to read message");
            return 1;
        }

        // Set the chip select to 1
        if (ioctl(spi_fd, SPI_IOC_WR_CHIP_SELECT, &CHANNEL_1) < 0) {
            perror("Failed to set chip select");
            return 1;
        }

        // Read the analog voltage on channel 1
        if (ioctl(spi_fd, SPI_IOC_RD_MESSAGE, &channel_1) < 0) {
            perror("Failed to read message");
            return 1;
        }

        // Set the chip select to 2
        if (ioctl(spi_fd, SPI_IOC_WR_CHIP_SELECT, &CHANNEL_2) < 0) {
            perror("Failed to set chip select");
            return 1;
        }

        // Read the analog voltage on channel 2
        if (ioctl(spi_fd, SPI_IOC_RD_MESSAGE, &channel_2) < 0) {
            perror("Failed to read message");
            return 1;
        }

        // Convert the 10-bit values to voltages
        float voltage_0 = (float)channel_0 / 1023.0 * VREF;
        float voltage_1 = (float)channel_1 / 1023.0 * VREF;
        float voltage_2 = (float)channel_2 / 1023.0 * VREF;

        // Get the current time
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        // Write the voltage readings to the CSV file
        fprintf(csv_file, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                voltage_0, voltage_1, voltage_2);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the SPI device
    close(spi_fd);

    // Close the CSV file
    fclose(csv_file);

    // Shut down the driver library
    pigpio_stop();

    return 0;
}
