    if (pwm_fd < 0) {
        perror("pigpio_open");
        return -1;
    }
    return 0;
}

static void pwm_set_duty_cycle(int duty_cycle) {
    pigpio_set_dutycycle(pwm_fd, MOTOR_PWM_FREQ, MOTOR_PWM_DUTY_CYCLE, MOTOR_PWM_PERIOD);
}

static void pwm_stop(void) {
    pigpio_set_dutycycle(pwm_fd, MOTOR_PWM_FREQ, 0, MOTOR_PWM_PERIOD);
}

static void vibration_log(int timestamp) {
    FILE *fp = fopen(VIBRATION_LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
