        int16_t adc_value;
        if (mcp3008_read(adc_fd, &adc_value) < 0) {
            perror("mcp3008_read");
            continue;
        }
        if (adc_value > THRESHOLD) {
            pwm_set_duty_cycle(MOTOR_PWM_DUTY_CYCLE);
            vibration_log(time(NULL));
        } else {
            pwm_stop();
        }
        usleep(10000);
    }

    return 0;
}

