    adc_fd = mcp3008_open(spi_fd, ADC_CHANNEL);
    if (adc_fd < 0) {
        printf("Error opening ADC interface: %s\n", strerror(errno));
        pigpio_close(spi_fd);
        return 1;
    }

    // Open fan interface
    fan_fd = gpio_open(FAN_PIN, GPIO_OUTPUT);
    if (fan_fd < 0) {
        printf("Error opening fan interface: %s\n", strerror(errno));
        mcp3008_close(adc_fd);
        pigpio_close(spi_fd);
        return 1;
    }

    // Set up logging
    FILE *log_file = fopen("air_quality.log", "w");
    if (log_file == NULL) {
        printf("Error opening log file: %s\n", strerror(errno));
        gpio_close(fan_fd);
        mcp3008_close(adc_fd);
        pigpio_close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = mcp3008_read(adc_fd);
        if (adc_value < 0) {
            printf("Error reading ADC value: %s\n", strerror(errno));
            continue;
        }

        // Convert ADC value to CO2 concentration
        uint16_t co2_ppm = (adc_value * 1000) / 1023;

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d, %d, %d\n", tm->tm_hour, tm->tm_min, tm->tm_sec, co2_ppm, (co2_ppm > CO2_THRESHOLD) ? 1 : 0);

        // Turn on fan if CO2 concentration exceeds threshold
        if (co2_ppm > CO2_THRESHOLD) {
            gpio_write(fan_fd, 1);
        } else {
            gpio_write(fan_fd, 0);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    gpio_close(fan_fd);
    mcp3008_close(adc_fd);
    pigpio_close(spi_fd);

    return 0;
}
