#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define VALVE_PIN 17
#define VALVE_PWM_FREQ 100
#define VALVE_PWM_RANGE 100

#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

static int spi_fd;
static int adc_fd;
static int valve_fd;
static int log_fd;

static void sigint_handler(int signum) {
    // Set valve PWM to 0
    pigpio_set_PWM_dutycycle(valve_fd, 0);

    // Close SPI interface
    pigpio_close(spi_fd);

    // Close log file
    close(log_fd);

    // Terminate driver library
    pigpio_terminate();

    // Exit program
    exit(0);
}

static void sigterm_handler(int signum) {
    // Set valve PWM to 0
    pigpio_set_PWM_dutycycle(valve_fd, 0);

    // Close SPI interface
    pigpio_close(spi_fd);

    // Close log file
    close(log_fd);

    // Terminate driver library
    pigpio_terminate();

    // Exit program
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize driver library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize driver library\n");
        return 1;
    }

    // Open SPI interface
    spi_fd = pigpio_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        return 1;
    }

    // Open ADC interface
    adc_fd = pigpio_open_adc(ADC_CHANNEL);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC interface\n");
        return 1;
    }

    // Open valve interface
    valve_fd = pigpio_open_PWM(VALVE_PIN, VALVE_PWM_FREQ, VALVE_PWM_RANGE);
    if (valve_fd < 0) {
        fprintf(stderr, "Failed to open valve interface\n");
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read three successive samples from ADC
        uint16_t adc_values[3];
        for (int i = 0; i < 3; i++) {
            if (pigpio_read_adc(adc_fd, &adc_values[i]) < 0) {
                fprintf(stderr, "Failed to read from ADC\n");
                return 1;
            }
