        // Compute average of three raw ADC values
        uint16_t adc_average = (adc_values[0] + adc_values[1] + adc_values[2]) / 3;

        // Set valve position based on average ADC value
        uint16_t valve_position = (adc_average * VALVE_PWM_RANGE) / 1023;
        pigpio_set_PWM_dutycycle(valve_fd, valve_position);

        // Log data to file
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_entry[100];
        sprintf(log_entry, "%s, %d, %d, %d\n", timestamp, adc_values[0], adc_values[1], adc_values[2]);
        write(log_fd, log_entry, strlen(log_entry));

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close SPI interface
    pigpio_close(spi_fd);

    // Close ADC interface
    pigpio_close_adc(adc_fd);

    // Close valve interface
    pigpio_close_PWM(valve_fd);

    // Close log file
    close(log_fd);

    // Terminate driver library
    pigpio_terminate();

    return 0;
}

