#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_DELAY 5000
#define SPI_RETRIES 5
#define SPI_BACKOFF 2

#define SOIL_MIN 0
#define SOIL_MAX 1023
#define SOIL_ERROR -1

#define SOIL_FILE "soil_data.txt"

static int spi_fd;
static int spi_handle;
static int spi_retry;

static void spi_init(void) {
    spi_fd = pigpio_start(NULL, 0);
    if (spi_fd < 0) {
        printf("Failed to start pigpio\n");
        exit(1);
    }

    spi_handle = pigpio_spi_open(spi_fd, SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS);
    if (spi_handle < 0) {
        printf("Failed to open SPI channel %d\n", SPI_CHANNEL);
        exit(1);
    }
}

static void spi_close(void) {
    pigpio_spi_close(spi_handle);
    pigpio_stop(spi_fd);
}

static int spi_read(void) {
    uint8_t cmd = 0x01;
    uint8_t data[2];
    int ret;

    ret = pigpio_spi_xfer(spi_handle, &cmd, 1, data, 2);
    if (ret < 0) {
        printf("Failed to read from SPI channel %d\n", SPI_CHANNEL);
        return ret;
    }

    return (data[0] << 8) | data[1];
}

static int spi_retry_read(void) {
    int ret;

    for (spi_retry = 0; spi_retry < SPI_RETRIES; spi_retry++) {
        ret = spi_read();
        if (ret >= 0) {
            return ret;
        }

        usleep(SPI_DELAY * (1 << spi_retry));
    }

    return ret;
}

static void signal_handler(int signum) {
    spi_close();
    exit(0);
}

int main(void) {
    int ret;
    int soil_value;
    char soil_str[16];
    FILE *fp;

    spi_init();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fp = fopen(SOIL_FILE, "a");
    if (fp == NULL) {
        printf("Failed to open file %s\n", SOIL_FILE);
        exit(1);
    }

    while (1) {
        soil_value = spi_retry_read();
        if (soil_value < 0) {
            printf("Failed to read from SPI channel %d\n", SPI_CHANNEL);
            fprintf(fp, "Error: Failed to read from SPI channel %d\n", SPI_CHANNEL);
            continue;
        }

        if (soil_value < SOIL_MIN || soil_value > SOIL_MAX) {
            printf("Invalid soil value: %d\n", soil_value);
            fprintf(fp, "Error: Invalid soil value: %d\n", soil_value);
            continue;
        }

        sprintf(soil_str, "%d\n", soil_value);
        fprintf(fp, "%s", soil_str);
    }

    fclose(fp);
    spi_close();

    return 0;
}

