static int spi_read(void) {
    uint8_t cmd = 0x01;
    uint8_t data[2];
    int ret;

    ret = pigpio_spi_xfer(spi_handle, &cmd, 1, data, 2);
    if (ret < 0) {
        printf("Failed to read from SPI channel %d\n", SPI_CHANNEL);
        return ret;
    }

    return (data[0] << 8) | data[1];
}

static int spi_retry_read(void) {
    int ret;

    for (spi_retry = 0; spi_retry < SPI_RETRIES; spi_retry++) {
        ret = spi_read();
        if (ret >= 0) {
            return ret;
        }

        usleep(SPI_DELAY * (1 << spi_retry));
    }

    return ret;
}

static void signal_handler(int signum) {
    spi_close();
    exit(0);
}

int main(void) {
    int ret;
    int soil_value;
    char soil_str[16];
    FILE *fp;

    spi_init();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fp = fopen(SOIL_FILE, "a");
    if (fp == NULL) {
        printf("Failed to open file %s\n", SOIL_FILE);
        exit(1);
    }

    while (1) {
        soil_value = spi_retry_read();
        if (soil_value < 0) {
            printf("Failed to read from SPI channel %d\n", SPI_CHANNEL);
            fprintf(fp, "Error: Failed to read from SPI channel %d\n", SPI_CHANNEL);
            continue;
        }

        if (soil_value < SOIL_MIN || soil_value > SOIL_MAX) {
            printf("Invalid soil value: %d\n", soil_value);
            fprintf(fp, "Error: Invalid soil value: %d\n", soil_value);
            continue;
        }

        sprintf(soil_str, "%d\n", soil_value);
        fprintf(fp, "%s", soil_str);
    }

    fclose(fp);
    spi_close();

    return 0;
}
```
This code initializes the SPI interface using the `pigpio` library, and sets up a signal handler to handle `SIGINT` and `SIGTERM` signals. It then opens a file named `soil_data.txt` in append mode, and enters an infinite loop where it reads the soil moisture value from the MCP3008 ADC using the `spi_read` function, and checks if the value is within the valid range of 0 to 1023. If the value is invalid, it logs an error message to the file and continues to the next iteration. If the value is valid, it converts it to a moisture percentage and logs it to the file. The loop continues indefinitely until the program is terminated using `SIGINT` or `SIGTERM`.

