#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define FAN_GPIO 18

int main(int argc, char *argv[]) {
  // Initialize the SPI interface
  if (spi_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
    fprintf(stderr, "Failed to initialize SPI interface\n");
    return 1;
  }

  // Initialize the MCP3008 ADC
  if (mcp3008_init() < 0) {
    fprintf(stderr, "Failed to initialize MCP3008 ADC\n");
    return 1;
  }

  // Open the log file in append mode
  int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
  if (log_fd < 0) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Initialize the fan GPIO pin
  if (gpio_init(FAN_GPIO, GPIO_OUT) < 0) {
    fprintf(stderr, "Failed to initialize fan GPIO pin\n");
    return 1;
  }

  // Set the fan GPIO pin to low
  gpio_write(FAN_GPIO, 0);

  // Set up signal handlers
  signal(SIGINT, sigint_handler);
  signal(SIGTERM, sigterm_handler);

  // Main loop
  while (1) {
    // Read the ADC value
    int adc_value = mcp3008_read(ADC_CHANNEL);
    if (adc_value < 0) {
      fprintf(stderr, "Failed to read ADC value\n");
      return 1;
    }

    // Compute the AQI value
    int aqi = compute_aqi(adc_value);

    // Log the timestamp and AQI value
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char log_entry[100];
    sprintf(log_entry, "%s, %d\n", timestamp, aqi);
    write(log_fd, log_entry, strlen(log_entry));

    // Turn on the fan if the AQI exceeds the threshold
    if (aqi > AQI_THRESHOLD) {
      gpio_write(FAN_GPIO, 1);
    } else {
      gpio_write(FAN_GPIO, 0);
    }

    // Sleep for 5 seconds
    sleep(5);
  }

  // Clean up
  close(log_fd);
  mcp3008_close();
  spi_close();
  gpio_close();

  return 0;
}

// Signal handler for SIGINT
void sigint_handler(int signal) {
  // Turn off the fan
  gpio_write(FAN_GPIO, 0);

  // Close the log file
  close(log_fd);

  // Close the SPI interface
  spi_close();

  // Close the MCP3008 ADC
  mcp3008_close();

  // Close the GPIO pin
  gpio_close();

  // Terminate the driver library
  gpio_terminate();

  // Exit the program
  exit(0);
}

// Signal handler for SIGTERM
void sigterm_handler(int signal) {
  // Turn off the fan
  gpio_write(FAN_GPIO, 0);

  // Close the log file
  close(log_fd);

  // Close the SPI interface
  spi_close();

  // Close the MCP3008 ADC
  mcp3008_close();

  // Close the GPIO pin
  gpio_close();

  // Terminate the driver library
  gpio_terminate();

  // Exit the program
  exit(0);
}

