    if (log_fd < 0) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize the MCP3008 ADC
    mcp3008_t adc;
    if (mcp3008_init(&adc, ADC_CHANNEL, ADC_SPI_SPEED, ADC_SPI_MODE, ADC_SPI_BITS) < 0) {
