    if (gpiod_init(&gpio, GPIO_8, GPIO_OUTPUT) < 0) {
        perror("Error initializing GPIO pin");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the ADC value
        int adc_value = mcp3008_read(&adc);
        if (adc_value < 0) {
