                continue;
            } else {
                // Retry the read up to ADC_SPI_RETRIES times with a delay of ADC_SPI_DELAY ms
                for (int i = 0; i < ADC_SPI_RETRIES; i++) {
                    adc_value = mcp3008_read(&adc);
                    if (adc_value >= 0) {
                        break;
                    }
                    usleep(ADC_SPI_DELAY * 1000);
                }
                if (adc_value < 0) {
                    // Log the error
                    fprintf(stderr, ADC_SPI_ERROR_MSG, strerror(adc_value));
                    continue;
                }
            }
