        }

        // Write the message to the log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "%s: %s\n", timestamp, message);
        write(log_fd, log_message, strlen(log_message));
    }

    // Clean up
    mcp3008_close(&adc);
    gpiod_close(&gpio);
    close(log_fd);

    return 0;
}

