#include <pigpio/pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define THRESHOLD 300
#define PUMP_GPIO 18

static int spi_fd;
static int log_fd;
static int pump_fd;

static void sigint_handler(int signum) {
    printf("Received signal %d, turning off pump and closing SPI interface\n", signum);
    gpiod_set_value(pump_fd, 0);
    close(spi_fd);
    close(log_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize driver library
    if (gpiod_init() < 0) {
        printf("Failed to initialize GPIO driver\n");
        return 1;
    }

    // Open SPI interface
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        printf("Failed to open SPI device %s\n", SPI_DEVICE);
        return 1;
    }

    // Set SPI speed and mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        printf("Failed to set SPI mode\n");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        printf("Failed to set SPI speed\n");
        return 1;
    }

    // Open log file
    log_fd = open("irrigation.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO for pump control
    pump_fd = gpiod_open(PUMP_GPIO, GPIOD_OUTPUT);
    if (pump_fd < 0) {
        printf("Failed to open GPIO %d for pump control\n", PUMP_GPIO);
        return 1;
    }

    // Main loop
    while (1) {
        // Read moisture value from sensor
        uint16_t moisture = 0;
        if (spi_xfer(spi_fd, SPI_CHANNEL, &moisture, 1) < 0) {
            printf("Failed to read moisture value from sensor\n");
            continue;
        }

        // Check if moisture value is below threshold
        if (moisture < THRESHOLD) {
            // Turn on pump
            gpiod_set_value(pump_fd, 1);

            // Log moisture value and pump status
            char buf[100];
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            snprintf(buf, sizeof(buf), "%s, %d, %d, %d\n", asctime(tm), moisture, 1, t);
            write(log_fd, buf, strlen(buf));
        } else {
            // Turn off pump
            gpiod_set_value(pump_fd, 0);

            // Log moisture value and pump status
            char buf[100];
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            snprintf(buf, sizeof(buf), "%s, %d, %d, %d\n", asctime(tm), moisture, 0, t);
            write(log_fd, buf, strlen(buf));
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    gpiod_close(pump_fd);
    close(spi_fd);
    close(log_fd);
    gpiod_cleanup();

    return 0;
}

