#include <mcp3008.h>
#include <wiringPi.h>

#define MOTOR1_ENABLE_PIN 18
#define MOTOR2_ENABLE_PIN 24
#define MOTOR1_DIRECTION_PIN 23
#define MOTOR2_DIRECTION_PIN 25

#define POT1_ADC_CHANNEL 0
#define POT2_ADC_CHANNEL 1

#define SPEED_STEP 10
#define SPEED_MAX 100

#define ACCELERATION_STEP 10
#define ACCELERATION_MAX 100

#define DECELERATION_STEP 10
#define DECELERATION_MAX 100

#define DIRECTION_DELAY 100

#define ERROR_POT_ABSENT -1
#define ERROR_SPI_BUS -2

int main(int argc, char **argv) {
  // Initialize GPIO
  if (wiringPiSetup() == -1) {
    fprintf(stderr, "Failed to initialize GPIO\n");
    return 1;
  }

  // Initialize SPI
  if (spiSetup(0, 1000000, 0) == -1) {
    fprintf(stderr, "Failed to initialize SPI\n");
    return 1;
  }

  // Initialize MCP3008 ADC
  if (mcp3008Setup(0, 1000000, 0) == -1) {
    fprintf(stderr, "Failed to initialize MCP3008 ADC\n");
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (1) {
    // Read potentiometers
    int pot1 = mcp3008Read(POT1_ADC_CHANNEL);
    int pot2 = mcp3008Read(POT2_ADC_CHANNEL);

    // Check for errors
    if (pot1 == ERROR_POT_ABSENT || pot2 == ERROR_POT_ABSENT) {
      fprintf(stderr, "Potentiometer not found\n");
      return 1;
    } else if (pot1 == ERROR_SPI_BUS || pot2 == ERROR_SPI_BUS) {
      fprintf(stderr, "SPI bus error\n");
      return 1;
    }

    // Map potentiometer readings to speed values
    int speed1 = map(pot1, 0, 1023, 0, SPEED_MAX);
    int speed2 = map(pot2, 0, 1023, 0, SPEED_MAX);

    // Accelerate motors
    for (int i = 0; i <= SPEED_MAX; i += ACCELERATION_STEP) {
      // Set motor speeds
      pwmWrite(MOTOR1_ENABLE_PIN, i);
      pwmWrite(MOTOR2_ENABLE_PIN, i);

      // Set motor directions
      digitalWrite(MOTOR1_DIRECTION_PIN, HIGH);
      digitalWrite(MOTOR2_DIRECTION_PIN, LOW);

      // Wait for acceleration
      delay(ACCELERATION_STEP);
    }

    // Hold constant speed
    delay(2000);

    // Decelerate motors
    for (int i = SPEED_MAX; i >= 0; i -= DECELERATION_STEP) {
      // Set motor speeds
      pwmWrite(MOTOR1_ENABLE_PIN, i);
      pwmWrite(MOTOR2_ENABLE_PIN, i);

      // Set motor directions
      digitalWrite(MOTOR1_DIRECTION_PIN, HIGH);
      digitalWrite(MOTOR2_DIRECTION_PIN, LOW);

      // Wait for deceleration
      delay(DECELERATION_STEP);
    }

    // Pause
    delay(5000);

    // Reverse motors
    digitalWrite(MOTOR1_DIRECTION_PIN, LOW);
    digitalWrite(MOTOR2_DIRECTION_PIN, HIGH);

    // Wait for direction change
    delay(DIRECTION_DELAY);
  }

  // Clean up resources
  pwmWrite(MOTOR1_ENABLE_PIN, 0);
  pwmWrite(MOTOR2_ENABLE_PIN, 0);
  digitalWrite(MOTOR1_DIRECTION_PIN, LOW);
  digitalWrite(MOTOR2_DIRECTION_PIN, LOW);
  spiClose(0);
  mcp3008Close(0);
  wiringPiClose();

  return 0;
}

