    if (pot1 == ERROR_POT_ABSENT || pot2 == ERROR_POT_ABSENT) {
      fprintf(stderr, "Potentiometer not found\n");
      return 1;
    } else if (pot1 == ERROR_SPI_BUS || pot2 == ERROR_SPI_BUS) {
      fprintf(stderr, "SPI bus error\n");
      return 1;
    }

    // Map potentiometer readings to speed values
    int speed1 = map(pot1, 0, 1023, 0, SPEED_MAX);
    int speed2 = map(pot2, 0, 1023, 0, SPEED_MAX);

    // Accelerate motors
    for (int i = 0; i <= SPEED_MAX; i += ACCELERATION_STEP) {
      // Set motor speeds
      pwmWrite(MOTOR1_ENABLE_PIN, i);
      pwmWrite(MOTOR2_ENABLE_PIN, i);

      // Set motor directions
      digitalWrite(MOTOR1_DIRECTION_PIN, HIGH);
      digitalWrite(MOTOR2_DIRECTION_PIN, LOW);

      // Wait for acceleration
      delay(ACCELERATION_STEP);
    }

    // Hold constant speed
    delay(2000);

    // Decelerate motors
    for (int i = SPEED_MAX; i >= 0; i -= DECELERATION_STEP) {
      // Set motor speeds
      pwmWrite(MOTOR1_ENABLE_PIN, i);
      pwmWrite(MOTOR2_ENABLE_PIN, i);

      // Set motor directions
      digitalWrite(MOTOR1_DIRECTION_PIN, HIGH);
      digitalWrite(MOTOR2_DIRECTION_PIN, LOW);

      // Wait for deceleration
      delay(DECELERATION_STEP);
    }

    // Pause
    delay(5000);

    // Reverse motors
    digitalWrite(MOTOR1_DIRECTION_PIN, LOW);
    digitalWrite(MOTOR2_DIRECTION_PIN, HIGH);

    // Wait for direction change
    delay(DIRECTION_DELAY);
  }

  // Clean up resources
  pwmWrite(MOTOR1_ENABLE_PIN, 0);
  pwmWrite(MOTOR2_ENABLE_PIN, 0);
  digitalWrite(MOTOR1_DIRECTION_PIN, LOW);
  digitalWrite(MOTOR2_DIRECTION_PIN, LOW);
  spiClose(0);
  mcp3008Close(0);
  wiringPiClose();

  return 0;
}

void signal_handler(int signal) {
  // Clean up resources
  pwmWrite(MOTOR1_ENABLE_PIN, 0);
  pwmWrite(MOTOR2_ENABLE_PIN, 0);
  digitalWrite(MOTOR1_DIRECTION_PIN, LOW);
  digitalWrite(MOTOR2_DIRECTION_PIN, LOW);
  spiClose(0);
  mcp3008Close(0);
  wiringPiClose();

  exit(0);
}
