#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX_CLOCK 1000000
#define ADC_SAMPLE_RATE 1000
#define ADC_SAMPLE_PERIOD 1000000 / ADC_SAMPLE_RATE

#define GPIO_CHIP_SELECT 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11

#define LOG_FILE "audio_log.txt"

static int spi_fd;
static int gpio_fd;
static int log_fd;

static void handle_sigint(int signum) {
    printf("Received SIGINT, releasing GPIO line request and closing SPI file descriptor\n");
    ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, GPIO_CHIP_SELECT, 0);
    close(spi_fd);
    exit(0);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, releasing GPIO line request and closing SPI file descriptor\n");
    ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, GPIO_CHIP_SELECT, 0);
    close(spi_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    // Configure SPI device
    struct spi_ioc_transfer spi_config = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = ADC_MAX_CLOCK,
        .bits_per_word = ADC_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .word_delay_usecs = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_config) < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        exit(1);
    }

    // Open GPIO device
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(spi_fd);
        exit(1);
    }

    // Request GPIO line
    if (ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, GPIO_CHIP_SELECT, 1) < 0) {
        perror("Failed to request GPIO line");
        close(gpio_fd);
        close(spi_fd);
        exit(1);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(gpio_fd);
        close(spi_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint32_t adc_value;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &adc_value) < 0) {
            perror("Failed to read ADC value");
            close(gpio_fd);
            close(spi_fd);
            close(log_fd);
            exit(1);
        }

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);

        // Write to log file
        char line[100];
        snprintf(line, sizeof(line), "%ld|%u\n", ts.tv_nsec, adc_value);
        if (write(log_fd, line, strlen(line)) < 0) {
            perror("Failed to write to log file");
            close(gpio_fd);
            close(spi_fd);
            close(log_fd);
            exit(1);
        }

        // Flush log file
        if (fsync(log_fd) < 0) {
            perror("Failed to flush log file");
            close(gpio_fd);
            close(spi_fd);
            close(log_fd);
            exit(1);
        }

        // Sleep until next sample period
        struct timespec sleep_time = {
            .tv_sec = 0,
            .tv_nsec = ADC_SAMPLE_PERIOD,
        };
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line request and close SPI file descriptor
    ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, GPIO_CHIP_SELECT, 0);
    close(spi_fd);

    // Close log file
    close(log_fd);

    return 0;
}

