static void init_spi(void) {
    int fd;
    struct spi_ioc_transfer xfer;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    xfer.tx_buf = (unsigned long)NULL;
    xfer.rx_buf = (unsigned long)NULL;
    xfer.len = 0;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.cs_change = 0;
    xfer.tx_nbits = 0;
    xfer.rx_nbits = 0;
    xfer.pad = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("ioctl");
        exit(1);
    }

    close(fd);
}

static void read_gas_sensor(void) {
    int fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[4];
    uint8_t rx_buf[4];
    uint16_t adc_value;
    float voltage;
    int ppm;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    xfer.tx_buf = (unsigned long)tx_buf;
    xfer.rx_buf = (unsigned long)rx_buf;
    xfer.len = 4;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.cs_change = 0;
    xfer.tx_nbits = 0;
    xfer.rx_nbits = 0;
    xfer.pad = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("ioctl");
        exit(1);
    }

    adc_value = (rx_buf[1] << 8) | rx_buf[2];
    voltage = (float)adc_value * 3.3 / 1024;
    ppm = (int)(voltage * 1000);

    printf("Voltage: %.3f V, PPM: %d\n", voltage, ppm);

    close(fd);
