#include <sys/types.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 100000
#define SPI_RETRIES 3
#define GAS_LOG_FILE "gas_log.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_spi(void) {
    int fd;
    struct spi_ioc_transfer xfer;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    xfer.tx_buf = (unsigned long)NULL;
    xfer.rx_buf = (unsigned long)NULL;
    xfer.len = 0;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.cs_change = 0;
    xfer.tx_nbits = 0;
    xfer.rx_nbits = 0;
    xfer.pad = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("ioctl");
        exit(1);
    }

    close(fd);
}

static void read_gas_sensor(void) {
    int fd;
    struct spi_ioc_transfer xfer;
    uint8_t tx_buf[4];
    uint8_t rx_buf[4];
    uint16_t adc_value;
    float voltage;
    int ppm;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    xfer.tx_buf = (unsigned long)tx_buf;
    xfer.rx_buf = (unsigned long)rx_buf;
    xfer.len = 4;
    xfer.delay_usecs = SPI_DELAY;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS;
    xfer.cs_change = 0;
    xfer.tx_nbits = 0;
    xfer.rx_nbits = 0;
    xfer.pad = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("ioctl");
        exit(1);
    }

    adc_value = (rx_buf[1] << 8) | rx_buf[2];
    voltage = (float)adc_value * 3.3 / 1024;
    ppm = (int)(voltage * 1000);

    printf("Voltage: %.3f V, PPM: %d\n", voltage, ppm);

    close(fd);
}

static void log_gas_sensor(void) {
    int fd;
    struct tm *tm;
    time_t t;
    char buf[100];

    fd = open(GAS_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    t = time(NULL);
    tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);

    dprintf(fd, "%s, %.3f, %d\n", buf, voltage, ppm);

    close(fd);
}

int main(void) {
    int retries = 0;

    signal(SIGINT, sigint_handler);

    init_spi();

    while (running) {
        read_gas_sensor();
        log_gas_sensor();
        sleep(1);
    }

    return 0;
}
```
This code uses the `libgpiod` library to initialize the SPI interface and read the voltage from the gas sensor. It also uses the `time` library to get the current time and the `dprintf` function to write the data to a log file. The `signal` function is used to handle the `SIGINT` signal, which is triggered when the user presses `Ctrl+C`, and the `running` variable is used to keep track of whether the program is still running or not. The `init_spi` function initializes the SPI interface, the `read_gas_sensor` function reads the voltage from the gas sensor, and the `log_gas_sensor` function logs the data to a file. The `main` function sets up the signal handler, initializes the SPI interface, and reads the gas sensor data and logs it to a file once per second until the program is interrupted.

