#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 27

#define MAGNETIC_FIELD_MIN -100
#define MAGNETIC_FIELD_MAX 100

#define LOG_FILE "magnetic_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (line1 == NULL || line2 == NULL || line3 == NULL) {
        fprintf(stderr, "Error opening GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        fprintf(stderr, "Error opening log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read GPIO pins
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);
        int value3 = gpiod_line_get_value(line3);

        if (value1 == -1 || value2 == -1 || value3 == -1) {
            fprintf(stderr, "Error reading GPIO values\n");
            continue;
        }

        // Convert GPIO values to magnetic field strength
        float mT1 = (value1 == 1) ? 3.3 : 0.0;
        float mT2 = (value2 == 1) ? 3.3 : 0.0;
        float mT3 = (value3 == 1) ? 3.3 : 0.0;

        // Check for out-of-range values
        if (mT1 < MAGNETIC_FIELD_MIN || mT1 > MAGNETIC_FIELD_MAX ||
            mT2 < MAGNETIC_FIELD_MIN || mT2 > MAGNETIC_FIELD_MAX ||
            mT3 < MAGNETIC_FIELD_MIN || mT3 > MAGNETIC_FIELD_MAX) {
            fprintf(stderr, "Warning: computed magnetic field out of range\n");
            continue;
        }

        // Write to log file
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "%.2f,%.2f,%.2f\n", mT1, mT2, mT3);
        write(fd, buffer, strlen(buffer));
    }

    // Clean up
    close(fd);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

