#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000

#define CHANNEL_COUNT 3

int main(int argc, char **argv) {
    int spi_fd;
    int channel_fd[CHANNEL_COUNT];
    int i;
    int ret;
    char *csv_file = "sensor_data.csv";
    FILE *fp;

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set the SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open the CSV file
    fp = fopen(csv_file, "w");
    if (fp == NULL) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Read the analog values from the MCP3008 channels
    for (i = 0; i < CHANNEL_COUNT; i++) {
        int channel_value;

        // Read the analog value from the channel
        ret = read(spi_fd, &channel_value, sizeof(channel_value));
        if (ret < 0) {
            perror("Failed to read from SPI device");
            close(spi_fd);
            fclose(fp);
            return 1;
        }

        // Write the analog value to the CSV file
        fprintf(fp, "%d,", channel_value);
    }

    // Close the CSV file
    fclose(fp);

    // Close the SPI device
    close(spi_fd);

    return 0;
}

void sigint_handler(int signum) {
    // Close the CSV file
    fclose(fp);

    // Close the SPI device
    close(spi_fd);

    // Exit the program
    exit(0);
}

