#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <mosquitto.h>
#include <json-c/json.h>
#include <libgpiod/libgpiod.h>

#define LED_PIN 17
#define MQTT_SERVER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MQTT_QOS 0

static int gpio_fd;
static int mqtt_fd;
static struct mosquitto *mosq;
static struct mosquitto_message *msg;
static struct json_object *json;
static struct json_object_iterator it;
static struct json_object_iterator_entry entry;

static void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        // Clean up and exit
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        gpiod_release(gpio_fd);
        exit(0);
    }
}

static void handle_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->topic == NULL || msg->payload == NULL) {
        fprintf(stderr, "Error: Invalid MQTT message\n");
        return;
    }

    if (strcmp(msg->topic, MQTT_TOPIC) != 0) {
        fprintf(stderr, "Error: Unexpected MQTT topic: %s\n", msg->topic);
        return;
    }

    json = json_tokener_parse(msg->payload);
    if (json == NULL) {
        fprintf(stderr, "Error: Invalid JSON payload\n");
        return;
    }

    it = json_object_iter_begin(json);
    while (!json_object_iter_end(json, it)) {
        entry = json_object_iter_peek_value(it);
        if (strcmp(json_object_iter_peek_name(it), "led_state") == 0) {
            if (json_object_get_type(entry) != json_type_boolean) {
                fprintf(stderr, "Error: Invalid JSON type for led_state\n");
                return;
            }

            int led_state = json_object_get_boolean(entry);
            if (led_state) {
                gpiod_set_value(gpio_fd, LED_PIN, 1);
            } else {
                gpiod_set_value(gpio_fd, LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error: Unexpected JSON key: %s\n", json_object_iter_peek_name(it));
            return;
        }

        it = json_object_iter_next(it);
    }

    json_object_put(json);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    gpio_fd = gpiod_open(LED_PIN, GPIOD_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO pin %d\n", LED_PIN);
        return 1;
    }

    // Initialize MQTT
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        return 1;
    }

    mqtt_fd = mosquitto_connect(mosq, MQTT_SERVER, MQTT_PORT, 60);
    if (mqtt_fd < 0) {
        fprintf(stderr, "Error: Failed to connect to MQTT server\n");
        return 1;
    }

    mosquitto_message_callback_set(mosq, handle_mqtt_message);

    // Subscribe to MQTT topic
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Turn off LED at startup
    gpiod_set_value(gpio_fd, LED_PIN, 0);

    // Wait for signal
    while (1) {
        sleep(1);
    }

    // Clean up and exit
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpiod_release(gpio_fd);
    return 0;
}

