#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN_SOUND_SENSOR 17
#define GPIO_PIN_ALARM_LED 18

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    int fd_gpio;
    int fd_chip;
    int fd_line;
    int ret;
    bool sound_detected = false;

    // Initialize the GPIO driver
    if ((fd_gpio = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Open the chip
    if ((fd_chip = pigpio_open(fd_gpio, 0, 0)) < 0) {
        fprintf(stderr, "Failed to open chip\n");
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Request the line
    if ((fd_line = pigpio_line_request(fd_chip, GPIO_PIN_SOUND_SENSOR)) < 0) {
        fprintf(stderr, "Failed to request line\n");
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set the line to input mode
    if ((ret = pigpio_line_mode(fd_line, PI_LINE_MODE_INPUT)) < 0) {
        fprintf(stderr, "Failed to set line mode\n");
        pigpio_line_release(fd_line);
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set the line to pull-up mode
    if ((ret = pigpio_line_pull(fd_line, PI_LINE_PULL_UP)) < 0) {
        fprintf(stderr, "Failed to set line pull\n");
        pigpio_line_release(fd_line);
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set the line to trigger on falling edge
    if ((ret = pigpio_line_trigger(fd_line, PI_LINE_TRIGGER_FALLING)) < 0) {
        fprintf(stderr, "Failed to set line trigger\n");
        pigpio_line_release(fd_line);
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set the alarm LED to output mode
    if ((ret = pigpio_line_mode(fd_chip, GPIO_PIN_ALARM_LED, PI_LINE_MODE_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set alarm LED mode\n");
        pigpio_line_release(fd_line);
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set the alarm LED to low
    if ((ret = pigpio_line_write(fd_chip, GPIO_PIN_ALARM_LED, 0)) < 0) {
        fprintf(stderr, "Failed to set alarm LED low\n");
        pigpio_line_release(fd_line);
        pigpio_close(fd_chip);
        pigpio_stop(fd_gpio);
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        // Read the sound sensor
        if ((ret = pigpio_line_read(fd_line, &sound_detected)) < 0) {
            fprintf(stderr, "Failed to read sound sensor\n");
            pigpio_line_release(fd_line);
            pigpio_close(fd_chip);
            pigpio_stop(fd_gpio);
            return 1;
        }

        // If sound is detected, trigger the alarm LED
        if (sound_detected) {
            // Set the alarm LED to high
            if ((ret = pigpio_line_write(fd_chip, GPIO_PIN_ALARM_LED, 1)) < 0) {
                fprintf(stderr, "Failed to set alarm LED high\n");
                pigpio_line_release(fd_line);
                pigpio_close(fd_chip);
                pigpio_stop(fd_gpio);
                return 1;
            }

            // Wait for 1 second
            sleep(1);

            // Set the alarm LED to low
            if ((ret = pigpio_line_write(fd_chip, GPIO_PIN_ALARM_LED, 0)) < 0) {
                fprintf(stderr, "Failed to set alarm LED low\n");
                pigpio_line_release(fd_line);
                pigpio_close(fd_chip);
                pigpio_stop(fd_gpio);
                return 1;
            }
        }

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    pigpio_line_release(fd_line);
    pigpio_close(fd_chip);
    pigpio_stop(fd_gpio);

    return 0;
}

