#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_NAME "vibration-monitor"
#define LOG_FILE_PATH "/var/log/vibration_shutdown.log"

volatile sig_atomic_t sigint_flag = 0;
volatile sig_atomic_t sigterm_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

void sigterm_handler(int signum) {
    sigterm_flag = 1;
}

int main(int argc, char *argv[]) {
    int gpio_chip_fd, gpio_line_fd, ret;
    struct gpiohandle_request gpio_req;
    struct gpioevent_request gpio_event_req;
    struct gpioevent_data gpio_event_data;
    char timestamp[32];

    // Open the GPIO chip
    gpio_chip_fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (gpio_chip_fd < 0) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    memset(&gpio_req, 0, sizeof(gpio_req));
    gpio_req.lineoffsets[0] = GPIO_LINE_NAME;
    gpio_req.flags = GPIOHANDLE_REQUEST_INPUT;
    gpio_req.default_values[0] = GPIO_LINE_NAME;
    gpio_req.consumer_label = "vibration-monitor";
    ret = ioctl(gpio_chip_fd, GPIO_GET_LINEHANDLE_IOCTL, &gpio_req);
    if (ret < 0) {
        perror("Error getting GPIO line");
        close(gpio_chip_fd);
        return 1;
    }
    gpio_line_fd = gpio_req.fd;

    // Set up the GPIO event request
    memset(&gpio_event_req, 0, sizeof(gpio_event_req));
    gpio_event_req.lineoffset = GPIO_LINE_NAME;
    gpio_event_req.handleflags = GPIOHANDLE_REQUEST_INPUT;
    gpio_event_req.eventflags = GPIOEVENT_REQUEST_FALLING_EDGE;
    ret = ioctl(gpio_chip_fd, GPIO_GET_LINEEVENT_IOCTL, &gpio_event_req);
    if (ret < 0) {
        perror("Error setting up GPIO event");
        close(gpio_line_fd);
        close(gpio_chip_fd);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!sigint_flag && !sigterm_flag) {
        // Wait for an event
        ret = read(gpio_line_fd, &gpio_event_data, sizeof(gpio_event_data));
        if (ret < 0) {
            perror("Error reading GPIO event");
            break;
        }

        // Read the event
        ret = ioctl(gpio_chip_fd, GPIO_GET_LINEEVENT_IOCTL, &gpio_event_data);
        if (ret < 0) {
            perror("Error reading GPIO event");
            break;
        }

        // Print the event
        printf("Vibration detected at %s\n", ctime(&gpio_event_data.timestamp));

        // Append a timestamped message to the log file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));
        FILE *log_file = fopen(LOG_FILE_PATH, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            break;
        }
        fprintf(log_file, "%s: Vibration detected\n", timestamp);
        fclose(log_file);

        // Shut down the system
        system("sudo shutdown -h now");
    }

    // Clean up
    close(gpio_line_fd);
    close(gpio_chip_fd);

    return 0;
}

