#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_DELAY 10000
#define BUFFER_SIZE 120
#define FILENAME "temp_log.dat"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Initialize the GPIO pins
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    gpiod_line_t *line_ce0 = gpiod_chip_get_line(chip, 8);
    gpiod_line_t *line_miso = gpiod_chip_get_line(chip, 9);
    gpiod_line_t *line_mosi = gpiod_chip_get_line(chip, 10);
    gpiod_line_t *line_sclk = gpiod_chip_get_line(chip, 11);

    if (!line_ce0 || !line_miso || !line_mosi || !line_sclk) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    // Initialize the SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)NULL;
    transfer.rx_buf = (unsigned long)NULL;
    transfer.len = 1;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS;
    transfer.delay_usecs = SPI_DELAY;

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    // Set up the circular buffer
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Open the file for writing
