#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define BCM_PIN 17
#define FLAME_EVENTS_FILE "flame_events.log"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the GPIO line for input with a pull-down resistor
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor") != 0) {
        fprintf(stderr, "Error: unable to request GPIO line for input\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the CSV file for writing
    FILE *fp = fopen(FLAME_EVENTS_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error: unable to open CSV file for writing\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Poll the GPIO line once every second
    while (running) {
        struct timespec ts;
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);

        // Read the GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            fclose(fp);
            return 1;
        }

        // Log the reading to the CSV file
        fprintf(fp, "%ld,%d,%d\n", time(NULL), BCM_PIN, value);

        // Print an alarm message to stdout if the sensor reports a HIGH
        if (value == 1) {
            printf("ALARM: Flame detected!\n");
        }
    }

    // Clean up GPIO resources
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    fclose(fp);

    return 0;
}

