#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define ADC_CHANNEL 0
#define THRESHOLD 500
#define SAMPLE_RATE 10000
#define DEBOUNCE_DELAY 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the GPIO library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Initialize the MCP3008 ADC
    mcp3008_t adc;
    if (mcp3008_init(&adc, 0, 1000000) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008 ADC\n");
        return 1;
    }

    // Set up the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        return 1;
    }

    // Open the sound events log file
    FILE *log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open sound events log file\n");
        return 1;
    }

    // Set up the LED
    gpiod_t led;
    if (gpiod_init(&led, 16, GPIOD_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the ADC value
        uint16_t adc_value = mcp3008_read(&adc, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Check if the value exceeds the threshold
        if (adc_value > THRESHOLD) {
            // Turn on the LED
            gpiod_set(&led, 1);

            // Log the event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);

            // Wait for the debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Turn off the LED
            gpiod_set(&led, 0);
        }

        // Wait for the sample rate
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    gpiod_close(&led);
    fclose(log_file);
    mcp3008_close(&adc);
    gpiod_cleanup();

    return 0;
}

