#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200

static int gpio_fd;
static int log_fd;

static void handle_sigint(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(gpio_fd);
    close(log_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO file
    gpio_fd = open("/dev/gpiochip0", O_RDONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO file");
        exit(1);
    }

    // Open log file
    log_fd = open("distance_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        exit(1);
    }

    // Set up GPIO pin
    struct gpiod_line *line = gpiod_line_get(gpio_fd, GPIO_PIN, "my-consumer");
    if (!line) {
        perror("Error getting GPIO line");
        exit(1);
    }

    // Set up GPIO line as input
    if (gpiod_line_request_input(line, "my-consumer") < 0) {
        perror("Error requesting GPIO line as input");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line");
            continue;
        }

        // Log distance
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        char log_entry[100];
        sprintf(log_entry, "%s, %d\n", timestamp, value);
        write(log_fd, log_entry, strlen(log_entry));

        // Print to console
        if (value < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    close(gpio_fd);
    close(log_fd);

    return 0;
}

