#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0

#define ADC_CHANNEL 0
#define ADC_RESOLUTION 12
#define ADC_REFERENCE 3300
#define ADC_GAIN 1

#define PUMP_GPIO 17
#define PUMP_ACTIVE_HIGH true

#define THRESHOLD 20

#define LOG_FILE "soil_moisture.log"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_gpio(void) {
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
}

static void init_spi(void) {
    if (spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS, SPI_DELAY) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(1);
    }
}

static void init_adc(void) {
    if (adc_init(ADC_CHANNEL, ADC_RESOLUTION, ADC_REFERENCE, ADC_GAIN) < 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        exit(1);
    }
}

static void init_log(void) {
    if (open(LOG_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }
}

static void read_adc(void) {
    uint16_t adc_value;
    if (adc_read(ADC_CHANNEL, &adc_value) < 0) {
        fprintf(stderr, "Failed to read ADC\n");
        exit(1);
    }
