#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_DELAY 100
#define THRESHOLD 10.0
#define LED_PIN 21

static int spi_fd;
static int adc_fd;
static int log_fd;
static int led_fd;

static void sigint_handler(int signum) {
    // Close SPI connection
    spi_close(spi_fd);

    // Switch off LED
    gpio_write(led_fd, 0);

    // Terminate driver library
    pigpio_terminate();

    // Exit program
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize driver library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open SPI connection
    spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_DELAY);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI connection\n");
        return 1;
    }

    // Open ADC connection
    adc_fd = mcp3008_open(spi_fd, SPI_CHANNEL);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC connection\n");
        return 1;
    }

    // Open log file
    log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Open LED pin
    led_fd = gpio_open(LED_PIN, GPIO_OUTPUT);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to open LED pin\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = mcp3008_read(adc_fd, SPI_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Convert ADC value to magnetic field strength
        float magnetic_field = (float)adc_value / 1000.0;

        // Append timestamped reading to log file
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);
        char log_entry[50];
        snprintf(log_entry, sizeof(log_entry), "%s, %f\n", timestamp, magnetic_field);
        write(log_fd, log_entry, strlen(log_entry));

        // Turn on LED if magnetic field exceeds threshold
        if (magnetic_field > THRESHOLD) {
            gpio_write(led_fd, 1);
        } else {
            gpio_write(led_fd, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close SPI connection
    spi_close(spi_fd);

    // Close ADC connection
    mcp3008_close(adc_fd);

    // Close log file
    close(log_fd);

    // Close LED pin
    gpio_close(led_fd);

    // Terminate driver library
    pigpio_terminate();

    return 0;
}

