static int mcp3008_read(int fd, int channel, int *value) {
    int retries = 0;
    int ret;
    uint8_t cmd[MCP3008_READ_LEN];
    uint8_t data[MCP3008_READ_LEN];

    cmd[0] = MCP3008_READ_CMD;
    cmd[1] = MCP3008_READ_ADDR;
    cmd[2] = MCP3008_READ_LEN;

    while (retries < MCP3008_READ_RETRIES) {
        ret = write(fd, cmd, MCP3008_READ_LEN);
        if (ret != MCP3008_READ_LEN) {
            printf("Failed to write MCP3008 read command: %s\n", strerror(errno));
            return MCP3008_READ_ERROR;
        }

        ret = read(fd, data, MCP3008_READ_LEN);
        if (ret != MCP3008_READ_LEN) {
            printf("Failed to read MCP3008 read data: %s\n", strerror(errno));
            return MCP3008_READ_ERROR;
        }

        *value = (data[1] << 8) | data[2];
        return 0;
    }

    return MCP3008_READ_ERROR;
}

