void init_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    struct gpio_config config = {
        .direction = GPIO_DIR_OUT,
        .value = GPIO_VAL_LOW
    };

    if (ioctl(gpio_fd, GPIO_SET_CONFIG, &config) < 0) {
        perror("Failed to configure GPIO pin");
        exit(1);
    }
}

void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    struct spi_config config = {
        .mode = SPI_MODE_0,
        .bits_per_word = 8,
        .speed_hz = 1000000
    };

    if (ioctl(spi_fd, SPI_SET_CONFIG, &config) < 0) {
        perror("Failed to configure SPI device");
        exit(1);
    }
}

void init_adc() {
    adc_fd = open(SPI_DEVICE, O_RDWR);
    if (adc_fd < 0) {
        perror("Failed to open ADC device");
        exit(1);
    }

    struct adc_config config = {
        .channel = ADC_CHANNEL,
        .range = VOLTAGE_RANGE,
        .resolution = CURRENT_RESOLUTION
    };

    if (ioctl(adc_fd, ADC_SET_CONFIG, &config) < 0) {
        perror("Failed to configure ADC device");
        exit(1);
    }
}

void read_current() {
    uint16_t adc_value;
    if (read(adc_fd, &adc_value, sizeof(adc_value)) < 0) {
        perror("Failed to read ADC value");
        exit(1);
    }

    float current = (adc_value / CURRENT_RESOLUTION) * CURRENT_RANGE;
    printf("Current: %.2f A\n", current);
}

