    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char line[50];
    snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, current);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    fputs(line, fp);
    fclose(fp);
}

void cleanup() {
    close(spi_fd);
    close(gpio_fd);
    close(adc_fd);
}

void sigint_handler(int signal) {
    cleanup();
    exit(0);
}

int main() {
    init_gpio();
    init_spi();
    init_adc();

    signal(SIGINT, sigint_handler);

    while (1) {
        read_current();
        write_log(current);
        sleep(SAMPLE_RATE);
    }

    return 0;
}

