#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DELAY 100
#define VOLTAGE_MIN 0
#define VOLTAGE_MAX 5

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    int fd, spi_fd, adc_fd;
    struct spi_ioc_transfer spi_xfer;
    struct timeval tv;
    struct tm *tm;
    char buf[100];
    double voltage, current;

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open SPI bus
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open ADC device
    adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        perror("Failed to open ADC device");
        close(spi_fd);
        return 1;
    }

    // Open log file
    fd = open("current_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        close(spi_fd);
        close(adc_fd);
        return 1;
    }

    // Main loop
    while (!stop) {
        // Read ADC value
        if (ioctl(adc_fd, SPI_IOC_RD_TRANSFER, &spi_xfer) < 0) {
            perror("Failed to read ADC value");
            close(spi_fd);
            close(adc_fd);
            close(fd);
            return 1;
        }

        // Convert ADC value to voltage
        voltage = spi_xfer.rx_buf[0] * 5.0 / 255.0;

        // Check voltage range
        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            fprintf(stderr, "Voltage out of range: %f\n", voltage);
            continue;
        }

        // Convert voltage to current
        current = voltage / 1000.0;

        // Get current time
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);

        // Write to log file
        snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d %05.2f\n",
                 tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                 tm->tm_hour, tm->tm_min, tm->tm_sec, current);
        if (write(fd, buf, strlen(buf)) < 0) {
            perror("Failed to write to log file");
            close(spi_fd);
            close(adc_fd);
            close(fd);
            return 1;
        }

        // Sleep for SPI_DELAY ms
        usleep(SPI_DELAY * 1000);
    }

    // Close log file
    close(fd);

    // Close SPI bus
    close(spi_fd);

    // Close ADC device
    close(adc_fd);

    return 0;
}

