#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_DELAY 2
#define LOG_INTERVAL 1000

static bool sensor1_state = false;
static bool sensor2_state = false;

static void sigint_handler(int signum) {
    printf("Releasing GPIO resources...\n");
    gpiod_release(SENSOR1_PIN);
    gpiod_release(SENSOR2_PIN);
    exit(0);
}

static void read_sensors(void) {
    int sensor1_value = 0;
    int sensor2_value = 0;

    for (int i = 0; i < 5; i++) {
        sensor1_value = gpiod_read(SENSOR1_PIN);
        sensor2_value = gpiod_read(SENSOR2_PIN);
        usleep(DEBOUNCE_DELAY * 1000);
    }

    sensor1_state = (sensor1_value == 0);
    sensor2_state = (sensor2_value == 0);
}

int main(void) {
    signal(SIGINT, sigint_handler);

    if (gpiod_init(SENSOR1_PIN, GPIOD_INPUT) < 0) {
        printf("Error initializing GPIO %d\n", SENSOR1_PIN);
        return 1;
    }

    if (gpiod_init(SENSOR2_PIN, GPIOD_INPUT) < 0) {
        printf("Error initializing GPIO %d\n", SENSOR2_PIN);
        return 1;
    }

    while (true) {
        read_sensors();

        if (sensor1_state && sensor2_state) {
            printf("ALERT: Both sensors detect object\n");
        } else {
            printf("%d\n", sensor1_state || sensor2_state);
        }

        usleep(LOG_INTERVAL * 1000);
    }

    return 0;
}
