#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 50
#define CAPTURE_FILENAME_FORMAT "/home/pi/security_cam/%s_%s.jpg"

int main(int argc, char *argv[]) {
    // Initialize the GPIO driver
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the PIR pin as an input with a pull-down resistor
    gpiod_line_t *line = gpiod_chip_get_line(chip, PIR_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }
    gpiod_line_request_input(line, "PIR sensor");
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_INPUT, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);

    // Initialize the camera driver
    pigpio_t *pi = pigpio_start(NULL, NULL);
    if (pi == NULL) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Set up the capture directory
    char capture_dir[256];
    snprintf(capture_dir, sizeof(capture_dir), "/home/pi/security_cam");
    if (access(capture_dir, F_OK) != 0) {
        fprintf(stderr, "Capture directory does not exist\n");
        return 1;
    }

    // Set up the syslog
    openlog("security_cam", LOG_PID, LOG_USER);

    // Main loop
    while (1) {
        // Read the PIR pin
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read PIR pin\n");
            return 1;
        }

        // Debounce the value
        usleep(DEBOUNCE_DELAY * 1000);
        int value2 = gpiod_line_get_value(line);
        if (value2 < 0) {
            fprintf(stderr, "Failed to read PIR pin\n");
            return 1;
        }
        if (value != value2) {
            continue;
        }

        // If the value is high, capture an image
        if (value == 1) {
            // Construct the capture filename
            char capture_filename[256];
            snprintf(capture_filename, sizeof(capture_filename), CAPTURE_FILENAME_FORMAT, "capture", iso8601_timestamp());

            // Launch the camera capture
            int pid = fork();
            if (pid == 0) {
                char *args[] = {"libcamera-still", "-o", capture_filename, NULL};
                execvp("libcamera-still", args);
                exit(1);
            } else if (pid < 0) {
                fprintf(stderr, "Failed to fork\n");
                return 1;
            }

            // Wait for the child to exit
            int status;
            waitpid(pid, &status, 0);
            if (status != 0) {
                fprintf(stderr, "Capture failed\n");
                return 1;
            }

            // Log the capture
            syslog(LOG_INFO, "Captured image %s", capture_filename);
        }

        // Sleep for the capture delay
        usleep(CAPTURE_DELAY * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    pigpio_stop(pi);
    closelog();

    return 0;
}

char *iso8601_timestamp() {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char *timestamp = malloc(20);
    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm);
    return timestamp;
}

