#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"

#define BUFFER_SIZE 1024 * 1024
#define FRAME_SIZE 1920 * 1080 * 3

int main(int argc, char **argv) {
    int fd, fd_log;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct timeval tv;
    char *buffer;
    char *log_buffer;
    int ret;

    // Open video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    // Query device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query device capabilities");
        return 1;
    }

    // Set video format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set video format");
        return 1;
    }

    // Request buffers
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Failed to request buffers");
        return 1;
    }

    // Map buffers
    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffers");
        return 1;
    }

    // Open log file
    fd_log = open(FRAME_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd_log < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up select()
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    // Main loop
    while (1) {
        // Wait for frame
        ret = select(fd + 1, &fds, NULL, NULL, NULL);
        if (ret < 0) {
            perror("Failed to wait for frame");
            return 1;
        }

        // Read frame
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;
        buf.length = FRAME_SIZE;
        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            perror("Failed to read frame");
            return 1;
        }

        // Write frame to log file
        gettimeofday(&tv, NULL);
        log_buffer = buffer + buf.bytesused;
        snprintf(log_buffer, BUFFER_SIZE - buf.bytesused, "%ld.%ld\n", tv.tv_sec, tv.tv_usec);
        ret = write(fd_log, log_buffer, strlen(log_buffer));
        if (ret < 0) {
            perror("Failed to write to log file");
            return 1;
        }

        // Queue buffer for reuse
        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("Failed to queue buffer for reuse");
            return 1;
        }
    }

    // Clean up
    munmap(buffer, BUFFER_SIZE);
    close(fd);
    close(fd_log);

    return 0;
}

