#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define BUFFER_COUNT 4
#define BUFFER_SIZE 65536
#define FRAME_HEADER_SIZE 12
#define FRAGMENT_SIZE 65000

int main(int argc, char *argv[]) {
    // Check command line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target IP> <target port>\n", argv[0]);
        return 1;
    }

    // Open the CSI camera
    int fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Configure the camera
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("ioctl");
        return 1;
    }

    struct v4l2_format fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("ioctl");
        return 1;
    }

    // Allocate buffers
    void *buffers[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; i++) {
        buffers[i] = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, i);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            return 1;
        }
    }

    // Create a UDP socket
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("socket");
        return 1;
    }

    // Set the target IP and port
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(atoi(argv[2]));
    if (inet_pton(AF_INET, argv[1], &addr.sin_addr) != 1) {
        perror("inet_pton");
        return 1;
    }

    // Set the socket options
    int optval = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval)) == -1) {
        perror("setsockopt");
        return 1;
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &fmt) == -1) {
        perror("ioctl");
        return 1;
    }

    // Main loop
    while (1) {
        // Read a frame
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("ioctl");
            return 1;
        }

        // Fragment the frame
        int frame_index = buf.index;
        int fragment_index = 0;
        int total_fragments = (buf.bytesused + FRAGMENT_SIZE - 1) / FRAGMENT_SIZE;
        for (int i = 0; i < total_fragments; i++) {
            // Create a UDP datagram
            char *data = buffers[buf.index] + i * FRAGMENT_SIZE;
            int size = FRAGMENT_SIZE;
            if (i == total_fragments - 1) {
                size = buf.bytesused - i * FRAGMENT_SIZE;
            }

            // Prepend the header
            char header[FRAME_HEADER_SIZE];
            header[0] = frame_index;
            header[1] = fragment_index;
            header[2] = total_fragments;
            header[3] = size;
            memcpy(data - FRAME_HEADER_SIZE, header, FRAME_HEADER_SIZE);

            // Send the datagram
            if (sendto(sock, data - FRAME_HEADER_SIZE, size + FRAME_HEADER_SIZE, 0, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
                perror("sendto");
                return 1;
            }

            fragment_index++;
        }

        // Release the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("ioctl");
            return 1;
        }
    }

    // Clean up
    close(sock);
    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buffers[i], BUFFER_SIZE);
    }
    close(fd);

    return 0;
}

