            exit(1);
        }
        buffers[i].start = mmap(NULL, req.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (buffers[i].start == MAP_FAILED) {
            perror("Failed to map buffer");
            exit(1);
        }
        buffers[i].length = req.length;
    }

