#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MID 75

#define PAN_STEP 5
#define TILT_STEP 5

#define BUTTON_DEBOUNCE_TIME 50

static volatile bool running = true;

static void handle_signal(int signal) {
    running = false;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(PAN_SERVO_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", PAN_SERVO_GPIO);
        exit(1);
    }

    if (gpioSetMode(TILT_SERVO_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", TILT_SERVO_GPIO);
        exit(1);
    }

    if (gpioSetMode(TILT_UP_BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", TILT_UP_BUTTON_GPIO);
        exit(1);
    }

    if (gpioSetMode(TILT_DOWN_BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", TILT_DOWN_BUTTON_GPIO);
        exit(1);
    }

    if (gpioSetMode(PAN_LEFT_BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", PAN_LEFT_BUTTON_GPIO);
        exit(1);
    }

    if (gpioSetMode(PAN_RIGHT_BUTTON_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", PAN_RIGHT_BUTTON_GPIO);
        exit(1);
    }
}

static void set_pwm_duty(int gpio, int duty) {
    if (gpioPWM(gpio, PWM_PERIOD, duty) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        exit(1);
    }
}

static void set_servo_position(int gpio, int position) {
    int duty = (position * 1000) / 125;
    set_pwm_duty(gpio, duty);
}

static void handle_button_press(int gpio, int step) {
    int position = gpioRead(gpio);
    position += step;
    if (position < 25) {
        position = 25;
    } else if (position > 125) {
        position = 125;
    }
    set_servo_position(gpio, position);
}

static void handle_button_release(int gpio) {
    set_servo_position(gpio, PWM_DUTY_MID);
}

static void handle_button_presses(void) {
    int tilt_up_button = gpioRead(TILT_UP_BUTTON_GPIO);
    int tilt_down_button = gpioRead(TILT_DOWN_BUTTON_GPIO);
    int pan_left_button = gpioRead(PAN_LEFT_BUTTON_GPIO);
    int pan_right_button = gpioRead(PAN_RIGHT_BUTTON_GPIO);

    if (tilt_up_button == 0) {
        handle_button_press(TILT_SERVO_GPIO, TILT_STEP);
    } else if (tilt_down_button == 0) {
        handle_button_press(TILT_SERVO_GPIO, -TILT_STEP);
    } else if (pan_left_button == 0) {
        handle_button_press(PAN_SERVO_GPIO, -PAN_STEP);
    } else if (pan_right_button == 0) {
        handle_button_press(PAN_SERVO_GPIO, PAN_STEP);
    }
}

int main(void) {
    signal(SIGINT, handle_signal);

    init_gpio();

    set_servo_position(PAN_SERVO_GPIO, PWM_DUTY_MID);
    set_servo_position(TILT_SERVO_GPIO, PWM_DUTY_MID);

    while (running) {
        handle_button_presses();
        usleep(BUTTON_DEBOUNCE_TIME * 1000);
    }

    gpioTerminate();

    return 0;
}

