#include <pigpio/pigpio.h>

#define CAMERA_DEVICE "/dev/video0"
#define BUFFER_SIZE 1024 * 1024
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2)
#define JPEG_QUALITY 75

int main(int argc, char **argv) {
  // Open the camera device
  int camera_fd = open(CAMERA_DEVICE, O_RDWR);
  if (camera_fd < 0) {
    fprintf(stderr, "Error opening camera device: %s\n", strerror(errno));
    return 1;
  }

  // Request buffers
  struct v4l2_requestbuffers req = {
    .count = 1,
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
  };
  if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
    fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
    close(camera_fd);
    return 1;
  }

  // Memory-map the buffer
  struct v4l2_buffer buf = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
    .index = 0,
  };
  if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
    fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
    close(camera_fd);
    return 1;
  }
  void *buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, 0);
  if (buffer == MAP_FAILED) {
    fprintf(stderr, "Error memory-mapping buffer: %s\n", strerror(errno));
    close(camera_fd);
    return 1;
  }

