#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    // Query the device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return 1;
    }

    // Enumerate all supported frame sizes
    frmsize.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("Frame size: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);

        // Enumerate all available frame intervals for this size
        frmival.index = 0;
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            printf("  Frame interval: %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
            frmival.index++;
        }

        frmsize.index++;
    }

    // Query the V4L2_CID_FOCUS_AUTO control
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) < 0) {
        perror("Error querying focus auto control");
        close(fd);
        return 1;
    }

    // Print a summary of the resolutions, frame rates, and autofocus capability
    printf("Resolutions:\n");
    for (int i = 0; i < frmsize.index; i++) {
        printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
    }
    printf("Frame rates:\n");
    for (int i = 0; i < frmival.index; i++) {
        printf("  %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
    }
    printf("Autofocus: %s\n", queryctrl.value ? "supported" : "not supported");

    close(fd);
    return 0;
}

