#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

#define PWM_FREQ 50
#define PWM_PERIOD 20000

#define PWM_INCREMENT 10

#define BUTTON_DEBOUNCE_TIME 50

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static void setup_pwm(void) {
    if (gpioPWM(PAN_SERVO_PIN, PWM_FREQ, CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set PWM for pan servo\n");
        exit(1);
    }

    if (gpioPWM(TILT_SERVO_PIN, PWM_FREQ, CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set PWM for tilt servo\n");
        exit(1);
    }
}

static void cleanup_pwm(void) {
    gpioPWM(PAN_SERVO_PIN, 0, 0);
    gpioPWM(TILT_SERVO_PIN, 0, 0);
}

static void handle_button_press(int pin, int pulse_width) {
    if (gpioRead(pin) == PI_LOW) {
        gpioPWM(pin, PWM_FREQ, pulse_width);
        usleep(BUTTON_DEBOUNCE_TIME * 1000);
        gpioPWM(pin, PWM_FREQ, CENTER_PULSE_WIDTH);
    }
}

int main(void) {
    setup_gpio();
    setup_pwm();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    printf("Pan servo on GPIO %d, tilt servo on GPIO %d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("UP button on GPIO %d, DOWN button on GPIO %d, LEFT button on GPIO %d, RIGHT button on GPIO %d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);

    while (running) {
        handle_button_press(UP_BUTTON_PIN, CENTER_PULSE_WIDTH + PWM_INCREMENT);
        handle_button_press(DOWN_BUTTON_PIN, CENTER_PULSE_WIDTH - PWM_INCREMENT);
        handle_button_press(LEFT_BUTTON_PIN, CENTER_PULSE_WIDTH - PWM_INCREMENT);
        handle_button_press(RIGHT_BUTTON_PIN, CENTER_PULSE_WIDTH + PWM_INCREMENT);

        usleep(PWM_PERIOD * 1000);
    }

    cleanup_pwm();
    cleanup_gpio();

    return 0;
}

