struct motion_data {
    int pin;
    int status;
    char *timestamp;
    char *filename;
};

struct http_data {
    int sock;
    struct sockaddr_in addr;
    char *buf;
};

void init_gpio(void) {
    int ret;
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        exit(1);
    }
}

void init_http(struct http_data *http) {
    int ret;
    http->sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http->sock < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        exit(1);
    }
    http->addr.sin_family = AF_INET;
    http->addr.sin_port = htons(HTTP_PORT);
    http->addr.sin_addr.s_addr = inet_addr("127.0.0.1");
    ret = connect(http->sock, (struct sockaddr *)&http->addr, sizeof(http->addr));
    if (ret < 0) {
        fprintf(stderr, "Error connecting to server: %s\n", strerror(errno));
        exit(1);
    }
    http->buf = malloc(HTTP_BUF_SIZE);
    if (http->buf == NULL) {
        fprintf(stderr, "Error allocating memory for HTTP buffer: %s\n", strerror(errno));
        exit(1);
    }
}

void cleanup_gpio(void) {
    gpiod_cleanup();
}

void cleanup_http(struct http_data *http) {
    close(http->sock);
    free(http->buf);
}

void capture_motion(struct motion_data *motion) {
    int ret;
    struct timeval tv;
    struct tm *tm;
    char filename[256];
    char *timestamp;
    char *status;
    char *pin;
    char *json;
    FILE *fp;
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row_pointer[1];
    int row_stride;

    // Capture timestamp
    gettimeofday(&tv, NULL);
    tm = localtime(&tv.tv_sec);
    timestamp = asctime(tm);

    // Capture filename
    snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", timestamp);

    // Capture image
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        exit(1);
    }
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, fp);
    cinfo.image_width = 640;
    cinfo.image_height = 480;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 85, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    row_stride = cinfo.image_width * cinfo.input_components;
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image_data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
