#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 50
#define CAPTURE_TIMEOUT 2000
#define CAPTURE_OPTIONS "-o /home/pi/images/%Y%m%d_%H%M%S_%L.jpg -w 640 -h 480 -q 85 --timeout 2000 --nopreview"

static int gpio_fd;
static int capture_fd;

static void handle_sigint(int signum) {
    printf("Received SIGINT, releasing GPIO resources and closing file descriptors\n");
    gpio_close(gpio_fd);
    close(capture_fd);
    exit(0);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, releasing GPIO resources and closing file descriptors\n");
    gpio_close(gpio_fd);
    close(capture_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open GPIO chip
    gpio_fd = gpio_open(GPIO_PIN, GPIO_INPUT);
    if (gpio_fd < 0) {
        printf("Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pin as input with edge-falling detection
    if (gpio_set_direction(gpio_fd, GPIO_INPUT) < 0) {
        printf("Error setting GPIO direction: %s\n", strerror(errno));
        return 1;
    }
    if (gpio_set_edge(gpio_fd, GPIO_EDGE_FALLING) < 0) {
        printf("Error setting GPIO edge: %s\n", strerror(errno));
        return 1;
    }

    // Open capture command
    capture_fd = popen("raspistill -o /home/pi/images/%Y%m%d_%H%M%S_%L.jpg -w 640 -h 480 -q 85 --timeout 2000 --nopreview", "r");
    if (capture_fd < 0) {
        printf("Error opening capture command: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for GPIO edge
        int edge = gpio_wait_edge(gpio_fd, GPIO_EDGE_FALLING, DEBOUNCE_TIME);
        if (edge < 0) {
            printf("Error waiting for GPIO edge: %s\n", strerror(errno));
            return 1;
        }

        // Capture image
        int ret = pclose(capture_fd);
        if (ret < 0) {
            printf("Error capturing image: %s\n", strerror(errno));
            return 1;
        }

        // Log capture result
        if (ret == 0) {
            printf("Captured image successfully\n");
        } else {
            printf("Error capturing image: %s\n", strerror(errno));
        }
    }

    // Clean up
    gpio_close(gpio_fd);
    close(capture_fd);
    return 0;
}

