#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define CAMERA_PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define CAMERA_FIELD_TYPE V4L2_FIELD_NONE
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    // Clean up resources
    if (munmap(buffer, buffer_size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
    if (close(fd) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }
    if (fclose(fp) == EOF) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
    free(buffer);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open camera device
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Query camera capabilities
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Camera does not support video capture\n");
        exit(EXIT_FAILURE);
    }

    // Configure camera capture
    struct v4l2_format fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = CAMERA_WIDTH;
    fmt.fmt.pix.height = CAMERA_HEIGHT;
    fmt.fmt.pix.pixelformat = CAMERA_PIXEL_FORMAT;
    fmt.fmt.pix.field = CAMERA_FIELD_TYPE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Request a single memory-mapped buffer
    struct v4l2_requestbuffers req;
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &req) == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Wait for a frame
    struct timeval timeout;
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    if (select(fd + 1, &fds, NULL, NULL, &timeout) == -1) {
        perror("select");
        exit(EXIT_FAILURE);
    }

    // Check for a frame
    if (FD_ISSET(fd, &fds)) {
        // Read frame
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("ioctl");
            exit(EXIT_FAILURE);
        }

        // Check frame size and pixel format
        if (buf.bytesused != CAMERA_WIDTH * CAMERA_HEIGHT * 2) {
            fprintf(stderr, "Invalid frame size: %d\n", buf.bytesused);
            exit(EXIT_FAILURE);
        }
        if (buf.fmt.pix.pixelformat != CAMERA_PIXEL_FORMAT) {
            fprintf(stderr, "Invalid pixel format: %d\n", buf.fmt.pix.pixelformat);
            exit(EXIT_FAILURE);
        }

        // Crop frame
        unsigned char *buffer = mmap(NULL, buf.bytesused, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        if (buffer == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        unsigned char *cropped_buffer = buffer + (CAMERA_WIDTH * CROP_HEIGHT + CROP_WIDTH) * 2;
        memcpy(cropped_buffer, buffer, CROP_WIDTH * CROP_HEIGHT * 2);

        // Write cropped frame to file
        FILE *fp = fopen("cropped.yuv", "wb");
        if (fp == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        if (fwrite(cropped_buffer, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp) != CROP_WIDTH * CROP_HEIGHT * 2) {
            perror("fwrite");
            exit(EXIT_FAILURE);
        }
        if (fclose(fp) == EOF) {
            perror("fclose");
            exit(EXIT_FAILURE);
        }

        // Release resources
        if (munmap(buffer, buf.bytesused) == -1) {
            perror("munmap");
            exit(EXIT_FAILURE);
        }
        if (close(fd) == -1) {
            perror("close");
            exit(EXIT_FAILURE);
        }
        free(buffer);
    } else {
        fprintf(stderr, "Timeout waiting for frame\n");
        exit(EXIT_FAILURE);
    }

    return EXIT_SUCCESS;
}

