#include <pigpio/pigpio.h>

#define PAN_SERVO_GPIO 17
#define TILT_SERVO_GPIO 18
#define PWM_FREQ 50
#define PWM_RES 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 1000
#define PWM_DUTY_STEP 5
#define PWM_DUTY_NEUTRAL 90
#define PWM_DUTY_MIN_ERROR "Angle out of range (min)"
#define PWM_DUTY_MAX_ERROR "Angle out of range (max)"
#define PWM_DUTY_STEP_ERROR "Angle out of range (step)"

int main(int argc, char *argv[]) {
    // Initialize the GPIO driver
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Initialize the PWM driver
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM driver\n");
        return 1;
    }

    // Set up the PWM channels
    int pan_servo_channel = pigpio_pwm_allocate_channel(PAN_SERVO_GPIO);
    int tilt_servo_channel = pigpio_pwm_allocate_channel(TILT_SERVO_GPIO);

    // Set the PWM frequency and resolution
    pigpio_pwm_set_frequency(pan_servo_channel, PWM_FREQ);
    pigpio_pwm_set_resolution(pan_servo_channel, PWM_RES);
    pigpio_pwm_set_frequency(tilt_servo_channel, PWM_FREQ);
    pigpio_pwm_set_resolution(tilt_servo_channel, PWM_RES);

    // Set the PWM duty cycle to neutral
    pigpio_pwm_set_duty_cycle(pan_servo_channel, PWM_DUTY_NEUTRAL);
    pigpio_pwm_set_duty_cycle(tilt_servo_channel, PWM_DUTY_NEUTRAL);

    // Set up the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the input from stdin
        char input = getchar();

        // Check for the 'q' character
        if (input == 'q') {
            break;
        }

        // Check for arrow key presses
        if (input == 'w') {
            // Pan up
            int pan_duty_cycle = pigpio_pwm_get_duty_cycle(pan_servo_channel) + PWM_DUTY_STEP;
            if (pan_duty_cycle > PWM_DUTY_MAX) {
                fprintf(stderr, PWM_DUTY_MAX_ERROR);
                break;
            }
            pigpio_pwm_set_duty_cycle(pan_servo_channel, pan_duty_cycle);
        } else if (input == 's') {
            // Pan down
            int pan_duty_cycle = pigpio_pwm_get_duty_cycle(pan_servo_channel) - PWM_DUTY_STEP;
            if (pan_duty_cycle < PWM_DUTY_MIN) {
                fprintf(stderr, PWM_DUTY_MIN_ERROR);
                break;
            }
            pigpio_pwm_set_duty_cycle(pan_servo_channel, pan_duty_cycle);
        } else if (input == 'a') {
            // Tilt left
            int tilt_duty_cycle = pigpio_pwm_get_duty_cycle(tilt_servo_channel) + PWM_DUTY_STEP;
            if (tilt_duty_cycle > PWM_DUTY_MAX) {
                fprintf(stderr, PWM_DUTY_MAX_ERROR);
                break;
            }
            pigpio_pwm_set_duty_cycle(tilt_servo_channel, tilt_duty_cycle);
        } else if (input == 'd') {
            // Tilt right
            int tilt_duty_cycle = pigpio_pwm_get_duty_cycle(tilt_servo_channel) - PWM_DUTY_STEP;
            if (tilt_duty_cycle < PWM_DUTY_MIN) {
                fprintf(stderr, PWM_DUTY_MIN_ERROR);
                break;
            }
            pigpio_pwm_set_duty_cycle(tilt_servo_channel, tilt_duty_cycle);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_pwm_free_channel(pan_servo_channel);
    pigpio_pwm_free_channel(tilt_servo_channel);
    pigpio_close();
    gpiod_close();

    return 0;
}

void signal_handler(int signal) {
    // Set the PWM duty cycle to neutral
    pigpio_pwm_set_duty_cycle(pan_servo_channel, PWM_DUTY_NEUTRAL);
    pigpio_pwm_set_duty_cycle(tilt_servo_channel, PWM_DUTY_NEUTRAL);

    // Clean up
    pigpio_pwm_free_channel(pan_servo_channel);
    pigpio_pwm_free_channel(tilt_servo_channel);
    pigpio_close();
    gpiod_close();

    exit(0);
}

