#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <mcp3008.h>
#include <pcf8574.h>
#include <lcd.h>

#define GPIO_ANEMOMETER 17
#define GPIO_WIND_VANE 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define I2C_ADDR 0x40
#define I2C_SPEED 100000
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

#define WIND_SPEED_SAMPLE_WINDOW 500
#define WIND_SPEED_SAMPLE_COUNT 10
#define WIND_SPEED_SAMPLE_INTERVAL 50

#define WIND_DIRECTION_SAMPLE_WINDOW 500
#define WIND_DIRECTION_SAMPLE_COUNT 10
#define WIND_DIRECTION_SAMPLE_INTERVAL 50

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signum) {
    g_running = 0;
}

static void sigterm_handler(int signum) {
    g_running = 0;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_ANEMOMETER, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_ANEMOMETER);
        exit(1);
    }

    if (gpioSetISRFunc(GPIO_ANEMOMETER, RISING_EDGE, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO %d ISR function\n", GPIO_ANEMOMETER);
        exit(1);
    }
}

static void init_spi(void) {
    if (spiOpen(SPI_DEVICE, SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        exit(1);
    }
}

static void init_i2c(void) {
    if (i2cOpen(I2C_DEVICE, I2C_ADDR, I2C_SPEED) < 0) {
        fprintf(stderr, "Failed to open I2C device %s\n", I2C_DEVICE);
        exit(1);
    }
}

static void init_lcd(void) {
    if (lcdInit(LCD_ADDR, LCD_WIDTH, LCD_HEIGHT) < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        exit(1);
    }
}

static void read_wind_speed(void) {
    int count = 0;
    int pulse_count = 0;
    int pulse_time = 0;
    int wind_speed = 0;

    while (count < WIND_SPEED_SAMPLE_COUNT) {
        pulse_count = gpioPulseIn(GPIO_ANEMOMETER, PI_INPUT, WIND_SPEED_SAMPLE_WINDOW);
        pulse_time = gpioPulseIn(GPIO_ANEMOMETER, PI_INPUT, WIND_SPEED_SAMPLE_WINDOW);
        wind_speed = (pulse_count * 1000) / pulse_time;
        count++;
    }

    wind_speed /= WIND_SPEED_SAMPLE_COUNT;

    printf("Wind speed: %d km/h\n", wind_speed);
}

static void read_wind_direction(void) {
    int count = 0;
    int wind_direction = 0;

    while (count < WIND_DIRECTION_SAMPLE_COUNT) {
        wind_direction = mcp3008Read(SPI_CHANNEL, SPI_SPEED, I2C_ADDR, I2C_SPEED, GPIO_WIND_VANE);
        count++;
    }

    wind_direction /= WIND_DIRECTION_SAMPLE_COUNT;

    printf("Wind direction: %d\n", wind_direction);
}

static void update_lcd(void) {
    char buf[16];

    snprintf(buf, sizeof(buf), "Wind speed: %d km/h", wind_speed);
    lcdPrintf(buf);

    snprintf(buf, sizeof(buf), "Wind direction: %d", wind_direction);
    lcdPrintf(buf);
}

int main(void) {
    init_gpio();
    init_spi();
    init_i2c();
    init_lcd();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (g_running) {
        read_wind_speed();
        read_wind_direction();
        update_lcd();
        usleep(WIND_SPEED_SAMPLE_INTERVAL);
    }

    spiClose(SPI_DEVICE);
    i2cClose(I2C_DEVICE);
    lcdClose();

    return 0;
}

