#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8

#define ROW_ANODES {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_CATHODES {14, 15, 18, 23, 24, 25, 8, 7}

#define ROW_ANODE_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_CATHODE_PINS {14, 15, 18, 23, 24, 25, 8, 7}

#define ROW_ANODE_VALUES {0, 0, 0, 0, 0, 0, 0, 0}
#define COL_CATHODE_VALUES {1, 1, 1, 1, 1, 1, 1, 1}

#define DELAY_MS 150

int main(void) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the row anodes and column cathodes as outputs
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_request_output(chip, ROW_ANODE_PINS[i], "row_anode", 0);
        gpiod_line_request_output(chip, COL_CATHODE_PINS[i], "col_cathode", 0);
    }

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_set_value(chip, COL_CATHODE_PINS[i], 1);
        }
        for (int i = 0; i < NUM_ROWS; i++) {
            gpiod_line_set_value(chip, ROW_ANODE_PINS[i], 0);
        }

        // Scan the columns left to right
        for (int col = 0; col < NUM_COLS; col++) {
            // Set the column cathode LOW and light the LEDs sequentially by setting the corresponding row anodes HIGH
            gpiod_line_set_value(chip, COL_CATHODE_PINS[col], 0);
            for (int row = 0; row < NUM_ROWS; row++) {
                gpiod_line_set_value(chip, ROW_ANODE_PINS[row], 1);
                usleep(DELAY_MS * 1000);
                gpiod_line_set_value(chip, ROW_ANODE_PINS[row], 0);
            }

            // Set the column cathode HIGH again
            gpiod_line_set_value(chip, COL_CATHODE_PINS[col], 1);
        }
    }

    // Clean up on exit
    gpiod_chip_close(chip);
    return 0;
}

void signal_handler(int signum) {
    // Clean up on SIGINT or SIGTERM
    gpiod_chip_close(chip);
    exit(0);
}

