#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define I2C_BUS 1
#define MLX75031_ADDR 0x5A
#define MLX75031_REG_DISTANCE 0x00
#define MLX75031_REG_STATUS 0x01
#define MLX75031_STATUS_RDY 0x01

#define DEPTH_LOG_FILE "depth_log.csv"

int i2c_fd;
int log_fd;

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        close(i2c_fd);
        close(log_fd);
        exit(0);
    }
}

int main(void) {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Open log file
    log_fd = open(DEPTH_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(1);
    }

    // Write CSV header row if file is new
    if (lseek(log_fd, 0, SEEK_END) == 0) {
        char header[] = "timestamp,distance\n";
        write(log_fd, header, sizeof(header));
    }

    // Main loop
    while (1) {
        // Read distance data from sensor
        uint8_t status;
        uint16_t distance;
        if (read(i2c_fd, &status, 1) != 1 || read(i2c_fd, &distance, 2) != 2) {
            perror("Failed to read distance data");
            close(i2c_fd);
            close(log_fd);
            exit(1);
        }

        // Check if sensor is ready
        if ((status & MLX75031_STATUS_RDY) == 0) {
            printf("Sensor not ready, skipping sample\n");
            continue;
        }

        // Write distance data to log file
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "%ld,%d\n", time(NULL), distance);
        write(log_fd, buffer, strlen(buffer));
    }

    // Graceful shutdown
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

