    struct gpiod_chip *chip = gpiod_chip_open_by_name(NULL);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the GPIO lines
    struct gpiod_line *proximity_sensor = gpiod_chip_get_line(chip, PROXIMITY_SENSOR_PIN);
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!proximity_sensor || !led) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the log file
    int log_fd = open("proximity.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the proximity sensor
        int value = gpiod_line_get_value(proximity_sensor);
        if (value < 0) {
            fprintf(stderr, "Failed to read proximity sensor\n");
            return 1;
        }

        // Check for a falling edge
        if (value == 0 && gpiod_line_get_value(proximity_sensor, GPIOD_LINE_EVENT_FALLING_EDGE) == 1) {
            // Get the current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Write the timestamp to the log file
            char buf[100];
            strftime(buf, sizeof(buf), "%FT%TZ", gmtime(&ts.tv_sec));
            dprintf(log_fd, "%s Object detected\n", buf);

            // Blink the LED
            gpiod_line_set_value(led, 1);
            usleep(100000);
            gpiod_line_set_value(led, 0);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(log_fd);
    gpiod_line_release(proximity_sensor);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

