#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_PULSE_WIDTH 10
#define ECHO_TIMEOUT 30
#define DISTANCE_RANGE 200
#define LOG_FILE "distance_log.txt"

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }

    // Set up trigger line
    gpiod_line_request_output(trigger_line, "trigger", 0);
    gpiod_line_set_value(trigger_line, 0);

    // Set up echo line
    gpiod_line_request_input(echo_line, "echo");

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_WIDTH);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rise
        struct timespec timeout = {.tv_sec = 0, .tv_nsec = ECHO_TIMEOUT * 1000000};
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &timeout) < 0) {
            fprintf(stderr, "Failed to wait for echo rise\n");
            continue;
        }

        // Wait for echo pulse width
        timeout.tv_sec = 0;
        timeout.tv_nsec = ECHO_TIMEOUT * 1000000;
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &timeout) < 0) {
            fprintf(stderr, "Failed to wait for echo pulse width\n");
            continue;
        }

        // Read echo pulse width
        struct gpiod_line_event event;
        if (gpiod_line_event_read(echo_line, &event) < 0) {
            fprintf(stderr, "Failed to read echo pulse width\n");
            continue;
        }

        // Compute distance
        double distance = (event.ts.tv_sec * 1000000 + event.ts.tv_nsec / 1000) / 58.0;

        // Check distance range
        if (distance < 2 || distance > DISTANCE_RANGE) {
            fprintf(stderr, "Distance out of range: %f\n", distance);
            continue;
        }

        // Log distance
        char buf[128];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(buf, sizeof(buf), "%FT%T%z", tm);
        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " %f\n", distance);
        write(log_fd, buf, strlen(buf));

        // Check if time to water the plant
        if (distance < 15) {
            write(log_fd, "Time to water the plant!\n", 22);
        }
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    close(log_fd);
    gpiod_chip_close(chip);

    return 0;
}

