#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x20
#define PROX_DATA_REG 0x00
#define PROX_THRESH_REG 0x01
#define PROX_COUNT_REG 0x02
#define PROX_INTERVAL_REG 0x03
#define PROX_CONFIG_REG 0x04

#define PROX_THRESH 0x01
#define PROX_COUNT 0x01
#define PROX_INTERVAL 0x01
#define PROX_CONFIG 0x01

#define BPM_CONST 60

volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    int i2c_fd;
    int csv_fd;
    char csv_path[256];
    char timestamp[256];
    uint8_t prox_data;
    uint8_t prox_thresh;
    uint8_t prox_count;
    uint8_t prox_interval;
    uint8_t prox_config;
    int bpm;

    // Initialize I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize CSV file
    strcpy(csv_path, "heartrate.csv");
    csv_fd = open(csv_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Set SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize I2C device
    if (i2c_smbus_write_byte_data(i2c_fd, PROX_THRESH_REG, PROX_THRESH) < 0) {
        perror("Failed to write to I2C device");
        return 1;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, PROX_COUNT_REG, PROX_COUNT) < 0) {
        perror("Failed to write to I2C device");
        return 1;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, PROX_INTERVAL_REG, PROX_INTERVAL) < 0) {
        perror("Failed to write to I2C device");
        return 1;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, PROX_CONFIG_REG, PROX_CONFIG) < 0) {
        perror("Failed to write to I2C device");
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        if (i2c_smbus_read_byte_data(i2c_fd, PROX_DATA_REG) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        // Calculate heart rate
        bpm = BPM_CONST / prox_data;

        // Write to CSV file
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&time));
        fprintf(csv_fd, "%s,%d\n", timestamp, bpm);
        fflush(csv_fd);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    close(csv_fd);

    return 0;
}
