#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define SAMPLE_INTERVAL 200
#define TIMESTAMP_BUF_SIZE 20

static volatile sig_atomic_t stop_sampling = 0;

void sigint_handler(int signum) {
    stop_sampling = 1;
}

int main(void) {
    int i2c_fd, trigger_fd, echo_fd;
    char timestamp_buf[TIMESTAMP_BUF_SIZE];
    struct tm *tm;
    time_t t;
    int distance;

    // Initialize the driver
    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Open the trigger pin
    trigger_fd = gpiod_open_chip("gpiochip0");
    if (trigger_fd < 0) {
        fprintf(stderr, "Failed to open trigger pin\n");
        return 1;
    }

    // Open the echo pin
    echo_fd = gpiod_open_chip("gpiochip0");
    if (echo_fd < 0) {
        fprintf(stderr, "Failed to open echo pin\n");
        return 1;
    }

    // Set the trigger pin as output
    if (gpiod_set_direction(trigger_fd, TRIGGER_PIN, GPIOD_OUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        return 1;
    }

    // Set the echo pin as input
