#define LOG_INTERVAL 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Set up GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    if (line1 == NULL) {
        fprintf(stderr, "Error: unable to get GPIO line for sensor 1\n");
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *line2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (line2 == NULL) {
        fprintf(stderr, "Error: unable to get GPIO line for sensor 2\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up logging file
    int fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd == -1) {
        fprintf(stderr, "Error: unable to open log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int value1 = gpiod_line_get_value(line1);
        if (value1 == -1) {
            fprintf(stderr, "Error: unable to read sensor 1 value\n");
            continue;
        }

        int value2 = gpiod_line_get_value(line2);
        if (value2 == -1) {
            fprintf(stderr, "Error: unable to read sensor 2 value\n");
            continue;
        }

        // Log values
        char buf[100];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
        snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " %d %d\n", value1, value2);
        write(fd, buf, strlen(buf));

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    close(fd);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

