#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>
#include <i2c/i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 17

#define TIMEOUT_MS 100
#define DISTANCE_THRESHOLD 20

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void log_distance(int distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%LZ", gmtime(&tv.tv_sec));
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s,%d\n", timestamp, distance);
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fputs(log_entry, fp);
    fclose(fp);
}

static void set_led(bool on) {
    int gpio_fd = gpiod_open(GPIO_PIN, "led", GPIOD_OUT);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }
    gpiod_set_value(gpio_fd, on);
    gpiod_close(gpio_fd);
}

static int read_distance() {
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }
    uint8_t cmd = 0x00;
    uint8_t data[2];
    int ret = i2c_write(i2c_fd, &cmd, 1);
    if (ret < 0) {
        perror("i2c_write");
        exit(EXIT_FAILURE);
    }
    ret = i2c_read(i2c_fd, data, 2);
    if (ret < 0) {
        perror("i2c_read");
        exit(EXIT_FAILURE);
    }
    int distance = (data[0] << 8) | data[1];
    i2c_close(i2c_fd);
    return distance;
}

int main() {
    setup_signal_handlers();
    int gpio_fd = gpiod_open(GPIO_PIN, "led", GPIOD_OUT);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE, 0);
    if (i2c_fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }
    while (running) {
        int distance = read_distance();
        log_distance(distance);
        set_led(distance < DISTANCE_THRESHOLD);
        usleep(TIMEOUT_MS * 1000);
    }
    gpiod_close(gpio_fd);
    i2c_close(i2c_fd);
    return 0;
}

