#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define WHO_AM_I_REG 0x00
#define DISTANCE_REG 0x02
#define LED_PIN 17
#define THRESHOLD 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_gpio(void) {
    int fd;
    char buf[1];

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    snprintf(buf, sizeof(buf), "%d", LED_PIN);
    write(fd, buf, strlen(buf));
    close(fd);

    fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    write(fd, "out", 3);
    close(fd);
}

static void init_i2c(void) {
    int fd;
    char buf[1];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

    if (read(fd, buf, 1) < 0) {
        perror("read");
        exit(1);
    }

    if (buf[0] != WHO_AM_I_REG) {
        fprintf(stderr, "Invalid WHO_AM_I register value: %02x\n", buf[0]);
        exit(1);
    }
}

static void read_distance(void) {
    int fd;
    uint8_t buf[2];
    uint16_t distance;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

    if (read(fd, buf, 2) < 0) {
        perror("read");
        exit(1);
    }

    distance = (buf[0] << 8) | buf[1];
    printf("Distance: %d mm\n", distance);

    if (distance < THRESHOLD) {
        printf("Distance below threshold: %d mm\n", distance);
        write(LED_PIN, "1", 1);
    } else {
        write(LED_PIN, "0", 1);
    }
}

static void log_reading(void) {
    struct timeval tv;
    char buf[100];
    FILE *fp;

    gettimeofday(&tv, NULL);
    snprintf(buf, sizeof(buf), "%ld.%06ld\t%d\n", tv.tv_sec, tv.tv_usec, distance);

    fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }

    fprintf(fp, buf);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int fd;
    uint16_t distance;
    struct sigaction sa;

    if (argc > 1) {
        THRESHOLD = atoi(argv[1]);
    }

    init_gpio();
    init_i2c();

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        read_distance();
        log_reading();
        usleep(50000);
    }

    close(fd);
    close(LED_PIN);

    return 0;
}

