#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define I2C_ADDR 0x20
#define I2C_DEV "/dev/i2c-1"
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000
#define I2C_RETRIES 3
#define I2C_DELAY 100
#define I2C_HEADER 0x52
#define I2C_DISTANCE 0x0000
#define I2C_CYCLES 10
#define I2C_LOG_FILE "intrusion_log.txt"

int main(void) {
    int i2c_fd;
    int i2c_ret;
    int i2c_err;
    int i2c_retry;
    uint8_t i2c_buf[15];
    uint16_t i2c_distance;
    uint32_t i2c_avg_distance;
    uint32_t i2c_sum_distance;
    uint32_t i2c_count;
    uint32_t i2c_cycle;
    uint32_t i2c_timestamp;
    FILE *i2c_log_file;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C speed and timeout
    i2c_ret = ioctl(i2c_fd, I2C_SPEED, I2C_SPEED);
    if (i2c_ret < 0) {
        perror("Failed to set I2C speed");
        close(i2c_fd);
        return 1;
    }

    i2c_ret = ioctl(i2c_fd, I2C_TIMEOUT, I2C_TIMEOUT);
    if (i2c_ret < 0) {
        perror("Failed to set I2C timeout");
        close(i2c_fd);
        return 1;
    }

    // Set I2C address
    i2c_ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (i2c_ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, i2c_sigint_handler);

    // Initialize variables
    i2c_avg_distance = 0;
    i2c_sum_distance = 0;
    i2c_count = 0;
    i2c_cycle = 0;
    i2c_timestamp = 0;

    // Open log file
    i2c_log_file = fopen(I2C_LOG_FILE, "w");
    if (i2c_log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send command frame
        i2c_buf[0] = I2C_HEADER;
        i2c_buf[1] = I2C_DISTANCE;
        i2c_ret = write(i2c_fd, i2c_buf, 2);
        if (i2c_ret < 0) {
            perror("Failed to send command frame");
            close(i2c_fd);
            fclose(i2c_log_file);
            return 1;
        }

        // Wait for response
        usleep(I2C_DELAY);

        // Read response
        i2c_ret = read(i2c_fd, i2c_buf, 15);
        if (i2c_ret < 0) {
            perror("Failed to read response");
            close(i2c_fd);
            fclose(i2c_log_file);
            return 1;
        }

        // Check header
        if (i2c_buf[0] != I2C_HEADER) {
            fprintf(stderr, "Invalid header in response\n");
            close(i2c_fd);
            fclose(i2c_log_file);
            return 1;
        }

        // Extract distance
        i2c_distance = (i2c_buf[11] << 8) | i2c_buf[12];

        // Compute average distance
        i2c_sum_distance += i2c_distance;
        i2c_count++;
        i2c_avg_distance = i2c_sum_distance / i2c_count;

        // Check for intrusion
        if (i2c_avg_distance < 1000) {
            // Get timestamp
            i2c_timestamp = time(NULL);

            // Write to log file
            fprintf(i2c_log_file, "%lu, %u\n", i2c_timestamp, i2c_avg_distance);
        }

        // Increment cycle
        i2c_cycle++;
        if (i2c_cycle >= I2C_CYCLES) {
            i2c_cycle = 0;
        }
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(i2c_log_file);

    return 0;
}

void i2c_sigint_handler(int signum) {
    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(i2c_log_file);

    // Release resources
    exit(0);
}

