#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define PROX_DATA_REG 0x00
#define PROX_DATA_LEN 2

#define SIGINT_HANDLER(sig) \
    void sigint_handler(int sig) { \
        printf("Caught signal %d\n", sig); \
        gpiod_close(i2c_handle); \
        pigpio_close(i2c_handle); \
        exit(EXIT_SUCCESS); \
    }

int main(void) {
    // Initialize I2C handle
    gpiod_handle_t i2c_handle;
    pigpio_handle_t i2c_handle;
    if (gpiod_init(&i2c_handle, I2C_BUS, I2C_ADDR) != 0) {
        printf("Error initializing I2C handle\n");
        return EXIT_FAILURE;
    }
    if (pigpio_init(&i2c_handle, I2C_BUS, I2C_ADDR) != 0) {
        printf("Error initializing I2C handle\n");
        return EXIT_FAILURE;
    }

    // Set up SIGINT handler
    SIGINT_HANDLER(SIGINT);
    signal(SIGINT, sigint_handler);

    // Read proximity data
    uint8_t prox_data[PROX_DATA_LEN];
    while (1) {
        // Check for sensor presence
        if (gpiod_read(i2c_handle, PROX_DATA_REG, PROX_DATA_LEN) != 0) {
            printf("Sensor not present\n");
            return EXIT_FAILURE;
        }
        if (pigpio_read(i2c_handle, PROX_DATA_REG, PROX_DATA_LEN) != 0) {
            printf("Sensor not present\n");
            return EXIT_FAILURE;
        }

        // Read proximity data
        if (gpiod_read(i2c_handle, PROX_DATA_REG, PROX_DATA_LEN, prox_data) != 0) {
            printf("Error reading proximity data\n");
            return EXIT_FAILURE;
        }
        if (pigpio_read(i2c_handle, PROX_DATA_REG, PROX_DATA_LEN, prox_data) != 0) {
            printf("Error reading proximity data\n");
            return EXIT_FAILURE;
