#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x5A

int main(void) {
    int fd;
    int ret;
    int distance;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg;

    // Open the I2C device file
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device file");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Verify that the device responds
    msg.addr = I2C_SLAVE_ADDR;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = (char *)malloc(1);
    if (msg.buf == NULL) {
        perror("Failed to allocate memory for I2C message");
        close(fd);
        return 1;
    }
    data.msgs = &msg;
    data.nmsgs = 1;
    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        free(msg.buf);
        close(fd);
        return 1;
    }
    free(msg.buf);

    // Set up the SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Enter the measurement loop
    while (1) {
        // Read the distance measurement
        ret = ioctl(fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            continue;
        }
        distance = msg.buf[0];

        // Print the distance measurement
        printf("Distance: %d mm\n", distance);

        // Sleep for 500 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000;
        nanosleep(&ts, NULL);
    }

    // Clean up and exit
    close(fd);
    return 0;
}

void sigint_handler(int signum) {
    close(fd);
    exit(0);
}

