#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define OPT3101_ADDR 0x45

#define DISTANCE_CHANNEL 0
#define AMBIENT_LIGHT_CHANNEL 1

#define ERROR_FLAGS_REG 0x00
#define DISTANCE_REG 0x01
#define AMBIENT_LIGHT_REG 0x02

#define I2C_READ_TIMEOUT 1000

int main(void) {
    // Initialize I2C bus
    int i2c_fd = i2c_open(I2C_BUS, 0, I2C_SLAVE, I2C_READ_TIMEOUT);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize OPT3101 sensor
    uint8_t reg_addr = OPT3101_ADDR;
    uint8_t reg_data = 0;
    if (i2c_smbus_write_byte_data(i2c_fd, reg_addr, reg_data) < 0) {
        perror("Failed to initialize OPT3101 sensor");
        i2c_close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigemptyset(&sigint_handler.sa_mask);
    sigint_handler.sa_flags = 0;
    sigaction(SIGINT, &sigint_handler, NULL);

    // Main loop
    while (1) {
        // Read error flags
        reg_addr = ERROR_FLAGS_REG;
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr, &reg_data) < 0) {
            perror("Failed to read error flags");
            i2c_close(i2c_fd);
            return 1;
        }

        // Check for errors
        if (reg_data & 0x01) {
            printf("Error: Sensor not detected\n");
            i2c_close(i2c_fd);
            return 1;
        }
        if (reg_data & 0x02) {
            printf("Error: Sensor initialization failed\n");
            i2c_close(i2c_fd);
            return 1;
        }

        // Read distance measurement
        reg_addr = DISTANCE_REG;
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr, &reg_data) < 0) {
            perror("Failed to read distance measurement");
            i2c_close(i2c_fd);
            return 1;
        }

        // Read ambient light value
        reg_addr = AMBIENT_LIGHT_REG;
        if (i2c_smbus_read_byte_data(i2c_fd, reg_addr, &reg_data) < 0) {
            perror("Failed to read ambient light value");
            i2c_close(i2c_fd);
            return 1;
        }

        // Print results
        printf("Distance: %d mm\n", reg_data);
        printf("Ambient light: %d lux\n", reg_data);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Graceful shutdown
    i2c_close(i2c_fd);
    return 0;
}

void sigint_handler_func(int signum) {
    printf("Received SIGINT, shutting down...\n");
    exit(0);
}

