#include <unistd.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define MAX_PULSE_US 38000

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void setup_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        exit(1);
    }

    gpiod_line_request_output(trig_line, "trigger", 0);
    gpiod_line_request_input(echo_line, "echo");
}

static void cleanup_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        exit(1);
    }

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);

    gpiod_chip_close(chip);
}

static void trigger_pulse(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        exit(1);
    }

    gpiod_line_set_value(trig_line, 1);
    usleep(TRIG_PULSE_US);
    gpiod_line_set_value(trig_line, 0);

    gpiod_chip_close(chip);
}

static int read_echo(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *echo_line;
    int64_t start_time, end_time;
    int64_t pulse_duration;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        exit(1);
    }

    start_time = gpiod_line_get_value(echo_line);
    if (start_time < 0) {
        fprintf(stderr, "Failed to get echo start time\n");
        exit(1);
    }

    end_time = gpiod_line_get_value(echo_line);
    if (end_time < 0) {
        fprintf(stderr, "Failed to get echo end time\n");
        exit(1);
    }

    pulse_duration = end_time - start_time;
    if (pulse_duration <= 0 || pulse_duration > MAX_PULSE_US) {
        fprintf(stderr, "Invalid pulse duration: %lld\n", pulse_duration);
        exit(1);
    }

    gpiod_chip_close(chip);

    return pulse_duration;
}

int main(void) {
    struct timespec ts;
    int64_t pulse_duration;

    setup_gpio();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        trigger_pulse();

        pulse_duration = read_echo();
        if (pulse_duration > 0) {
            printf("Distance: %lld\n", pulse_duration);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += 1;
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
    }

    cleanup_gpio();

    return 0;
}

