#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio17"
#define BUZZER_GPIO_LINE_NAME "gpio18"
#define POLL_INTERVAL 100

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Open the GPIO line for the sensor
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (line == NULL) {
        fprintf(stderr, "Error opening GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the GPIO line for the buzzer
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO_LINE_NAME);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Error opening GPIO line for buzzer\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the buzzer as an output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error setting up buzzer as output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the sensor as an input
    if (gpiod_line_request_input(line, "sensor") < 0) {
        fprintf(stderr, "Error setting up sensor as input\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("obstacle_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read the sensor value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            gpiod_chip_close(chip);
            return 1;
        }

        // Check if an obstacle is detected
        if (value == 0) {
            // Activate the buzzer
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error activating buzzer\n");
                gpiod_chip_close(chip);
                return 1;
            }

            // Log the state transition
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
            fprintf(log_file, "%s: Obstacle detected\n", timestamp);
        } else {
            // Deactivate the buzzer
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer\n");
                gpiod_chip_close(chip);
                return 1;
            }

            // Log the state transition
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
            fprintf(log_file, "%s: Obstacle removed\n", timestamp);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(buzzer_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

