#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define GPIO_PIN 17

#define DISTANCE_LOG_FILE "distance_log.txt"

#define DISTANCE_THRESHOLD 10.0

int main(void) {
    int i2c_fd, gpio_fd;
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_event_request gpio_req;
    struct gpio_event_response gpio_resp;
    struct timespec ts;
    uint8_t i2c_buf[2];
    float distance;
    char timestamp[20];

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO pin
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO pin");
        close(i2c_fd);
        return 1;
    }

    // Set GPIO pin direction
    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_PIN, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO pin direction");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO pin value
    if (ioctl(gpio_fd, GPIO_SET_VAL, GPIO_PIN, GPIO_VAL_LOW) < 0) {
        perror("Failed to set GPIO pin value");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up I2C read/write message
    i2c_msg.addr = I2C_ADDR;
    i2c_msg.flags = 0;
    i2c_msg.len = 2;
    i2c_msg.buf = i2c_buf;

    // Set up I2C read/write data
    i2c_data.msgs = &i2c_msg;
    i2c_data.nmsgs = 1;

    // Set up GPIO event request
    gpio_req.lineoffsets = GPIO_PIN;
    gpio_req.handleflags = GPIOHANDLE_REQUEST_OUTPUT;
    gpio_req.eventflags = GPIOEVENT_REQUEST_RISING_EDGE;

    // Set up GPIO event response
    gpio_resp.lineoffsets = GPIO_PIN;
    gpio_resp.eventflags = GPIOEVENT_EVENT_RISING_EDGE;

    // Open log file
    if ((fp = fopen(DISTANCE_LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance measurement
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read distance measurement");
            close(gpio_fd);
            close(i2c_fd);
            fclose(fp);
            return 1;
        }

        // Convert distance measurement to float
        distance = (float)i2c_buf[0] + (float)i2c_buf[1] / 100.0;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write distance measurement to log file
        fprintf(fp, "%s,%.2f\n", timestamp, distance);

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            // Set GPIO pin value
            if (ioctl(gpio_fd, GPIO_SET_VAL, GPIO_PIN, GPIO_VAL_HIGH) < 0) {
                perror("Failed to set GPIO pin value");
                close(gpio_fd);
                close(i2c_fd);
                fclose(fp);
                return 1;
            }

            // Wait for GPIO event
            if (ioctl(gpio_fd, GPIO_GET_EVENT, &gpio_req, &gpio_resp) < 0) {
                perror("Failed to get GPIO event");
                close(gpio_fd);
                close(i2c_fd);
                fclose(fp);
                return 1;
            }

            // Clear GPIO pin value
            if (ioctl(gpio_fd, GPIO_SET_VAL, GPIO_PIN, GPIO_VAL_LOW) < 0) {
                perror("Failed to clear GPIO pin value");
                close(gpio_fd);
                close(i2c_fd);
                fclose(fp);
                return 1;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(fp);

    // Close GPIO pin
    close(gpio_fd);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

