#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LED_PIN 18
#define LED_FREQ 100
#define LED_DUTY_CYCLE 50
#define SAMPLE_INTERVAL 100

static int i2c_fd;
static int led_fd;
static int led_state = 0;

static void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    close(led_fd);
    pigpio_stop(PI_DEFAULT);
    exit(0);
}

static void sigterm_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    close(led_fd);
    pigpio_stop(PI_DEFAULT);
    exit(0);
}

static void init_gpio() {
    if (pigpio_start(PI_DEFAULT, NULL) < 0) {
        printf("Failed to start pigpio\n");
        exit(1);
    }

    if (gpio_mode_set(PI_DEFAULT, LED_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO %d as output\n", LED_PIN);
        exit(1);
    }

    if (gpio_write(PI_DEFAULT, LED_PIN, 0) < 0) {
        printf("Failed to write to GPIO %d\n", LED_PIN);
        exit(1);
    }
}

static void init_i2c() {
    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE, 0)) < 0) {
        printf("Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }
}

static void init_led() {
    if ((led_fd = gpio_open(PI_DEFAULT, LED_PIN, PI_OUTPUT)) < 0) {
        printf("Failed to open GPIO %d as output\n", LED_PIN);
        exit(1);
    }

    if (gpio_write(PI_DEFAULT, LED_PIN, 0) < 0) {
        printf("Failed to write to GPIO %d\n", LED_PIN);
        exit(1);
    }
}

static void read_distance() {
    uint8_t buf[2];
    int ret;

    if ((ret = i2c_read(i2c_fd, buf, 2)) < 0) {
        printf("Failed to read from I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    uint16_t distance = (buf[0] << 8) | buf[1];
    printf("Distance: %d\n", distance);

    int led_duty_cycle = (distance * LED_DUTY_CYCLE) / 100;
    if (led_duty_cycle < 0) {
        led_duty_cycle = 0;
    } else if (led_duty_cycle > 100) {
        led_duty_cycle = 100;
    }

    if (led_state == 0) {
        if (gpio_write(PI_DEFAULT, LED_PIN, 1) < 0) {
            printf("Failed to write to GPIO %d\n", LED_PIN);
            exit(1);
        }
        led_state = 1;
    } else {
        if (gpio_write(PI_DEFAULT, LED_PIN, 0) < 0) {
            printf("Failed to write to GPIO %d\n", LED_PIN);
            exit(1);
        }
        led_state = 0;
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_gpio();
    init_i2c();
    init_led();

    while (1) {
        read_distance();
        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

