#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x50
#define MLX75030_MEASURE_CMD 0x04
#define MLX75030_MEASURE_DELAY 100000
#define MLX75030_READ_DELAY 10000
#define MLX75030_READ_RETRIES 3

int main(void) {
    int fd;
    uint8_t buf[2];
    uint16_t distance;
    char filename[20];
    FILE *fp;
    struct timespec ts;

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set I2C frequency
    if (ioctl(fd, I2C_SET_FREQ, 400000) < 0) {
        perror("Failed to set I2C frequency");
        close(fd);
        return 1;
    }

    // Set I2C timeout
    if (ioctl(fd, I2C_SET_TIMEOUT, 1000) < 0) {
        perror("Failed to set I2C timeout");
        close(fd);
        return 1;
    }

    // Set I2C retries
    if (ioctl(fd, I2C_SET_RETRIES, MLX75030_READ_RETRIES) < 0) {
        perror("Failed to set I2C retries");
        close(fd);
        return 1;
    }

    // Set filename
    snprintf(filename, sizeof(filename), "distance_log_%ld.csv", time(NULL));

    // Open file
    if ((fp = fopen(filename, "w")) == NULL) {
        perror("Failed to open file");
        close(fd);
        return 1;
    }

    // Write header
    fprintf(fp, "timestamp,distance_cm\n");

    // Main loop
    while (1) {
        // Trigger measurement
        if (write(fd, &MLX75030_MEASURE_CMD, 1) != 1) {
            perror("Failed to trigger measurement");
            close(fd);
            fclose(fp);
            return 1;
        }

        // Wait for measurement to complete
        usleep(MLX75030_MEASURE_DELAY);

        // Read distance
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read distance");
            close(fd);
            fclose(fp);
            return 1;
        }

        // Convert distance to centimeters
        distance = (buf[0] << 8) | buf[1];

        // Write to file
        fprintf(fp, "%ld,%d\n", time(NULL), distance);
    }

    // Close file
    fclose(fp);

    // Close I2C bus
    close(fd);

    return 0;
}

