#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define DEBOUNCE_TIME 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up GPIO lines
    struct gpiod_line *sensor_1 = gpiod_chip_get_line(chip, SENSOR_1_PIN);
    struct gpiod_line *sensor_2 = gpiod_chip_get_line(chip, SENSOR_2_PIN);
    if (sensor_1 == NULL || sensor_2 == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up GPIO line configuration
    struct gpiod_line_config config = {
        .direction = GPIOD_LINE_DIRECTION_INPUT,
        .flags = GPIOD_LINE_FLAG_ACTIVE_LOW,
    };
    if (gpiod_line_request_input(sensor_1, "sensor_1", &config) != 0 ||
        gpiod_line_request_input(sensor_2, "sensor_2", &config) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO lines\n");
        gpiod_line_release(sensor_1);
        gpiod_line_release(sensor_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("proximity_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpiod_line_release(sensor_1);
        gpiod_line_release(sensor_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int sensor_1_value = gpiod_line_get_value(sensor_1);
        int sensor_2_value = gpiod_line_get_value(sensor_2);
        if (sensor_1_value < 0 || sensor_2_value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO lines\n");
            break;
        }

        // Check for state transitions
        if (sensor_1_value == 1 && sensor_2_value == 0) {
            // Sensor 1 detected an obstacle
            fprintf(log_file, "%s,1,DETECTED\n", get_iso_8601_timestamp());
        } else if (sensor_1_value == 0 && sensor_2_value == 1) {
            // Sensor 2 detected an obstacle
            fprintf(log_file, "%s,2,DETECTED\n", get_iso_8601_timestamp());
        } else if (sensor_1_value == 0 && sensor_2_value == 0) {
            // Both sensors cleared
            fprintf(log_file, "%s,1,CLEARED\n", get_iso_8601_timestamp());
            fprintf(log_file, "%s,2,CLEARED\n", get_iso_8601_timestamp());
        }

        // Debounce
        usleep(DEBOUNCE_TIME * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(sensor_1);
    gpiod_line_release(sensor_2);
    gpiod_chip_close(chip);

    return 0;
}

char *get_iso_8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    timestamp = asctime(timeinfo);
    timestamp[strlen(timestamp) - 1] = '\0';

    return timestamp;
}

