#define MEAS_DATA_MASK 0xFF
#define POLL_TIMEOUT 50
#define SAMPLE_INTERVAL 500

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    exit(0);
}

static void sigterm_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    exit(0);
}

static int read_meas_status(void) {
    uint8_t status;
    if (read(i2c_fd, &status, 1) != 1) {
        fprintf(stderr, "Error reading MEAS_STATUS register: %s\n", strerror(errno));
        return -1;
    }
    return status & MEAS_STATUS_MASK;
}

static int read_meas_data(void) {
    uint8_t data;
    if (read(i2c_fd, &data, 1) != 1) {
        fprintf(stderr, "Error reading MEAS_DATA register: %s\n", strerror(errno));
        return -1;
    }
    return data & MEAS_DATA_MASK;
}

static int poll_meas_status(void) {
    int status;
    struct timespec timeout;
    timeout.tv_sec = POLL_TIMEOUT / 1000;
    timeout.tv_nsec = (POLL_TIMEOUT % 1000) * 1000000;
    while ((status = read_meas_status()) == 0) {
        if (nanosleep(&timeout, NULL) == -1) {
            fprintf(stderr, "Error waiting for MEAS_STATUS: %s\n", strerror(errno));
            return -1;
        }
    }
    return status;
}

static int read_distance(void) {
    int status;
    if ((status = poll_meas_status()) == -1) {
        return -1;
    }
    if (status != 1) {
        fprintf(stderr, "MEAS_STATUS not ready: %d\n", status);
        return -1;
    }
    int distance = read_meas_data();
    if (distance == -1) {
        return -1;
    }
    return distance;
}

int main(void) {
    struct sigaction sigint_action;
    struct sigaction sigterm_action;
    sigint_action.sa_handler = sigint_handler;
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);
    sigterm_action.sa_handler = sigterm_handler;
    sigterm_action.sa_flags = 0;
    sigaction(SIGTERM, &sigterm_action, NULL);

    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) == -1) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if ((csv_file = fopen("distance_log.csv", "w")) == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        int distance = read_distance();
        if (distance == -1) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            continue;
        }
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(csv_file, "%s,%d\n", timestamp, distance);
        fflush(csv_file);
        sleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    fflush(csv_file);
    fclose(csv_file);
    return 0;
}

