#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x29
#define I2C_REG_START 0x00
#define I2C_REG_END 0x0F
#define I2C_REG_ZONE_DISTANCE 0x10
#define I2C_REG_ZONE_CONFIG 0x20
#define I2C_REG_ZONE_ENABLE 0x30
#define I2C_REG_ZONE_DISABLE 0x40
#define I2C_REG_ZONE_CLEAR 0x50
#define I2C_REG_ZONE_STATUS 0x60
#define I2C_REG_ZONE_COUNT 0x70
#define I2C_REG_ZONE_DATA 0x80

#define ZONE_GRID_WIDTH 8
#define ZONE_GRID_HEIGHT 8
#define ZONE_GRID_SIZE (ZONE_GRID_WIDTH * ZONE_GRID_HEIGHT)

int main() {
    int fd;
    uint8_t reg_val;
    uint16_t zone_distance;
    uint8_t zone_config;
    uint8_t zone_enable;
    uint8_t zone_disable;
    uint8_t zone_clear;
    uint8_t zone_status;
    uint8_t zone_count;
    uint8_t zone_data[ZONE_GRID_SIZE];

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Configure zone grid
    zone_config = (ZONE_GRID_WIDTH << 4) | ZONE_GRID_HEIGHT;
    if (write(fd, &zone_config, 1) != 1) {
        perror("Failed to write zone config");
        close(fd);
        return 1;
    }

    // Enable zone grid
    zone_enable = 1;
    if (write(fd, &zone_enable, 1) != 1) {
        perror("Failed to enable zone grid");
        close(fd);
        return 1;
    }

    // Clear zone grid
    zone_clear = 1;
    if (write(fd, &zone_clear, 1) != 1) {
        perror("Failed to clear zone grid");
        close(fd);
        return 1;
    }

    // Read zone distance
    if (read(fd, &zone_distance, 2) != 2) {
        perror("Failed to read zone distance");
        close(fd);
        return 1;
    }

    // Read zone status
    if (read(fd, &zone_status, 1) != 1) {
        perror("Failed to read zone status");
        close(fd);
        return 1;
    }

    // Read zone count
    if (read(fd, &zone_count, 1) != 1) {
        perror("Failed to read zone count");
        close(fd);
        return 1;
    }

    // Read zone data
    if (read(fd, zone_data, ZONE_GRID_SIZE) != ZONE_GRID_SIZE) {
        perror("Failed to read zone data");
        close(fd);
        return 1;
    }

    // Print zone distance
    printf("Zone distance: %d\n", zone_distance);

    // Print zone status
    printf("Zone status: %d\n", zone_status);

    // Print zone count
    printf("Zone count: %d\n", zone_count);

    // Print zone data
    for (int i = 0; i < ZONE_GRID_SIZE; i++) {
        printf("Zone data[%d]: %d\n", i, zone_data[i]);
    }

    // Disable zone grid
    zone_disable = 1;
    if (write(fd, &zone_disable, 1) != 1) {
        perror("Failed to disable zone grid");
        close(fd);
        return 1;
    }

    // Close I2C device
    close(fd);

    return 0;
}

