#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x50
#define MLX75030_DIST_REG 0x00
#define MLX75030_DIST_SIZE 2
#define MLX75030_DIST_RES 10
#define MLX75030_DIST_MAX 1000
#define MLX75030_DIST_MIN 0

#define RETRY_COUNT 3
#define RETRY_DELAY 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static int read_distance(int fd, uint16_t *distance) {
    uint8_t data[MLX75030_DIST_SIZE];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(fd, MLX75030_DIST_REG, MLX75030_DIST_SIZE, data);
    if (ret < 0) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

int main(int argc, char *argv[]) {
    int fd;
    uint16_t distance;
    struct timespec ts;
    int ret;
    int retry_count;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    fd = i2c_open(I2C_BUS, 0, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        retry_count = 0;
        while (retry_count < RETRY_COUNT) {
            ret = read_distance(fd, &distance);
            if (ret == 0) {
                break;
            }
            retry_count++;
            usleep(RETRY_DELAY * 1000);
        }
        if (retry_count == RETRY_COUNT) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld: %d mm\n", ts.tv_sec, ts.tv_nsec, distance);

        usleep(100 * 1000);
    }

    i2c_close(fd);
    return 0;
}

