#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUZZER_GPIO 22

#define DISTANCE_THRESHOLD 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    int i2c_fd;
    int buzzer_fd;
    int ret;
    uint16_t distance;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open buzzer GPIO
    buzzer_fd = open("/dev/gpiochip0", O_RDWR);
    if (buzzer_fd < 0) {
        perror("Failed to open buzzer GPIO");
        return 1;
    }

    // Set up VL53L1X sensor
    ret = vl53l1x_init(i2c_fd, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to initialize VL53L1X sensor");
        return 1;
    }

    // Set continuous ranging mode
    ret = vl53l1x_set_mode(i2c_fd, I2C_ADDR, VL53L1X_MODE_CONTINUOUS);
    if (ret < 0) {
        perror("Failed to set continuous ranging mode");
        return 1;
    }

    // Set buzzer GPIO as output
    ret = gpio_export(buzzer_fd, BUZZER_GPIO);
    if (ret < 0) {
        perror("Failed to export buzzer GPIO");
        return 1;
    }

    ret = gpio_set_direction(buzzer_fd, BUZZER_GPIO, GPIO_OUT);
    if (ret < 0) {
        perror("Failed to set buzzer GPIO direction");
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance measurement
        ret = vl53l1x_get_distance(i2c_fd, I2C_ADDR, &distance);
        if (ret < 0) {
            perror("Failed to read distance measurement");
            continue;
        }

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            // Activate buzzer
            ret = gpio_set_value(buzzer_fd, BUZZER_GPIO, 1);
            if (ret < 0) {
                perror("Failed to activate buzzer");
                continue;
            }
        } else {
            // Deactivate buzzer
            ret = gpio_set_value(buzzer_fd, BUZZER_GPIO, 0);
            if (ret < 0) {
                perror("Failed to deactivate buzzer");
                continue;
            }
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    ret = gpio_unexport(buzzer_fd, BUZZER_GPIO);
    if (ret < 0) {
        perror("Failed to unexport buzzer GPIO");
    }

    ret = close(buzzer_fd);
    if (ret < 0) {
        perror("Failed to close buzzer GPIO");
    }

    ret = close(i2c_fd);
    if (ret < 0) {
        perror("Failed to close I2C bus");
    }

    return 0;
}

