#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize PIGPIO\n");
        exit(1);
    }

    if (gpiod_export(TRIG_PIN, GPIOD_OUT) != 0) {
        fprintf(stderr, "Failed to export TRIG_PIN\n");
        exit(1);
    }

    if (gpiod_export(ECHO_PIN, GPIOD_IN) != 0) {
        fprintf(stderr, "Failed to export ECHO_PIN\n");
        exit(1);
    }

    if (gpiod_export(SERVO_PIN, GPIOD_OUT) != 0) {
        fprintf(stderr, "Failed to export SERVO_PIN\n");
        exit(1);
    }
}

static void cleanup_gpio(void) {
    gpiod_unexport(TRIG_PIN);
    gpiod_unexport(ECHO_PIN);
    gpiod_unexport(SERVO_PIN);
    gpiod_close();
    pigpio_close();
}

static void set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return;
    }

    pigpio_set_servo_pulsewidth(SERVO_PIN, angle);
}

static int get_distance(void) {
    int distance = 0;

    gpiod_set_value(TRIG_PIN, 1);
    usleep(10);
    gpiod_set_value(TRIG_PIN, 0);

    while (gpiod_get_value(ECHO_PIN) == 0) {
        if (gpiod_get_value(ECHO_PIN) == 1) {
            fprintf(stderr, "Echo line is high\n");
            return -1;
        }

        if (gpiod_get_value(ECHO_PIN) == 0) {
            fprintf(stderr, "Echo line is low\n");
            return -1;
        }
    }

    distance = gpiod_get_value(ECHO_PIN);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance: %d\n", distance);
        return -1;
    }

    return distance;
}

int main(void) {
    init_gpio();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        int distance = get_distance();

        if (distance == -1) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        int angle = (distance - MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + SERVO_MIN_ANGLE;
        set_servo_angle(angle);

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        FILE *fp = fopen("sensor_data.log", "a");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open sensor_data.log\n");
            continue;
        }

        fprintf(fp, "%s, %d\n", timestamp, distance);
        fclose(fp);

        usleep(200000);
    }

    cleanup_gpio();

    return 0;
}

