#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

#define TIMEOUT_US 100000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define BUZZER_THRESHOLD 30

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void buzzer_on(void) {
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_HIGH);
}

static void buzzer_off(void) {
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_LOW);
}

static void measure_distance(void) {
    uint32_t start_time, end_time, elapsed_time;
    uint32_t distance;

    // Set trigger pin to HIGH for 10 µs
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioWrite(TRIG_PIN, PI_HIGH);
    usleep(10);
    gpioWrite(TRIG_PIN, PI_LOW);

    // Wait for echo pin to go HIGH
    gpioSetMode(ECHO_PIN, PI_INPUT);
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        usleep(10);
    }

    // Measure echo time
    start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        usleep(10);
    }
    end_time = gpioTick();
    elapsed_time = end_time - start_time;

    // Calculate distance
    distance = (elapsed_time * 17000) / 1000000;

    // Check for timeout or invalid reading
    if (distance == 0 || distance > MAX_DISTANCE) {
        printf("Sensor not present or invalid reading\n");
        return;
    }

    // Check for buzzer condition
    if (distance < BUZZER_THRESHOLD) {
        buzzer_on();
    } else {
        buzzer_off();
    }

    // Output distance
    printf("Distance: %d cm\n", distance);
}

int main(void) {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler
    if (gpioSetISRFunc(ECHO_PIN, PI_RISING_EDGE, measure_distance) < 0) {
        fprintf(stderr, "Failed to register interrupt handler\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        usleep(100000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

