#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 18
#define SERVO_FREQ 50
#define SERVO_RANGE 180
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"

#define SIGINT_HANDLER(sig) \
    void sigint_handler(int sig) { \
        printf("Received signal %d, exiting...\n", sig); \
        exit(EXIT_SUCCESS); \
    }

#define SIGTERM_HANDLER(sig) \
    void sigterm_handler(int sig) { \
        printf("Received signal %d, exiting...\n", sig); \
        exit(EXIT_SUCCESS); \
    }

#define SIGINT_INSTALL() \
    signal(SIGINT, sigint_handler);

#define SIGTERM_INSTALL() \
    signal(SIGTERM, sigterm_handler);

#define I2C_INIT() \
    if (i2c_init(I2C_BUS) < 0) { \
        printf("Failed to initialize I2C bus %d\n", I2C_BUS); \
        exit(EXIT_FAILURE); \
    }

#define I2C_RESET() \
    if (i2c_reset(I2C_BUS) < 0) { \
        printf("Failed to reset I2C bus %d\n", I2C_BUS); \
        exit(EXIT_FAILURE); \
    }

#define I2C_START_RANGING() \
    if (i2c_start_ranging(I2C_BUS, I2C_ADDR) < 0) { \
        printf("Failed to start ranging on I2C bus %d\n", I2C_BUS); \
        exit(EXIT_FAILURE); \
    }

#define I2C_READ_DISTANCE() \
    uint16_t distance; \
    if (i2c_read_distance(I2C_BUS, I2C_ADDR, &distance) < 0) { \
        printf("Failed to read distance from I2C bus %d\n", I2C_BUS); \
        exit(EXIT_FAILURE); \
    }

#define SERVO_INIT() \
    if (servo_init(GPIO_PIN, SERVO_FREQ, SERVO_RANGE) < 0) { \
        printf("Failed to initialize servo on GPIO pin %d\n", GPIO_PIN); \
        exit(EXIT_FAILURE); \
    }

#define SERVO_OPEN() \
    if (servo_open(GPIO_PIN) < 0) { \
        printf("Failed to open servo on GPIO pin %d\n", GPIO_PIN); \
        exit(EXIT_FAILURE); \
    }

#define SERVO_CLOSE() \
    if (servo_close(GPIO_PIN) < 0) { \
        printf("Failed to close servo on GPIO pin %d\n", GPIO_PIN); \
        exit(EXIT_FAILURE); \
    }

#define LOG_EVENT(event) \
    if (log_event(event) < 0) { \
        printf("Failed to log event %s\n", event); \
        exit(EXIT_FAILURE); \
    }

int main(void) {
    SIGINT_INSTALL();
    SIGTERM_INSTALL();

    I2C_INIT();
    I2C_RESET();
    I2C_START_RANGING();

    SERVO_INIT();
    SERVO_OPEN();

    while (true) {
        I2C_READ_DISTANCE();

        if (distance < DISTANCE_THRESHOLD) {
            SERVO_CLOSE();
            LOG_EVENT("Object detected within 20 cm, gate closed");
        } else {
            SERVO_OPEN();
            LOG_EVENT("Object not detected within 20 cm, gate open");
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

int i2c_init(int bus) {
    if (ioctl(bus, I2C_RESET, NULL) < 0) {
        return -1;
    }

    if (ioctl(bus, I2C_START_RANGING, NULL) < 0) {
        return -1;
    }

    return 0;
