#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIG_PULSE_WIDTH 10
#define TRIG_PULSE_PERIOD 200
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000
#define TIMEOUT_MS 60

static volatile bool running = true;
static volatile bool timeout = false;
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;

static void handle_sigint(int signal) {
    running = false;
}

static void handle_sigterm(int signal) {
    running = false;
}

static void handle_alert(struct gpiod_line *line, uint32_t tick) {
    if (gpiod_line_get_value(line) == 1) {
        rising_tick = tick;
    } else {
        falling_tick = tick;
    }
}

static void log_distance(uint32_t distance) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    printf("%s: %d cm\n", timestamp, distance);
    fprintf(stderr, "%s: %d cm\n", timestamp, distance);
}

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    struct gpiod_line_request *trig_request, *echo_request;
    struct gpiod_line_event *event;
    uint32_t tick;
    uint32_t pulse_width;
    uint32_t distance;

    // Initialize the GPIO driver
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the TRIG and ECHO lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    // Set the TRIG line to output and the ECHO line to input
    trig_request = gpiod_line_request_output(trig_line, "trig", 0);
    echo_request = gpiod_line_request_input(echo_line, "echo");
    if (!trig_request || !echo_request) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        return 1;
    }

    // Set the TRIG line to LOW
    gpiod_line_set_value(trig_line, 0);

    // Set up the alert callback
    gpiod_line_request_events(echo_line, handle_alert);

    // Set up the signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (running) {
        // Generate a 10 µs trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIG_PULSE_WIDTH);
        gpiod_line_set_value(trig_line, 0);

        // Wait for the echo line to go high
        while (gpiod_line_get_value(echo_line) == 0) {
            if (timeout) {
                fprintf(stderr, "Timeout waiting for echo\n");
                timeout = false;
                break;
            }
        }

        // Wait for the echo line to go low
        while (gpiod_line_get_value(echo_line) == 1) {
            if (timeout) {
                fprintf(stderr, "Timeout waiting for echo\n");
                timeout = false;
                break;
            }
        }

        // Calculate the pulse width
        pulse_width = falling_tick - rising_tick;

        // Check for valid pulse width
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            continue;
        }

        // Calculate the distance
        distance = pulse_width * 17150 / 1000000;

        // Log the distance
        log_distance(distance);

        // Wait for the next trigger period
        usleep(TRIG_PULSE_PERIOD * 1000 - TRIG_PULSE_WIDTH);
    }

    // Clean up
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

