#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define HYSTERESIS 50
#define MAX_DISTANCE 60

#define LOG_FILE "parking_log.txt"

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        exit(1);
    }

    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        exit(1);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        exit(1);
    }
}

static void init_vl53l1x(void) {
    if (vl53l1x_init(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        exit(1);
    }

    uint8_t model_id;
    if (vl53l1x_get_model_id(&model_id) < 0) {
        fprintf(stderr, "Failed to get VL53L1X model ID\n");
        exit(1);
    }

    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid VL53L1X model ID: %d\n", model_id);
        exit(1);
    }
}

static void init_servo(void) {
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        exit(1);
    }

    if (pigpio_set_mode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        exit(1);
    }

    if (pigpio_set_servo_frequency(SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set servo frequency\n");
        exit(1);
    }
}

static void log_state(bool open) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, open ? "open" : "close");

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        exit(1);
    }

    close(fd);
}

static void open_gate(void) {
    if (gpioWrite(SHUTDOWN_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to open gate\n");
        exit(1);
    }

    log_state(true);
}

static void close_gate(void) {
    if (gpioWrite(SHUTDOWN_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to close gate\n");
        exit(1);
    }

    log_state(false);
}

static void handle_interrupt(void) {
    uint8_t status;
    if (vl53l1x_get_interrupt_status(&status) < 0) {
        fprintf(stderr, "Failed to get interrupt status\n");
        exit(1);
    }

    if (status & VL53L1X_INT_STATUS_THRESH_HIGH) {
        open_gate();
    } else if (status & VL53L1X_INT_STATUS_THRESH_LOW) {
        close_gate();
    }
}

int main(void) {
    init_gpio();
    init_vl53l1x();
    init_servo();

    if (vl53l1x_set_interrupt_thresholds(HYSTERESIS, MAX_DISTANCE) < 0) {
        fprintf(stderr, "Failed to set interrupt thresholds\n");
        exit(1);
    }

    if (vl53l1x_start_ranging() < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        handle_interrupt();
    }

    vl53l1x_stop_ranging();
    pigpio_stop();

    return 0;
}

