    if (vl53l1x_set_interrupt_thresholds(HYSTERESIS, MAX_DISTANCE) < 0) {
        fprintf(stderr, "Failed to set interrupt thresholds\n");
        exit(1);
    }

    if (vl53l1x_start_ranging() < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        handle_interrupt();
    }

