#define GPIO_19 19
#define TIMING_BUDGET 50000
#define DISTANCE_THRESHOLD 200

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_fd) < 0) {
        perror("Failed to initialize VL53L1X sensor");
        close(i2c_fd);
        return 1;
    }

    // Configure timing budget
    if (vl53l1x_set_timing_budget(i2c_fd, TIMING_BUDGET) < 0) {
        perror("Failed to set timing budget");
        close(i2c_fd);
        return 1;
    }

