    if (vl53l1x_start_ranging(i2c_fd) < 0) {
        perror("Failed to start ranging");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO pins
    int gpio_18_fd = gpiod_open(GPIO_18, GPIO_OUTPUT);
    if (gpio_18_fd < 0) {
        perror("Failed to open GPIO pin 18");
        close(i2c_fd);
        return 1;
    }

    int gpio_19_fd = gpiod_open(GPIO_19, GPIO_OUTPUT);
    if (gpio_19_fd < 0) {
        perror("Failed to open GPIO pin 19");
        close(i2c_fd);
        close(gpio_18_fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("gate_events.log", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(gpio_18_fd);
        close(gpio_19_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance measurement
        uint16_t distance = vl53l1x_read_distance(i2c_fd);
        if (distance < 0) {
            perror("Failed to read distance measurement");
            close(i2c_fd);
            close(gpio_18_fd);
            close(gpio_19_fd);
            fclose(log_file);
            return 1;
        }

        // Check if object is within 20 cm
        if (distance < DISTANCE_THRESHOLD) {
            // Open gate
            gpiod_set_value(gpio_18_fd, 1);
            gpiod_set_value(gpio_19_fd, 0);

            // Log event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s: Open\n", timestamp);
        } else {
            // Close gate
            gpiod_set_value(gpio_18_fd, 0);
            gpiod_set_value(gpio_19_fd, 1);

            // Log event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s: Close\n", timestamp);
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    close(i2c_fd);
    close(gpio_18_fd);
    close(gpio_19_fd);
    fclose(log_file);
    return 0;
}

