#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_FWD 17
#define GPIO_BWD 18
#define GPIO_INT 24

#define DIST_THRESH_FWD 100
#define DIST_THRESH_BWD 300

#define I2C_RETRIES 5
#define I2C_DELAY 1000

#define MOTOR_STOP 0
#define MOTOR_FWD 1
#define MOTOR_BWD 2

#define SIGINT_HANDLER(sig) \
    if (sig == SIGINT) { \
        printf("Received SIGINT, stopping motor and releasing resources\n"); \
        motor_stop(); \
        i2c_close(); \
        pigpio_stop(); \
        exit(0); \
    }

#define SIGTERM_HANDLER(sig) \
    if (sig == SIGTERM) { \
        printf("Received SIGTERM, stopping motor and releasing resources\n"); \
        motor_stop(); \
        i2c_close(); \
        pigpio_stop(); \
        exit(0); \
    }

void i2c_init() {
    if (pigpio_start() < 0) {
        printf("Failed to start pigpio\n");
        exit(1);
    }

    if (i2c_open(I2C_BUS, I2C_ADDR) < 0) {
        printf("Failed to open I2C bus %d with address 0x%02X\n", I2C_BUS, I2C_ADDR);
        exit(1);
    }
}

void i2c_close() {
    i2c_close(I2C_BUS);
    pigpio_stop();
}

void motor_stop() {
    gpio_write(GPIO_FWD, MOTOR_STOP);
    gpio_write(GPIO_BWD, MOTOR_STOP);
}

void motor_forward() {
    gpio_write(GPIO_FWD, MOTOR_FWD);
    gpio_write(GPIO_BWD, MOTOR_STOP);
}

void motor_backward() {
    gpio_write(GPIO_FWD, MOTOR_STOP);
    gpio_write(GPIO_BWD, MOTOR_BWD);
}

void distance_read() {
    uint16_t distance;
    int retries = 0;

    while (retries < I2C_RETRIES) {
        if (i2c_read(I2C_BUS, I2C_ADDR, 0x16, 2, &distance) < 0) {
            printf("Failed to read distance from sensor, retrying\n");
            usleep(I2C_DELAY);
            retries++;
        } else {
            break;
        }
    }

    if (retries == I2C_RETRIES) {
        printf("Failed to read distance from sensor after %d retries, stopping motor\n", I2C_RETRIES);
        motor_stop();
        return;
    }

    printf("Distance: %d mm\n", distance);

    if (distance < DIST_THRESH_FWD) {
        motor_forward();
    } else if (distance > DIST_THRESH_BWD) {
        motor_backward();
    } else {
        motor_stop();
    }
}

void gpio_init() {
    if (gpio_init() < 0) {
        printf("Failed to initialize GPIO\n");
        exit(1);
    }

    gpio_set_mode(GPIO_FWD, GPIO_OUTPUT);
    gpio_set_mode(GPIO_BWD, GPIO_OUTPUT);
    gpio_set_mode(GPIO_INT, GPIO_INPUT);
}

void gpio_close() {
    gpio_close();
}

void gpio_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        distance_read();
    }
}

int main() {
    i2c_init();
    gpio_init();

    gpio_set_isr(GPIO_INT, GPIO_RISING_EDGE, gpio_isr);

    while (true) {
        sleep(1);
    }

    gpio_close();
    i2c_close();

    return 0;
}

