#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_MS 30

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Set up the trigger and echo pins
    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        return 1;
    }

    // Set up the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: unable to set SIGINT handler\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error: unable to open log file\n");
        return 1;
    }

    // Main loop
    while (!sigint_flag) {
        // Set the trigger pin low
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Error: unable to set trigger pin low\n");
            return 1;
        }

        // Wait for the echo pin to go high
        struct timespec timeout = {0, TIMEOUT_MS * 1000000};
        if (gpiod_line_wait_for_value(echo_line, 1, &timeout) < 0) {
            fprintf(stderr, "Error: timeout waiting for echo pin to go high\n");
            return 1;
        }

        // Measure the echo pulse width
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        if (gpiod_line_wait_for_value(echo_line, 0, &timeout) < 0) {
            fprintf(stderr, "Error: timeout waiting for echo pin to go low\n");
            return 1;
        }
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        double pulse_width = (end_time.tv_sec - start_time.tv_sec) * 1000000.0 + (end_time.tv_nsec - start_time.tv_nsec) / 1000.0;

        // Compute the distance
        double distance = pulse_width * SPEED_OF_SOUND / 2.0;

        // Check the distance range
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Error: distance out of range\n");
            return 1;
        }

        // Write the distance to the log file
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file);

        // Wait for the next second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

