#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIG_PULSE_WIDTH 10000
#define ECHO_PULSE_WIDTH_MIN 58000
#define ECHO_PULSE_WIDTH_MAX 2500000

static volatile bool running = true;
static int log_fd;

static void sigint_handler(int signum) {
    running = false;
}

static void log_distance(uint32_t distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[128];
    snprintf(buf, sizeof(buf), "%ld.%06ld,%u\n", tv.tv_sec, tv.tv_usec, distance);
    write(log_fd, buf, strlen(buf));
}

static void echo_callback(struct gpiod_line *line, uint32_t event, void *data) {
    uint32_t pulse_width = gpiod_line_get_value(line);
    if (pulse_width > ECHO_PULSE_WIDTH_MIN && pulse_width < ECHO_PULSE_WIDTH_MAX) {
        log_distance(pulse_width / 1000);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    struct gpiod_line_request_config config = {
        .consumer = "ultrasonic_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN,
    };

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    log_fd = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        return 1;
    }

    if (gpiod_line_request_input(echo_line, &config) < 0) {
        perror("gpiod_line_request_input");
        return 1;
    }

    if (gpiod_line_request_output(trig_line, &config) < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    if (gpiod_line_set_value(trig_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }

    if (gpiod_line_set_value(echo_line, 0) < 0) {
        perror("gpiod_line_set_value");
        return 1;
    }

    if (gpiod_line_request_both_edges_events(echo_line) < 0) {
        perror("gpiod_line_request_both_edges_events");
        return 1;
    }

    if (gpiod_line_set_event_callback(echo_line, echo_callback, NULL) < 0) {
        perror("gpiod_line_set_event_callback");
