#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <time.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define XSHUT_PIN 27

int main(int argc, char **argv) {
    // Initialize the VL53L1X driver
    if (vl53l1x_init() != 0) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X driver");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return 1;
    }

    // Set the I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        return 1;
    }

    // Set the XSHUT pin as an output and set it high
    if (gpio_export(XSHUT_PIN) < 0) {
        syslog(LOG_ERR, "Failed to export XSHUT pin");
        return 1;
    }
    if (gpio_direction(XSHUT_PIN, GPIO_OUT) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin as output");
        return 1;
    }
    if (gpio_set_value(XSHUT_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin high");
        return 1;
    }

    // Set up the SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read the distance
        int distance = vl53l1x_read_distance(i2c_fd);
        if (distance < 0) {
            syslog(LOG_ERR, "Failed to read distance");
            continue;
        }

        // Log the reading
        char buf[100];
        snprintf(buf, sizeof(buf), "Distance: %d mm", distance);
        syslog(LOG_INFO, buf);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpio_unexport(XSHUT_PIN);
    close(i2c_fd);
    vl53l1x_cleanup();

    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C handle and terminate the driver library
    gpio_unexport(XSHUT_PIN);
    close(i2c_fd);
    vl53l1x_cleanup();

    // Exit cleanly
    exit(0);
}

