#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 24

#define CM_PER_MM 10
#define DIST_THRESHOLD 20

#define LOG_FILE "gate_log.txt"

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        exit(1);
    }

    if (gpioWrite(GPIO_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write to GPIO\n");
        exit(1);
    }
}

static void init_i2c(void) {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
}

static void init_sensor(void) {
    if (vl53l1xInit() < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        exit(1);
    }
}

static void init_log(void) {
    if (open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }
}

static void log_distance(uint16_t distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    char buf[128];
    snprintf(buf, sizeof(buf), "%ld.%06ld, %d\n", tv.tv_sec, tv.tv_usec, distance);

    if (write(LOG_FILE, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        exit(1);
    }
}

static void log_gate_state(bool state) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    char buf[128];
    snprintf(buf, sizeof(buf), "%ld.%06ld, %s\n", tv.tv_sec, tv.tv_usec, state ? "open" : "closed");

    if (write(LOG_FILE, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        exit(1);
    }
}

static void handle_error(int error) {
    fprintf(stderr, "Error: %s\n", strerror(error));
    exit(1);
}

int main(void) {
    init_gpio();
    init_i2c();
    init_sensor();
    init_log();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        uint16_t distance = vl53l1xReadDistance();
        if (distance < 0) {
            handle_error(distance);
        }

        log_distance(distance);

        bool gate_state = (distance < DIST_THRESHOLD) ? true : false;
        if (gate_state != gpioRead(GPIO_PIN)) {
            gpioWrite(GPIO_PIN, gate_state ? PI_HIGH : PI_LOW);
            log_gate_state(gate_state);
        }

        usleep(100000);
    }

    gpioWrite(GPIO_PIN, PI_LOW);
    close(LOG_FILE);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

