#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <pigpiod_if2.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MOVING_AVG_SIZE 5

volatile sig_atomic_t new_pulse = false;
volatile sig_atomic_t pulse_width = 0;

void sigint_handler(int signum) {
    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Close the CSV file
    fclose(csv_file);

    // Clean up the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Start the timer
        start_time = tick;
    } else {
        // Stop the timer
        end_time = tick;

        // Calculate the pulse width
        pulse_width = end_time - start_time;

        // Set the new_pulse flag
        new_pulse = true;
    }
}

int main(void) {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        return 1;
    }

    // Set up the interrupt callback
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt callback\n");
        return 1;
    }

    // Open the CSV file
    csv_file = fopen("distance_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Write the header row
    fprintf(csv_file, "timestamp,distance,angle\n");

    // Set up the moving average filter
    moving_avg = 0;
    moving_avg_count = 0;

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (true) {
        // Check for a new pulse
        if (new_pulse) {
            // Calculate the distance
            distance = pulse_width * 17150 / 1000000;

            // Check for a valid distance reading
            if (distance >= 2 && distance <= 400) {
                // Calculate the angle
                angle = (distance - 2) / 2;

                // Write the data to the CSV file
                fprintf(csv_file, "%ld,%f,%d\n", time(NULL), distance, angle);

                // Update the moving average
                moving_avg += distance;
                moving_avg_count++;
                if (moving_avg_count == MOVING_AVG_SIZE) {
                    moving_avg /= MOVING_AVG_SIZE;
                    moving_avg_count = 0;
                }

                // Set the servo angle
                gpioServo(SERVO_PIN, angle);
            } else {
                // Log an invalid distance reading
                fprintf(csv_file, "%ld,-1.0,90\n", time(NULL));

                // Set the servo angle to 90 degrees
                gpioServo(SERVO_PIN, 90);
            }

            // Clear the new_pulse flag
            new_pulse = false;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up the pigpio library
    gpioTerminate();

    // Close the CSV file
    fclose(csv_file);

    // Exit the program
    return 0;
}

