        // Check for a new pulse
        if (new_pulse) {
            // Calculate the distance
            distance = pulse_width * 17150 / 1000000;

            // Check for a valid distance reading
            if (distance >= 2 && distance <= 400) {
                // Calculate the angle
                angle = (distance - 2) / 2;

                // Write the data to the CSV file
                fprintf(csv_file, "%ld,%f,%d\n", time(NULL), distance, angle);

                // Update the moving average
                moving_avg += distance;
                moving_avg_count++;
                if (moving_avg_count == MOVING_AVG_SIZE) {
                    moving_avg /= MOVING_AVG_SIZE;
                    moving_avg_count = 0;
                }

                // Set the servo angle
                gpioServo(SERVO_PIN, angle);
            } else {
                // Log an invalid distance reading
                fprintf(csv_file, "%ld,-1.0,90\n", time(NULL));

                // Set the servo angle to 90 degrees
                gpioServo(SERVO_PIN, 90);
            }

            // Clear the new_pulse flag
            new_pulse = false;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up the pigpio library
    gpioTerminate();

    // Close the CSV file
    fclose(csv_file);

    // Exit the program
    return 0;
}
