#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <pigpiod_if2.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define PWM_FREQ 2000
#define PWM_DUTY 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQ 200
#define MAX_FREQ 2000

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void set_pwm_freq(int freq) {
    if (freq < MIN_FREQ || freq > MAX_FREQ) {
        fprintf(stderr, "Invalid frequency: %d\n", freq);
        return;
    }

    int err = pigpio_set_PWM_frequency(PWM_PIN, freq);
    if (err < 0) {
        fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(err));
        return;
    }
}

static void set_pwm_duty(int duty) {
    if (duty < 0 || duty > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty);
        return;
    }

    int err = pigpio_set_PWM_dutycycle(PWM_PIN, duty);
    if (err < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(err));
        return;
    }
}

static void read_distance(void) {
    int err;

    // Set trigger pin to low
    err = pigpio_gpio_write(TRIG_PIN, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting trigger pin: %s\n", strerror(err));
        return;
    }

    // Wait for 10 us
    usleep(10);

    // Set trigger pin to high
    err = pigpio_gpio_write(TRIG_PIN, 1);
    if (err < 0) {
        fprintf(stderr, "Error setting trigger pin: %s\n", strerror(err));
        return;
    }

    // Wait for echo pin to go low
    err = pigpio_gpio_wait_for_edge(ECHO_PIN, 0, 200);
    if (err < 0) {
        fprintf(stderr, "Error waiting for echo pin: %s\n", strerror(err));
        return;
    }

    // Read echo pin
    int echo_time = pigpio_gpio_read(ECHO_PIN);
    if (echo_time < 0) {
        fprintf(stderr, "Error reading echo pin: %s\n", strerror(echo_time));
        return;
    }

    // Calculate distance
    int distance = echo_time * 17150;

    // Map distance to frequency
    int freq = (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQ;

    // Set PWM frequency and duty cycle
    set_pwm_freq(freq);
    set_pwm_duty(PWM_DUTY);
}

int main(void) {
    // Initialize pigpio library
    int err = pigpio_start(NULL, NULL);
    if (err < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(err));
        return 1;
    }

    // Set trigger and echo pins to input
    err = pigpio_gpio_mode(TRIG_PIN, PI_INPUT);
    if (err < 0) {
        fprintf(stderr, "Error setting trigger pin: %s\n", strerror(err));
        return 1;
    }
    err = pigpio_gpio_mode(ECHO_PIN, PI_INPUT);
    if (err < 0) {
        fprintf(stderr, "Error setting echo pin: %s\n", strerror(err));
        return 1;
    }

    // Set PWM pin to output
    err = pigpio_gpio_mode(PWM_PIN, PI_OUTPUT);
    if (err < 0) {
        fprintf(stderr, "Error setting PWM pin: %s\n", strerror(err));
        return 1;
    }

    // Set PWM frequency and duty cycle
    set_pwm_freq(PWM_FREQ);
    set_pwm_duty(PWM_DUTY);

    // Set SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        read_distance();
    }

    // Clean up
    pigpio_stop();

    return 0;
}

