This code uses the `pigpio` library to interface with the Raspberry Pi's GPIO pins and the `pigpiod_if2` library to communicate with the `pigpiod` daemon. It sets up the trigger and echo pins as inputs, the PWM pin as an output, and sets the PWM frequency and duty cycle. It then reads the distance from the HC‑SR04 sensor and maps it to a frequency between 200 Hz and 2000 Hz on a logarithmic scale with a 50% duty cycle. It also sets up a SIGINT/SIGTERM handler to cleanly stop the PWM and terminate the driver when the program is interrupted.

Note that this code assumes that the HC‑SR04 sensor is connected to the Raspberry Pi's GPIO pins as follows:

* Trigger pin (TRIG) to GPIO23 (BCM)
* Echo pin (ECHO) to GPIO24 (BCM)
* PWM pin (PWM0) to GPIO18 (BCM)

Also, this code uses the `usleep` function to wait for 10 microseconds between the trigger and echo pins being set to high and low, respectively. This is the recommended delay for the HC‑SR04 sensor according to the datasheet.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define TIMEOUT_MS 100
#define MIN_DISTANCE 5
#define MAX_DISTANCE 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 50

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for TRIG_PIN\n");
        exit(1);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for ECHO_PIN\n");
        exit(1);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for BUZZER_PIN\n");
        exit(1);
    }
}

static void cleanup_gpio(void) {
    gpioTerminate();
}

static void trigger_sensor(void) {
    gpioWrite(TRIG_PIN, PI_LOW);
    usleep(10);
    gpioWrite(TRIG_PIN, PI_HIGH);
    usleep(10);
    gpioWrite(TRIG_PIN, PI_LOW);
}

static int measure_distance(void) {
    struct timeval start, end;
    int distance;

    gpioWrite(TRIG_PIN, PI_LOW);
    usleep(10);
    gpioWrite(TRIG_PIN, PI_HIGH);
    usleep(10);
    gpioWrite(TRIG_PIN, PI_LOW);

    gettimeofday(&start, NULL);
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        gettimeofday(&end, NULL);
        if (end.tv_sec - start.tv_sec > TIMEOUT_MS / 1000) {
            fprintf(stderr, "Echo timeout\n");
            return -1;
        }
    }

    gettimeofday(&end, NULL);
    distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

    return distance;
}

static int map_distance_to_frequency(int distance) {
    int frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MIN_FREQ;
    } else if (distance > MAX_DISTANCE) {
        frequency = MAX_FREQ;
    } else {
        frequency = MIN_FREQ + (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

static void generate_tone(int frequency) {
    gpioPWM(BUZZER_PIN, PWM_FREQ, PWM_DUTY_CYCLE);
}

int main(void) {
    init_gpio();

    signal(SIGINT, sigint_handler);

    while (running) {
        int distance = measure_distance();
        if (distance < 0) {
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        generate_tone(frequency);

        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);

        usleep(10000);
    }

    cleanup_gpio();

    return 0;
}

