    int frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MIN_FREQ;
    } else if (distance > MAX_DISTANCE) {
        frequency = MAX_FREQ;
    } else {
        frequency = MIN_FREQ + (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

static void generate_tone(int frequency) {
    gpioPWM(BUZZER_PIN, PWM_FREQ, PWM_DUTY_CYCLE);
}

int main(void) {
    init_gpio();

    signal(SIGINT, sigint_handler);

    while (running) {
        int distance = measure_distance();
        if (distance < 0) {
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        generate_tone(frequency);

        printf("Distance: %d cm, Frequency: %d Hz\n", distance, frequency);

        usleep(10000);
    }

    cleanup_gpio();

    return 0;
}
```
This code initializes the GPIO pins, sets up the signal handler for SIGINT, and enters an infinite loop where it measures the distance using the HC-SR04 sensor, maps the distance to a frequency range, and generates a tone on the buzzer using the PWM output. The program also handles any sensor read failures gracefully and shuts down the driver library cleanly on program termination.

