#include <stdbool.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_MS 50
#define INVALID_DISTANCE -1

static volatile sig_atomic_t exit_flag = 0;

static void sigint_handler(int signum) {
    exit_flag = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    struct gpiod_line_request *trig_request, *echo_request;
    struct gpiod_line_bulk request_bulk;
    struct gpiod_line_event event;
    int ret;

    // Initialize the GPIO driver
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the trigger and echo pins
    request_bulk = gpiod_line_request_bulk_input(chip, TRIG_PIN, ECHO_PIN);
    if (!request_bulk) {
        fprintf(stderr, "Failed to request GPIO pins\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the trigger and echo lines
    trig_line = gpiod_line_get(chip, TRIG_PIN);
    echo_line = gpiod_line_get(chip, ECHO_PIN);

    // Set the trigger pin as an output initially low
    ret = gpiod_line_request_output(trig_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the echo pin as an input
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!exit_flag) {
        // Trigger the sensor
        ret = gpiod_line_set_value(trig_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger the sensor\n");
            break;
        }
        usleep(10);
        ret = gpiod_line_set_value(trig_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger the sensor\n");
            break;
        }

        // Read the echo pulse duration
        ret = gpiod_line_event_read(echo_line, &event, TIMEOUT_MS);
        if (ret < 0) {
            fprintf(stderr, "Failed to read the echo pulse duration\n");
            break;
        }

        // Convert the pulse duration to distance in centimeters
        int distance = event.duration * 17150 / 1000000;

        // Check if the distance is valid
        if (distance < 2 || distance > 400) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance / 100.0);
            if (distance < 10) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

