#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_ADDR 0x60
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"

int main(void) {
    int fd;
    uint8_t als_visible;
    char timestamp[20];

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "timestamp,als_visible\n");

    // Main loop
    while (1) {
        // Read ambient light value
        if (read(fd, &als_visible, 1) != 1) {
            perror("Failed to read ambient light value");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Write timestamp and ambient light value to log file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_file, "%s,%u\n", timestamp, als_visible);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    close(fd);
    fclose(log_file);

    return 0;
}

