#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define SI1120_I2C_ADDR 0x60
#define SI1120_PART_ID_REG 0x00
#define SI1120_PART_ID_VAL 0x20
#define SI1120_ALS_DATA_REG 0x04
#define SI1120_PS_DATA_REG 0x06
#define SI1120_RESET_REG 0x07
#define SI1120_RESET_VAL 0x01

#define I2C_RETRIES 3
#define I2C_DELAY 10

#define LOG_FILE "si1120_log.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int fd;
    int ret;
    uint8_t part_id;
    uint16_t als_data;
    uint16_t ps_data;
    char timestamp[20];

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Reset the sensor
    if (write(fd, &SI1120_RESET_VAL, 1) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Verify the part ID
    if (read(fd, &part_id, 1) < 0) {
        fprintf(stderr, "Error reading part ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (part_id != SI1120_PART_ID_VAL) {
        fprintf(stderr, "Invalid part ID: %02x\n", part_id);
        close(fd);
        return 1;
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read ALS data
        ret = read(fd, &als_data, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        if (ret != 2) {
            fprintf(stderr, "Incomplete ALS data read: %d\n", ret);
            close(fd);
            return 1;
        }

        // Read PS data
        ret = read(fd, &ps_data, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading PS data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        if (ret != 2) {
            fprintf(stderr, "Incomplete PS data read: %d\n", ret);
            close(fd);
            return 1;
        }

        // Combine ALS and PS data into 16-bit little-endian values
        als_data = (als_data[0] << 8) | als_data[1];
        ps_data = (ps_data[0] << 8) | ps_data[1];

        // Get timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to log file
        ret = write(fd, timestamp, strlen(timestamp));
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        ret = write(fd, ", ALS: ", 7);
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        ret = write(fd, &als_data, 2);
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        ret = write(fd, ", PS: ", 6);
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        ret = write(fd, &ps_data, 2);
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        ret = write(fd, "\n", 1);
        if (ret < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close log file
    close(fd);

    // Close I2C bus
    close(fd);

    return 0;
}

