    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Verify sensor by reading part ID
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }
    if (read(fd, &part_id, 1) < 0) {
        perror("Failed to read part ID");
        close(fd);
        return 1;
    }
    if (part_id != 0x40) {
        fprintf(stderr, "Invalid part ID: 0x%02x\n", part_id);
        close(fd);
        return 1;
    }

    // Configure measurement rate
    meas_rate = I2C_MEAS_RATE_100MS;
    if (write(fd, &meas_rate, 1) < 0) {
        perror("Failed to write measurement rate");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(CSV_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ambient light and proximity data
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(fd);
            fclose(log_file);
            return 1;
        }
        if (read(fd, &ambient_light, 2) < 0) {
            perror("Failed to read ambient light");
            close(fd);
            fclose(log_file);
            return 1;
        }
        if (read(fd, &proximity, 2) < 0) {
            perror("Failed to read proximity");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Print timestamped reading to stdout
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%L", localtime(&now));
        printf("%s, %d, %d\n", timestamp, ambient_light, proximity);

        // Write timestamped reading to log file
        fprintf(log_file, "%s, %d, %d\n", timestamp, ambient_light, proximity);
    }

    // Close I2C device and log file
    close(fd);
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, closing I2C device and log file\n");
    close(fd);
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, closing I2C device and log file\n");
    close(fd);
    fclose(log_file);
    exit(0);
}

