#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

#define TRIG_PULSE_WIDTH 10
#define MIN_DISTANCE 20

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void trigger_callback(struct gpiod_line *line, void *data) {
    struct timespec start, end;
    uint64_t duration;

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pulse to end
    while (gpiod_line_get_value(line) == 1) {
        usleep(100);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Compute the distance
    double distance = (duration / 2) * 17150;

    // Print the distance to stdout
    printf("Distance: %.2f cm\n", distance);

    // Set the buzzer pin high if the distance is under 20 cm
    if (distance < MIN_DISTANCE) {
        gpiod_line_set_value(data, 1);
    } else {
        gpiod_line_set_value(data, 0);
    }
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *buzzer_line;
    struct gpiod_line_request *trig_request, *echo_request, *buzzer_request;
    struct gpiod_line_event *event;
    struct timespec start, end;
    uint64_t duration;

    // Initialize the driver library
    if (gpiod_chip_open_by_name("gpiochip0", &chip) != 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the trigger, echo, and buzzer pins
    if (gpiod_chip_get_line(chip, TRIG_PIN, &trig_line) != 0) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }
    if (gpiod_chip_get_line(chip, ECHO_PIN, &echo_line) != 0) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }
    if (gpiod_chip_get_line(chip, BUZZER_PIN, &buzzer_line) != 0) {
        fprintf(stderr, "Failed to get buzzer line\n");
        return 1;
    }

    // Set the trigger and echo pins as output
    if (gpiod_line_request_output(trig_line, "trigger", 0) != 0) {
        fprintf(stderr, "Failed to set trigger line as output\n");
        return 1;
    }
    if (gpiod_line_request_output(echo_line, "echo", 0) != 0) {
        fprintf(stderr, "Failed to set echo line as output\n");
        return 1;
    }

    // Set the buzzer pin as output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) != 0) {
        fprintf(stderr, "Failed to set buzzer line as output\n");
        return 1;
    }

    // Set the trigger pin high for 10 µs
    gpiod_line_set_value(trig_line, 1);
    usleep(TRIG_PULSE_WIDTH);
    gpiod_line_set_value(trig_line, 0);

    // Set the buzzer pin low
    gpiod_line_set_value(buzzer_line, 0);

    // Set the echo pin as input
    if (gpiod_line_request_input(echo_line, "echo") != 0) {
        fprintf(stderr, "Failed to set echo line as input\n");
        return 1;
    }

    // Set the rising/falling edge alert callback for the echo pin
    if (gpiod_line_request_event(echo_line, "echo", GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE, trigger_callback, buzzer_line) != 0) {
        fprintf(stderr, "Failed to set event callback\n");
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Wait for the next event
        event = gpiod_line_event_wait(echo_line, -1);

        // Check if the event is a rising edge
        if (event->event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Record the start time
            clock_gettime(CLOCK_MONOTONIC, &start);
        }

        // Check if the event is a falling edge
        if (event->event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Record the end time
            clock_gettime(CLOCK_MONOTONIC, &end);

            // Compute the duration
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

            // Compute the distance
            double distance = (duration / 2) * 17150;

            // Print the distance to stdout
            printf("Distance: %.2f cm\n", distance);

            // Set the buzzer pin high if the distance is under 20 cm
            if (distance < MIN_DISTANCE) {
                gpiod_line_set_value(buzzer_line, 1);
            } else {
                gpiod_line_set_value(buzzer_line, 0);
            }
        }

        // Free the event
        gpiod_line_event_free(event);
    }

    // Clean up
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

