#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define TIMEOUT_US 100000
#define RETRY_DELAY_US 10000

#define MIN_DISTANCE 200
#define MAX_DISTANCE 20

#define MIN_ANGLE 0
#define MAX_ANGLE 180

#define ANGLE_STEP 1

#define SIGINT_HANDLER void sigint_handler(int signum)

int main(void) {
    // Initialize the GPIO library
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Initialize the PWM library
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM library\n");
        return 1;
    }

    // Set up the GPIO pins
    gpiod_set_direction(TRIG_PIN, GPIOD_OUT);
    gpiod_set_direction(ECHO_PIN, GPIOD_IN);
    gpiod_set_direction(SERVO_PIN, GPIOD_OUT);

    // Set up the PWM pin
    pigpio_set_mode(SERVO_PIN, PI_OUTPUT);

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the distance
        double distance = read_distance();

        // Calculate the servo angle
        int angle = calculate_angle(distance);

        // Set the servo angle
        set_servo_angle(angle);

        // Print the distance and angle
        printf("Distance: %f cm, Angle: %d\n", distance, angle);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_cleanup();
    pigpio_cleanup();

    return 0;
}

// Read the distance from the HC-SR04 sensor
double read_distance() {
    // Set the trigger pin high for 10 us
    gpiod_set_value(TRIG_PIN, 1);
    usleep(10);
    gpiod_set_value(TRIG_PIN, 0);

    // Wait for the echo pin to go high
    while (gpiod_get_value(ECHO_PIN) == 0) {
        usleep(10);
    }

    // Measure the time it takes for the echo pin to go low
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_get_value(ECHO_PIN) == 1) {
        usleep(10);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the distance
    double distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    // Return the distance
    return distance;
}

// Calculate the servo angle based on the distance
int calculate_angle(double distance) {
    // Calculate the angle
    int angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;

    // Return the angle
    return angle;
}

// Set the servo angle
void set_servo_angle(int angle) {
    // Set the PWM duty cycle
    pigpio_set_dutycycle(SERVO_PIN, angle);
}

// SIGINT handler
SIGINT_HANDLER {
    // Stop the PWM
    pigpio_stop(SERVO_PIN);

    // Clean up
    gpiod_cleanup();
    pigpio_cleanup();

    // Exit
    exit(0);
}
