#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_CENTER_PULSE_WIDTH (SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 2)
#define TIMEOUT_MS 50
#define PAUSE_MS 100

static int gpio_fd;
static int servo_fd;

static void sigint_handler(int signum) {
    printf("Received SIGINT, stopping servo...\n");
    gpio_write(gpio_fd, SERVO_PIN, SERVO_MIN_PULSE_WIDTH);
    gpio_close(gpio_fd);
    exit(0);
}

int main(int argc, char **argv) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    // Initialize GPIO
    gpio_fd = gpio_open(TRIG_PIN, ECHO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", gpio_error(gpio_fd));
        return 1;
    }

    // Initialize servo
    servo_fd = gpio_open(SERVO_PIN, GPIO_OUTPUT);
    if (servo_fd < 0) {
        fprintf(stderr, "Failed to open servo: %s\n", gpio_error(servo_fd));
        gpio_close(gpio_fd);
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Trigger pulse
        gpio_write(gpio_fd, TRIG_PIN, 1);
        usleep(10);
        gpio_write(gpio_fd, TRIG_PIN, 0);

        // Wait for echo
        int64_t start_time = gpio_time(gpio_fd);
        int64_t end_time = start_time + TIMEOUT_MS * 1000;
        int64_t echo_time = gpio_wait(gpio_fd, ECHO_PIN, GPIO_RISING_EDGE, end_time);
        if (echo_time < 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        // Calculate distance
        double distance = (echo_time - start_time) * 17150.0;
        if (distance < 0.0) {
            fprintf(stderr, "Invalid distance: %f\n", distance);
            continue;
        }

        // Map distance to angle
        double angle = 0.0;
        if (distance < 20.0) {
            angle = 0.0;
        } else if (distance > 200.0) {
            angle = 180.0;
        } else {
            angle = (distance - 20.0) / (200.0 - 20.0) * 160.0;
        }

        // Set servo angle
        gpio_write(servo_fd, SERVO_PIN, SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) * angle / 180.0);

        // Print distance and angle
        printf("Distance: %f cm, Angle: %f°\n", distance, angle);

        // Pause before next measurement
        usleep(PAUSE_MS * 1000);
    }

    // Clean up
    gpio_close(gpio_fd);
    gpio_close(servo_fd);

    return 0;
}

