#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define MEASURE_REG 0x05

#define READ_DELAY 10
#define WRITE_DELAY 10

#define MAX_RETRIES 3

int main(void) {
    int fd;
    int ret;
    int i;
    uint8_t config;
    uint8_t measure;
    uint8_t data[2];

    // Initialize the I2C bus
    fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        perror("i2c_open");
        return 1;
    }

    // Initialize the driver library
    ret = gpiod_init();
    if (ret < 0) {
        perror("gpiod_init");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Configure the sensor
    config = 0x00;
    ret = i2c_write(fd, CONFIG_REG, &config, 1);
    if (ret < 0) {
        perror("i2c_write");
        goto error;
    }

    // Read the sensor data
    while (1) {
        // Write the register address to be read
        ret = i2c_write(fd, MEASURE_REG, &measure, 1);
        if (ret < 0) {
            perror("i2c_write");
            goto error;
        }

        // Wait for conversion
        usleep(READ_DELAY * 1000);

        // Read the data
        ret = i2c_read(fd, data, 2);
        if (ret < 0) {
            perror("i2c_read");
            goto error;
        }

        // Print the data
        printf("Humidity: %d.%d%%, Temperature: %d.%d°C\n", data[0] >> 1, data[0] & 0x01, data[1] >> 1, data[1] & 0x01);

        // Wait for next read
        sleep(2);
    }

error:
    // Close the I2C handle
    i2c_close(fd);

    // Close the driver library
    gpiod_close();

    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C handle
    i2c_close(fd);

    // Close the driver library
    gpiod_close();

    // Exit the program
    exit(0);
}

