#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define ACCEL_XOUTH_REG 0x3B
#define ACCEL_XOUTL_REG 0x3C
#define ACCEL_YOUTH_REG 0x3D
#define ACCEL_YOUTL_REG 0x3E
#define ACCEL_ZOUTH_REG 0x3F
#define ACCEL_ZOUTL_REG 0x40
#define TEMP_OUTH_REG 0x41
#define TEMP_OUTL_REG 0x42
#define GYRO_XOUTH_REG 0x43
#define GYRO_XOUTL_REG 0x44
#define GYRO_YOUTH_REG 0x45
#define GYRO_YOUTL_REG 0x46
#define GYRO_ZOUTH_REG 0x47
#define GYRO_ZOUTL_REG 0x48

#define ACCEL_SCALE 16384.0
#define GYRO_SCALE 131.0

int main(int argc, char **argv) {
    int fd;
    uint8_t who_am_i;
    int16_t accel_x, accel_y, accel_z;
    int16_t temp;
    int16_t gyro_x, gyro_y, gyro_z;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Verify the sensor is present
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Sensor not present\n");
        close(fd);
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the accelerometer data
        if (read(fd, &accel_x, 2) != 2) {
            perror("Failed to read accelerometer X data");
            close(fd);
            return 1;
        }
        if (read(fd, &accel_y, 2) != 2) {
            perror("Failed to read accelerometer Y data");
            close(fd);
            return 1;
        }
        if (read(fd, &accel_z, 2) != 2) {
            perror("Failed to read accelerometer Z data");
            close(fd);
            return 1;
        }

        // Read the temperature data
        if (read(fd, &temp, 2) != 2) {
            perror("Failed to read temperature data");
            close(fd);
            return 1;
        }

        // Read the gyroscope data
        if (read(fd, &gyro_x, 2) != 2) {
            perror("Failed to read gyroscope X data");
            close(fd);
            return 1;
        }
        if (read(fd, &gyro_y, 2) != 2) {
            perror("Failed to read gyroscope Y data");
            close(fd);
            return 1;
        }
        if (read(fd, &gyro_z, 2) != 2) {
            perror("Failed to read gyroscope Z data");
            close(fd);
            return 1;
        }

        // Print the data to stdout
        printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Temperature: %d\n", temp);
        printf("Gyroscope: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    return 0;
}

void sigint_handler(int signum) {
    printf("Caught SIGINT\n");
    close(fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Caught SIGTERM\n");
    close(fd);
    exit(0);
}

