int main(int argc, char **argv) {
    int fd;
    uint8_t who_am_i;
    int16_t accel_x, accel_y, accel_z;
    int16_t temp;
    int16_t gyro_x, gyro_y, gyro_z;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Verify the sensor is present
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Sensor not present\n");
        close(fd);
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the accelerometer data
        if (read(fd, &accel_x, 2) != 2) {
            perror("Failed to read accelerometer X data");
            close(fd);
            return 1;
        }
        if (read(fd, &accel_y, 2) != 2) {
            perror("Failed to read accelerometer Y data");
            close(fd);
            return 1;
