#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REPEATABILITY 0x2C
#define SHT40_CMD_READ_MEASUREMENT 0xE0
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

#define I2C_BUS 1
#define I2C_ADDR SHT40_ADDR

#define TEMPERATURE_OFFSET 0x00
#define HUMIDITY_OFFSET 0x02
#define CRC_OFFSET 0x04

#define TEMPERATURE_CRC_OFFSET 0x01
#define HUMIDITY_CRC_OFFSET 0x03

#define TEMPERATURE_SCALE 175.72
#define HUMIDITY_SCALE 125.0

#define READ_INTERVAL 5

int main(int argc, char **argv) {
    int i2c_fd;
    uint8_t buf[6];
    uint16_t temperature, humidity;
    uint8_t crc;

    // Initialize the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Trigger high repeatability measurement
        if (i2c_write(i2c_fd, SHT40_CMD_HIGH_REPEATABILITY, 1) < 0) {
            fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
            goto error;
        }

        // Wait at least 10 ms
        usleep(10000);

        // Read measurement
        if (i2c_read(i2c_fd, buf, 6) < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            goto error;
        }

        // Validate CRC
        crc = crc8(buf, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT);
        if (crc != buf[TEMPERATURE_CRC_OFFSET]) {
            fprintf(stderr, "Error validating temperature CRC: %02X != %02X\n", crc, buf[TEMPERATURE_CRC_OFFSET]);
            goto error;
        }

        crc = crc8(buf + 2, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT);
        if (crc != buf[HUMIDITY_CRC_OFFSET]) {
            fprintf(stderr, "Error validating humidity CRC: %02X != %02X\n", crc, buf[HUMIDITY_CRC_OFFSET]);
            goto error;
        }

        // Convert temperature and humidity
        temperature = (buf[TEMPERATURE_OFFSET] << 8) | buf[TEMPERATURE_OFFSET + 1];
        humidity = (buf[HUMIDITY_OFFSET] << 8) | buf[HUMIDITY_OFFSET + 1];

        // Print temperature and humidity
        printf("Temperature: %d.%02d°C\n", temperature / TEMPERATURE_SCALE, (temperature % TEMPERATURE_SCALE) * 100 / TEMPERATURE_SCALE);
        printf("Humidity: %d.%02d%%\n", humidity / HUMIDITY_SCALE, (humidity % HUMIDITY_SCALE) * 100 / HUMIDITY_SCALE);

        // Wait for next measurement
        sleep(READ_INTERVAL);
    }

error:
    // Close I2C handle
    i2c_close(i2c_fd);

    // Terminate driver library
    pigpio_terminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle
    i2c_close(i2c_fd);

    // Terminate driver library
    pigpio_terminate();

    exit(0);
}

void sigterm_handler(int signum) {
    // Close I2C handle
    i2c_close(i2c_fd);

    // Terminate driver library
    pigpio_terminate();

    exit(0);
}

