#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_REG_TA 0x06
#define MLX90614_REG_TOBJ1 0x07
#define MLX90614_REG_TOBJ2 0x08

#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"

int main(void) {
    int fd;
    int ret;
    int16_t ta, tobj1, tobj2;
    char buf[10];
    FILE *log_file;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[2];
    struct timespec ts;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, MLX90614_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set up I2C read message
    msgs[0].addr = MLX90614_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buf;

    // Set up I2C write message
    msgs[1].addr = MLX90614_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = buf;

    // Set up I2C read/write data
    data.msgs = msgs;
    data.nmsgs = 2;

    while (1) {
        // Read ambient temperature
        msgs[0].buf[0] = MLX90614_REG_TA;
        ret = ioctl(fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read ambient temperature");
            close(fd);
            fclose(log_file);
            return 1;
        }
        ta = (int16_t)((buf[0] << 8) | buf[1]);

        // Read object temperature
        msgs[0].buf[0] = MLX90614_REG_TOBJ1;
        ret = ioctl(fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read object temperature");
            close(fd);
            fclose(log_file);
            return 1;
        }
        tobj1 = (int16_t)((buf[0] << 8) | buf[1]);

        // Read object temperature
        msgs[0].buf[0] = MLX90614_REG_TOBJ2;
        ret = ioctl(fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read object temperature");
            close(fd);
            fclose(log_file);
            return 1;
        }
        tobj2 = (int16_t)((buf[0] << 8) | buf[1]);

        // Write to log file
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, ta, tobj1, tobj2);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(fd);
    fclose(log_file);

    return 0;
}

