#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_READ_TIMEOUT 1000
#define I2C_WRITE_TIMEOUT 1000
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 1000

#define SENSOR_READ_INTERVAL 100

volatile sig_atomic_t running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C bus
    int i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, I2C_READ_TIMEOUT, I2C_WRITE_TIMEOUT);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pigpio_i2c_close(i2c_fd);
        return 1;
    }

    // Set up I2C read buffer
    uint8_t read_buf[6];

    // Set up I2C write buffer
    uint8_t write_buf[1];
    write_buf[0] = 0x00; // Trigger continuous measurement

    // Set up timestamp
    time_t timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    // Set up pressure and temperature variables
    int16_t pressure;
    int16_t temperature;

    // Main loop
    while (running) {
        // Trigger continuous measurement
        if (pigpio_i2c_write(i2c_fd, write_buf, 1) < 0) {
            fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Wait at least 1 ms after trigger
        usleep(1000);

        // Read response
        if (pigpio_i2c_read(i2c_fd, read_buf, 6) < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Convert pressure and temperature values
        pressure = (read_buf[0] << 8) | read_buf[1];
        temperature = (read_buf[3] << 8) | read_buf[4];

        // Get timestamp
        timestamp = time(NULL);
        timeinfo = localtime(&timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write to log file
        fprintf(log_file, "%s, %d, %d\n", timestamp_str, pressure, temperature);
        fflush(log_file);

        // Sleep for sampling interval
        usleep(SENSOR_READ_INTERVAL * 1000);
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Invoke library cleanup API
    pigpio_cleanup();

    return 0;
}

