#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_READ_TIMEOUT 20
#define SAMPLE_INTERVAL 5

int main(void) {
    int fd, i2c_fd, ret;
    char *filename = "sensor_data.txt";
    char buf[2];
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct timespec ts;

    // Initialize the I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the sensor
    if ((fd = libgpiod_init(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to initialize sensor: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    if ((fd = open(filename, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the I2C message
    msg.addr = I2C_ADDR;
    msg.flags = 0;
    msg.len = 2;
    msg.buf = buf;

    // Set up the I2C read/write data
    ioctl_data.msgs = &msg;
    ioctl_data.nmsgs = 1;

    // Set up the timestamp
    clock_gettime(CLOCK_REALTIME, &ts);

    // Main loop
    while (1) {
        // Take a temperature reading
        msg.buf[0] = 0xE3;
        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            return 1;
        }

        // Take a humidity reading
        msg.buf[0] = 0xE5;
        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
            return 1;
        }

        // Print the timestamped values to the console
        printf("%ld.%ld: Temperature: %d°C, Humidity: %d%%\n", ts.tv_sec, ts.tv_nsec, buf[0], buf[1]);

        // Write the timestamped values to the log file
        dprintf(fd, "%ld.%ld: Temperature: %d°C, Humidity: %d%%\n", ts.tv_sec, ts.tv_nsec, buf[0], buf[1]);

        // Sleep for the sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    close(i2c_fd);
    close(fd);
    libgpiod_exit(fd);

    return 0;
}

