#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_GPIO 18
#define FAN_ON_TEMP 28.0
#define FAN_OFF_TEMP 27.0
#define BUFFER_SIZE 60

struct reading {
    float temperature;
    time_t timestamp;
};

struct reading buffer[BUFFER_SIZE];
int buffer_index = 0;

void fan_on(void) {
    gpiod_set_value(FAN_GPIO, 1);
}

void fan_off(void) {
    gpiod_set_value(FAN_GPIO, 0);
}

void handle_sigint(int signal) {
    fan_off();
    gpiod_close(FAN_GPIO);
    pigpio_close();
    exit(0);
}

int main(void) {
    // Initialize the GPIO pin for the fan
    gpiod_init(FAN_GPIO, GPIOD_OUTPUT);
    fan_off();

    // Initialize the I2C bus
    pigpio_init();
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (true) {
        // Read the temperature from the sensor
        int retries = 0;
        while (retries < 3) {
            int16_t temperature = 0;
            int result = pigpio_i2c_read(i2c_handle, I2C_ADDR, 0, (uint8_t *)&temperature, 2);
            if (result < 0) {
                fprintf(stderr, "Error reading temperature: %s\n", pigpio_error(result));
                retries++;
                continue;
            }
            break;
        }
        if (retries == 3) {
            fprintf(stderr, "Error reading temperature: %s\n", pigpio_error(result));
            return 1;
        }

        // Convert the temperature to a float
        float temperature = (float)temperature / 100.0;

        // Check if the temperature is above the threshold
        if (temperature > FAN_ON_TEMP) {
            fan_on();
        } else if (temperature < FAN_OFF_TEMP) {
            fan_off();
        }

        // Add the reading to the buffer
        buffer[buffer_index].temperature = temperature;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Print the reading to stdout
        printf("%.2f°C\n", temperature);

        // Wait for at least 10 ms before reading again
        usleep(10000);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    pigpio_close();
    gpiod_close(FAN_GPIO);
    return 0;
}

