#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/mman.h>
#include <libgpiod.h>

#define TMP05_PIN 4
#define TMP05_LOW_TIME 50
#define TMP05_HIGH_TIME 100
#define TMP05_CYCLE_TIME 200
#define TMP05_TEMP_RANGE -40.0f
#define TMP05_TEMP_RANGE 150.0f
#define TMP05_TEMP_STEP 0.01f
#define TMP05_TEMP_ERROR -1.0f

#define TMP05_LOG_FILE "temperature_log.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void sigterm_handler(int signum) {
    running = 0;
}

static void init_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void log_temperature(float temperature) {
    FILE *fp = fopen(TMP05_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
}

static void log_error(const char *message) {
    FILE *fp = fopen(TMP05_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    fprintf(fp, "%s,ERROR,%s\n", timestamp, message);
    fclose(fp);
}

int main() {
    init_signal_handlers();

    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Set up the GPIO pin for input
    struct gpiod_line *line = gpiod_chip_get_line(chip, TMP05_PIN);
    if (line == NULL) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_input(line, "tmp05");

    // Open the log file
    FILE *fp = fopen(TMP05_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for the start of a new cycle
        gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE);

        // Measure the high and low times
        uint64_t high_time = 0;
        uint64_t low_time = 0;
        uint64_t cycle_time = 0;
        while (gpiod_line_get_value(line) == 1) {
            high_time += gpiod_line_get_value_timestamp(line);
        }
        while (gpiod_line_get_value(line) == 0) {
            low_time += gpiod_line_get_value_timestamp(line);
        }
        cycle_time = high_time + low_time;

        // Compute the temperature
        float temperature = (float)high_time / (float)cycle_time * 100.0f;

        // Check for errors
        if (temperature < TMP05_TEMP_RANGE || temperature > TMP05_TEMP_RANGE) {
            log_error("Temperature out of range");
            continue;
        }

        // Log the temperature
        log_temperature(temperature);
    }

    // Clean up
    fclose(fp);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

