#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CONV_TIME 45
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define CRC_XOR 0x00
#define CRC_MASK 0xFF

#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 5

int main(void) {
    int fd, i2c_fd, ret;
    uint8_t buf[9];
    uint16_t pressure;
    uint8_t crc;
    struct timeval tv;
    struct tm *tm;
    char time_str[20];

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send continuous measurement command
        buf[0] = 0x20;
        buf[1] = 0x00;
        ret = write(i2c_fd, buf, 2);
        if (ret < 0) {
            perror("Failed to send measurement command");
            close(i2c_fd);
            close(fd);
            return 1;
        }

        // Wait for conversion time
        usleep(CONV_TIME * 1000);

        // Read pressure data
        ret = read(i2c_fd, buf, 9);
        if (ret < 0) {
            perror("Failed to read pressure data");
            close(i2c_fd);
            close(fd);
            return 1;
        }

        // Validate CRC
        crc = buf[8];
        for (int i = 0; i < 8; i++) {
            crc = crc_update(crc, buf[i]);
        }
        if (crc != CRC_INIT) {
            fprintf(stderr, "CRC failure\n");
            close(i2c_fd);
            close(fd);
            return 1;
        }

        // Extract pressure data
        pressure = (buf[0] << 8) | buf[1];

        // Get current time
        gettimeofday(&tv, NULL);
        tm = localtime(&tv.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        // Log pressure reading
        fprintf(fd, "%s, %d\n", time_str, pressure);

        // Sleep for LOG_INTERVAL seconds
        sleep(LOG_INTERVAL);
    }

    // Clean up
    close(i2c_fd);
    close(fd);
    return 0;
}

uint8_t crc_update(uint8_t crc, uint8_t data) {
    uint8_t i;
    crc ^= data;
    for (i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ CRC_POLY;
        } else {
            crc <<= 1;
        }
    }
    return crc;
}

