#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_ADDR 0x28
#define I2C_BUS 1
#define FAN_PIN 18
#define FAN_FREQ 25000
#define SAMPLE_PERIOD 100

int main(int argc, char *argv[]) {
  // Initialize the I2C bus
  int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE);
  if (i2c_fd < 0) {
    fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
    return 1;
  }

  // Initialize the PWM fan
  int fan_fd = pigpio_open(FAN_PIN, PI_OUTPUT);
  if (fan_fd < 0) {
    fprintf(stderr, "Error opening PWM fan: %s\n", strerror(errno));
    return 1;
  }
  pigpio_set_mode(fan_fd, PI_OUTPUT);
  pigpio_set_frequency(fan_fd, FAN_FREQ);

  // Open the log file
  FILE *log_file = fopen("flow_log.txt", "w");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    return 1;
  }

  // Set up the signal handler
  struct sigaction sigint_action;
  sigint_action.sa_handler = sigint_handler;
  sigint_action.sa_flags = 0;
  sigemptyset(&sigint_action.sa_mask);
  sigaction(SIGINT, &sigint_action, NULL);

  // Main loop
  while (1) {
    // Read the differential pressure from the sensor
    uint16_t pressure = 0;
    if (i2c_read(i2c_fd, &pressure, 2) != 2) {
      fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
      return 1;
    }

    // Compute the flow rate
    float flow_rate = pressure * 1000.0 / SAMPLE_PERIOD;

    // Set the PWM duty cycle
    pigpio_set_dutycycle(fan_fd, flow_rate);

    // Log the measurement
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld,%.2f\n", tv.tv_sec, tv.tv_usec, flow_rate);
  }

  // Clean up on exit
  pigpio_close(fan_fd);
  i2c_close(i2c_fd);
  fclose(log_file);

  return 0;
}

void sigint_handler(int signum) {
  // Turn off the fan
  pigpio_set_dutycycle(fan_fd, 0);

  // Close the I2C handle
  i2c_close(i2c_fd);

  // Flush and close the log file
  fflush(log_file);
  fclose(log_file);

  // Terminate the driver library
  pigpio_terminate();

  // Exit the program
  exit(0);
}
