#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_PIN 17

#define BUFFER_SIZE 10

int main(void) {
    // Initialize the GPIO library
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set up the circular buffer
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up the LED pin
    gpiod_line_set_value(LED_PIN, 0);

    while (1) {
        // Read the temperature from the sensor
        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature from sensor\n");
            continue;
        }

        // Convert the temperature to a float
        float temperature = (data[0] << 8) | data[1];

        // Add the temperature to the buffer
        buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Compute the running average
        float average = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            average += buffer[i];
        }
        average /= BUFFER_SIZE;

        // Turn the LED on or off based on the average temperature
        if (average > 28.0) {
            gpiod_line_set_value(LED_PIN, 1);
        } else {
            gpiod_line_set_value(LED_PIN, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    gpiod_cleanup();

    return 0;
}

void sigint_handler(int signum) {
    // Turn the LED off
    gpiod_line_set_value(LED_PIN, 0);

    // Close the I2C handle
    close(i2c_fd);

    // Clean up
    gpiod_cleanup();

    // Exit the program
    exit(0);
}

