#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_MEASUREMENT_INTERVAL 5
#define SCD30_LOG_FILE "air_quality.log"

#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200

#define VENTILATION_OFF 0
#define VENTILATION_LOW 1
#define VENTILATION_HIGH 2

#define SIGINT_HANDLER 1
#define SIGTERM_HANDLER 2

static int gpio_handle;
static int i2c_handle;
static int log_file;
static int ventilation_state = VENTILATION_OFF;

static void sigint_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, stopping measurement and closing handles\n");
        gpiod_close(gpio_handle);
        i2c_close(i2c_handle);
        fclose(log_file);
        pigpio_stop();
        exit(0);
    }
}

static void sigterm_handler(int signum) {
    if (signum == SIGTERM) {
        printf("Received SIGTERM, stopping measurement and closing handles\n");
        gpiod_close(gpio_handle);
        i2c_close(i2c_handle);
        fclose(log_file);
        pigpio_stop();
        exit(0);
    }
}

static void init_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void init_gpio() {
    gpio_handle = gpiod_open(0, 0, 0);
    if (gpio_handle < 0) {
        printf("Failed to open GPIO handle: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_i2c() {
    i2c_handle = i2c_open(1, 0, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C handle: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_log() {
    log_file = fopen(SCD30_LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_sensors() {
    uint8_t cmd[2] = {0x21, 0x00};
    uint8_t resp[3];
    int ret = i2c_write(i2c_handle, SCD30_I2C_ADDR, cmd, 2, resp, 3);
    if (ret < 0) {
        printf("Failed to write to I2C: %s\n", strerror(errno));
        exit(1);
    }
    if (resp[0] != 0x00 || resp[1] != 0x00 || resp[2] != 0x00) {
        printf("Sensor not responding: %02x %02x %02x\n", resp[0], resp[1], resp[2]);
        exit(1);
    }
}

static void read_sensors() {
    uint8_t cmd[2] = {0x22, 0x00};
    uint8_t resp[18];
    int ret = i2c_write(i2c_handle, SCD30_I2C_ADDR, cmd, 2, resp, 18);
    if (ret < 0) {
        printf("Failed to read from I2C: %s\n", strerror(errno));
        exit(1);
    }
    if (resp[0] != 0x00 || resp[1] != 0x00 || resp[2] != 0x00) {
        printf("Sensor not responding: %02x %02x %02x\n", resp[0], resp[1], resp[2]);
        exit(1);
    }
    uint16_t co2 = (resp[0] << 8) | resp[1];
    uint16_t temp = (resp[2] << 8) | resp[3];
    uint16_t hum = (resp[4] << 8) | resp[5];
    if (co2 < CO2_LOW_THRESHOLD) {
        ventilation_state = VENTILATION_OFF;
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        ventilation_state = VENTILATION_LOW;
    } else {
        ventilation_state = VENTILATION_HIGH;
    }
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, co2, temp, hum);
    fflush(log_file);
}

static void ventilation_control() {
    switch (ventilation_state) {
        case VENTILATION_OFF:
            gpiod_set_value(gpio_handle, 0, 0);
            break;
        case VENTILATION_LOW:
            gpiod_set_value(gpio_handle, 0, 1);
            break;
        case VENTILATION_HIGH:
            gpiod_set_value(gpio_handle, 0, 2);
            break;
    }
}

int main() {
    init_handlers();
    init_gpio();
    init_i2c();
    init_log();
    init_sensors();
    while (1) {
        read_sensors();
        ventilation_control();
        sleep(SCD30_MEASUREMENT_INTERVAL);
    }
    return 0;
}

