#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define I2C_REG_PRESSURE 0x00

#define SIGINT_HANDLER(sig) \
    void sigint_handler(int sig) { \
        printf("Received signal %d, exiting...\n", sig); \
        exit(EXIT_SUCCESS); \
    }

#define SIGTERM_HANDLER(sig) \
    void sigterm_handler(int sig) { \
        printf("Received signal %d, exiting...\n", sig); \
        exit(EXIT_SUCCESS); \
    }

int main(void) {
    // Initialize the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_REG_PRESSURE);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize the signal handlers
    SIGINT_HANDLER(SIGINT);
    SIGTERM_HANDLER(SIGTERM);

    // Set up the I2C read buffer
    uint8_t read_buf[2];

    // Set up the I2C write buffer
    uint8_t write_buf[1];
    write_buf[0] = I2C_REG_PRESSURE;

    // Set up the pressure value
    uint16_t pressure = 0;

    // Set up the timestamp
    time_t timestamp;

    // Loop forever
    while (1) {
        // Read the pressure value from the sensor
        if (i2c_read(i2c_fd, read_buf, 2) != 2) {
            printf("Failed to read pressure value: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        // Convert the pressure value to a 16-bit integer
        pressure = (read_buf[0] << 8) | read_buf[1];

        // Get the current timestamp
        timestamp = time(NULL);

        // Print the pressure value and timestamp to the console
        printf("Pressure: %d, Timestamp: %s\n", pressure, ctime(&timestamp));

        // Sleep for 500 milliseconds
        usleep(500000);
    }

    // Close the I2C bus
    i2c_close(i2c_fd);

    // Release the resources
    return EXIT_SUCCESS;
}

