#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_READ_TIMEOUT 1000
#define I2C_WRITE_TIMEOUT 1000
#define I2C_READ_RETRIES 3
#define I2C_WRITE_RETRIES 3

#define TEMP_REG 0x00
#define PRESS_REG 0x01
#define DEFAULT_TEMP 0x8000
#define DEFAULT_PRESS 0x8000

#define SIGINT_HANDLER(sig) \
    void sigint_handler(int sig) { \
        printf("Received SIGINT, closing I2C handle\n"); \
        gpiod_close(i2c_handle); \
        pigpio_cleanup(); \
        exit(EXIT_SUCCESS); \
    }

#define SIGTERM_HANDLER(sig) \
    void sigterm_handler(int sig) { \
        printf("Received SIGTERM, closing I2C handle\n"); \
        gpiod_close(i2c_handle); \
        pigpio_cleanup(); \
        exit(EXIT_SUCCESS); \
    }

int main(void) {
    // Initialize I2C handle
    gpiod_handle_t i2c_handle;
    if (gpiod_open(I2C_BUS, I2C_ADDR, &i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return EXIT_FAILURE;
    }

    // Initialize PIGPIO
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize PIGPIO\n");
        return EXIT_FAILURE;
    }

    // Install SIGINT and SIGTERM handlers
    SIGINT_HANDLER(SIGINT);
    SIGTERM_HANDLER(SIGTERM);

    // Set up I2C read and write timeouts
    gpiod_set_timeout(i2c_handle, I2C_READ_TIMEOUT, I2C_WRITE_TIMEOUT);

    // Set up I2C read and write retries
    gpiod_set_retries(i2c_handle, I2C_READ_RETRIES, I2C_WRITE_RETRIES);

    // Main loop
    while (1) {
        // Trigger measurement
        if (gpiod_write(i2c_handle, TEMP_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            return EXIT_FAILURE;
        }

        // Wait 7 ms for measurement to complete
        usleep(7000);

        // Read temperature and pressure
        uint16_t temp, press;
        if (gpiod_read(i2c_handle, TEMP_REG, &temp, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            return EXIT_FAILURE;
        }
        if (gpiod_read(i2c_handle, PRESS_REG, &press, 2) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            return EXIT_FAILURE;
        }

        // Check for sensor absence
        if (temp == DEFAULT_TEMP && press == DEFAULT_PRESS) {
            fprintf(stderr, "Sensor is not present\n");
            return EXIT_FAILURE;
        }

        // Print results
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        printf("%s - Temperature: %d.%02d°C, Pressure: %d.%02d Pa\n", timestamp, temp / 100, temp % 100, press / 100, press % 100);

        // Wait 5 seconds before next measurement
        sleep(5);
    }

    // Clean up
    gpiod_close(i2c_handle);
    pigpio_cleanup();

    return EXIT_SUCCESS;
}
