#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000
#define CSV_FILE "pressure_log.csv"
#define CSV_HEADER "timestamp,pressure_kPa\n"
#define SAFE_PRESSURE_MIN 200
#define SAFE_PRESSURE_MAX 250

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void init_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

static void close_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = SIG_DFL;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static void write_csv_header(FILE *fp) {
    fprintf(fp, CSV_HEADER);
}

static void write_csv_row(FILE *fp, double pressure) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, pressure);
}

static void read_pressure(FILE *fp) {
    int fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return;
    }

    double pressure;
    if (i2c_read(fd, &pressure, sizeof(pressure)) < 0) {
        fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
        i2c_close(fd);
        return;
    }

    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "Warning: pressure out of safe range: %.2f kPa\n", pressure);
    }

    write_csv_row(fp, pressure);
    i2c_close(fd);
}

int main(void) {
    init_handlers();

    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        write_csv_header(fp);
    }

    while (running) {
        read_pressure(fp);
        sleep(1);
    }

    fclose(fp);
    close_handlers();

    return 0;
}

