#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME 3
#define SYNC_PULSE 56
#define DATA_NIBBLES 3
#define CHECKSUM_NIBBLE 1
#define STATUS_NIBBLE 0
#define PRESSURE_LOG "pressure_log.txt"

// Function prototypes
void handle_sigint(int signal);
void handle_sigterm(int signal);
void read_pressure(void);
void log_pressure(float pressure);
void check_sensor_absent(void);
void check_bus_errors(void);

// Global variables
int gpio_fd;
struct timeval start_time;
struct timeval end_time;
uint32_t pulse_width;
uint8_t status_nibble;
uint8_t data_nibbles[DATA_NIBBLES];
uint8_t checksum_nibble;
bool sensor_absent;
bool bus_error;

int main(void) {
    // Initialize the GPIO pin
    gpio_fd = pigpio_init(GPIO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error initializing GPIO pin\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open the pressure log file
    FILE *log_file = fopen(PRESSURE_LOG, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening pressure log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read the pressure
        read_pressure();

        // Check for sensor absent condition
        check_sensor_absent();

        // Check for bus errors
        check_bus_errors();

        // Log the pressure
        log_pressure(pulse_width);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    pigpio_close(gpio_fd);

    return 0;
}

void handle_sigint(int signal) {
    // Clean up
    fclose(log_file);
    pigpio_close(gpio_fd);

    // Exit
    exit(0);
}

void handle_sigterm(int signal) {
    // Clean up
    fclose(log_file);
    pigpio_close(gpio_fd);

    // Exit
    exit(0);
}

void read_pressure(void) {
    // Reset the pulse width and status nibble
    pulse_width = 0;
    status_nibble = 0;

    // Read the pulse width
    pigpio_read_pulse(gpio_fd, &pulse_width);

    // Check for timeout
    if (pulse_width == 0) {
        sensor_absent = true;
        return;
    }

    // Check for bus error
    if (pulse_width < 12 || pulse_width > 271) {
        bus_error = true;
        return;
    }

    // Extract the status nibble
    status_nibble = (pulse_width >> 12) & 0xF;

    // Extract the data nibbles
    for (int i = 0; i < DATA_NIBBLES; i++) {
        data_nibbles[i] = (pulse_width >> (12 - (i * 4))) & 0xF;
    }

    // Extract the checksum nibble
    checksum_nibble = (pulse_width >> 16) & 0xF;
}

void log_pressure(float pressure) {
    // Get the current time
    gettimeofday(&end_time, NULL);

    // Calculate the elapsed time
    float elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

    // Calculate the pressure
    pressure = (pulse_width - SYNC_PULSE) / 1000.0;

    // Log the pressure
    fprintf(log_file, "%s, Pressure: %f Pa\n", ctime(&end_time.tv_sec), pressure);
}

void check_sensor_absent(void) {
    // Check for sensor absent condition
    if (sensor_absent) {
        fprintf(stderr, "Sensor absent\n");
        return;
    }
}

void check_bus_errors(void) {
    // Check for bus error
    if (bus_error) {
        fprintf(stderr, "Bus error\n");
        return;
    }
}

