#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_READ_LEN 4
#define I2C_WRITE_LEN 0
#define I2C_DELAY_MS 1000

#define FLOW_REG 0x00
#define TEMP_REG 0x01

#define FLOW_MASK 0x3FFF
#define TEMP_MASK 0x0FFF

#define FLOW_SCALE 1000
#define TEMP_SCALE 1000

#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

static void sigterm_handler(int signum) {
    stop = 1;
}

static void init_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void log_measurement(int fd, uint16_t flow, uint16_t temp) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld %d %d\n", tv.tv_sec, tv.tv_usec, flow, temp);
    write(fd, buf, strlen(buf));
}

int main(void) {
    int fd;
    uint8_t data[I2C_READ_LEN];
    uint16_t flow, temp;

    init_handlers();

    if ((fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("open");
        return 1;
    }

    if (libgpiod_init() < 0) {
        perror("libgpiod_init");
        return 1;
    }

    if (libgpiod_i2c_open(I2C_BUS, I2C_ADDR) < 0) {
        perror("libgpiod_i2c_open");
        return 1;
    }

    while (!stop) {
        if (libgpiod_i2c_read(I2C_BUS, I2C_ADDR, data, I2C_READ_LEN) < 0) {
            perror("libgpiod_i2c_read");
            continue;
        }

        flow = (data[0] << 8) | data[1];
        temp = (data[2] << 8) | data[3];

        flow &= FLOW_MASK;
        temp &= TEMP_MASK;

        flow *= FLOW_SCALE;
        temp *= TEMP_SCALE;

        log_measurement(fd, flow, temp);

        usleep(I2C_DELAY_MS * 1000);
    }

    close(fd);
    libgpiod_i2c_close(I2C_BUS, I2C_ADDR);
    libgpiod_exit();

    return 0;
}

