#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define DHT11_PIN 4
#define DHT11_START_LOW_MS 18
#define DHT11_START_HIGH_MS 0
#define DHT11_DATA_BITS 40
#define DHT11_DATA_LOW_US 50
#define DHT11_DATA_HIGH_US 26
#define DHT11_DATA_HIGH_US_ZERO 70
#define DHT11_CHECKSUM_BITS 8
#define DHT11_CHECKSUM_LOW_US 26
#define DHT11_CHECKSUM_HIGH_US 70
#define DHT11_READ_INTERVAL_MS 2000

#define DHT11_ERROR_TIMEOUT -1
#define DHT11_ERROR_CHECKSUM -2
#define DHT11_ERROR_SENSOR_ABSENT -3

#define DHT11_READINGS_FILE "dht11_readings.txt"

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

static void sigterm_handler(int signum) {
    stop = 1;
}

static void init_gpio(void) {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(-ret));
        exit(EXIT_FAILURE);
    }
}

static void cleanup_gpio(void) {
    gpiod_cleanup();
}

static void set_gpio_direction(int pin, int direction) {
    int ret;

    ret = gpiod_set_direction(pin, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction: %s\n", strerror(-ret));
        exit(EXIT_FAILURE);
    }
}

static void set_gpio_level(int pin, int level) {
    int ret;

    ret = gpiod_set_level(pin, level);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO level: %s\n", strerror(-ret));
        exit(EXIT_FAILURE);
    }
}

static int get_gpio_level(int pin) {
    int ret;

    ret = gpiod_get_level(pin);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO level: %s\n", strerror(-ret));
        exit(EXIT_FAILURE);
    }

    return ret;
}

static void wait_us(int us) {
    struct timespec ts;

    ts.tv_sec = us / 1000000;
    ts.tv_nsec = (us % 1000000) * 1000;

    nanosleep(&ts, NULL);
}

static void wait_ms(int ms) {
    struct timespec ts;

    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000;

    nanosleep(&ts, NULL);
}

static void read_dht11(void) {
    int ret;
    int i;
    int data[DHT11_DATA_BITS];
    int checksum;
    int checksum_bits[DHT11_CHECKSUM_BITS];
    int checksum_low;
    int checksum_high;
    int humidity_integer;
    int humidity_decimal;
    int temperature_integer;
    int temperature_decimal;
    char timestamp[20];
    FILE *fp;

    // Initialize GPIO
    init_gpio();

    // Set GPIO direction
    set_gpio_direction(DHT11_PIN, GPIOD_OUT);

    // Start signal
    set_gpio_level(DHT11_PIN, GPIOD_LOW);
    wait_ms(DHT11_START_LOW_MS);
    set_gpio_level(DHT11_PIN, GPIOD_HIGH);
    wait_ms(DHT11_START_HIGH_MS);

    // Read data bits
    for (i = 0; i < DHT11_DATA_BITS; i++) {
        // Wait for low pulse
        ret = get_gpio_level(DHT11_PIN);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO level: %s\n", strerror(-ret));
            exit(EXIT_FAILURE);
        }

        if (ret == GPIOD_LOW) {
            wait_us(DHT11_DATA_LOW_US);
        } else {
            wait_us(DHT11_DATA_HIGH_US);
        }

        // Read high pulse
        ret = get_gpio_level(DHT11_PIN);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO level: %s\n", strerror(-ret));
            exit(EXIT_FAILURE);
        }

        if (ret == GPIOD_LOW) {
            data[i] = 0;
        } else {
            data[i] = 1;
        }
    }

    // Read checksum bits
    for (i = 0; i < DHT11_CHECKSUM_BITS; i++) {
        // Wait for low pulse
        ret = get_gpio_level(DHT11_PIN);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO level: %s\n", strerror(-ret));
            exit(EXIT_FAILURE);
        }

        if (ret == GPIOD_LOW) {
            wait_us(DHT11_CHECKSUM_LOW_US);
        } else {
            wait_us(DHT11_CHECKSUM_HIGH_US);
        }

        // Read high pulse
        ret = get_gpio_level(DHT11_PIN);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO level: %s\n", strerror(-ret));
            exit(EXIT_FAILURE);
        }

        if (ret == GPIOD_LOW) {
            checksum_bits[i] = 0;
        } else {
            checksum_bits[i] = 1;
        }
    }

    // Calculate checksum
    checksum_low = 0;
    checksum_high = 0;
    for (i = 0; i < DHT11_CHECKSUM_BITS; i++) {
        if (i < 8) {
            checksum_low += checksum_bits[i];
        } else {
            checksum_high += checksum_bits[i];
        }
    }

    // Calculate humidity and temperature
    humidity_integer = data[0] + (data[1] << 1) + (data[2] << 2) + (data[3] << 3);
    humidity_decimal = data[4];
    temperature_integer = data[5] + (data[6] << 1) + (data[7] << 2) + (data[8] << 3);
    temperature_decimal = data[9];

    // Verify checksum
    if (checksum_low != data[16] || checksum_high != data[17]) {
        fprintf(stderr, "Checksum failed\n");
        exit(EXIT_FAILURE);
    }

    // Write to file
    fp = fopen(DHT11_READINGS_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d.%d, %d.%d\n", timestamp, humidity_integer, humidity_decimal, temperature_integer, temperature_decimal);

    fclose(fp);

    // Cleanup
    cleanup_gpio();
}

int main(void) {
    int ret;

    // Set signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!stop) {
        read_dht11();
        wait_ms(DHT11_READ_INTERVAL_MS);
    }

    return EXIT_SUCCESS;
}

