#define SHT31D_ADDR 0x44
#define SHT31D_TEMP_HIGH_CMD 0x2C
#define SHT31D_TEMP_LOW_CMD 0x24
#define SHT31D_HUM_HIGH_CMD 0x2C
#define SHT31D_HUM_LOW_CMD 0x24
#define SHT31D_CRC_POLY 0x31
#define SHT31D_CRC_INIT 0xFF

#define SHT31D_TEMP_HIGH_REG 0x00
#define SHT31D_TEMP_LOW_REG 0x01
#define SHT31D_HUM_HIGH_REG 0x02
#define SHT31D_HUM_LOW_REG 0x03

#define SHT31D_TEMP_HIGH_CRC_REG 0x04
#define SHT31D_TEMP_LOW_CRC_REG 0x05
#define SHT31D_HUM_HIGH_CRC_REG 0x06
#define SHT31D_HUM_LOW_CRC_REG 0x07

#define SHT31D_READ_RETRY_COUNT 3

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_fd = pigpio_i2c_open(1, SHT31D_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("sht31d_data.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Read temperature and humidity
        int temp_high = read_sht31d_reg(i2c_fd, SHT31D_TEMP_HIGH_CMD, SHT31D_TEMP_HIGH_REG);
        int temp_low = read_sht31d_reg(i2c_fd, SHT31D_TEMP_LOW_CMD, SHT31D_TEMP_LOW_REG);
        int hum_high = read_sht31d_reg(i2c_fd, SHT31D_HUM_HIGH_CMD, SHT31D_HUM_HIGH_REG);
        int hum_low = read_sht31d_reg(i2c_fd, SHT31D_HUM_LOW_CMD, SHT31D_HUM_LOW_REG);

        // Calculate temperature and humidity
        int temp = (temp_high << 8) | temp_low;
        int hum = (hum_high << 8) | hum_low;

        // Print to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d,%d\n", timestamp, temp, hum);

        // Wait for next measurement
        sleep(5);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    fclose(log_file);
    gpiod_cleanup();

    return 0;
}

int read_sht31d_reg(int i2c_fd, uint8_t cmd, uint8_t reg) {
    // Send command
    uint8_t buf[2];
    buf[0] = cmd;
    buf[1] = reg;
    if (pigpio_i2c_write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        return -1;
    }

    // Read data
    uint8_t data[6];
    if (pigpio_i2c_read(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Failed to read from I2C bus\n");
        return -1;
    }

    // Validate CRC
    uint8_t crc = data[5];
    uint8_t expected_crc = crc8(data, 5, SHT31D_CRC_POLY, SHT31D_CRC_INIT);
    if (crc != expected_crc) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Return data
    return data[0] << 8 | data[1];
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int signal) {
    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Clean up GPIO library
    gpiod_cleanup();

    // Exit program
    exit(0);
}

void handle_sigterm(int signal) {
    // Close I2C handle
    pigpio_i2c_close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Clean up GPIO library
    gpiod_cleanup();

    // Exit program
    exit(0);
}

