#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define I2C_FREQ 100000
#define LOG_FILE "pressure_log.txt"

int main(void) {
    // Initialize the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_FREQ);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize the sensor library
    int sensor_fd = mlx90824_init(i2c_fd);
    if (sensor_fd < 0) {
        perror("Failed to initialize sensor");
        return 1;
    }

    // Open the log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the pressure and temperature from the sensor
        float pressure, temperature;
        int ret = mlx90824_read(sensor_fd, &pressure, &temperature);
        if (ret < 0) {
            perror("Failed to read from sensor");
            return 1;
        }

        // Get the current time
        struct timeval tv;
        gettimeofday(&tv, NULL);

        // Write the measurement to the log file
        char buf[100];
        snprintf(buf, sizeof(buf), "%ld.%06ld, %f, %f\n", tv.tv_sec, tv.tv_usec, pressure, temperature);
        write(log_fd, buf, strlen(buf));

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up on exit
    close(i2c_fd);
    close(log_fd);
    mlx90824_cleanup(sensor_fd);

    return 0;
}

