#define AVG_COUNT 10
#define AVG_THRESHOLD 28.0
#define HYSTERESIS 2.0

int main(int argc, char *argv[]) {
  int i2c_fd, fan_fd, i, j, k;
  float temp, avg, last_avg;
  uint8_t buf[2];
  struct lm75b_data data;
  struct sigaction sigint_action, sigterm_action;

  // Initialize the driver library
  if (pigpio_start(NULL, NULL) < 0) {
    fprintf(stderr, "Failed to initialize pigpio library\n");
    return 1;
  }

  // Open the I2C interface
  i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    fprintf(stderr, "Failed to open I2C interface\n");
    return 1;
  }

  // Open the GPIO interface
  fan_fd = open("/dev/gpiochip0", O_WRONLY);
  if (fan_fd < 0) {
    fprintf(stderr, "Failed to open GPIO interface\n");
    return 1;
  }

  // Set up signal handlers
  sigint_action.sa_handler = sigint_handler;
  sigint_action.sa_flags = 0;
  sigaction(SIGINT, &sigint_action, NULL);

  sigterm_action.sa_handler = sigterm_handler;
  sigterm_action.sa_flags = 0;
  sigaction(SIGTERM, &sigterm_action, NULL);

  // Set up the I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
    fprintf(stderr, "Failed to set I2C slave address\n");
    return 1;
  }

  // Set up the GPIO pin
  if (ioctl(fan_fd, GPIO_SET_PIN, FAN_GPIO) < 0) {
    fprintf(stderr, "Failed to set GPIO pin\n");
    return 1;
  }

  // Set up the circular buffer
  float samples[SAMPLE_COUNT];
  int sample_count = 0;
  int sample_index = 0;

  // Set up the running average
  avg = 0.0;
  last_avg = 0.0;

  // Main loop
  while (1) {
    // Read the temperature from the sensor
    if (read(i2c_fd, buf, 2) < 0) {
      fprintf(stderr, "Failed to read from I2C interface\n");
      continue;
    }

    // Convert the temperature to a float
    temp = (float)((buf[0] << 8) | buf[1]) / 16.0;

    // Add the temperature to the circular buffer
    samples[sample_index] = temp;
    sample_index = (sample_index + 1) % SAMPLE_COUNT;
    sample_count = (sample_count + 1) % SAMPLE_COUNT;

    // Compute the running average
    avg = 0.0;
    for (i = 0; i < sample_count; i++) {
      avg += samples[i];
    }
    avg /= sample_count;

    // Check if the temperature exceeds the threshold
    if (avg > AVG_THRESHOLD) {
      // Turn on the fan
      if (write(fan_fd, FAN_ON, 1) < 0) {
        fprintf(stderr, "Failed to write to GPIO interface\n");
        continue;
