    fprintf(stderr, "Failed to write to GPIO interface\n");
  }

  // Close the I2C handle
  close(i2c_fd);

  // Close the GPIO handle
  close(fan_fd);

  // Stop the driver library
  pigpio_stop();

  // Exit the program
  exit(0);
}

