#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <libgpiod/libgpiod.h>

#define SENSOR_ADDR 0x28
#define SENSOR_CMD_MEASURE 0x10
#define SENSOR_CMD_READ 0x00
#define SENSOR_CMD_CRC 0x02
#define SENSOR_CRC_POLY 0x31
#define SENSOR_CRC_INIT 0xFF
#define SENSOR_CRC_LEN 2
#define SENSOR_DATA_LEN 9
#define SENSOR_DATA_OFFSET 3
#define SENSOR_TEMP_OFFSET 5
#define SENSOR_PRESS_OFFSET 6
#define SENSOR_PRESS_LEN 3
#define SENSOR_TEMP_LEN 2
#define SENSOR_PRESS_MAX 5000
#define SENSOR_TEMP_MAX 125
#define SENSOR_PRESS_MIN -5000
#define SENSOR_TEMP_MIN -125

#define LOG_FILE "airflow.log"

static int i2c_fd;
static int log_fd;

static void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    libgpiod_cleanup();
    exit(0);
}

static void sigterm_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    libgpiod_cleanup();
    exit(0);
}

static void init_i2c(void) {
    i2c_fd = libgpiod_i2c_open(SENSOR_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_log(void) {
    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_sensor(void) {
    uint8_t data[SENSOR_DATA_LEN];
    uint8_t crc[SENSOR_CRC_LEN];
    int ret;

    // Send measurement command
    ret = libgpiod_i2c_write(i2c_fd, SENSOR_CMD_MEASURE, 1);
    if (ret < 0) {
        fprintf(stderr, "Error sending measurement command: %s\n", strerror(errno));
        exit(1);
    }

    // Wait 45 ms
    usleep(45000);

    // Read data
    ret = libgpiod_i2c_read(i2c_fd, data, SENSOR_DATA_LEN);
    if (ret < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        exit(1);
    }

    // Read CRC
    ret = libgpiod_i2c_read(i2c_fd, crc, SENSOR_CRC_LEN);
    if (ret < 0) {
        fprintf(stderr, "Error reading CRC: %s\n", strerror(errno));
        exit(1);
    }

    // Validate CRC
    uint8_t crc_calc = libgpiod_crc8(data, SENSOR_DATA_LEN, SENSOR_CRC_POLY, SENSOR_CRC_INIT);
    if (crc_calc != crc[0]) {
        fprintf(stderr, "CRC mismatch: %02x != %02x\n", crc_calc, crc[0]);
        exit(1);
    }

    // Extract temperature and pressure
    int16_t temp = (data[SENSOR_TEMP_OFFSET] << 8) | data[SENSOR_TEMP_OFFSET + 1];
    int32_t press = (data[SENSOR_PRESS_OFFSET] << 16) | (data[SENSOR_PRESS_OFFSET + 1] << 8) | data[SENSOR_PRESS_OFFSET + 2];

    // Check for sensor absence
    if (temp == 0 && press == 0) {
        fprintf(stderr, "Sensor is absent\n");
        exit(1);
    }

    // Check for pressure out of range
    if (press > SENSOR_PRESS_MAX || press < SENSOR_PRESS_MIN) {
        fprintf(stderr, "Pressure out of range: %d Pa\n", press);
        exit(1);
    }

    // Check for temperature out of range
    if (temp > SENSOR_TEMP_MAX || temp < SENSOR_TEMP_MIN) {
        fprintf(stderr, "Temperature out of range: %d °C\n", temp);
        exit(1);
    }

    // Print to log
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld, %d, %d\n", time(NULL), press, temp);
    write(log_fd, buf, strlen(buf));

    // Print to stdout
    printf("Pressure: %d Pa, Temperature: %d °C\n", press, temp);

    // Check for warning
    if (press > 5000) {
        fprintf(stderr, "Warning: pressure exceeds 5 Pa\n");
    }
}

int main(void) {
    // Initialize I2C
    init_i2c();

    // Initialize log
    init_log();

    // Set signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        read_sensor();
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    close(log_fd);
    libgpiod_cleanup();

    return 0;
}

