    // Set GPIO pin value
    if (ioctl(gpio_fd, GPIO_SET_VAL, GPIO_VAL_LOW) < 0) {
        perror("Failed to set GPIO pin value");
        close(gpio_fd);
        close(i2c_fd);
        exit(1);
