                exit(1);
            }
        } else if (temperature < 27.0) {
            if (ioctl(gpio_fd, GPIO_SET_VAL, GPIO_VAL_LOW) < 0) {
                perror("Failed to set GPIO pin value");
                close(gpio_fd);
                close(i2c_fd);
                exit(1);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on exit
    close(gpio_fd);
    close(i2c_fd);
    return 0;
}

void signal_handler(int signal)
{
