#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_ADDR 0x40
#define I2C_BUS 1

#define READ_TEMP_CMD 0xE3
#define READ_HUMIDITY_CMD 0xE5
#define READ_TEMP_FROM_RH_CMD 0xE0

#define MAX_RETRIES 3

int main(void) {
    int fd, i2c_fd, ret;
    uint8_t buf[2];
    uint16_t temp, humidity;
    char timestamp[20];
    FILE *log_file;

    // Initialize the I2C bus
    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Validate sensor presence
    ret = pigpio_i2c_read(i2c_fd, I2C_ADDR, 0xFA, 0x0F, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return 1;
    }
    if (buf[0] != 0x15 || buf[1] != 0x20) {
        fprintf(stderr, "Invalid sensor ID: %02X%02X\n", buf[0], buf[1]);
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        ret = pigpio_i2c_read(i2c_fd, I2C_ADDR, READ_TEMP_CMD, 0, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            return 1;
        }
        temp = (buf[0] << 8) | buf[1];

        ret = pigpio_i2c_read(i2c_fd, I2C_ADDR, READ_HUMIDITY_CMD, 0, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading humidity: %s\n", strerror(errno));
            return 1;
        }
        humidity = (buf[0] << 8) | buf[1];

        // Print to stdout
        printf("%s,%.2f,%.2f\n", timestamp, temp / 100.0, humidity / 100.0);

        // Write to log file
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp / 100.0, humidity / 100.0);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Cleanup
    pigpio_i2c_close(i2c_fd);
    fclose(log_file);
    return 0;
}

