#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x40
#define I2C_READ_LEN 3
#define CRC8_POLYNOMIAL 0x31

int main(void) {
    int i2c_fd;
    int log_fd;
    uint8_t data[I2C_READ_LEN];
    uint8_t crc;
    uint16_t temperature;
    char timestamp[20];

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fd = open("temperature_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read temperature data
        if (read(i2c_fd, data, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            continue;
        }

        // Verify CRC8
        crc = data[2];
        if (crc != crc8(data, 2, CRC8_POLYNOMIAL)) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        // Extract temperature
        temperature = (data[0] << 8) | data[1];

        // Log temperature
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_fd, "%s, %d\n", timestamp, temperature);

        // Wait for next measurement
        usleep(10000);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);

    return 0;
}

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t polynomial) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

