        // Read temperature data
        if (read(i2c_fd, data, I2C_READ_LEN) != I2C_READ_LEN) {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            continue;
        }

        // Verify CRC8
        crc = data[2];
        if (crc != crc8(data, 2, CRC8_POLYNOMIAL)) {
            fprintf(stderr, "CRC8 mismatch\n");
            continue;
        }

        // Extract temperature
        temperature = (data[0] << 8) | data[1];

        // Log temperature
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_fd, "%s, %d\n", timestamp, temperature);

        // Wait for next measurement
        usleep(10000);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);

    return 0;
}

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t polynomial) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}
