    // Initialize the Sensirion SDP810-500Pa differential pressure sensor
    int ret = i2c_write(i2c_fd, 0x10, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to initialize Sensirion SDP810-500Pa differential pressure sensor\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

