    while (!stop) {
        // Trigger a measurement
        ret = i2c_write(i2c_fd, 0x10, 0x01);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to trigger measurement\n");
            break;
        }

        // Wait at least 50 ms
        usleep(50000);

        // Read the 9-byte result
        uint8_t data[9];
        ret = i2c_read(i2c_fd, data, 9);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read measurement result\n");
            break;
        }

        // Validate the CRC
        uint8_t crc = crc8(data, 7, CRC_POLYNOMIAL, CRC_INITIAL_VALUE);
        if (crc != data[7]) {
            fprintf(stderr, "Error: CRC mismatch\n");
            break;
        }

        // Extract the pressure and temperature
        uint16_t pressure = (data[0] << 8) | data[1];
        int16_t temperature = (data[2] << 8) | data[3];

        // Log the sample
        fprintf(log_file, "%ld, %u, %d\n", time(NULL), pressure, temperature);
    }

    // Clean up
    fclose(log_file);
    i2c_close(i2c_fd);
    pigpio_cleanup();

    return 0;
}

