#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod/libgpiod.h>
#include <scd40/scd40.h>

#define BUFFER_SIZE 100
#define CSV_FILE_PATH "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE_PATH "/var/log/scd40_error.log"

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} scd40_reading_t;

typedef struct {
    scd40_reading_t buffer[BUFFER_SIZE];
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
} scd40_buffer_t;

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void* logging_thread(void* arg) {
    scd40_buffer_t* buffer = (scd40_buffer_t*)arg;
    while (running) {
        pthread_mutex_lock(&buffer->mutex);
        if (buffer->head != buffer->tail) {
            scd40_reading_t reading = buffer->buffer[buffer->tail];
            buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
            pthread_mutex_unlock(&buffer->mutex);
            FILE* fp = fopen(CSV_FILE_PATH, "a");
            if (fp == NULL) {
                fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
                return NULL;
            }
            fprintf(fp, "%d,%f,%f\n", reading.co2, reading.temperature, reading.humidity);
            fclose(fp);
        } else {
            pthread_mutex_unlock(&buffer->mutex);
            sleep(60);
        }
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    scd40_buffer_t buffer;
    buffer.head = 0;
    buffer.tail = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    // Initialize the SCD40 driver
    scd40_t scd40;
    if (scd40_init(&scd40) != 0) {
        fprintf(stderr, "Error initializing SCD40 driver\n");
        return 1;
    }

    // Start the logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, &buffer) != 0) {
        fprintf(stderr, "Error creating logging thread\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler\n");
        return 1;
    }

    // Start periodic measurement
    if (scd40_start_periodic_measurement(&scd40) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        return 1;
    }

    // Read from the SCD40 sensor every 5 seconds
    while (running) {
        scd40_reading_t reading;
        if (scd40_read_measurement(&scd40, &reading) != 0) {
            fprintf(stderr, "Error reading measurement\n");
            continue;
        }
        pthread_mutex_lock(&buffer.mutex);
        buffer.buffer[buffer.head] = reading;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer.mutex);
        sleep(5);
    }

    // Stop periodic measurement
    if (scd40_stop_periodic_measurement(&scd40) != 0) {
        fprintf(stderr, "Error stopping periodic measurement\n");
        return 1;
    }

    // Join the logging thread
    if (pthread_join(logging_thread_id, NULL) != 0) {
        fprintf(stderr, "Error joining logging thread\n");
        return 1;
    }

    // Flush any remaining buffered data to a final CSV file
    FILE* fp = fopen(CSV_FILE_PATH, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }
    for (size_t i = buffer.tail; i != buffer.head; i = (i + 1) % BUFFER_SIZE) {
        scd40_reading_t reading = buffer.buffer[i];
        fprintf(fp, "%d,%f,%f\n", reading.co2, reading.temperature, reading.humidity);
    }
    fclose(fp);

    // Close the I2C handle
    if (scd40_close(&scd40) != 0) {
        fprintf(stderr, "Error closing SCD40 driver\n");
        return 1;
    }

    return 0;
}

