#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_READ_TIMEOUT 1000
#define I2C_WRITE_TIMEOUT 1000
#define SAMPLE_INTERVAL 5000

static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main(void) {
    // Initialize the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_READ_TIMEOUT, I2C_WRITE_TIMEOUT);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the pressure sensor
    int ret = pigpio_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open the file for appending
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (!exit_flag) {
        // Wait for the next sample
        usleep(SAMPLE_INTERVAL);

        // Read the pressure and temperature from the sensor
        float pressure, temperature;
        ret = pigpio_read_pressure(i2c_fd, &pressure, &temperature);
        if (ret < 0) {
            fprintf(stderr, "Error reading pressure and temperature: %s\n", strerror(errno));
            continue;
        }

        // Print the reading to stdout
        printf("%f %f\n", pressure, temperature);

        // Write the reading to the file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(fp, "%s %f %f\n", timestamp, pressure, temperature);
        fflush(fp);
    }

    // Clean up
    pigpio_cleanup();
    i2c_close(i2c_fd);
    fclose(fp);

    return 0;
}

