                // Set GPIO pin value to 0
                ret = ioctl(gpio_fd, GPIO_SET_VAL, GPIO_PIN, 0);
                if (ret < 0) {
                    perror("Failed to set GPIO pin value");
                    close(gpio_fd);
                    close(i2c_fd);
                    return 1;
                }

                // Wait for 500 ms
                usleep(500000);
            }
        }

        // Wait for 20 ms
        usleep(20000);
    }

    // Close I2C device
    close(i2c_fd);

    // Close GPIO device
    close(gpio_fd);

