#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <mlx90614.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define TEMP_THRESHOLD_HIGH 30
#define TEMP_THRESHOLD_LOW 28
#define RETRY_COUNT 3
#define RETRY_DELAY 10

static int i2c_fd;
static int fan_fd;
static int fan_state = FAN_OFF;
static int retry_count = 0;

static void handle_sigint(int signum) {
    printf("Received SIGINT, closing I2C handle and turning off fan\n");
    close(i2c_fd);
    gpio_write(fan_fd, FAN_OFF);
    exit(0);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, closing I2C handle and turning off fan\n");
    close(i2c_fd);
    gpio_write(fan_fd, FAN_OFF);
    exit(0);
}

static void init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        exit(1);
    }
}

static void init_fan() {
    fan_fd = gpio_open(FAN_GPIO, GPIO_OUTPUT);
    if (fan_fd < 0) {
        printf("Failed to open GPIO %d for fan control\n", FAN_GPIO);
        exit(1);
    }
}

static void read_temperature() {
    int16_t ambient_temp, object_temp;
    if (mlx90614_read_temperature(i2c_fd, &ambient_temp, &object_temp) < 0) {
        printf("Failed to read temperature\n");
        retry_count++;
        if (retry_count > RETRY_COUNT) {
            printf("Retry count exceeded, skipping logging\n");
            return;
        }
        usleep(RETRY_DELAY * 1000);
        read_temperature();
    }
    retry_count = 0;
    if (object_temp > TEMP_THRESHOLD_HIGH) {
        fan_state = FAN_ON;
    } else if (object_temp < TEMP_THRESHOLD_LOW) {
        fan_state = FAN_OFF;
    }
    gpio_write(fan_fd, fan_state);
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    char log_entry[100];
    sprintf(log_entry, "%s, %d, %d\n", timestamp, ambient_temp, object_temp);
    FILE *fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        printf("Failed to open temperature_log.txt for writing\n");
        exit(1);
    }
    fprintf(fp, log_entry);
    fclose(fp);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);
    init_i2c();
    init_fan();
    while (1) {
        read_temperature();
        sleep(2);
    }
    return 0;
}

