#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <sensirion_i2c.h>

#define SENSOR_ADDR 0x40
#define SENSOR_CMD 0xF3
#define SENSOR_DATA_LEN 6
#define HTTP_PORT 8080
#define HTTP_BUF_LEN 1024

int main(int argc, char *argv[]) {
    int sock, client_sock;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char http_buf[HTTP_BUF_LEN];
    int retries = 0;

    // Initialize the I2C bus
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Set up the HTTP server
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create socket\n");
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(HTTP_PORT);

    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        return 1;
    }

    if (listen(sock, 3) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Accept a new connection
        client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            fprintf(stderr, "Failed to accept connection\n");
            continue;
        }

        // Read the SHT40 sensor data
        uint8_t data[SENSOR_DATA_LEN];
        while (retries < 3) {
            if (sensirion_i2c_read(SENSOR_ADDR, SENSOR_CMD, data, SENSOR_DATA_LEN) < 0) {
                fprintf(stderr, "Failed to read SHT40 sensor data\n");
                retries++;
                continue;
            }
            break;
        }

        // Calculate the temperature and humidity values
        float temperature = (data[0] << 8 | data[1]) * 175 / 65535 - 45;
        float humidity = (data[3] << 8 | data[4]) * 100 / 65535;

        // Clamp the humidity value to the range 0-100%
        if (humidity > 100) {
            humidity = 100;
        } else if (humidity < 0) {
            humidity = 0;
        }

        // Build the HTTP response
        snprintf(http_buf, HTTP_BUF_LEN, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body>Temperature: %f°C<br>Humidity: %f%%</body></html>", temperature, humidity);

        // Send the HTTP response
        if (send(client_sock, http_buf, strlen(http_buf), 0) < 0) {
            fprintf(stderr, "Failed to send HTTP response\n");
        }

        // Close the connection
        close(client_sock);
    }

    // Clean up
    close(sock);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT\n");
    exit(1);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM\n");
    exit(1);
}

