    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Accept a new connection
        client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            fprintf(stderr, "Failed to accept connection\n");
            continue;
        }

        // Read the SHT40 sensor data
        uint8_t data[SENSOR_DATA_LEN];
        while (retries < 3) {
            if (sensirion_i2c_read(SENSOR_ADDR, SENSOR_CMD, data, SENSOR_DATA_LEN) < 0) {
                fprintf(stderr, "Failed to read SHT40 sensor data\n");
                retries++;
                continue;
            }
            break;
        }

        // Calculate the temperature and humidity values
        float temperature = (data[0] << 8 | data[1]) * 175 / 65535 - 45;
        float humidity = (data[3] << 8 | data[4]) * 100 / 65535;

        // Clamp the humidity value to the range 0-100%
        if (humidity > 100) {
            humidity = 100;
        } else if (humidity < 0) {
            humidity = 0;
        }

        // Build the HTTP response
        snprintf(http_buf, HTTP_BUF_LEN, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body>Temperature: %f°C<br>Humidity: %f%%</body></html>", temperature, humidity);

        // Send the HTTP response
        if (send(client_sock, http_buf, strlen(http_buf), 0) < 0) {
            fprintf(stderr, "Failed to send HTTP response\n");
        }

        // Close the connection
        close(client_sock);
    }

    // Clean up
    close(sock);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT\n");
    exit(1);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM\n");
    exit(1);
}
```
This code sets up a simple HTTP server on port 8080 that reads the SHT40 sensor data and sends the temperature and humidity values to the client as an HTML page. It uses the `pigpio` library to communicate with the I2C bus and the `sensirion_i2c` library to read the sensor data. The code includes robust error handling for I2C communication and cleanly releases all resources on every exit path. It also sets up signal handlers for `SIGINT` and `SIGTERM` to handle termination signals.

