#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define MEASUREMENT_CONFIG 0x02
#define MEASUREMENT_RESULT 0x00
#define TIMEOUT_MS 500
#define RETRY_COUNT 3

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    int fd;
    uint8_t data[2];
    uint16_t temperature, humidity;
    bool timeout = false;
    int retries = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set up I2C transaction
    pigpio_i2c_transaction_t transaction;
    transaction.addr = I2C_ADDR;
    transaction.flags = 0;
    transaction.len = 2;
    transaction.data = data;

    while (!sigint_flag) {
        // Read MEASUREMENT_CONFIG register
        transaction.reg = MEASUREMENT_CONFIG;
        if (pigpio_i2c_read(fd, &transaction) < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register: %s\n", strerror(errno));
            goto cleanup;
        }

        // Check if bit 0 is cleared
        if ((data[0] & 0x01) == 0) {
            // Read MEASUREMENT_RESULT register
            transaction.reg = MEASUREMENT_RESULT;
            if (pigpio_i2c_read(fd, &transaction) < 0) {
                fprintf(stderr, "Error reading MEASUREMENT_RESULT register: %s\n", strerror(errno));
                goto cleanup;
            }

            // Extract temperature and humidity values
            temperature = (data[0] << 8) | data[1];
            humidity = (data[2] << 8) | data[3];

            // Print readings to console
            printf("Temperature: %d.%d°C\n", temperature / 10, temperature % 10);
            printf("Humidity: %d.%d%%\n", humidity / 10, humidity % 10);

            // Wait for next reading
            sleep(5);
        } else {
            // Check for timeout
            if (retries++ > RETRY_COUNT) {
                timeout = true;
                break;
            }

            // Wait for bit 0 to clear
            usleep(1000);
        }
    }

cleanup:
    // Close I2C bus
    pigpio_i2c_close(fd);

    // Check for timeout
    if (timeout) {
        fprintf(stderr, "Timeout waiting for MEASUREMENT_CONFIG register to clear\n");
        return 1;
    }

    return 0;
}

