#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_READ_LEN 6
#define I2C_WRITE_LEN 2
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buf[I2C_READ_LEN];
    uint16_t pressure, temperature;
    uint8_t crc;
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up I2C line
    line = gpiod_line_request(chip, I2C_ADDR, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (!line) {
        fprintf(stderr, "Failed to request I2C line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize Sensirion SDP800-500Pa
    ret = gpiod_line_write(line, I2C_WRITE_LEN, (uint8_t[]){0x00, 0x00});
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize Sensirion SDP800-500Pa\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read pressure and temperature
        ret = gpiod_line_read(line, I2C_READ_LEN, buf);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from Sensirion SDP800-500Pa\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Validate CRC
        crc = buf[0] ^ buf[1] ^ buf[2] ^ buf[3] ^ buf[4] ^ buf[5];
        if (crc != buf[6]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // Extract pressure and temperature
        pressure = (buf[0] << 8) | buf[1];
        temperature = (buf[2] << 8) | buf[3];

        // Print results
        printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);

        // Wait for next measurement
        usleep(45000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

