    // Initialize DS18B20
    int ds18b20_fd = wiringPiI2CSetup(DS18B20_ADDR);
    if (ds18b20_fd == -1) {
        printf("Failed to initialize DS18B20\n");
        return 1;
    }

    // Initialize relay
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW);

    // Initialize PWM
    pinMode(PWM_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(PWM_FREQ);
    pwmSetRange(PWM_RES);
    pwmWrite(PWM_PIN, 0);

    // Initialize log file
    FILE *log_file = fopen("greenhouse.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read temperature
        int temp = read_temperature(ds18b20_fd);
        if (temp == -1) {
            printf("Failed to read temperature\n");
            return 1;
        }

        // Compute PID output
        float error = setpoint - temp;
        float integral = Ki * (error + prev_error);
        float derivative = Kd * (error - prev_error);
        float output = Kp * error + integral + derivative;

        // Set PWM duty cycle and relay state
        if (output > 0) {
            pwmWrite(PWM_PIN, output);
            digitalWrite(RELAY_PIN, HIGH);
        } else {
            pwmWrite(PWM_PIN, 0);
            digitalWrite(RELAY_PIN, LOW);
        }

        // Log temperature and PID output
        log_temperature(log_file, temp, setpoint, output);

        // Wait for next iteration
        usleep(5000000);
    }

    // Clean up on exit
    fclose(log_file);
    pwmWrite(PWM_PIN, 0);
    digitalWrite(RELAY_PIN, LOW);

    return 0;
}

int read_temperature(int fd) {
    uint8_t data[9];
    if (wiringPiI2CReadReg8(fd, 0xAA, data, 9) != 9) {
        return -1;
    }

    if (data[8] != crc8(data, 8)) {
        return -1;
    }

    int16_t temp = (data[0] << 8) | data[1];
    return temp / 16;
}

void log_temperature(FILE *log_file, int temp, int setpoint, float output) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    fprintf(log_file, "%ld.%06ld %d %d %f\n", tv.tv_sec, tv.tv_usec, temp, setpoint, output);
}

void sigint_handler(int signum) {
    printf("Received SIGINT\n");
    fclose(log_file);
    pwmWrite(PWM_PIN, 0);
    digitalWrite(RELAY_PIN, LOW);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM\n");
    fclose(log_file);
    pwmWrite(PWM_PIN, 0);
    digitalWrite(RELAY_PIN, LOW);
    exit(0);
}
