#define AHT20_STATUS_BUSY 0x01
#define AHT20_RETRY_COUNT 3
#define AHT20_RETRY_DELAY 10
#define AHT20_POLL_INTERVAL 5
#define AHT20_HUMIDITY_THRESHOLD_HIGH 60
#define AHT20_HUMIDITY_THRESHOLD_LOW 55

int main(void)
{
    int fd;
    uint8_t buf[6];
    uint8_t status;
    uint16_t humidity;
    int retries;
    int i;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Initialize GPIO pin for dehumidifier relay
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        close(fd);
        return 1;
    }

    // Set GPIO pin for dehumidifier relay as output
    if (gpio_set_mode(17, GPIO_OUTPUT) < 0) {
        perror("Failed to set GPIO pin as output");
        gpio_close();
        close(fd);
        return 1;
    }

    // Set GPIO pin for dehumidifier relay to low
    if (gpio_write(17, 0) < 0) {
        perror("Failed to set GPIO pin to low");
        gpio_close();
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger measurement
        if (i2c_smbus_write_byte_data(fd, AHT20_CMD_MEASURE) < 0) {
            perror("Failed to trigger measurement");
            gpio_close();
            close(fd);
            return 1;
        }

        // Wait for measurement to complete
        usleep(80000);

        // Read measurement result
        if (i2c_smbus_read_i2c_block_data(fd, AHT20_CMD_READ, 6, buf) < 0) {
            perror("Failed to read measurement result");
            gpio_close();
            close(fd);
            return 1;
        }

        // Check status byte
        status = buf[0];
        if ((status & AHT20_STATUS_CALIBRATED) == 0 || (status & AHT20_STATUS_BUSY) != 0) {
            perror("Sensor not calibrated or busy");
            gpio_close();
            close(fd);
            return 1;
        }

        // Calculate humidity
        humidity = (buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4);

        // Print humidity reading
        printf("Humidity: %d.%02d%%\n", humidity / 100, humidity % 100);

        // Check humidity threshold
        if (humidity > AHT20_HUMIDITY_THRESHOLD_HIGH) {
            // Activate dehumidifier relay
            if (gpio_write(17, 1) < 0) {
                perror("Failed to activate dehumidifier relay");
                gpio_close();
                close(fd);
                return 1;
            }
        } else if (humidity < AHT20_HUMIDITY_THRESHOLD_LOW) {
            // Deactivate dehumidifier relay
            if (gpio_write(17, 0) < 0) {
                perror("Failed to deactivate dehumidifier relay");
                gpio_close();
                close(fd);
                return 1;
            }
        }

        // Wait for next measurement
        sleep(AHT20_POLL_INTERVAL);
    }

    // Clean up
    gpio_close();
    close(fd);
    return 0;
}

