#define HTU21D_I2C_ADDR 0x40
#define HTU21D_TEMP_REG 0xE3
#define HTU21D_HUM_REG 0xE5
#define HTU21D_TEMP_RES 0x00
#define HTU21D_HUM_RES 0x00
#define HTU21D_TEMP_CAL 0x00
#define HTU21D_HUM_CAL 0x00

#define API_URL "http://api.example.com/humidity"

int main(int argc, char *argv[]) {
  // Initialize syslog
  openlog("htu21d-reader", LOG_PID, LOG_USER);

  // Initialize I2C bus
  int i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
    return 1;
  }

  // Initialize HTU21D sensor
  int htu21d_fd = pigpio_i2c_open(i2c_fd, HTU21D_I2C_ADDR, 0);
  if (htu21d_fd < 0) {
    syslog(LOG_ERR, "Failed to open HTU21D sensor: %s", strerror(errno));
    return 1;
  }

  // Set HTU21D sensor resolution and calibration
  if (pigpio_i2c_write(htu21d_fd, HTU21D_TEMP_REG, HTU21D_TEMP_RES) < 0) {
    syslog(LOG_ERR, "Failed to set HTU21D temperature resolution: %s", strerror(errno));
    return 1;
  }
  if (pigpio_i2c_write(htu21d_fd, HTU21D_HUM_REG, HTU21D_HUM_RES) < 0) {
    syslog(LOG_ERR, "Failed to set HTU21D humidity resolution: %s", strerror(errno));
    return 1;
  }
  if (pigpio_i2c_write(htu21d_fd, HTU21D_TEMP_CAL, HTU21D_TEMP_CAL) < 0) {
    syslog(LOG_ERR, "Failed to set HTU21D temperature calibration: %s", strerror(errno));
    return 1;
  }
  if (pigpio_i2c_write(htu21d_fd, HTU21D_HUM_CAL, HTU21D_HUM_CAL) < 0) {
    syslog(LOG_ERR, "Failed to set HTU21D humidity calibration: %s", strerror(errno));
    return 1;
  }

  // Set up HTTP POST request
  int sock_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (sock_fd < 0) {
    syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
    return 1;
  }
  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(80);
  server_addr.sin_addr.s_addr = inet_addr("api.example.com");
  if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
    return 1;
  }
  char request[1024];
  snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: 100\r\n\r\n", API_URL);

  // Main loop
  while (1) {
    // Read temperature and humidity from HTU21D sensor
    int temp = pigpio_i2c_read(htu21d_fd, HTU21D_TEMP_REG);
    if (temp < 0) {
      syslog(LOG_ERR, "Failed to read temperature from HTU21D sensor: %s", strerror(errno));
      return 1;
    }
    int hum = pigpio_i2c_read(htu21d_fd, HTU21D_HUM_REG);
    if (hum < 0) {
      syslog(LOG_ERR, "Failed to read humidity from HTU21D sensor: %s", strerror(errno));
      return 1;
    }

    // Build JSON document
    char json[1024];
    snprintf(json, sizeof(json), "{\"temperature\": %d, \"humidity\": %d}", temp, hum);

    // Send HTTP POST request
    if (send(sock_fd, request, strlen(request), 0) < 0) {
      syslog(LOG_ERR, "Failed to send HTTP POST request: %s", strerror(errno));
      return 1;
    }
    if (send(sock_fd, json, strlen(json), 0) < 0) {
      syslog(LOG_ERR, "Failed to send JSON document: %s", strerror(errno));
      return 1;
    }

    // Wait for 60 seconds
    sleep(60);
  }

  // Clean up
  close(sock_fd);
  pigpio_i2c_close(htu21d_fd);
  close(i2c_fd);
  closelog();

  return 0;
}

