#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_CHIP_LINE_RAIN 17
#define GPIO_CHIP_LINE_MOTOR_ENA 22
#define GPIO_CHIP_LINE_MOTOR_IN1 23
#define GPIO_CHIP_LINE_MOTOR_IN2 24

#define MOTOR_DURATION 5

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void setup_signal_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void log_timestamp(void) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    printf("%02d:%02d:%02d ", tm->tm_hour, tm->tm_min, tm->tm_sec);
}

static void log_rain_detected(void) {
    log_timestamp();
    printf("Rain detected\n");
}

static void log_motor_start(void) {
    log_timestamp();
    printf("Motor started\n");
}

static void log_motor_stop(void) {
    log_timestamp();
    printf("Motor stopped\n");
}

static void log_error(const char *msg) {
    log_timestamp();
    printf("Error: %s\n", msg);
}

static void motor_start(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line_ena;
    struct gpiod_line *line_in1;
    struct gpiod_line *line_in2;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return;
    }

    line_ena = gpiod_chip_get_line(chip, GPIO_CHIP_LINE_MOTOR_ENA);
    if (!line_ena) {
        log_error("Failed to get ENA line");
        goto error_ena;
    }

    line_in1 = gpiod_chip_get_line(chip, GPIO_CHIP_LINE_MOTOR_IN1);
    if (!line_in1) {
        log_error("Failed to get IN1 line");
        goto error_in1;
    }

    line_in2 = gpiod_chip_get_line(chip, GPIO_CHIP_LINE_MOTOR_IN2);
    if (!line_in2) {
        log_error("Failed to get IN2 line");
        goto error_in2;
    }

    ret = gpiod_line_request_output(line_ena, "motor_ena", 1);
    if (ret < 0) {
        log_error("Failed to request ENA line");
        goto error_ena_request;
    }

    ret = gpiod_line_request_output(line_in1, "motor_in1", 1);
    if (ret < 0) {
        log_error("Failed to request IN1 line");
        goto error_in1_request;
    }

    ret = gpiod_line_request_output(line_in2, "motor_in2", 1);
    if (ret < 0) {
        log_error("Failed to request IN2 line");
        goto error_in2_request;
    }

    log_motor_start();

    sleep(MOTOR_DURATION);

    gpiod_line_release(line_ena);
    gpiod_line_release(line_in1);
    gpiod_line_release(line_in2);

    log_motor_stop();

    return;

error_ena_request:
    gpiod_line_release(line_in1);
error_in1_request:
    gpiod_line_release(line_in2);
error_in2_request:
    gpiod_line_release(line_ena);
error_ena:
    gpiod_chip_close(chip);
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line_rain;

    setup_signal_handlers();

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return 1;
    }

    line_rain = gpiod_chip_get_line(chip, GPIO_CHIP_LINE_RAIN);
    if (!line_rain) {
        log_error("Failed to get rain line");
        goto error_rain;
    }

    ret = gpiod_line_request_input(line_rain, "rain");
    if (ret < 0) {
        log_error("Failed to request rain line");
        goto error_rain_request;
    }

