#define RED_CATHODE 17
#define GREEN_CATHODE 22
#define BLUE_CATHODE 27

#define RED_CHANNEL 0
#define GREEN_CHANNEL 1
#define BLUE_CHANNEL 2

#define MIN_PWM 0
#define MAX_PWM 255

#define CPU_LOAD_FILE "/proc/stat"

#define CPU_LOAD_INTERVAL 500 // ms

#define COLOR_GREEN 0x00ff00
#define COLOR_YELLOW 0xffff00
#define COLOR_RED 0xff0000

int main(int argc, char *argv[]) {
  // Initialize the pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio library\n");
    return 1;
  }

  // Set up the LED channels
  if (gpioSetMode(RED_CATHODE, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set mode for red cathode\n");
    return 1;
  }
  if (gpioSetMode(GREEN_CATHODE, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set mode for green cathode\n");
    return 1;
  }
  if (gpioSetMode(BLUE_CATHODE, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set mode for blue cathode\n");
    return 1;
  }

  // Set up the signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open the CPU load file
  int fd = open(CPU_LOAD_FILE, O_RDONLY);
  if (fd < 0) {
    fprintf(stderr, "Failed to open CPU load file\n");
    return 1;
  }

  // Read the initial CPU load
  char buffer[1024];
  if (read(fd, buffer, sizeof(buffer)) < 0) {
    fprintf(stderr, "Failed to read CPU load\n");
    return 1;
  }
  float initial_load = parse_cpu_load(buffer);

  // Main loop
  while (1) {
    // Read the current CPU load
    if (read(fd, buffer, sizeof(buffer)) < 0) {
      fprintf(stderr, "Failed to read CPU load\n");
      return 1;
    }
    float current_load = parse_cpu_load(buffer);

    // Calculate the color gradient
    int red = 0;
    int green = 0;
    int blue = 0;
    if (current_load < initial_load) {
      red = (int)((current_load / initial_load) * 255);
      green = 255 - red;
    } else {
      green = (int)((current_load / initial_load) * 255);
      red = 255 - green;
    }

    // Set the PWM values
    if (gpioPWM(RED_CATHODE, RED_CHANNEL, red) < 0) {
      fprintf(stderr, "Failed to set PWM value for red channel\n");
      return 1;
    }
    if (gpioPWM(GREEN_CATHODE, GREEN_CHANNEL, green) < 0) {
      fprintf(stderr, "Failed to set PWM value for green channel\n");
      return 1;
    }
    if (gpioPWM(BLUE_CATHODE, BLUE_CHANNEL, blue) < 0) {
      fprintf(stderr, "Failed to set PWM value for blue channel\n");
      return 1;
    }

    // Sleep for the specified interval
    usleep(CPU_LOAD_INTERVAL * 1000);
  }

  // Clean up
  gpioTerminate();
  close(fd);

  return 0;
}

float parse_cpu_load(char *buffer) {
  // Parse the CPU load from the buffer
  float load = 0.0;
  sscanf(buffer, "%f", &load);
  return load;
}

void signal_handler(int signal) {
  // Turn off the LED
  gpioPWM(RED_CATHODE, RED_CHANNEL, MIN_PWM);
  gpioPWM(GREEN_CATHODE, GREEN_CHANNEL, MIN_PWM);
  gpioPWM(BLUE_CATHODE, BLUE_CHANNEL, MIN_PWM);

  // Clean up
  gpioTerminate();
  close(fd);

  // Exit
  exit(0);
}

