#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <bmp280.h>

#define I2C_ADDR 0x76
#define I2C_SDA 2
#define I2C_SCL 3
#define UDP_ADDR "192.168.1.100"
#define UDP_PORT 5000

int main(int argc, char *argv[]) {
    int i2c_fd, udp_fd;
    struct bmp280_dev dev;
    struct bmp280_data data;
    char json_str[100];

    // Initialize I2C
    if ((i2c_fd = pigpio_start(I2C_SDA, I2C_SCL)) < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Initialize BMP280
    if (bmp280_init(&dev, i2c_fd, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize BMP280\n");
        return 1;
    }

    // Initialize UDP
    if ((udp_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Failed to initialize UDP\n");
        return 1;
    }

    // Set up UDP address
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_ADDR, &addr.sin_addr);

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read temperature and pressure from BMP280
        if (bmp280_read(&dev, &data) < 0) {
            fprintf(stderr, "Failed to read from BMP280\n");
            continue;
        }

        // Format data as JSON string
        snprintf(json_str, sizeof(json_str), "{\"temperature\":%.2f, \"pressure\":%.2f}", data.temperature, data.pressure);

        // Send JSON string via UDP
        if (sendto(udp_fd, json_str, strlen(json_str), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
            continue;
        }

        // Wait for 5 seconds before sending next packet
        sleep(5);
    }

    // Clean up
    bmp280_close(&dev);
    pigpio_stop(i2c_fd);
    close(udp_fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT\n");
    bmp280_close(&dev);
    pigpio_stop(i2c_fd);
    close(udp_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM\n");
    bmp280_close(&dev);
    pigpio_stop(i2c_fd);
    close(udp_fd);
    exit(0);
}

