#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <max31855.h>

#define FAN_PWM_PIN 18
#define FAN_PWM_FREQ 1000
#define FAN_PWM_RANGE 255
#define TEMP_BUFFER_SIZE 20

struct temp_data {
    time_t timestamp;
    float temperature;
    uint8_t duty_cycle;
};

struct temp_data temp_buffer[TEMP_BUFFER_SIZE];

void handle_sigint(int signal) {
    printf("Received SIGINT, stopping PWM and closing SPI interface\n");
    pigpio_stop_pwm(FAN_PWM_PIN);
    pigpio_close_spi(0);
    printf("Full contents of circular buffer:\n");
    for (int i = 0; i < TEMP_BUFFER_SIZE; i++) {
        printf("%d: %f°C, %d%%\n", temp_buffer[i].timestamp, temp_buffer[i].temperature, temp_buffer[i].duty_cycle);
    }
    pigpio_terminate();
    exit(0);
}

int main(void) {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (pigpio_open_spi(0, 500000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel 0\n");
        pigpio_terminate();
        return 1;
    }

    if (pigpio_start_pwm(FAN_PWM_PIN, FAN_PWM_FREQ, FAN_PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO %d\n", FAN_PWM_PIN);
        pigpio_close_spi(0);
        pigpio_terminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (true) {
        float temperature;
        if (max31855_read_temperature(0, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature from MAX31855\n");
            continue;
        }

        uint8_t duty_cycle;
        if (temperature < 25) {
            duty_cycle = 0;
        } else if (temperature < 40) {
            duty_cycle = (temperature - 25) / 15 * FAN_PWM_RANGE / 100;
        } else if (temperature < 60) {
            duty_cycle = (temperature - 40) / 20 * FAN_PWM_RANGE / 100;
        } else {
            duty_cycle = FAN_PWM_RANGE;
        }

        pigpio_set_pwm_dutycycle(FAN_PWM_PIN, duty_cycle);

        struct temp_data data = {
            .timestamp = time(NULL),
            .temperature = temperature,
            .duty_cycle = duty_cycle,
        };
        memcpy(&temp_buffer[temp_buffer_index], &data, sizeof(data));
        temp_buffer_index = (temp_buffer_index + 1) % TEMP_BUFFER_SIZE;

        sleep(1);
    }

    return 0;
}

