#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define GPIO_PIN 24
#define SAMPLE_PERIOD 50
#define BUFFER_SIZE 60
#define AVERAGE_WINDOW 5
#define THRESHOLD 5

struct sample {
    uint32_t timestamp;
    int32_t pressure;
};

struct sample buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_pressure(int32_t pressure) {
    printf("Pressure: %d hPa\n", pressure);
}

void log_alert(int32_t pressure) {
    printf("Alert: pressure deviation exceeded threshold (%d hPa)\n", pressure);
}

void sample_pressure() {
    int32_t pressure;
    if (bmp180_read_pressure(i2c_fd, &pressure) != 0) {
        log_error("Failed to read pressure");
        return;
    }
    struct sample sample;
    sample.timestamp = time(NULL);
    sample.pressure = pressure;
    buffer[buffer_head] = sample;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
}

void compute_average() {
    int32_t sum = 0;
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        sum += buffer[i].pressure;
    }
    int32_t average = sum / (buffer_head - buffer_tail);
    if (average < 0) {
        log_error("Invalid average");
        return;
    }
    int32_t deviation = abs(buffer[buffer_head].pressure - average);
    if (deviation > THRESHOLD) {
        log_alert(deviation);
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return 1;
    }
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }
    if (bmp180_init(i2c_fd, I2C_ADDR) != 0) {
        log_error("Failed to initialize BMP180");
        return 1;
    }
    signal(SIGINT, sigint_handler);
    while (true) {
        sample_pressure();
        compute_average();
        usleep(SAMPLE_PERIOD * 1000);
    }
    return 0;
}

