#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_PWM_GPIO 18
#define FAN_PWM_FREQ 25000
#define FAN_PWM_RANGE 255
#define MIN_TEMP 40
#define MAX_TEMP 70

int main(int argc, char *argv[]) {
  // Initialize the PWM driver
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize PWM driver\n");
    return 1;
  }

  // Open the CPU temperature file
  int temp_fd = open(CPU_TEMP_FILE, O_RDONLY);
  if (temp_fd < 0) {
    fprintf(stderr, "Failed to open CPU temperature file\n");
    return 1;
  }

  // Open the log file
  int log_fd = open("fan_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
  if (log_fd < 0) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, handle_sigint);
  signal(SIGTERM, handle_sigterm);

  // Main loop
  while (1) {
    // Read the CPU temperature
    char temp_str[10];
    if (read(temp_fd, temp_str, 10) < 0) {
      fprintf(stderr, "Failed to read CPU temperature\n");
      return 1;
    }
    int temp = atoi(temp_str);

    // Map the temperature to a PWM duty cycle
    int duty = map_temp_to_duty(temp);

    // Set the PWM duty cycle
    if (gpioPWM(FAN_PWM_GPIO, FAN_PWM_FREQ, duty) < 0) {
      fprintf(stderr, "Failed to set PWM duty cycle\n");
      return 1;
    }

    // Log the current timestamp, temperature, and duty cycle
    char log_str[100];
    sprintf(log_str, "%ld, %d, %d\n", time(NULL), temp, duty);
    if (write(log_fd, log_str, strlen(log_str)) < 0) {
      fprintf(stderr, "Failed to write to log file\n");
      return 1;
    }

    // Sleep for 5 seconds
    sleep(5);
  }

  // Clean up
  close(temp_fd);
  close(log_fd);
  gpioTerminate();

  return 0;
}

int map_temp_to_duty(int temp) {
  if (temp < MIN_TEMP) {
    return 0;
  } else if (temp > MAX_TEMP) {
    return FAN_PWM_RANGE;
  } else {
    return (temp - MIN_TEMP) * FAN_PWM_RANGE / (MAX_TEMP - MIN_TEMP);
  }
}

void handle_sigint(int signal) {
  // Gracefully stop the fan
  gpioPWM(FAN_PWM_GPIO, FAN_PWM_FREQ, 0);

  // Close any open files
  close(temp_fd);
  close(log_fd);

  // Terminate the PWM driver
  gpioTerminate();

  // Exit the program
  exit(0);
}

void handle_sigterm(int signal) {
  // Gracefully stop the fan
  gpioPWM(FAN_PWM_GPIO, FAN_PWM_FREQ, 0);

  // Close any open files
  close(temp_fd);
  close(log_fd);

  // Terminate the PWM driver
  gpioTerminate();

  // Exit the program
  exit(0);
}

