#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define GPIO_PIN 18

#define BUFFER_SIZE 60
#define AVG_SIZE 10

#define TEMP_THRESHOLD 28.0

typedef struct {
    float temperature;
    uint64_t timestamp;
} temperature_t;

temperature_t buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

void* alert_thread(void* arg) {
    while (true) {
        pthread_mutex_lock(&buffer_mutex);
        float avg = 0;
        for (int i = 0; i < AVG_SIZE; i++) {
            avg += buffer[i].temperature;
        }
        avg /= AVG_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        if (avg > TEMP_THRESHOLD) {
            gpio_set_value(GPIO_PIN, 1);
        } else {
            gpio_set_value(GPIO_PIN, 0);
        }

        sleep(1);
    }
}

int main(int argc, char* argv[]) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    int gpio_fd = gpio_export(GPIO_PIN);
    if (gpio_fd < 0) {
        perror("Failed to export GPIO pin");
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(gpio_fd, GPIO_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    pthread_t alert_thread_id;
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        perror("Failed to create alert thread");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    while (true) {
        temperature_t temp;
        if (read(i2c_fd, &temp, sizeof(temperature_t)) != sizeof(temperature_t)) {
            perror("Failed to read temperature");
            close(gpio_fd);
            close(i2c_fd);
            return 1;
        }

        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_head].temperature = temp.temperature;
        buffer[buffer_head].timestamp = temp.timestamp;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        sleep(1);
    }

    close(gpio_fd);
    close(i2c_fd);
    return 0;
}

