#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>
#include <max31865.h>

#define PWM_FREQ 1000
#define PWM_DUTY 100
#define PWM_GPIO 18
#define SPI_CE0 0
#define SPI_SPEED 500000
#define RTD_RESISTANCE 430
#define PT100_NOMINAL_RESISTANCE 100
#define PT100_TEMP_COEFF 3950
#define PT100_TEMP_OFFSET -50
#define PID_KP 1.0
#define PID_KI 0.1
#define PID_KD 0.01
#define PID_TARGET_TEMP 25
#define PID_MAX_TEMP 80
#define PID_MIN_TEMP 0
#define PID_MAX_DUTY 100
#define PID_MIN_DUTY 0

int main(int argc, char *argv[]) {
  // Initialize the PWM driver
  if (pigpio_init() < 0) {
    fprintf(stderr, "Failed to initialize PWM driver\n");
    return 1;
  }

  // Initialize the SPI interface
  if (spi_init(SPI_CE0, SPI_SPEED) < 0) {
    fprintf(stderr, "Failed to initialize SPI interface\n");
    return 1;
  }

  // Load the PID gains and target temperature from the configuration file
  char *config_file = "/etc/pid.json";
  FILE *fp = fopen(config_file, "r");
  if (fp == NULL) {
    fprintf(stderr, "Failed to open configuration file: %s\n", config_file);
    return 1;
  }
  char *line = NULL;
  size_t len = 0;
  ssize_t read;
  while ((read = getline(&line, &len, fp)) != -1) {
    if (strstr(line, "target_temp") != NULL) {
      PID_TARGET_TEMP = atoi(strchr(line, ':') + 1);
    } else if (strstr(line, "kp") != NULL) {
      PID_KP = atof(strchr(line, ':') + 1);
    } else if (strstr(line, "ki") != NULL) {
      PID_KI = atof(strchr(line, ':') + 1);
    } else if (strstr(line, "kd") != NULL) {
      PID_KD = atof(strchr(line, ':') + 1);
    }
  }
  fclose(fp);

  // Set up the PID loop
  double error = 0;
  double integral = 0;
  double derivative = 0;
  double last_temp = 0;
  double last_duty = 0;
  double temp = 0;
  double duty = 0;
  double dt = 0.1;

  // Main loop
  while (1) {
    // Read the temperature from the RTD
    if (max31865_read_temp(SPI_CE0, RTD_RESISTANCE, PT100_NOMINAL_RESISTANCE, PT100_TEMP_COEFF, PT100_TEMP_OFFSET, &temp) < 0) {
      fprintf(stderr, "Failed to read temperature from RTD\n");
      return 1;
    }

    // Calculate the PID output
    error = PID_TARGET_TEMP - temp;
    integral += error * dt;
    derivative = (error - last_temp) / dt;
    duty = PID_KP * error + PID_KI * integral + PID_KD * derivative;
    duty = clamp(duty, PID_MIN_DUTY, PID_MAX_DUTY);

    // Set the PWM duty cycle
    if (pigpio_set_dutycycle(PWM_GPIO, PWM_FREQ, duty) < 0) {
      fprintf(stderr, "Failed to set PWM duty cycle\n");
      return 1;
    }

    // Check for failsafe conditions
    if (temp > PID_MAX_TEMP || temp < PID_MIN_TEMP) {
      fprintf(stderr, "Temperature out of range: %f\n", temp);
      return 1;
    }

    // Sleep for the loop period
    usleep(100000);
  }

  // Clean up and exit
  pigpio_close();
  spi_close(SPI_CE0);
  return 0;
}

// Clamp a value to a range
double clamp(double value, double min, double max) {
  if (value < min) {
    return min;
  } else if (value > max) {
    return max;
  } else {
    return value;
  }
}

