#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define GPIO_PIN 27
#define DEBOUNCE_TIME 200
#define LOG_FILE "pressure_log.txt"

static volatile bool logging_enabled = false;
static volatile bool logging_error = false;
static volatile bool i2c_error = false;
static volatile bool driver_error = false;

static void sigint_handler(int signum) {
    logging_enabled = false;
    logging_error = false;
    i2c_error = false;
    driver_error = false;
    pigpio_stop();
    exit(0);
}

static void gpio_handler(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        logging_enabled = !logging_enabled;
    }
}

static void i2c_handler(int i2c, int level, uint32_t tick) {
    if (level == 0) {
        i2c_error = true;
    }
}

static void driver_handler(int driver, int level, uint32_t tick) {
    if (level == 0) {
        driver_error = true;
    }
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up GPIO pin
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }
    if (pigpio_gpio_mode_set(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }
    if (pigpio_gpio_pull_up_down(GPIO_PIN, PI_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin pull-up\n");
        return 1;
    }
    if (pigpio_gpio_glitch_filter(GPIO_PIN, 10000) < 0) {
        fprintf(stderr, "Failed to set GPIO pin glitch filter\n");
        return 1;
    }
    if (pigpio_gpio_notify_begin(GPIO_PIN, 0, 0) < 0) {
        fprintf(stderr, "Failed to start GPIO pin notification\n");
        return 1;
    }

    // Set up I2C bus
    if (pigpio_i2c_open(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }
    if (pigpio_i2c_set_slave_address(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }
    if (pigpio_i2c_set_frequency(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C frequency\n");
        return 1;
    }
    if (pigpio_i2c_set_timeout(I2C_BUS, 1000) < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        return 1;
    }

    // Set up BMP180 driver
    if (bmp180_init() < 0) {
        fprintf(stderr, "Failed to initialize BMP180 driver\n");
        return 1;
    }

    // Set up logging
    if (pigpio_file_open(LOG_FILE, "w") < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Check for GPIO interrupt
        if (pigpio_gpio_read(GPIO_PIN) == 0) {
            logging_enabled = !logging_enabled;
        }

        // Check for I2C error
        if (pigpio_i2c_read(I2C_BUS, I2C_ADDR, 1, 1) < 0) {
            i2c_error = true;
        }

        // Check for driver error
        if (bmp180_read_calibration_data() < 0) {
            driver_error = true;
        }

        // Read pressure data
        if (logging_enabled && !i2c_error && !driver_error) {
            int32_t ut = 0;
            int32_t up = 0;
            if (bmp180_read_uncompensated_temperature(&ut) < 0) {
                fprintf(stderr, "Failed to read uncompensated temperature\n");
                return 1;
            }
            if (bmp180_read_uncompensated_pressure(&up) < 0) {
                fprintf(stderr, "Failed to read uncompensated pressure\n");
                return 1;
            }
            int32_t t = bmp180_compensate_temperature(ut);
            int32_t p = bmp180_compensate_pressure(up, t);
            fprintf(stderr, "Temperature: %d.%02d°C\n", t / 100, t % 100);
            fprintf(stderr, "Pressure: %d.%02d Pa\n", p / 100, p % 100);
            if (pigpio_file_write(LOG_FILE, "Temperature: %d.%02d°C\n", t / 100, t % 100) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                return 1;
            }
            if (pigpio_file_write(LOG_FILE, "Pressure: %d.%02d Pa\n", p / 100, p % 100) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                return 1;
            }
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    pigpio_gpio_notify_end(GPIO_PIN);
    pigpio_i2c_close(I2C_BUS);
    pigpio_file_close(LOG_FILE);
    bmp180_deinit();
    pigpio_stop();

    return 0;
}

