#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define MAX31855_CS_PIN 8
#define MAX31855_MISO_PIN 9
#define MAX31855_MOSI_PIN 10
#define MAX31855_SCLK_PIN 11
#define MAX31855_SPI_FREQ 2000000

#define HEATER_PIN 17
#define HEATER_DUTY_CYCLE_MAX 80

#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up SPI
    spi_device_t *spi = spi_device_open(chip, MAX31855_CS_PIN, MAX31855_MISO_PIN, MAX31855_MOSI_PIN, MAX31855_SCLK_PIN, MAX31855_SPI_FREQ);
    if (spi == NULL) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    // Set up PWM
    pwm_device_t *pwm = pwm_device_open(chip, HEATER_PIN);
    if (pwm == NULL) {
        fprintf(stderr, "Error: Failed to open PWM device\n");
        return 1;
    }

    // Set up log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Set up PI controller
    double kp = 1.0;
    double ki = 0.0;
    double kd = 0.0;
    double target_temperature = 25.0;
    double error = 0.0;
    double integral = 0.0;
    double derivative = 0.0;
    double duty_cycle = 0.0;

    // Main loop
    while (running) {
        // Read temperature from MAX31855
        uint16_t raw_temperature = 0;
        if (spi_device_read(spi, &raw_temperature, 2) != 0) {
            fprintf(stderr, "Error: Failed to read temperature from MAX31855\n");
            continue;
        }

        // Convert raw temperature to Celsius
        double temperature = (raw_temperature / 32768.0) * 100.0;

        // Calculate error and integral
        error = target_temperature - temperature;
        integral += error;

        // Calculate derivative
        derivative = error - previous_error;

        // Calculate duty cycle
        duty_cycle = kp * error + ki * integral + kd * derivative;

        // Clamp duty cycle to maximum
        if (duty_cycle > HEATER_DUTY_CYCLE_MAX) {
            duty_cycle = HEATER_DUTY_CYCLE_MAX;
        }

        // Set duty cycle on PWM
        pwm_device_set_duty_cycle(pwm, duty_cycle);

        // Log temperature and duty cycle
        fprintf(log_file, "%s,%.2f,%.2f\n", time(NULL), temperature, duty_cycle);

        // Wait for next iteration
        usleep(1000000);
    }

    // Clean up
    pwm_device_close(pwm);
    spi_device_close(spi);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

