#define RED_DUTY 255
#define GREEN_DUTY 255
#define BLUE_DUTY 255

#define MIN_TEMP 40000
#define MAX_TEMP 60000

volatile sig_atomic_t sig_flag = 0;

void sigint_handler(int signum) {
    sig_flag = 1;
    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);
    gpioWrite(GPIO_RED, RED_DUTY);
    gpioWrite(GPIO_GREEN, GREEN_DUTY);
    gpioWrite(GPIO_BLUE, BLUE_DUTY);
    gpioTerminate();
}

int main(void) {
    int fd;
    char buf[10];
    int temp;
    int duty_red, duty_green, duty_blue;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((fd = open(TEMP_FILE, O_RDONLY)) < 0) {
        fprintf(stderr, "Failed to open temperature file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (!sig_flag) {
        if (read(fd, buf, 10) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        temp = atoi(buf);

        if (temp < MIN_TEMP) {
            duty_red = RED_DUTY;
            duty_green = GREEN_DUTY;
            duty_blue = BLUE_DUTY;
        } else if (temp < MAX_TEMP) {
            duty_red = RED_DUTY;
            duty_green = GREEN_DUTY;
            duty_blue = BLUE_DUTY;
        } else {
            duty_red = RED_DUTY;
            duty_green = GREEN_DUTY;
            duty_blue = BLUE_DUTY;
        }

        gpioSetMode(GPIO_RED, PI_OUTPUT);
        gpioSetMode(GPIO_GREEN, PI_OUTPUT);
        gpioSetMode(GPIO_BLUE, PI_OUTPUT);
        gpioWrite(GPIO_RED, duty_red);
        gpioWrite(GPIO_GREEN, duty_green);
        gpioWrite(GPIO_BLUE, duty_blue);

