#include <netdb.h>
#include <errno.h>
#include <fcntl.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define DHT22_START_LOW_MS 1
#define DHT22_RESPONSE_BITS 40
#define DHT22_CHECKSUM_BITS 8
#define DHT22_RETRIES 3

#define HTTP_SERVER "yourserver.com"
#define HTTP_PORT 80
#define HTTP_PATH "/api/humidity"

static int gpio_fd;
static int http_fd;

static void cleanup(void) {
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
    if (http_fd != -1) {
        close(http_fd);
    }
}

static void handle_sigint(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static void handle_sigterm(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static void init_gpio(void) {
    gpio_fd = pigpio_start(NULL, 0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void init_http(void) {
    struct addrinfo hints;
    struct addrinfo *result, *rp;
    int s;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;

    s = getaddrinfo(HTTP_SERVER, HTTP_PORT, &hints, &result);
    if (s != 0) {
        fprintf(stderr, "Failed to get address info: %s\n", gai_strerror(s));
        exit(EXIT_FAILURE);
    }

    for (rp = result; rp != NULL; rp = rp->ai_next) {
        http_fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (http_fd == -1) {
            continue;
        }

        if (connect(http_fd, rp->ai_addr, rp->ai_addrlen) == 0) {
            break;
        }

        close(http_fd);
        http_fd = -1;
    }

    if (http_fd == -1) {
        fprintf(stderr, "Failed to connect to HTTP server\n");
        exit(EXIT_FAILURE);
    }

    freeaddrinfo(result);
}

static void read_dht22(void) {
    uint8_t response[DHT22_RESPONSE_BITS];
    uint8_t checksum[DHT22_CHECKSUM_BITS];
    uint8_t data[DHT22_RESPONSE_BITS - DHT22_CHECKSUM_BITS];
    uint8_t i, j;

    // Start signal
    pigpio_gpio_write(gpio_fd, DHT22_PIN, PI_LOW);
    usleep(DHT22_START_LOW_MS * 1000);
    pigpio_gpio_write(gpio_fd, DHT22_PIN, PI_HIGH);

    // Read response
    for (i = 0; i < DHT22_RESPONSE_BITS; i++) {
        response[i] = pigpio_gpio_read(gpio_fd, DHT22_PIN);
    }

    // Checksum
    for (i = 0, j = 0; i < DHT22_RESPONSE_BITS - DHT22_CHECKSUM_BITS; i++) {
        if (i % 2 == 0) {
            checksum[j++] = response[i];
        }
    }

    // Data
    for (i = 0, j = 0; i < DHT22_RESPONSE_BITS - DHT22_CHECKSUM_BITS; i++) {
        if (i % 2 == 1) {
            data[j++] = response[i];
        }
    }

    // Validate checksum
    if (checksum[0] != (data[0] + data[1] + data[2] + data[3])) {
        fprintf(stderr, "Checksum mismatch\n");
        exit(EXIT_FAILURE);
    }

    // Post data to HTTP server
    char payload[1024];
    sprintf(payload, "{\"humidity\": %d, \"temperature\": %d}", data[0], data[2]);
    send(http_fd, payload, strlen(payload), 0);
}

int main(void) {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    init_gpio();
    init_http();

    for (int i = 0; i < DHT22_RETRIES; i++) {
        read_dht22();
    }

    cleanup();
    return EXIT_SUCCESS;
}

