#include <libgpiod.h>

#define FAN_PIN 18
#define FAN_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70

static int fan_fd;
static int log_fd;

static void handle_sigint(int signum) {
    // Turn off the fan
    gpiod_line_set_value(fan_fd, 0);

    // Close the log file
    close(log_fd);

    // Exit the program
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the fan GPIO line
    fan_fd = gpiod_line_open(FAN_PIN, "fan", GPIOD_LINE_OUTPUT);
    if (fan_fd < 0) {
        fprintf(stderr, "Failed to open fan GPIO line\n");
        return 1;
    }

    // Open the log file
    log_fd = open("cooling_log.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set the fan frequency
    if (gpiod_line_set_frequency(fan_fd, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set fan frequency\n");
        return 1;
    }

    // Set the fan duty cycle to 0%
    if (gpiod_line_set_value(fan_fd, 0) < 0) {
        fprintf(stderr, "Failed to set fan duty cycle\n");
        return 1;
    }

    // Register the signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Get the current CPU temperature
        double temp = get_cpu_temp();

        // Map the temperature to a PWM duty cycle
        int duty = map_temp_to_duty(temp);

        // Set the fan duty cycle
        if (gpiod_line_set_value(fan_fd, duty) < 0) {
            fprintf(stderr, "Failed to set fan duty cycle\n");
            return 1;
        }

        // Log the temperature and duty cycle
        log_temp_and_duty(temp, duty);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_line_close(fan_fd);
    close(log_fd);
    gpiod_cleanup();

    return 0;
}

double get_cpu_temp() {
    // TODO: Implement this function to read the CPU temperature
    return 0.0;
}

int map_temp_to_duty(double temp) {
    // Map the temperature to a PWM duty cycle
    int duty = (int)((temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * 100);

    // Clamp the duty cycle to the valid range
    if (duty < 0) {
        duty = 0;
    } else if (duty > 100) {
        duty = 100;
    }

    return duty;
}

void log_temp_and_duty(double temp, int duty) {
    // Log the temperature and duty cycle to the log file
    char buf[100];
    snprintf(buf, sizeof(buf), "%f,%d\n", temp, duty);
    write(log_fd, buf, strlen(buf));
}

