#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/libgpiod.h>

#define GPIO_CHANNEL_A 17
#define GPIO_CHANNEL_B 18
#define PULSES_PER_REV 360
#define RESOLUTION 2
#define FILENAME "encoder_log.txt"

// State machine states
typedef enum {
    STATE_A0,
    STATE_A1,
    STATE_B0,
    STATE_B1
} state_t;

// State machine transition table
static const state_t next_state[] = {
    [STATE_A0] = STATE_A1,
    [STATE_A1] = STATE_B0,
    [STATE_B0] = STATE_B1,
    [STATE_B1] = STATE_A0
};

// GPIO pin configuration
static const struct gpiod_line_config config = {
    .direction = GPIOD_LINE_DIRECTION_OUTPUT,
    .output_mode = GPIOD_LINE_OUTPUT_OPEN_DRAIN,
    .output_value = GPIOD_LINE_OUTPUT_ACTIVE_HIGH,
    .pull_mode = GPIOD_LINE_PULL_UP,
    .bias = GPIOD_LINE_BIAS_AS_IS
};

// GPIO pin handles
static struct gpiod_line *channel_a;
static struct gpiod_line *channel_b;

// Encoder position
static int32_t position = 0;

// Timestamp for logging
static struct timespec timestamp;

// Log file handle
static FILE *log_file;

// Signal handler for SIGINT and SIGTERM
static void signal_handler(int signal) {
    // Clean up resources
    gpiod_line_release(channel_a);
    gpiod_line_release(channel_b);
    fclose(log_file);

    // Exit program
    exit(EXIT_SUCCESS);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(FILENAME, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize GPIO pins
    channel_a = gpiod_line_get(GPIO_CHANNEL_A, &config);
    if (channel_a == NULL) {
        fprintf(stderr, "Error initializing GPIO pin %d: %s\n", GPIO_CHANNEL_A, strerror(errno));
        return EXIT_FAILURE;
    }

    channel_b = gpiod_line_get(GPIO_CHANNEL_B, &config);
    if (channel_b == NULL) {
        fprintf(stderr, "Error initializing GPIO pin %d: %s\n", GPIO_CHANNEL_B, strerror(errno));
        return EXIT_FAILURE;
    }

    // Set initial state
    state_t state = STATE_A0;

    // Main loop
    while (true) {
        // Read GPIO pins
        int a = gpiod_line_get_value(channel_a);
        int b = gpiod_line_get_value(channel_b);

        // Update state
        state = next_state[state];

        // Update position
        if (state == STATE_A1 && a == 1) {
            position++;
        } else if (state == STATE_B1 && b == 1) {
            position--;
        }

        // Normalize position
        if (position < 0) {
            position += PULSES_PER_REV;
        } else if (position >= PULSES_PER_REV) {
            position -= PULSES_PER_REV;
        }

        // Log position
        clock_gettime(CLOCK_REALTIME, &timestamp);
        fprintf(log_file, "%ld.%ld, %d\n", timestamp.tv_sec, timestamp.tv_nsec, position);
    }

    // Clean up resources
    gpiod_line_release(channel_a);
    gpiod_line_release(channel_b);
    fclose(log_file);

    return EXIT_SUCCESS;
}

