#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_ADDR 0x18
#define I2C_BUS 1
#define GPIO_LED 17
#define THRESHOLD 2000

int main(void) {
    // Open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open the GPIO line for the LED
    int gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Set the GPIO line direction to output
    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_LED, GPIO_OUT) < 0) {
        perror("Failed to set GPIO line direction");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("adpd144ri_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the sensor data
        uint16_t red, ir;
        if (read(i2c_fd, &red, 2) != 2) {
            perror("Failed to read sensor data");
            close(gpio_fd);
            close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Check the infrared reading
        if (ir > THRESHOLD) {
            // Turn on the LED
            if (write(gpio_fd, GPIO_LED, GPIO_HIGH) < 0) {
                perror("Failed to turn on LED");
                close(gpio_fd);
                close(i2c_fd);
                fclose(log_file);
                return 1;
            }
        } else {
            // Turn off the LED
            if (write(gpio_fd, GPIO_LED, GPIO_LOW) < 0) {
                perror("Failed to turn off LED");
                close(gpio_fd);
                close(i2c_fd);
                fclose(log_file);
                return 1;
            }
        }

        // Log the reading
        fprintf(log_file, "%d, %d\n", red, ir);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    close(gpio_fd);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

void signal_handler(int signal) {
    // Clean up on signal
    close(gpio_fd);
    close(i2c_fd);
    fclose(log_file);

    // Exit
    exit(0);
}

