    gain_line = gpiod_chip_get_line(chip, GPIO_GAIN);
    if (!gain_line) {
        fprintf(stderr, "Error: failed to get GPIO line for GAIN pin\n");
        return 1;
    }

    // Request the GPIO lines
    out_request = gpiod_line_request(out_line, "out", GPIOD_LINE_REQUEST_DIRECTION_INPUT, 0);
    if (!out_request) {
        fprintf(stderr, "Error: failed to request GPIO line for OUT pin\n");
        return 1;
    }

    gain_request = gpiod_line_request(gain_line, "gain", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0);
    if (!gain_request) {
        fprintf(stderr, "Error: failed to request GPIO line for GAIN pin\n");
        return 1;
    }

    // Set the GAIN pin to 60 dB
    ret = gpiod_line_set_value(gain_line, 0);
    if (ret < 0) {
