#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define TVOC_REG 0x08
#define eCO2_REG 0x09
#define IAQ_REG 0x0A

#define TVOC_MIN 0
#define TVOC_MAX 10000
#define eCO2_MIN 400
#define eCO2_MAX 2000

#define LOG_FILE "air_quality_log.csv"

int main(void) {
    // Initialize I2C interface
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C interface");
        return 1;
    }

    // Initialize SIGINT handler
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigaction(SIGINT, &sigint_handler, NULL);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read TVOC and eCO2 values
        uint16_t tvoc, eco2;
        if (i2c_read_word_data(i2c_fd, TVOC_REG, &tvoc) < 0) {
            perror("Failed to read TVOC value");
            return 1;
        }
        if (i2c_read_word_data(i2c_fd, eCO2_REG, &eco2) < 0) {
            perror("Failed to read eCO2 value");
            return 1;
        }

        // Compute IAQ index
        int iaq = (tvoc + eco2) / 2;

        // Log timestamp and IAQ value
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld.%06ld, %d\n", tv.tv_sec, tv.tv_usec, iaq);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C interface
    i2c_close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

void sigint_handler_func(int signum) {
    // Close I2C interface
    i2c_close(i2c_fd);

    // Flush and close log file
    fflush(log_file);
    fclose(log_file);

    // Terminate driver
    exit(0);
}

