#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define TTP223_TAMPER_PIN 17
#define TTP223_TAMPER_CHIP 0
#define TTP223_TAMPER_LINE 0
#define TTP223_TAMPER_DEBOUNCE_TIME 5000000

static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    gpiod_chip_close(TTP223_TAMPER_CHIP);
}

static void handle_signal(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int value;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(TTP223_TAMPER_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, TTP223_TAMPER_LINE);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the line as an input
    if (gpiod_line_request_input(line, "ttp223_tamper") != 0) {
        fprintf(stderr, "Error requesting input: %s\n", strerror(errno));
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the debounce time
    if (gpiod_line_set_debounce(line, TTP223_TAMPER_DEBOUNCE_TIME) != 0) {
        fprintf(stderr, "Error setting debounce time: %s\n", strerror(errno));
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read the line value
        if (gpiod_line_get_value(line, &value) != 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Check if the line is high
        if (value == 1) {
            // Get the current time
            clock_gettime(CLOCK_MONOTONIC, &ts);

            // Check if the line has been high for more than 5 seconds
            if (ts.tv_sec - line->tv_sec > 5) {
                // Print an intrusion alert
                printf("Intrusion detected!\n");

                // Reset the timer
                line->tv_sec = ts.tv_sec;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_close(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

