#include <alsa/asoundlib.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define SAMPLE_RATE 48000
#define CHANNELS 2
#define BUFFER_SIZE 1024

static int g_fd_i2s;
static int g_fd_file;
static int g_channel_select_pin;

static void sigint_handler(int signum)
{
    printf("Received SIGINT, terminating...\n");
    close(g_fd_i2s);
    close(g_fd_file);
    exit(0);
}

static void init_i2s(void)
{
    g_fd_i2s = open("/dev/snd/pcmC0D0c", O_RDONLY);
    if (g_fd_i2s < 0) {
        perror("Failed to open I2S device");
        exit(1);
    }

    if (ioctl(g_fd_i2s, SNDRV_PCM_IOCTL_PLAYBACK_START, NULL) < 0) {
        perror("Failed to start I2S playback");
        exit(1);
    }
}

static void init_file(void)
{
    g_fd_file = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (g_fd_file < 0) {
        perror("Failed to open file");
        exit(1);
    }
}

static void init_gpio(void)
{
    g_channel_select_pin = 17;
    if (gpio_export(g_channel_select_pin) < 0) {
        perror("Failed to export GPIO pin");
        exit(1);
    }

    if (gpio_set_direction(g_channel_select_pin, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        exit(1);
    }

    if (gpio_set_value(g_channel_select_pin, 0) < 0) {
        perror("Failed to set GPIO value");
        exit(1);
    }
}

int main(void)
{
    signal(SIGINT, sigint_handler);

    init_i2s();
    init_file();
    init_gpio();

    while (1) {
        char buffer[BUFFER_SIZE];
        ssize_t bytes_read = read(g_fd_i2s, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("Failed to read from I2S device");
            exit(1);
        }

        if (write(g_fd_file, buffer, bytes_read) < 0) {
            perror("Failed to write to file");
            exit(1);
        }

        if (gpio_set_value(g_channel_select_pin, 1) < 0) {
            perror("Failed to set GPIO value");
            exit(1);
        }
    }

    return 0;
}

