        exit(1);
    }

    gpio_set_mode(g_fd_gpio, GPIO_MODE_INPUT);
    gpio_set_pull(g_fd_gpio, GPIO_PULL_UP);
}

static void init_pwm() {
    g_fd_pwm = pwm_open(GPIO_PIN_PWM);
    if (g_fd_pwm < 0) {
