    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, event);
    write(g_fd_log, buf, strlen(buf));
}

