#define GPIO_DATA_READY 24
#define HEADER_MAGIC_NUMBER 4144
#define HEADER_SIZE 8
#define FRAME_SIZE 32768
#define FRAME_COUNT 64
#define SAMPLE_COUNT 256
#define TIMESTAMP_SIZE 8
#define FRAME_NUMBER_SIZE 4

struct config_struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t chirps;
    uint16_t samples;
};

struct header {
    uint32_t magic_number;
    uint64_t timestamp;
    struct config_struct config;
};

struct frame {
    uint64_t timestamp;
    uint32_t frame_number;
    uint8_t data[FRAME_SIZE];
};

void handle_sigint(int signal) {
    printf("Received SIGINT, closing SPI device and GPIO pins\n");
    gpioTerminate();
    close(spi_fd);
    close(log_fd);
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, closing SPI device and GPIO pins\n");
    gpioTerminate();
    close(spi_fd);
    close(log_fd);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize GPIO pins
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set up SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    // Set up SPI configuration
    struct spi_ioc_transfer spi_config;
    spi_config.bits_per_word = 8;
    spi_config.speed_hz = SPI_SPEED;
    spi_config.mode = SPI_MODE;
    spi_config.delay_usecs = 0;
    spi_config.cs_change = 0;
    spi_config.tx_nbits = 0;
    spi_config.rx_nbits = 0;
    spi_config.word_delay_usecs = 0;
    spi_config.pad = 0;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_config) < 0) {
        printf("Failed to set SPI configuration\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_CE, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO mode for CE\n");
        return 1;
    }
    if (gpioSetMode(GPIO_FRAME_TRIGGER, PI_INPUT) < 0) {
        printf("Failed to set GPIO mode for frame trigger\n");
        return 1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        printf("Failed to set GPIO mode for data ready\n");
        return 1;
    }

    // Set up log file
    log_fd = open("log.bin", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Write header to log file
    struct header header;
    header.magic_number = HEADER_MAGIC_NUMBER;
    header.timestamp = time(NULL);
    header.config.start_frequency = 7700000000;
    header.config.end_frequency = 7900000000;
    header.config.chirps = 64;
    header.config.samples = 256;
    if (write(log_fd, &header, HEADER_SIZE) < 0) {
        printf("Failed to write header to log file\n");
        return 1;
    }

    // Set up frame buffer
    struct frame frame_buffer;
    frame_buffer.timestamp = 0;
    frame_buffer.frame_number = 0;
    memset(frame_buffer.data, 0, FRAME_SIZE);

    // Set up SPI transfer buffer
    uint8_t spi_buffer[FRAME_SIZE];

    // Set up GPIO pins for frame trigger and data ready
    if (gpioWrite(GPIO_CE, PI_LOW) < 0) {
        printf("Failed to set GPIO for CE\n");
        return 1;
    }
    if (gpioWrite(GPIO_FRAME_TRIGGER, PI_LOW) < 0) {
        printf("Failed to set GPIO for frame trigger\n");
        return 1;
    }
    if (gpioWrite(GPIO_DATA_READY, PI_LOW) < 0) {
        printf("Failed to set GPIO for data ready\n");
        return 1;
    }

    // Set up SPI transfer
    struct spi_ioc_transfer spi_transfer;
    spi_transfer.tx_buf = (unsigned long)spi_buffer;
    spi_transfer.rx_buf = (unsigned long)spi_buffer;
    spi_transfer.len = FRAME_SIZE;
    spi_transfer.speed_hz = SPI_SPEED;
    spi_transfer.bits_per_word = 8;
    spi_transfer.delay_usecs = 0;
    spi_transfer.cs_change = 0;
    spi_transfer.tx_nbits = 0;
    spi_transfer.rx_nbits = 0;
    spi_transfer.word_delay_usecs = 0;
    spi_transfer.pad = 0;

    // Set up frame trigger and data ready interrupts
    if (gpioSetISRFunc(GPIO_FRAME_TRIGGER, PI_RISING_EDGE, NULL, NULL) < 0) {
        printf("Failed to set GPIO ISR for frame trigger\n");
        return 1;
    }
    if (gpioSetISRFunc(GPIO_DATA_READY, PI_RISING_EDGE, NULL, NULL) < 0) {
        printf("Failed to set GPIO ISR for data ready\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for frame trigger
        if (gpioRead(GPIO_FRAME_TRIGGER) < 0) {
            printf("Failed to read GPIO for frame trigger\n");
            return 1;
        }
        if (gpioRead(GPIO_FRAME_TRIGGER) == PI_HIGH) {
            // Wait for data ready
            if (gpioRead(GPIO_DATA_READY) < 0) {
                printf("Failed to read GPIO for data ready\n");
                return 1;
            }
            if (gpioRead(GPIO_DATA_READY) == PI_HIGH) {
                // Read frame
                if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
                    printf("Failed to read frame\n");
                    return 1;
                }

                // Write frame to log file
                frame_buffer.timestamp = time(NULL);
                frame_buffer.frame_number++;
                memcpy(frame_buffer.data, spi_buffer, FRAME_SIZE);
                if (write(log_fd, &frame_buffer, FRAME_SIZE + TIMESTAMP_SIZE + FRAME_NUMBER_SIZE) < 0) {
                    printf("Failed to write frame to log file\n");
                    return 1;
                }
            }
        }
    }

    // Clean up
    gpioTerminate();
    close(spi_fd);
    close(log_fd);
    return 0;
}

