#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x45
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_CONVERSION 0x00
#define OPT3001_REG_RESULT 0x02
#define OPT3001_CONF_CONT_CONV 0x80
#define OPT3001_CONF_AUTO_RANGE 0x04
#define OPT3001_CONF_FULL_SCALE 0x02
#define OPT3001_CONF_100MS_CONV 0x01

#define LIGHT_DATA_FILE "light_data.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize I2C bus
    int i2c_fd = i2c_open(I2C_BUS, 0, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize OPT3001 sensor
    uint8_t config = OPT3001_CONF_CONT_CONV | OPT3001_CONF_AUTO_RANGE | OPT3001_CONF_FULL_SCALE | OPT3001_CONF_100MS_CONV;
    if (i2c_write(i2c_fd, OPT3001_ADDR, OPT3001_REG_CONFIG, &config, 1) < 0) {
        perror("Failed to configure OPT3001 sensor");
        return 1;
    }

    // Open file for writing
    int fd = open(LIGHT_DATA_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open file");
        return 1;
    }

    // Main loop
    while (running) {
        // Read lux value
        uint16_t lux;
        if (i2c_read(i2c_fd, OPT3001_ADDR, OPT3001_REG_RESULT, &lux, 2) < 0) {
            perror("Failed to read lux value");
            return 1;
        }

        // Convert to float
        float lux_float = (float)lux / 100.0;

        // Get current time
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);

        // Format time string
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        // Write to file
        char line[50];
        snprintf(line, sizeof(line), "%s,%.2f\n", time_str, lux_float);
        if (write(fd, line, strlen(line)) < 0) {
            perror("Failed to write to file");
            return 1;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    i2c_close(i2c_fd);

    return 0;
}

