#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *request;
    struct gpiod_line_event event;
    struct timespec ts;
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Request the line
    request = gpiod_line_request(chip, FLAME_SENSOR_PIN, "flame_detect", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!request) {
        fprintf(stderr, "Error: Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the line to be pulled up
    ret = gpiod_line_set_config(request, GPIOD_LINE_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set line bias\n");
        gpiod_line_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the line object
    line = gpiod_line_get(request);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_line_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!sigint_flag) {
        // Read the line
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line\n");
            gpiod_line_release(request);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the status
        printf("%s Flame Detected: %s\n", ctime(&ts), event.event_type == GPIOD_LINE_EVENT_RISING ? "YES" : "NO");

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(request);
    gpiod_chip_close(chip);

    return 0;
}

