#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *left_line, *center_line, *right_line;
    int left_value, center_value, right_value;

    // Initialize the GPIO chip and lines
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !center_line || !right_line) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to input mode
    if (gpiod_line_request_input_mode(left_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0) {
        fprintf(stderr, "Error: unable to set GPIO line to input mode\n");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input_mode(center_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0) {
        fprintf(stderr, "Error: unable to set GPIO line to input mode\n");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input_mode(right_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0) {
        fprintf(stderr, "Error: unable to set GPIO line to input mode\n");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Poll the GPIO lines every 50 ms
    while (running) {
        left_value = gpiod_line_get_value(left_line);
        center_value = gpiod_line_get_value(center_line);
        right_value = gpiod_line_get_value(right_line);

        if (left_value < 0 || center_value < 0 || right_value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line values\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        usleep(50000);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

