#include <signal.h>
#include <libgpiod.h>

#define CHIP_NAME "ttp226"
#define CHIP_ADDR 0x48
#define CHANNEL_COUNT 8

#define GPIO_PIN_BASE 2
#define GPIO_PIN_COUNT 8

#define POLL_INTERVAL 100

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the TTP226 chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME, CHIP_ADDR);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open TTP226 chip\n");
        return 1;
    }

    // Request the GPIO lines
    struct gpiod_line *lines[CHANNEL_COUNT];
    for (int i = 0; i < CHANNEL_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PIN_BASE + i);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %d\n", GPIO_PIN_BASE + i);
            return 1;
        }
    }

    // Set the GPIO lines to input mode
    for (int i = 0; i < CHANNEL_COUNT; i++) {
        if (gpiod_line_request_input(lines[i], "touch_sensor") != 0) {
            fprintf(stderr, "Error: Failed to set GPIO line %d to input mode\n", GPIO_PIN_BASE + i);
            return 1;
        }
    }

    // Poll the GPIO lines every POLL_INTERVAL ms
    while (running) {
        for (int i = 0; i < CHANNEL_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %d\n", GPIO_PIN_BASE + i);
                return 1;
            }
            printf("%d: %d\n", i, value);
