    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return 1;
    }

    ret = gpiod_line_request_input(line2, "sensor2");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the sensor values
        bool sensor1 = gpiod_line_get_value(line1);
        bool sensor2 = gpiod_line_get_value(line2);

        // Print the sensor values
        printf("Sensor 1: %s\n", sensor1 ? "HIGH" : "LOW");
        printf("Sensor 2: %s\n", sensor2 ? "HIGH" : "LOW");

        // Sleep for 500ms
        usleep(500000);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

