#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define BCM_PIN_2 2
#define BCM_PIN_3 3
#define BCM_PIN_4 4
#define BCM_PIN_17 17
#define BCM_PIN_27 27
#define BCM_PIN_22 22
#define BCM_PIN_10 10
#define BCM_PIN_9 9

#define NUM_CHANNELS 8

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request lines for all channels
    struct gpiod_line *lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: unable to get line %d\n", i);
            return 1;
        }

        // Set line as input with bias disabled
        if (gpiod_line_request_input(lines[i], "touch_sensor") != 0) {
            fprintf(stderr, "Error: unable to request input for line %d\n", i);
            return 1;
        }
    }

    // Poll the state of all channels every 50 ms
    while (running) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read the state of all channels
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state == -1) {
                fprintf(stderr, "Error: unable to read state of line %d\n", i);
                return 1;
            }

            // Print the state to the console
            printf("%s,%d\n", asctime(gmtime(&ts.tv_sec)), state);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Release all lines and the chip
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

