#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TILT_PIN 7

void sigint_handler(int signum) {
    printf("Exiting cleanly...\n");
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip\n");
        exit(1);
    }

    // Set up GPIO pin as input with internal pull-up resistor
    struct gpiod_line *line = gpiod_chip_get_line(chip, TILT_PIN);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line\n");
        exit(1);
    }
    gpiod_line_request_input(line, "tilt_sensor");
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_INPUT, GPIOD_LINE_FLAG_BIAS_PULL_UP);

    // Print startup banner
    printf("Starting tilt sensor polling...\n");

    // Enter main loop
    while (1) {
        // Read GPIO pin
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line\n");
            exit(1);
        }

        // Check if tilt state has changed
        if (value != gpiod_line_get_value(line)) {
            // Flush stdout and log to console
            fflush(stdout);
            printf("Tilted\n");
        } else {
            // Flush stdout and log to console
            fflush(stdout);
            printf("Not Tilted\n");
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

