#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define SAMPLE_RATE 50

struct sensor_data {
    bool obstacle;
    time_t timestamp;
};

struct sensor_data buffer[BUFFER_SIZE];

void handle_sigint(int signal) {
    printf("Received SIGINT, releasing resources...\n");
    gpiod_release(gpiod_chip_get_by_name("gpiochip0"));
    exit(0);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *request;
    struct sensor_data data;
    int i, ret;

    // Initialize the GPIO driver
    chip = gpiod_chip_get_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to get GPIO chip\n");
        return 1;
    }

    // Get the GPIO line for the sensor
    line = gpiod_chip_get_line(chip, 7);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    // Request the GPIO line
    request = gpiod_line_request(line, "sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN);
    if (!request) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    // Set the GPIO line to use the internal pull-up resistor
    ret = gpiod_line_set_pull(line, GPIOD_LINE_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line pull\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Poll the sensor every 50ms
    while (true) {
        // Read the sensor value
        ret = gpiod_line_get_value(line, &data.obstacle);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            return 1;
        }

        // Get the current timestamp
        data.timestamp = time(NULL);

        // Add the data to the buffer
        buffer[i++ % BUFFER_SIZE] = data;

        // Print the alert if an obstacle is detected
        if (data.obstacle) {
            printf("Obstacle detected at %s\n", ctime(&data.timestamp));
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Dump the buffer to stdout
    for (i = 0; i < BUFFER_SIZE; i++) {
        printf("%s: %s\n", ctime(&buffer[i].timestamp), buffer[i].obstacle ? "Obstacle" : "No obstacle");
    }

    return 0;
}

