#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_PIN 25
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24

#define LED_ON 1
#define LED_OFF 0

#define SENSOR_ACTIVE_LOW 0
#define SENSOR_ACTIVE_HIGH 1

#define POLL_INTERVAL 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the LED pin as an output
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        return 1;
    }
    gpiod_line_request_output(led_line, "led", LED_OFF);

    // Set up the sensor pins as inputs
    struct gpiod_line *sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get sensor 1 line\n");
        return 1;
    }
    gpiod_line_request_input(sensor1_line, "sensor1");

    struct gpiod_line *sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get sensor 2 line\n");
        return 1;
    }
    gpiod_line_request_input(sensor2_line, "sensor2");

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Poll the sensor pins every POLL_INTERVAL milliseconds
    while (running) {
        // Read the sensor values
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);

        // Check if either sensor is active
        if (sensor1_value == SENSOR_ACTIVE_LOW || sensor2_value == SENSOR_ACTIVE_LOW) {
            // Turn the LED on
            gpiod_line_set_value(led_line, LED_ON);
        } else {
            // Turn the LED off
            gpiod_line_set_value(led_line, LED_OFF);
        }

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up the GPIO lines
    gpiod_line_release(led_line);
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

