#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_THRESHOLD 2
#define STALL_LOG_FILE "stall_log.txt"

static bool sensor1_state = false;
static bool sensor2_state = false;
static bool stall_confirmed = false;
static time_t stall_start_time = 0;

static void handle_sigint(int signal) {
    printf("Received SIGINT signal, cleaning up...\n");
    gpiod_cleanup();
    exit(0);
}

static void handle_sigterm(int signal) {
    printf("Received SIGTERM signal, cleaning up...\n");
    gpiod_cleanup();
    exit(0);
}

static void handle_stall(void) {
    if (stall_confirmed) {
        return;
    }

    if (sensor1_state && sensor2_state) {
        stall_confirmed = true;
        stall_start_time = time(NULL);
    }
}

static void log_stall(void) {
    if (!stall_confirmed) {
        return;
    }

    FILE *fp = fopen(STALL_LOG_FILE, "a");
    if (fp == NULL) {
        printf("Error opening file %s for writing\n", STALL_LOG_FILE);
        return;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&stall_start_time));
    fprintf(fp, "%s\n", timestamp);
    fclose(fp);

    stall_confirmed = false;
}

int main(void) {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        printf("Error opening GPIO chip\n");
        return 1;
    }

    gpiod_line_t *sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (sensor1 == NULL) {
        printf("Error getting GPIO line for sensor 1\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_t *sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (sensor2 == NULL) {
        printf("Error getting GPIO line for sensor 2\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output(sensor1, "sensor1", 0);
    gpiod_line_request_output(sensor2, "sensor2", 0);

    while (true) {
        gpiod_line_get_value(sensor1, &sensor1_state);
        gpiod_line_get_value(sensor2, &sensor2_state);

        handle_stall();

        if (stall_confirmed) {
            log_stall();
        }

        usleep(100000);
    }

    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_chip_close(chip);

    return 0;
}

