#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONTINUOUS_CONVERSION_MODE 0x00
#define ALL_AXES_ENABLED 0x07
#define RANGE_50MT 0x00

#define CSV_FILE "magnetic_log.csv"
#define CSV_HEADER "timestamp,x,y,z\n"

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    int fd;
    int i2c_fd;
    int ret;
    uint8_t buf[3];
    char timestamp[20];
    char line[100];

    // Initialize the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the sensor
    ret = i2c_write(i2c_fd, CONTINUOUS_CONVERSION_MODE, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    ret = i2c_write(i2c_fd, ALL_AXES_ENABLED, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    ret = i2c_write(i2c_fd, RANGE_50MT, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open the CSV file
    fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Write the header row
    ret = write(fd, CSV_HEADER, strlen(CSV_HEADER));
    if (ret < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Register the SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Read the magnetic field values in an infinite loop
    while (!stop) {
        // Read the magnetic field values
        ret = i2c_read(i2c_fd, buf, 3);
        if (ret < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            continue;
        }

        // Convert the magnetic field values to a string
        snprintf(line, sizeof(line), "%s,%d,%d,%d\n", timestamp, buf[0], buf[1], buf[2]);

        // Write the line to the CSV file
        ret = write(fd, line, strlen(line));
        if (ret < 0) {
            fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
            continue;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Close the I2C handle
    i2c_close(i2c_fd);

    // Close the CSV file
    close(fd);

    // Clean up the sensor library
    pigpio_cleanup();

    return 0;
}

