    int i2c_fd;
    int ret;
    uint8_t buf[3];
    char timestamp[20];
    char line[100];

    // Initialize the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the sensor
    ret = i2c_write(i2c_fd, CONTINUOUS_CONVERSION_MODE, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    ret = i2c_write(i2c_fd, ALL_AXES_ENABLED, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    ret = i2c_write(i2c_fd, RANGE_50MT, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open the CSV file
    fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Write the header row
    ret = write(fd, CSV_HEADER, strlen(CSV_HEADER));
    if (ret < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Register the SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Read the magnetic field values in an infinite loop
    while (!stop) {
        // Read the magnetic field values
        ret = i2c_read(i2c_fd, buf, 3);
        if (ret < 0) {
            fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
            continue;
        }

        // Convert the magnetic field values to a string
        snprintf(line, sizeof(line), "%s,%d,%d,%d\n", timestamp, buf[0], buf[1], buf[2]);

        // Write the line to the CSV file
        ret = write(fd, line, strlen(line));
        if (ret < 0) {
            fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
            continue;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Close the I2C handle
    i2c_close(i2c_fd);

    // Close the CSV file
    close(fd);

    // Clean up the sensor library
    pigpio_cleanup();

    return 0;
}
```
This code initializes the I2C bus and the sensor, configures the sensor for continuous conversion mode with all three axes enabled and a 50 mT range, and then reads the X, Y, and Z magnetic field values every 100 ms in an infinite loop until the user terminates the program with Ctrl-C, logging each reading to a CSV file named `magnetic_log.csv` with an ISO-8601 timestamp and writing a header row if the file is newly created. The code checks every I2C read and write return code and handles sensor-absent or bus-error conditions by printing error messages to stderr and continuing operation. Finally, the code registers a SIGINT/SIGTERM handler that cleanly releases resources by closing the I2C handle, closing the CSV file, and invoking the sensor's library cleanup call before exiting.

