#define GPIO_PIN 23
#define POLL_INTERVAL 2

static bool initialized = false;
static bool running = false;
static int gpio_fd = -1;
static int log_fd = -1;

static void init_gpio() {
    if (initialized) {
        return;
    }

    gpio_fd = gpiod_open(GPIO_PIN, "in", GPIOD_LINE_REQUEST_DIRECTION_AS_IS);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO pin %d", GPIO_PIN);
        exit(1);
    }

    initialized = true;
}

static void init_log() {
    if (log_fd >= 0) {
        return;
    }

    log_fd = open("flood_log.txt", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }
}

static void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = false;
    }
}

static void poll_sensor() {
    if (!initialized) {
        init_gpio();
    }

    if (!running) {
        return;
    }

    int value = gpiod_read(gpio_fd);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read GPIO pin %d", GPIO_PIN);
        return;
    }

    if (value == 1) {
        char buffer[100];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ALERT: Water detected", tm);
        write(log_fd, buffer, strlen(buffer));
        printf("%s\n", buffer);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_log();

    running = true;
    while (running) {
        poll_sensor();
        sleep(POLL_INTERVAL);
    }

    close(gpio_fd);
    close(log_fd);

    return 0;
}

