#define PIN_NUM 4
#define PIN_NAME "GPIO4"
#define LOG_FILE "rpm_log.txt"

static volatile uint32_t pulse_count = 0;
static volatile bool running = true;

static void handle_sigint(int signum) {
    running = false;
}

static void handle_sigterm(int signum) {
    running = false;
}

static void timer_callback(void *data) {
    uint32_t count = atomic_add(&pulse_count, 0);
    float rpm = (float)count * 60.0f / 1000.0f;
    char buf[128];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), " %f", rpm);
    printf("%s\n", buf);
    fprintf(stderr, "%s\n", buf);
    fflush(stderr);
    atomic_store(&pulse_count, 0);
}

static void gpio_callback(void *data) {
    atomic_add(&pulse_count, 1);
}

