#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define GPIO_A 17
#define GPIO_B 27

#define FILENAME "rotation_log.txt"

// Quadrature state machine
typedef enum {
    QUAD_STATE_A_HIGH_B_LOW,
    QUAD_STATE_A_LOW_B_HIGH,
    QUAD_STATE_A_HIGH_B_HIGH,
    QUAD_STATE_A_LOW_B_LOW
} quad_state_t;

// Interrupt handler
void isr_handler(void *arg) {
    // Get the current state
    quad_state_t *state = (quad_state_t *)arg;

    // Check the current state
    switch (*state) {
        case QUAD_STATE_A_HIGH_B_LOW:
            // A is high, B is low
            // Check if B is high now
            if (gpiod_get_value(GPIO_B) == 1) {
                // B is high, so A is low
                *state = QUAD_STATE_A_LOW_B_HIGH;
            } else {
                // B is low, so A is high
                *state = QUAD_STATE_A_HIGH_B_HIGH;
            }
            break;
        case QUAD_STATE_A_LOW_B_HIGH:
            // A is low, B is high
            // Check if A is high now
            if (gpiod_get_value(GPIO_A) == 1) {
                // A is high, so B is low
                *state = QUAD_STATE_A_HIGH_B_LOW;
            } else {
                // A is low, so B is high
                *state = QUAD_STATE_A_LOW_B_LOW;
            }
            break;
        case QUAD_STATE_A_HIGH_B_HIGH:
            // A is high, B is high
            // Check if A is low now
            if (gpiod_get_value(GPIO_A) == 0) {
                // A is low, so B is high
                *state = QUAD_STATE_A_LOW_B_HIGH;
            } else {
                // A is high, so B is high
                *state = QUAD_STATE_A_HIGH_B_HIGH;
            }
            break;
        case QUAD_STATE_A_LOW_B_LOW:
            // A is low, B is low
            // Check if A is high now
            if (gpiod_get_value(GPIO_A) == 1) {
                // A is high, so B is low
                *state = QUAD_STATE_A_HIGH_B_LOW;
            } else {
                // A is low, so B is low
                *state = QUAD_STATE_A_LOW_B_LOW;
            }
            break;
    }
}

int main(void) {
    // Initialize the GPIO pins
    gpiod_init(GPIO_A);
    gpiod_init(GPIO_B);

    // Set the GPIO pins as inputs
    gpiod_set_direction(GPIO_A, GPIOD_IN);
    gpiod_set_direction(GPIO_B, GPIOD_IN);

    // Set the GPIO pins as pull-up resistors
    gpiod_set_pull(GPIO_A, GPIOD_PULL_UP);
    gpiod_set_pull(GPIO_B, GPIOD_PULL_UP);

    // Set the GPIO pins as interrupt-driven
    gpiod_set_edge(GPIO_A, GPIOD_RISING);
    gpiod_set_edge(GPIO_B, GPIOD_RISING);

    // Create a mutex to protect the shared state
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create a condition variable to wait for the interrupt
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Create a thread to handle the interrupt
    pthread_t thread;
    pthread_create(&thread, NULL, isr_handler, &mutex);

    // Open the log file
    FILE *fp = fopen(FILENAME, "w");
    if (fp == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Set the log file to millisecond precision
    setvbuf(fp, NULL, _IONBF, 0);

    // Set the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (true) {
        // Wait for the interrupt
        pthread_mutex_lock(&mutex);
        pthread_cond_wait(&cond, &mutex);
        pthread_mutex_unlock(&mutex);

        // Get the current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log the time to the file
        fprintf(fp, "%ld.%ld\n", ts.tv_sec, ts.tv_nsec / 1000000);
    }

    // Close the log file
    fclose(fp);

    // Clean up
    gpiod_cleanup();

    return 0;
}

void signal_handler(int signum) {
    // Flush and close the log file
    fflush(fp);
    fclose(fp);

    // Terminate the driver library
    gpiod_cleanup();

    // Exit the program
    exit(0);
}

