#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/syslog.h>
#include <signal.h>

#include <libgpiod.h>

#define LED_PIN 18
#define SENSOR_PIN 23

#define LED_ON 1
#define LED_OFF 0

#define SENSOR_ACTIVE 1
#define SENSOR_INACTIVE 0

#define POLL_INTERVAL 50

int main(int argc, char *argv[]) {
    // Open the GPIO chip
    int gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    // Request the input line for the sensor
    int sensor_line = gpiod_chip_get_line(gpio_chip, SENSOR_PIN);
    if (sensor_line < 0) {
        syslog(LOG_ERR, "Failed to get sensor line");
        return 1;
    }

    // Request the output line for the LED
    int led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (led_line < 0) {
        syslog(LOG_ERR, "Failed to get LED line");
        return 1;
    }

    // Set the LED to off
    gpiod_line_set_value(led_line, LED_OFF);

    // Set the sensor to active
    gpiod_line_set_value(sensor_line, SENSOR_ACTIVE);

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the sensor value
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            syslog(LOG_ERR, "Failed to read sensor value");
            return 1;
        }

        // If the sensor is active, turn the LED on
        if (sensor_value == SENSOR_ACTIVE) {
            gpiod_line_set_value(led_line, LED_ON);
        } else {
            gpiod_line_set_value(led_line, LED_OFF);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

void sigint_handler(int signal) {
    // Turn the LED off
    gpiod_line_set_value(led_line, LED_OFF);

    // Release the resources
    gpiod_line_release(led_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(gpio_chip);

    // Exit
    exit(0);
}

void sigterm_handler(int signal) {
    // Turn the LED off
    gpiod_line_set_value(led_line, LED_OFF);

    // Release the resources
    gpiod_line_release(led_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(gpio_chip);

    // Exit
    exit(0);
}

