#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define LED_PIN 18
#define TOUCH_PIN 17
#define DEBOUNCE_TIME 50

static int gpio_fd;
static int led_fd;
static int touch_fd;

static void handle_sigint(int signum)
{
    printf("Received signal %d, releasing resources...\n", signum);
    gpio_close(gpio_fd);
    gpio_close(led_fd);
    gpio_close(touch_fd);
    exit(0);
}

int main(void)
{
    // Initialize GPIO
    gpio_fd = gpio_open(GPIO_PATH, O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LED
    led_fd = gpio_open(LED_PIN, O_RDWR);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to open LED: %s\n", strerror(errno));
        return 1;
    }

    // Initialize touch sensor
    touch_fd = gpio_open(TOUCH_PIN, O_RDWR);
    if (touch_fd < 0) {
        fprintf(stderr, "Failed to open touch sensor: %s\n", strerror(errno));
        return 1;
    }

    // Set LED as output
    if (gpio_set_direction(led_fd, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set LED as output: %s\n", strerror(errno));
        return 1;
    }

    // Set touch sensor as input
    if (gpio_set_direction(touch_fd, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to set touch sensor as input: %s\n", strerror(errno));
        return 1;
    }

    // Set LED to LOW
    if (gpio_write(led_fd, 0) < 0) {
        fprintf(stderr, "Failed to set LED to LOW: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Wait for rising edges on the touch sensor
    while (1) {
        // Read the touch sensor
        int value = gpio_read(touch_fd);
        if (value < 0) {
            fprintf(stderr, "Failed to read touch sensor: %s\n", strerror(errno));
            return 1;
        }

        // If the touch sensor is high, toggle the LED
        if (value == 1) {
            // Toggle the LED
            if (gpio_write(led_fd, !gpio_read(led_fd)) < 0) {
                fprintf(stderr, "Failed to toggle LED: %s\n", strerror(errno));
                return 1;
            }

            // Wait for the debounce time
            usleep(DEBOUNCE_TIME * 1000);
        }
    }

    return 0;
}

