#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>

#define LED1_PIN 27
#define LED2_PIN 22
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_TIME 50
#define LOG_BUFFER_SIZE 100

struct touch_event {
    uint8_t sensor_pin;
    uint64_t timestamp;
    bool state;
};

struct touch_event log_buffer[LOG_BUFFER_SIZE];
size_t log_index = 0;
size_t overflow_count = 0;

void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpiod_cleanup();
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    gpiod_cleanup();
    exit(0);
}

void log_event(uint8_t sensor_pin, bool state) {
    struct touch_event event = {
        .sensor_pin = sensor_pin,
        .timestamp = time(NULL),
        .state = state
    };

    if (log_index < LOG_BUFFER_SIZE) {
        log_buffer[log_index] = event;
        log_index++;
    } else {
        overflow_count++;
    }
}

void print_log() {
    for (size_t i = 0; i < log_index; i++) {
        struct touch_event event = log_buffer[i];
        printf("Sensor %d: %s at %llu\n", event.sensor_pin, event.state ? "touched" : "released", event.timestamp);
    }
    printf("Overflow count: %zu\n", overflow_count);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize GPIO
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    gpiod_line_t *led1 = gpiod_chip_get_line(chip, LED1_PIN);
    gpiod_line_t *led2 = gpiod_chip_get_line(chip, LED2_PIN);
    gpiod_line_t *sensor1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    gpiod_line_t *sensor2 = gpiod_chip_get_line(chip, SENSOR2_PIN);

    if (led1 == NULL || led2 == NULL || sensor1 == NULL || sensor2 == NULL) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        return 1;
    }

    // Set up LEDs and sensors
    gpiod_line_request_output(led1, "led1", 0);
    gpiod_line_request_output(led2, "led2", 0);
    gpiod_line_request_input(sensor1, "sensor1");
    gpiod_line_request_input(sensor2, "sensor2");

    // Main loop
    while (true) {
        // Read sensor values
        bool sensor1_value = gpiod_line_get_value(sensor1);
        bool sensor2_value = gpiod_line_get_value(sensor2);

        // Debounce
        usleep(DEBOUNCE_TIME * 1000);

        // Check for changes
        if (sensor1_value != gpiod_line_get_value(sensor1)) {
            continue;
        }
        if (sensor2_value != gpiod_line_get_value(sensor2)) {
            continue;
        }

        // Update LEDs
        gpiod_line_set_value(led1, sensor1_value);
        gpiod_line_set_value(led2, sensor2_value);

        // Log event
        log_event(SENSOR1_PIN, sensor1_value);
        log_event(SENSOR2_PIN, sensor2_value);
    }

    // Clean up
    gpiod_line_release(led1);
    gpiod_line_release(led2);
    gpiod_line_release(sensor1);
    gpiod_line_release(sensor2);
    gpiod_chip_close(chip);

    return 0;
}

