#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    bool rain_detected = false;

    // Initialize the GPIO chip and line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Enable the internal pull-up resistor
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, GPIOD_LINE_REQUEST_FLAG_DEFAULT);

    // Set up the signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the log file
    FILE *log_file = fopen("/var/log/rain_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: unable to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Poll the GPIO pin every POLL_INTERVAL milliseconds
    while (running) {
        // Read the GPIO pin value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            break;
        }

        // Check if the rain is detected
        bool rain_detected = (value == 0);

        // If the state has changed, write a log message
        if (rain_detected != rain_detected) {
            // Get the current time
            clock_gettime(CLOCK_REALTIME, &ts);

            // Write the log message
            fprintf(log_file, "%ld.%ld: %s\n", ts.tv_sec, ts.tv_nsec, rain_detected ? "Rain Detected" : "No Rain");
        }

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

