#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define DEBOUNCE_TIME 5000
#define RPM_CALC_INTERVAL 1000
#define RPM_CALC_SAMPLES 10

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

#define LOG_FILE "shaft_log.txt"

static int gpio_fd;
static int log_fd;
static int rpm_samples[RPM_CALC_SAMPLES];
static int rpm_sample_count = 0;
static int rpm_calc_interval = RPM_CALC_INTERVAL;

static void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(gpio_fd);
    close(log_fd);
    exit(0);
}

static void handle_gpio_event(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rpm_samples[rpm_sample_count] = tick;
        rpm_sample_count++;
        if (rpm_sample_count == RPM_CALC_SAMPLES) {
            rpm_sample_count = 0;
            int rpm = calculate_rpm();
            printf("RPM: %d\n", rpm);
            write_to_log(rpm);
        }
    }
}

static int calculate_rpm() {
    int rpm = 0;
    for (int i = 0; i < RPM_CALC_SAMPLES; i++) {
        rpm += (rpm_samples[i] - rpm_samples[i - 1]) / rpm_calc_interval;
    }
    return rpm / RPM_CALC_SAMPLES;
}

static void write_to_log(int rpm) {
    char buf[100];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
    char *log_entry = malloc(strlen(buf) + 10);
    sprintf(log_entry, "%s,%d,%d\n", buf, rpm, rpm);
    write(log_fd, log_entry, strlen(log_entry));
    free(log_entry);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);

    gpio_fd = pigpio_start(NULL, NULL);
    if (gpio_fd < 0) {
        printf("Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    pigpio_gpio_init(gpio_fd, SENSOR1_GPIO);
    pigpio_gpio_init(gpio_fd, SENSOR2_GPIO);

    pigpio_gpio_set_mode(gpio_fd, SENSOR1_GPIO, PI_INPUT);
    pigpio_gpio_set_mode(gpio_fd, SENSOR2_GPIO, PI_INPUT);

    pigpio_gpio_set_pull_up_down(gpio_fd, SENSOR1_GPIO, PI_PUD_UP);
    pigpio_gpio_set_pull_up_down(gpio_fd, SENSOR2_GPIO, PI_PUD_UP);

    pigpio_callback_ex(gpio_fd, SENSOR1_GPIO, PI_FALLING_EDGE, DEBOUNCE_TIME, handle_gpio_event);
    pigpio_callback_ex(gpio_fd, SENSOR2_GPIO, PI_FALLING_EDGE, DEBOUNCE_TIME, handle_gpio_event);

    while (1) {
        sleep(1);
    }

    return 0;
}

