#define I2C_BUS 1
#define I2C_ADDR 0x60

#define HEART_RATE_REG 0x00
#define SPO2_REG 0x01

#define HEART_RATE_SCALE 100
#define SPO2_SCALE 100

#define BIOTRACK_LOG "biometric_log.txt"

int main(void) {
    int fd;
    int i2c_fd;
    int ret;
    char buf[10];
    char *heart_rate;
    char *spo2;
    char *timestamp;
    struct tm *tm;
    struct timespec ts;

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    fd = open(BIOTRACK_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the heart rate and SpO2 data
        ret = i2c_read(i2c_fd, HEART_RATE_REG, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read heart rate: %s\n", strerror(errno));
            return 1;
        }
        heart_rate = (char *)malloc(10);
        sprintf(heart_rate, "%d", (int)buf[0] * HEART_RATE_SCALE);

        ret = i2c_read(i2c_fd, SPO2_REG, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SpO2: %s\n", strerror(errno));
            return 1;
        }
        spo2 = (char *)malloc(10);
        sprintf(spo2, "%d", (int)buf[0] * SPO2_SCALE);

        // Get the current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        timestamp = (char *)malloc(20);
        sprintf(timestamp, "%d-%02d-%02d %02d:%02d:%02d", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);

        // Write the data to the log file
        ret = write(fd, timestamp, strlen(timestamp));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }
        ret = write(fd, ", Heart Rate: ", strlen(", Heart Rate: "));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }
        ret = write(fd, heart_rate, strlen(heart_rate));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }
        ret = write(fd, ", SpO2: ", strlen(", SpO2: "));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }
        ret = write(fd, spo2, strlen(spo2));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }
        ret = write(fd, "\n", strlen("\n"));
        if (ret < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            return 1;
        }

        // Flush the log file
        ret = fsync(fd);
        if (ret < 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            return 1;
        }

        // Sleep for one second
        sleep(1);
    }

    // Clean up
    close(fd);
    close(i2c_fd);
    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C handle
    i2c_close(i2c_fd);

    // Close the log file
    close(fd);

    // Terminate the driver library
    pigpio_terminate();

    // Exit the program
    exit(0);
}

