#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define ALARM_PIN 27
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define TILT_THRESHOLD 2000
#define POLL_INTERVAL 100

static int alarm_fd;
static int sensor1_fd;
static int sensor2_fd;
static int log_fd;
static int log_file_opened = 0;
static int alarm_active = 0;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (alarm_active) {
            gpiod_set_value(alarm_fd, 0);
            alarm_active = 0;
        }
        if (log_file_opened) {
            close(log_fd);
            log_file_opened = 0;
        }
        gpiod_cleanup();
        exit(0);
    }
}

static void log_event(const char *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s %s\n", timestamp, event);
    write(log_fd, log_entry, strlen(log_entry));
}

static void check_sensors(void) {
    int sensor1_value = gpiod_get_value(sensor1_fd);
    int sensor2_value = gpiod_get_value(sensor2_fd);
    if (sensor1_value == 1 || sensor2_value == 1) {
        if (!alarm_active) {
            gpiod_set_value(alarm_fd, 1);
            alarm_active = 1;
        }
        log_event("Tilt detected");
    } else {
        if (alarm_active) {
            gpiod_set_value(alarm_fd, 0);
            alarm_active = 0;
        }
        log_event("Tilt cleared");
    }
}

int main(void) {
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing GPIO driver\n");
        return 1;
    }

    alarm_fd = gpiod_open(ALARM_PIN, "alarm", GPIOD_IN);
    if (alarm_fd < 0) {
        fprintf(stderr, "Error opening alarm GPIO pin\n");
        return 1;
    }

    sensor1_fd = gpiod_open(SENSOR1_PIN, "sensor1", GPIOD_IN);
    if (sensor1_fd < 0) {
        fprintf(stderr, "Error opening sensor1 GPIO pin\n");
        return 1;
    }

    sensor2_fd = gpiod_open(SENSOR2_PIN, "sensor2", GPIOD_IN);
    if (sensor2_fd < 0) {
        fprintf(stderr, "Error opening sensor2 GPIO pin\n");
        return 1;
    }

    log_fd = open("bridge_integrity.log", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }
    log_file_opened = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        check_sensors();
        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

