#include <gpiod.h>

#define NUM_SENSORS 5
#define SENSOR_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_TIME 50

static volatile sig_atomic_t sig_flag = 0;

static void sigint_handler(int signum) {
    sig_flag = 1;
}

static void sigterm_handler(int signum) {
    sig_flag = 1;
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID, LOG_USER);

    // Initialize GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return 1;
    }

    // Initialize GPIO lines
    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get GPIO line for sensor %d", i);
            gpiod_chip_close(chip);
            closelog();
            return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!sig_flag) {
        // Read GPIO lines
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read GPIO line for sensor %d", i);
                continue;
            }

            // Debounce
            usleep(DEBOUNCE_TIME * 1000);
            int value2 = gpiod_line_get_value(lines[i]);
            if (value2 < 0) {
                syslog(LOG_ERR, "Failed to read GPIO line for sensor %d", i);
                continue;
            }

            // Check for flame detection
            if (value == 0 && value2 == 0) {
                // Flame detected
                char timestamp[20];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
                char line[100];
                snprintf(line, sizeof(line), "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, i, SENSOR_PINS[i]);
                FILE *fp = fopen("/var/log/flame_events.log", "a");
                if (fp == NULL) {
                    syslog(LOG_ERR, "Failed to open log file");
                    continue;
                }
                flock(fp, LOCK_EX);
                fprintf(fp, "%s\n", line);
                fflush(fp);
                flock(fp, LOCK_UN);
                fclose(fp);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

