int main(void) {
    // Initialize GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_errmsg);
        return 1;
    }

    // Set up GPIO lines
    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR_PINS[i], gpiod_errmsg);
            return 1;
        }
    }

    // Set up GPIO line requests
    struct gpiod_line_request *requests[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        requests[i] = gpiod_line_request_input(lines[i], "touch-sensor");
        if (!requests[i]) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", SENSOR_PINS[i], gpiod_errmsg);
            return 1;
        }
    }

    // Main loop
    while (true) {
        // Read GPIO lines
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading GPIO line %d: %s\n", SENSOR_PINS[i], gpiod_errmsg);
                return 1;
            }

            // Print state change
            if (value != 0) {
                char *state = value == 1 ? "touched" : "released";
                printf("%s: Sensor %d (pin %d) %s\n", get_iso_8601_timestamp(), i, SENSOR_PINS[i], state);
            }
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
        gpiod_line_request_release(requests[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

char *get_iso_8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);

    return timestamp;
}

