#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_PIN 17
#define NUM_CHANNELS 8
#define DEBOUNCE_TIME 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the LED pin as an output
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Error: Failed to get LED line\n");
        return 1;
    }
    gpiod_line_request_output(led, "led", 0);

    // Set up the input pins
    struct gpiod_line *inputs[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        inputs[i] = gpiod_chip_get_line(chip, i + 2);
        if (!inputs[i]) {
            fprintf(stderr, "Error: Failed to get input line %d\n", i + 2);
            return 1;
        }
        gpiod_line_request_input(inputs[i], "input");
        gpiod_line_set_debounce(inputs[i], DEBOUNCE_TIME);
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the log file
    FILE *log_file = fopen("touch_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the input pins
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(inputs[i]);
            if (value < 0) {
                fprintf(stderr, "Error: Failed to read input line %d\n", i + 2);
                return 1;
            }
            if (value == 1) {
                // Channel i is touched
                char buf[20];
                time_t t = time(NULL);
                struct tm *tm = localtime(&t);
                strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
                fprintf(log_file, "%s – Channel %d Touched\n", buf, i + 1);
                fflush(log_file);
            }
        }

        // Update the LED
        int any_touched = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(inputs[i]);
            if (value == 1) {
                any_touched = 1;
                break;
            }
        }
        gpiod_line_set_value(led, any_touched);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(led);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(inputs[i]);
    }
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

