            int value = gpiod_line_get_value(inputs[i]);
            if (value == 1) {
                any_touched = 1;
                break;
            }
        }
        gpiod_line_set_value(led, any_touched);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(led);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(inputs[i]);
    }
