#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x45
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_RESULT 0x02
#define OPT3001_CONFIG_MODE_SINGLE 0x00
#define OPT3001_CONFIG_MODE_CONTINUOUS 0x01
#define OPT3001_CONFIG_RANGE_100 0x00
#define OPT3001_CONFIG_RANGE_300 0x01
#define OPT3001_CONFIG_RANGE_1000 0x02
#define OPT3001_CONFIG_RANGE_4000 0x03
#define OPT3001_CONFIG_RANGE_MASK 0x03
#define OPT3001_CONFIG_RANGE_SHIFT 2
#define OPT3001_CONFIG_MODE_MASK 0x01
#define OPT3001_CONFIG_MODE_SHIFT 0
#define OPT3001_RESULT_MASK 0x0000FFFF
#define OPT3001_RESULT_SHIFT 0

#define LIGHT_DATA_FILE "light_data.txt"

static int i2c_fd;
static int opt3001_fd;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (opt3001_fd != -1) {
        close(opt3001_fd);
    }
    exit(0);
}

static int i2c_init(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

static int opt3001_init(void) {
    opt3001_fd = open("/dev/i2c-1", O_RDWR);
    if (opt3001_fd < 0) {
        fprintf(stderr, "Error opening OPT3001: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(opt3001_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting OPT3001 slave address: %s\n", strerror(errno));
        close(opt3001_fd);
        return -1;
    }

    return 0;
}

static int opt3001_read(uint16_t *result) {
    uint8_t buf[2];
    if (read(opt3001_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading OPT3001: %s\n", strerror(errno));
        return -1;
    }

    *result = (buf[0] << 8) | buf[1];
    return 0;
}

static int opt3001_write(uint16_t config) {
    uint8_t buf[2];
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    if (write(opt3001_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing OPT3001: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (i2c_init() < 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (opt3001_init() < 0) {
        fprintf(stderr, "Error initializing OPT3001: %s\n", strerror(errno));
        return -1;
    }

    uint16_t config = (OPT3001_CONFIG_MODE_SINGLE << OPT3001_CONFIG_MODE_SHIFT) |
                      (OPT3001_CONFIG_RANGE_100 << OPT3001_CONFIG_RANGE_SHIFT);
    if (opt3001_write(config) < 0) {
        fprintf(stderr, "Error writing OPT3001 configuration: %s\n", strerror(errno));
        return -1;
    }

    uint16_t result;
    if (opt3001_read(&result) < 0) {
        fprintf(stderr, "Error reading OPT3001 result: %s\n", strerror(errno));
        return -1;
    }

    uint16_t lux = result & OPT3001_RESULT_MASK;
    lux = (lux >> OPT3001_RESULT_SHIFT) & 0xFFFF;

    char buf[256];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S, %f", tm);
    printf("%s, %d.%02d\n", buf, lux / 100, lux % 100);

    FILE *fp = fopen(LIGHT_DATA_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LIGHT_DATA_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %d.%02d\n", buf, lux / 100, lux % 100);
    fclose(fp);

    return 0;
}

