#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_DO 4
#define GPIO_ALERT 17
#define POLL_INTERVAL 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the GPIO pins
    struct gpiod_line *do_line = gpiod_chip_get_line(chip, GPIO_DO);
    struct gpiod_line *alert_line = gpiod_chip_get_line(chip, GPIO_ALERT);
    if (!do_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the log file
    FILE *log_file = fopen("fire_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (running) {
        // Read the sensor value
        int value = gpiod_line_get_value(do_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        // Log the event
        time_t now = time(NULL);
        fprintf(log_file, "%s: %d\n", ctime(&now), value);

        // Set the alert pin
        if (value == 0) {
            gpiod_line_set_value(alert_line, 1);
            sleep(1);
            gpiod_line_set_value(alert_line, 0);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(do_line);
    gpiod_line_release(alert_line);
    gpiod_chip_close(chip);

    return 0;
}

