#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50

static int gpio_fd;
static int log_fd;

static void handle_sigint(int signum) {
    printf("Received SIGINT, releasing GPIO line and closing log file\n");
    gpiod_line_release(gpio_fd);
    close(log_fd);
    exit(1);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, releasing GPIO line and closing log file\n");
    gpiod_line_release(gpio_fd);
    close(log_fd);
    exit(1);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open GPIO line
    gpio_fd = gpiod_line_open(GPIO_PIN, "input", "touch_sensor");
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO line: %s\n", strerror(errno));
        return 1;
    }

    // Set up debounce interval
    gpiod_line_set_debounce(gpio_fd, DEBOUNCE_INTERVAL);

    // Open log file
    log_fd = open("touch_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(gpio_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO line
        int value = gpiod_line_read(gpio_fd);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            gpiod_line_release(gpio_fd);
            close(log_fd);
            return 1;
        }

        // Check for touch
        if (value == 1) {
            // Get current time
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);

            // Write to log file
            char buf[100];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S: Touch Detected\n", tm);
            write(log_fd, buf, strlen(buf));
            fsync(log_fd);
        }

        // Check for release
        if (value == 0) {
            // Get current time
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);

            // Write to log file
            char buf[100];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S: Touch Released\n", tm);
            write(log_fd, buf, strlen(buf));
            fsync(log_fd);
        }
    }

    // Clean up
    gpiod_line_release(gpio_fd);
    close(log_fd);
    return 0;
}

