#define INVALID_STR "INVALID"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_i2c(void) {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

    return fd;
}

static void read_i2c(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("read");
        exit(1);
    }
}

static void write_i2c(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("write");
        exit(1);
    }
}

static void close_i2c(int fd) {
    close(fd);
}

static void init_csv(void) {
    int fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    write(fd, CSV_HEADER, strlen(CSV_HEADER));
    close(fd);
}

static void log_csv(const char *timestamp, float flow_rate, uint8_t flags, const char *status) {
    int fd = open(CSV_FILE, O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    char buf[100];
    snprintf(buf, sizeof(buf), "%s,%.2f,%d,%s\n", timestamp, flow_rate, flags, status);
    write(fd, buf, strlen(buf));
    close(fd);
}

static void read_flow_rate(int fd, float *flow_rate, uint8_t *flags) {
    uint8_t buf[I2C_READ_LEN];
    read_i2c(fd, buf, I2C_READ_LEN);

    *flow_rate = (float)((buf[0] << 8) | buf[1]) / 100.0;
    *flags = buf[2];
}

static void validate_flow_rate(float flow_rate, uint8_t flags) {
    if (flow_rate < FLOW_RANGE_MIN || flow_rate > FLOW_RANGE_MAX) {
        log_csv(ERROR_STR, flow_rate, flags, INVALID_STR);
        return;
    }

    uint8_t crc = CRC_INIT;
    for (int i = 0; i < I2C_READ_LEN - 1; i++) {
        crc = crc_update(crc, buf[i]);
    }

    if (crc != buf[I2C_READ_LEN - 1]) {
        log_csv(ERROR_STR, flow_rate, flags, INVALID_STR);
        return;
    }

    log_csv(flow_rate, flags, "OK");
}

