#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

#define SAMPLE_PERIOD_MS 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the GPIO lines
    struct gpiod_line *left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    struct gpiod_line *middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    struct gpiod_line *right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to input mode
    if (gpiod_line_request_input_mode(left_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0 ||
        gpiod_line_request_input_mode(middle_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0 ||
        gpiod_line_request_input_mode(right_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0) {
        fprintf(stderr, "Failed to set GPIO lines to input mode: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("path_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read the sensor values
        int left_value = gpiod_line_get_value(left_line);
        int middle_value = gpiod_line_get_value(middle_line);
        int right_value = gpiod_line_get_value(right_line);

        // Write the values to the log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

