    running = 0;
}

int main(int argc, char *argv[]) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Request the GPIO line
    struct gpiod_line *line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to input mode
    if (gpiod_line_request_input(line, "flame_sensor") != 0) {
        fprintf(stderr, "Error: Failed to request GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to edge-triggered mode
    if (gpiod_line_set_edge_event(line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO line to edge-triggered mode\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        // Wait for a GPIO event
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event) != 0) {
            fprintf(stderr, "Error: Failed to wait for GPIO event\n");
            break;
        }

        // Check if the event is a flame detection
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Print the timestamp and append the event to the file
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            fprintf(stdout, "%s: Flame detected\n", timestamp);
            fprintf(FLAME_EVENTS_FILE, "%s: Flame detected\n", timestamp);
        }
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    return 0;
}

