#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define GPIO_CHIP_PATH "/dev/gpiochip4"
#define GPIO_SENSOR_PIN 23
#define GPIO_LED_PIN 24
#define POLL_TIMEOUT 1000

static volatile bool running = true;

static void handle_signal(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    int gpio_chip_fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (gpio_chip_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the sensor and LED lines
    struct gpiod_line *sensor_line = gpiod_chip_get_line(gpio_chip_fd, GPIO_SENSOR_PIN);
    struct gpiod_line *led_line = gpiod_chip_get_line(gpio_chip_fd, GPIO_LED_PIN);
    if (!sensor_line || !led_line) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", strerror(errno));
        return 1;
    }

    // Set up the sensor line as an input
    gpiod_line_request_input(sensor_line, "touch_sensor");
    if (gpiod_line_request_input(sensor_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error setting up sensor line: %s\n", strerror(errno));
        return 1;
    }

    // Set up the LED line as an output
    gpiod_line_request_output(led_line, "touch_led");
    if (gpiod_line_request_output(led_line, "touch_led") < 0) {
        fprintf(stderr, "Error setting up LED line: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    int log_fd = open("touch_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Poll the sensor line for a rising edge event
        struct gpiod_line_event event;
        if (gpiod_line_event_poll(sensor_line, POLL_TIMEOUT, &event) < 0) {
            fprintf(stderr, "Error polling sensor line: %s\n", strerror(errno));
            return 1;
        }

        // If the event is a rising edge, toggle the LED
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        }

        // Log the event
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", localtime(&now));
        char led_state[10];
        if (gpiod_line_get_value(led_line)) {
            strcpy(led_state, "on");
        } else {
            strcpy(led_state, "off");
        }
        char log_entry[100];
        sprintf(log_entry, "%s: %s\n", timestamp, led_state);
        write(log_fd, log_entry, strlen(log_entry));
    }

    // Clean up
    close(log_fd);
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    close(gpio_chip_fd);

    return 0;
}

