        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        }

        // Log the event
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", localtime(&now));
        char led_state[10];
        if (gpiod_line_get_value(led_line)) {
            strcpy(led_state, "on");
        } else {
            strcpy(led_state, "off");
        }
        char log_entry[100];
        sprintf(log_entry, "%s: %s\n", timestamp, led_state);
        write(log_fd, log_entry, strlen(log_entry));
    }

    // Clean up
    close(log_fd);
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    close(gpio_chip_fd);

    return 0;
}
