#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_INPUT 4
#define GPIO_PIN_OUTPUT 17
#define DEBOUNCE_TIME 200

static bool g_running = true;
static bool g_touched = false;
static struct gpiod_chip *chip;
static struct gpiod_line *line_in;
static struct gpiod_line *line_out;

static void handle_signal(int signum) {
    g_running = false;
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        exit(1);
    }

    line_in = gpiod_chip_get_line(chip, GPIO_PIN_INPUT);
    if (!line_in) {
        fprintf(stderr, "Error: Failed to get GPIO line for input\n");
        exit(1);
    }

    line_out = gpiod_chip_get_line(chip, GPIO_PIN_OUTPUT);
    if (!line_out) {
        fprintf(stderr, "Error: Failed to get GPIO line for output\n");
        exit(1);
    }

    gpiod_line_request_input(line_in, "touch_sensor");
    gpiod_line_request_output(line_out, "led", 0);
}

static void cleanup_gpio() {
    gpiod_line_release(line_in);
    gpiod_line_release(line_out);
    gpiod_chip_close(chip);
}

static void handle_touch() {
    if (!g_touched) {
        g_touched = true;
        gpiod_line_set_value(line_out, 1);
        printf("Touch detected at %s\n", ctime(&time(NULL)));
        fflush(stdout);
    }
}

int main() {
    init_gpio();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (g_running) {
        int value = gpiod_line_get_value(line_in);
        if (value == 1) {
            handle_touch();
        } else {
            g_touched = false;
        }
        usleep(DEBOUNCE_TIME * 1000);
    }

    cleanup_gpio();
    return 0;
}

