#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define POLL_INTERVAL 100 // ms

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    // Close the log file
    fclose(log_file);

    // Clean up the library
    gpiod_cleanup();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the library
    gpiod_init();

    // Set up the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    FILE *log_file = fopen("magnet_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up the GPIO pins
    gpiod_set_direction(SENSOR_1_PIN, GPIOD_IN);
    gpiod_set_direction(SENSOR_2_PIN, GPIOD_IN);
    gpiod_set_direction(SENSOR_3_PIN, GPIOD_IN);

    // Enable the internal pull-up resistors
    gpiod_set_pull(SENSOR_1_PIN, GPIOD_PULL_UP);
    gpiod_set_pull(SENSOR_2_PIN, GPIOD_PULL_UP);
    gpiod_set_pull(SENSOR_3_PIN, GPIOD_PULL_UP);

    // Check the GPIO modes and pull settings
    if (gpiod_get_mode(SENSOR_1_PIN) != GPIOD_IN || gpiod_get_pull(SENSOR_1_PIN) != GPIOD_PULL_UP) {
        fprintf(stderr, "Error setting up GPIO pin %d\n", SENSOR_1_PIN);
        return 1;
    }
    if (gpiod_get_mode(SENSOR_2_PIN) != GPIOD_IN || gpiod_get_pull(SENSOR_2_PIN) != GPIOD_PULL_UP) {
        fprintf(stderr, "Error setting up GPIO pin %d\n", SENSOR_2_PIN);
        return 1;
    }
    if (gpiod_get_mode(SENSOR_3_PIN) != GPIOD_IN || gpiod_get_pull(SENSOR_3_PIN) != GPIOD_PULL_UP) {
        fprintf(stderr, "Error setting up GPIO pin %d\n", SENSOR_3_PIN);
        return 1;
    }

    // Read the initial state of the sensors
    bool sensor_1_state = gpiod_get_value(SENSOR_1_PIN);
    bool sensor_2_state = gpiod_get_value(SENSOR_2_PIN);
    bool sensor_3_state = gpiod_get_value(SENSOR_3_PIN);

    // Log the initial state
    fprintf(log_file, "%s, Sensor 1: %s\n", get_timestamp(), sensor_1_state ? "Magnet present" : "Magnet removed");
    fprintf(log_file, "%s, Sensor 2: %s\n", get_timestamp(), sensor_2_state ? "Magnet present" : "Magnet removed");
    fprintf(log_file, "%s, Sensor 3: %s\n", get_timestamp(), sensor_3_state ? "Magnet present" : "Magnet removed");

    // Poll the sensors every POLL_INTERVAL ms
    while (true) {
        // Read the current state of the sensors
        bool sensor_1_state = gpiod_get_value(SENSOR_1_PIN);
        bool sensor_2_state = gpiod_get_value(SENSOR_2_PIN);
        bool sensor_3_state = gpiod_get_value(SENSOR_3_PIN);

        // Check for state changes
        if (sensor_1_state != sensor_1_state) {
            fprintf(log_file, "%s, Sensor 1: %s\n", get_timestamp(), sensor_1_state ? "Magnet present" : "Magnet removed");
        }
        if (sensor_2_state != sensor_2_state) {
            fprintf(log_file, "%s, Sensor 2: %s\n", get_timestamp(), sensor_2_state ? "Magnet present" : "Magnet removed");
        }
        if (sensor_3_state != sensor_3_state) {
            fprintf(log_file, "%s, Sensor 3: %s\n", get_timestamp(), sensor_3_state ? "Magnet present" : "Magnet removed");
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up the library
    gpiod_cleanup();

    // Close the log file
    fclose(log_file);

    return 0;
}

