#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio17"
#define FLAME_LOG_FILE "flame_log.txt"
#define POLL_INTERVAL 100 // ms

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip and line
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up line as input with internal pull-up
    gpiod_line_request_input(line, "flame_sensor");
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, GPIOD_LINE_REQUEST_FLAG_DEFAULT);
    gpiod_line_set_config(line, GPIOD_LINE_REQUEST_BIAS_PULL_UP, GPIOD_LINE_REQUEST_FLAG_DEFAULT);

    // Open log file
    int log_fd = open(FLAME_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file %s\n", FLAME_LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Poll line for falling edge events
    while (running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, &event, POLL_INTERVAL);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for GPIO line event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Print to console and log file
            printf("FLAME DETECTED\n");
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));
            char log_line[100];
            snprintf(log_line, sizeof(log_line), "%s FLAME DETECTED\n", timestamp);
            write(log_fd, log_line, strlen(log_line));
        }
    }

    // Clean up
    close(log_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

