// Function prototypes
void handle_sigint(int signal);
void handle_sigterm(int signal);
void handle_error(const char *message);
void handle_gpiod_error(const char *message);
void handle_file_error(const char *message);
void handle_output_error(const char *message);
void handle_sensor_error(const char *message);
void handle_log_error(const char *message);

// GPIO pin numbers
int sensor_pins[CHANNEL_COUNT] = {5, 6, 7, 8, 9, 10, 11, 12};
int output_pins[OUTPUT_PIN_COUNT] = {17, 18, 19, 20, 21, 22, 23, 24};

// GPIO chip and line handles
struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[CHANNEL_COUNT];
struct gpiod_line *output_lines[OUTPUT_PIN_COUNT];

// Counter variables
int counter = 0;

int main(void) {
    // Initialize GPIO chip and lines
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        handle_gpiod_error("Failed to open GPIO chip");
        return 1;
    }

    for (int i = 0; i < CHANNEL_COUNT; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            handle_gpiod_error("Failed to get sensor line");
            return 1;
        }
    }

    for (int i = 0; i < OUTPUT_PIN_COUNT; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (output_lines[i] == NULL) {
            handle_gpiod_error("Failed to get output line");
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize counter
    counter = 0;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        handle_file_error("Failed to open log file");
        return 1;
    }

    // Stabilization delay
    usleep(200000);

    // Main loop
    while (1) {
        // Read sensor lines
        for (int i = 0; i < CHANNEL_COUNT; i++) {
            int value = gpiod_line_get_value(sensor_lines[i]);
            if (value < 0) {
                handle_sensor_error("Failed to read sensor line");
                continue;
            }

            // Increment counter on rising edge
            if (value == 1) {
                counter++;
                if (counter > 255) {
                    counter = 0;
                }
            }
        }

        // Update output lines
        for (int i = 0; i < OUTPUT_PIN_COUNT; i++) {
            int value = counter & (1 << i);
            int ret = gpiod_line_set_value(output_lines[i], value);
            if (ret < 0) {
                handle_output_error("Failed to set output line");
                continue;
            }
        }

        // Log event
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counter);
        fflush(log_file);

        // Print to stdout
        printf("Touch on channel %d | Counter: %d\n", i + 1, counter);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

void handle_sigint(int signal) {
    // Reset output pins
    for (int i = 0; i < OUTPUT_PIN_COUNT; i++) {
        gpiod_line_set_value(output_lines[i], 0);
    }

    // Release driver resources
    gpiod_chip_close(chip);

    // Exit with status 0
    exit(0);
}

