#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_COUNT 4
#define SENSOR_PINS 17, 18, 27, 22
#define POLL_INTERVAL 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up GPIO lines
    struct gpiod_line *lines[SENSOR_COUNT];
    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line for pin %d\n", SENSOR_PINS[i]);
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "tracking") != 0) {
            fprintf(stderr, "Error: Failed to request input for GPIO line %d\n", SENSOR_PINS[i]);
            return 1;
        }
    }

    // Open CSV file
    FILE *fp = fopen("tracking_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        return 1;
    }

    // Write header row if necessary
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Poll sensors
    while (running) {
        // Read sensor values
        int values[SENSOR_COUNT];
        for (int i = 0; i < SENSOR_COUNT; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %d\n", SENSOR_PINS[i]);
                return 1;
            }
        }

        // Write values to CSV file
        time_t now = time(NULL);
        fprintf(fp, "%ld,", now);
        for (int i = 0; i < SENSOR_COUNT; i++) {
            fprintf(fp, "%d,", values[i]);
        }
        fprintf(fp, "\n");

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(fp);

    return 0;
}

