#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define DEBOUNCE_TIME 50
#define POLL_INTERVAL 100

static bool running = true;
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = false;
    }
}

static void cleanup(void) {
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    fclose(log_file);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request lines 17 and 18
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line1 || !line2) {
        fprintf(stderr, "Error: unable to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

