    running = false;
}

static void log_sample(FILE *log_file, uint64_t timestamp, bool sensor1, bool sensor2, bool led_state) {
    fprintf(log_file, "%llu,%d,%d,%d\n", timestamp, sensor1, sensor2, led_state);
    fflush(log_file);
}

int main(void) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Set up the GPIO lines
    struct gpiod_line *sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    struct gpiod_line *sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (sensor1_line == NULL || sensor2_line == NULL || led_line == NULL) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to input mode
    if (gpiod_line_request_input(sensor1_line, "sensor1") != 0 ||
        gpiod_line_request_input(sensor2_line, "sensor2") != 0 ||
        gpiod_line_request_output(led_line, "led") != 0) {
        fprintf(stderr, "Error: unable to request GPIO lines\n");
        gpiod_line_free(sensor1_line);
        gpiod_line_free(sensor2_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: unable to open log file\n");
        gpiod_line_free(sensor1_line);
        gpiod_line_free(sensor2_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read the sensor values
        bool sensor1 = gpiod_line_get_value(sensor1_line) == 0;
        bool sensor2 = gpiod_line_get_value(sensor2_line) == 0;

        // Calculate the LED state
        bool led_state = sensor1 && sensor2;

        // Log the sample
        uint64_t timestamp = time(NULL);
        log_sample(log_file, timestamp, sensor1, sensor2, led_state);

        // Set the LED state
        gpiod_line_set_value(led_line, led_state);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Graceful shutdown
    gpiod_line_set_value(led_line, false);
    gpiod_line_free(sensor1_line);
    gpiod_line_free(sensor2_line);
    gpiod_line_free(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

