#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SAMPLE_PERIOD_US 125
#define LED_ON_DURATION_MS 100

volatile sig_atomic_t stop_sampling = 0;

void sigint_handler(int signum) {
    stop_sampling = 1;
}

int main(void) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Set up the GPIO pin for input
    struct gpiod_line *line = gpiod_chip_get_line(chip, 4);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        return 1;
    }

    // Set up the LED pin for output
    struct gpiod_line *led = gpiod_chip_get_line(chip, 17);
    if (!led) {
        fprintf(stderr, "Error: unable to get LED line\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: unable to set signal handler\n");
        return 1;
    }

    // Main sampling loop
    while (!stop_sampling) {
        // Read the GPIO pin
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            return 1;
        }

        // Check for a sound peak
        if (value == 1) {
            // Get the current timestamp
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);

            // Print the timestamp to stdout
            printf("%ld.%ld\n", ts.tv_sec, ts.tv_nsec);

            // Turn on the LED for 100ms
            gpiod_line_set_value(led, 1);
            usleep(LED_ON_DURATION_MS * 1000);
            gpiod_line_set_value(led, 0);
        }

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD_US);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_line_release(led);
    gpiod_chip_close(chip);

    return 0;
}

