#include <fcntl.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

#define SENSOR_ACTIVE_LOW 1
#define SENSOR_PULL_UP 1

#define SENSOR_READ_INTERVAL 100

int main(int argc, char **argv) {
  int left_sensor_fd, center_sensor_fd, right_sensor_fd;
  int left_sensor_value, center_sensor_value, right_sensor_value;

  // Initialize the GPIO library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize GPIO library\n");
    return 1;
  }

  // Set up the left sensor pin
  if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set mode for left sensor pin\n");
    return 1;
  }
  if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) < 0) {
    fprintf(stderr, "Failed to set pull-up for left sensor pin\n");
    return 1;
  }

  // Set up the center sensor pin
  if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set mode for center sensor pin\n");
    return 1;
  }
  if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) < 0) {
    fprintf(stderr, "Failed to set pull-up for center sensor pin\n");
    return 1;
  }

  // Set up the right sensor pin
  if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set mode for right sensor pin\n");
    return 1;
  }
  if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) < 0) {
    fprintf(stderr, "Failed to set pull-up for right sensor pin\n");
    return 1;
  }

  // Set up the signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (1) {
    // Read the sensor values
    left_sensor_value = gpioRead(LEFT_SENSOR_PIN);
    center_sensor_value = gpioRead(CENTER_SENSOR_PIN);
    right_sensor_value = gpioRead(RIGHT_SENSOR_PIN);

    // Print the sensor values
    printf("Left sensor: %d\n", left_sensor_value);
    printf("Center sensor: %d\n", center_sensor_value);
    printf("Right sensor: %d\n", right_sensor_value);

    // Sleep for 100 ms
    usleep(SENSOR_READ_INTERVAL * 1000);
  }

  // Clean up
  gpioTerminate();

  return 0;
}

void signal_handler(int signal) {
  // Clean up
  gpioTerminate();

  // Exit
  exit(0);
}

