#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

#define DEVICE_PATH "/dev/gpiochip0"

int main(int argc, char **argv) {
    int left_fd, middle_fd, right_fd;
    int left_value, middle_value, right_value;

    // Open the GPIO device
    left_fd = open(DEVICE_PATH, O_RDONLY);
    if (left_fd < 0) {
        perror("Error opening GPIO device");
        return 1;
    }

    middle_fd = open(DEVICE_PATH, O_RDONLY);
    if (middle_fd < 0) {
        perror("Error opening GPIO device");
        close(left_fd);
        return 1;
    }

    right_fd = open(DEVICE_PATH, O_RDONLY);
    if (right_fd < 0) {
        perror("Error opening GPIO device");
        close(left_fd);
        close(middle_fd);
        return 1;
    }

    // Set up the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Poll the sensors every 100ms
    while (1) {
        // Read the sensor values
        left_value = gpiod_get_value(left_fd, LEFT_PIN);
        if (left_value < 0) {
            perror("Error reading left sensor");
            break;
        }

        middle_value = gpiod_get_value(middle_fd, MIDDLE_PIN);
        if (middle_value < 0) {
            perror("Error reading middle sensor");
            break;
        }

        right_value = gpiod_get_value(right_fd, RIGHT_PIN);
        if (right_value < 0) {
            perror("Error reading right sensor");
            break;
        }

        // Print the sensor values
        printf("L: %d M: %d R: %d\n", left_value, middle_value, right_value);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    close(left_fd);
    close(middle_fd);
    close(right_fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

