#include <time.h>
#include <libgpiod.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

#define RANGE 255
#define STEPS 50
#define INTERVAL 5

static int gpio_fd;
static int red_pin;
static int green_pin;
static int blue_pin;

static void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down", signum);
    gpiod_line_release(red_pin);
    gpiod_line_release(green_pin);
    gpiod_line_release(blue_pin);
    gpiod_chip_close(gpio_fd);
    closelog();
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize syslog
    openlog(NULL, LOG_PID, LOG_USER);

    // Initialize GPIO
    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set up GPIO lines
    red_pin = gpiod_chip_get_line(gpio_fd, RED_PIN);
    green_pin = gpiod_chip_get_line(gpio_fd, GREEN_PIN);
    blue_pin = gpiod_chip_get_line(gpio_fd, BLUE_PIN);
    if (red_pin < 0 || green_pin < 0 || blue_pin < 0) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(gpio_fd);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up PWM
    gpiod_line_request_output(red_pin, "red", 0);
    gpiod_line_request_output(green_pin, "green", 0);
    gpiod_line_request_output(blue_pin, "blue", 0);
    if (gpiod_line_request_output(red_pin, "red", 0) < 0 ||
        gpiod_line_request_output(green_pin, "green", 0) < 0 ||
        gpiod_line_request_output(blue_pin, "blue", 0) < 0) {
        syslog(LOG_ERR, "Failed to request PWM outputs: %s", strerror(errno));
        gpiod_line_release(red_pin);
        gpiod_line_release(green_pin);
        gpiod_line_release(blue_pin);
        gpiod_chip_close(gpio_fd);
        closelog();
        return 1;
    }

    // Set up PWM frequency
    gpiod_line_set_pwm_frequency(red_pin, 1000);
    gpiod_line_set_pwm_frequency(green_pin, 1000);
    gpiod_line_set_pwm_frequency(blue_pin, 1000);
    if (gpiod_line_set_pwm_frequency(red_pin, 1000) < 0 ||
        gpiod_line_set_pwm_frequency(green_pin, 1000) < 0 ||
        gpiod_line_set_pwm_frequency(blue_pin, 1000) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency: %s", strerror(errno));
        gpiod_line_release(red_pin);
        gpiod_line_release(green_pin);
        gpiod_line_release(blue_pin);
        gpiod_chip_close(gpio_fd);
        closelog();
        return 1;
    }

    // Set up PWM range
    gpiod_line_set_pwm_range(red_pin, RANGE);
    gpiod_line_set_pwm_range(green_pin, RANGE);
    gpiod_line_set_pwm_range(blue_pin, RANGE);
    if (gpiod_line_set_pwm_range(red_pin, RANGE) < 0 ||
        gpiod_line_set_pwm_range(green_pin, RANGE) < 0 ||
        gpiod_line_set_pwm_range(blue_pin, RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range: %s", strerror(errno));
        gpiod_line_release(red_pin);
        gpiod_line_release(green_pin);
        gpiod_line_release(blue_pin);
        gpiod_chip_close(gpio_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random hue
        int hue = rand() % 360;

        // Calculate RGB values
        int red = (hue < 120) ? 255 : 0;
        int green = (hue < 120) ? 255 - (hue - 120) * 255 / 120 : 0;
        int blue = (hue < 120) ? 0 : (hue - 120) * 255 / 120;

        // Set PWM values
        gpiod_line_set_pwm_value(red_pin, red);
        gpiod_line_set_pwm_value(green_pin, green);
        gpiod_line_set_pwm_value(blue_pin, blue);

        // Wait for interval
        usleep(INTERVAL * 1000000);
    }

    // Clean up
    gpiod_line_release(red_pin);
    gpiod_line_release(green_pin);
    gpiod_line_release(blue_pin);
    gpiod_chip_close(gpio_fd);
    closelog();

    return 0;
}

