#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define PON 0x01
#define AEN 0x10
#define INTEGRATION_TIME 0x02
#define CLEAR_CHANNEL 0x14
#define RED_CHANNEL 0x10
#define GREEN_CHANNEL 0x11
#define BLUE_CHANNEL 0x12
#define THRESHOLD 200

int main(void) {
    int i2c_fd, gpio_fd, ret;
    uint8_t reg_val;
    uint16_t red, green, blue, clear;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open GPIO line
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    // Power on sensor
    reg_val = PON;
    if (ioctl(i2c_fd, I2C_SMBUS, &reg_val) < 0) {
        perror("Failed to power on sensor");
        return 1;
    }

    // Enable RGBC
    reg_val = AEN;
    if (ioctl(i2c_fd, I2C_SMBUS, &reg_val) < 0) {
        perror("Failed to enable RGBC");
        return 1;
    }

    // Configure integration time
    reg_val = INTEGRATION_TIME;
    if (ioctl(i2c_fd, I2C_SMBUS, &reg_val) < 0) {
        perror("Failed to configure integration time");
        return 1;
    }

    // Enter main loop
    while (1) {
        // Read calibrated red, green, blue, and clear values
        if (read(i2c_fd, &red, 2) < 0) {
            perror("Failed to read red value");
            return 1;
        }
        if (read(i2c_fd, &green, 2) < 0) {
            perror("Failed to read green value");
            return 1;
        }
        if (read(i2c_fd, &blue, 2) < 0) {
            perror("Failed to read blue value");
            return 1;
        }
        if (read(i2c_fd, &clear, 2) < 0) {
            perror("Failed to read clear value");
            return 1;
        }

        // Print values to console
        printf("Red: %d\n", red);
        printf("Green: %d\n", green);
        printf("Blue: %d\n", blue);
        printf("Clear: %d\n", clear);

        // Control LED
        if (red > THRESHOLD) {
            gpio_write(gpio_fd, 17, 1);
        } else {
            gpio_write(gpio_fd, 17, 0);
        }

        // Sleep for 200 ms
        usleep(200000);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Clean up resources
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT\n");
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM\n");
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

