#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define LED_PIN 18
#define BUZZER_PIN 17
#define FLAME_PIN 4

#define LED_ON 1
#define LED_OFF 0
#define BUZZER_ON 1
#define BUZZER_OFF 0
#define FLAME_DETECTED 0
#define FLAME_CLEARED 1

#define SELF_TEST_DELAY 500
#define POLL_DELAY 50
#define ERROR_DELAY 100
#define BUZZER_PATTERN 200
#define BUZZER_REPEAT 3

#define LOG_FILE "flame_sensor.log"

int main(int argc, char **argv) {
  // Initialize the GPIO pins
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize GPIO\n");
    return 1;
  }

  // Set up the LED and buzzer pins as outputs
  if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set LED pin as output\n");
    return 1;
  }
  if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set buzzer pin as output\n");
    return 1;
  }

  // Set up the flame sensor pin as an input
  if (gpioSetMode(FLAME_PIN, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set flame sensor pin as input\n");
    return 1;
  }

  // Perform a self-test
  if (selfTest() < 0) {
    fprintf(stderr, "Self-test failed\n");
    return 1;
  }

  // Open the log file
  int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
  if (log_fd < 0) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Set up the signal handler
  signal(SIGINT, signalHandler);

  // Main loop
  while (true) {
    // Read the flame sensor
    int flame = gpioRead(FLAME_PIN);
    if (flame < 0) {
      fprintf(stderr, "Failed to read flame sensor\n");
      return 1;
    }

    // If flame detected, turn on the LED and buzzer
    if (flame == FLAME_DETECTED) {
      gpioWrite(LED_PIN, LED_ON);
      gpioWrite(BUZZER_PIN, BUZZER_ON);
    }

    // If flame cleared, turn off the LED and buzzer
    if (flame == FLAME_CLEARED) {
      gpioWrite(LED_PIN, LED_OFF);
      gpioWrite(BUZZER_PIN, BUZZER_OFF);
    }

    // Log the event
    char *event = flame == FLAME_DETECTED ? "flame detected" : "flame cleared";
    char *timestamp = asctime(localtime(&time(NULL)));
    char *log_entry = malloc(strlen(timestamp) + strlen(event) + 2);
    sprintf(log_entry, "%s %s\n", timestamp, event);
    write(log_fd, log_entry, strlen(log_entry));
    free(log_entry);

    // Sleep for POLL_DELAY milliseconds
    usleep(POLL_DELAY * 1000);
  }

  // Clean up
  close(log_fd);
  gpioTerminate();

  return 0;
}

int selfTest() {
  // Blink the LED twice
  for (int i = 0; i < 2; i++) {
    gpioWrite(LED_PIN, LED_ON);
    usleep(SELF_TEST_DELAY * 1000);
    gpioWrite(LED_PIN, LED_OFF);
    usleep(SELF_TEST_DELAY * 1000);
  }

  // Read the flame sensor five times at 100ms intervals
  for (int i = 0; i < 5; i++) {
    int flame = gpioRead(FLAME_PIN);
    if (flame < 0) {
      fprintf(stderr, "Failed to read flame sensor\n");
      return -1;
    }

    // If any read returns LOW, signal an error
    if (flame == FLAME_DETECTED) {
      return -1;
    }

    usleep(100 * 1000);
  }

  return 0;
}

void signalHandler(int signal) {
  // Clean up
  close(log_fd);
  gpioTerminate();

  // Exit with code 1
  exit(1);
}

