#define I2C_DEV "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_REG_DATA 0x46
#define BH1750_REG_POWER_DOWN 0x00
#define BH1750_REG_POWER_ON 0x01
#define BH1750_REG_RESET 0x07
#define BH1750_REG_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_REG_CONTINUOUS_LOW_RES_MODE 0x11
#define BH1750_REG_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_REG_ONE_TIME_LOW_RES_MODE 0x21
#define BH1750_REG_RED_DATA 0x52
#define BH1750_REG_GREEN_DATA 0x53
#define BH1750_REG_BLUE_DATA 0x54
#define BH1750_REG_CLEAR_DATA 0x55
#define BH1750_REG_IR_DATA 0x56

#define GPIO_PIN 17
#define GPIO_BCM 17

#define BUFFER_SIZE 60

int main(void)
{
    int i2c_fd, gpio_fd;
    uint8_t buffer[BUFFER_SIZE];
    uint16_t lux;
    int i, j;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open GPIO device
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Set GPIO pin as output
    if (ioctl(gpio_fd, GPIO_SET_OUTPUT, GPIO_PIN) < 0) {
        perror("Failed to set GPIO pin as output");
        return 1;
    }

    // Set GPIO pin to low
    if (ioctl(gpio_fd, GPIO_SET_LOW, GPIO_PIN) < 0) {
        perror("Failed to set GPIO pin to low");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Set I2C mode
    if (ioctl(i2c_fd, I2C_SET_MODE, I2C_MODE_MASTER) < 0) {
        perror("Failed to set I2C mode");
        return 1;
    }

    // Set I2C speed
    if (ioctl(i2c_fd, I2C_SET_SPEED, I2C_SPEED_STANDARD) < 0) {
        perror("Failed to set I2C speed");
        return 1;
    }

    // Set I2C timeout
    if (ioctl(i2c_fd, I2C_SET_TIMEOUT, 1000) < 0) {
        perror("Failed to set I2C timeout");
        return 1;
    }

    // Set BH1750 to continuous high resolution mode
    if (i2c_smbus_write_byte_data(i2c_fd, BH1750_REG_CONTINUOUS_HIGH_RES_MODE, 0x01) < 0) {
        perror("Failed to set BH1750 to continuous high resolution mode");
        return 1;
    }

    // Read BH1750 data
    if (i2c_smbus_read_word_data(i2c_fd, BH1750_REG_DATA) < 0) {
        perror("Failed to read BH1750 data");
        return 1;
    }

    // Compute average lux
    lux = 0;
    for (i = 0; i < BUFFER_SIZE; i++) {
