#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_DATA 17
#define GPIO_CLOCK 18
#define GPIO_LATCH 27

#define SEVEN_SEGMENT_PATTERN 0b01011110

int main() {
    int fd;
    uint8_t *gpio_map;
    int gpio_data, gpio_clock, gpio_latch;

    // Open the GPIO device
    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        return 1;
    }

    // Map the GPIO memory
    gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (gpio_map == MAP_FAILED) {
        perror("Failed to mmap GPIO memory");
        close(fd);
        return 1;
    }

    // Set the GPIO pins as outputs
    gpio_data = gpio_map + GPIO_DATA;
    gpio_clock = gpio_map + GPIO_CLOCK;
    gpio_latch = gpio_map + GPIO_LATCH;
    *gpio_data = 0;
    *gpio_clock = 0;
    *gpio_latch = 0;

    // Set the GPIO pins to their initial values
    *gpio_data = SEVEN_SEGMENT_PATTERN;
    *gpio_clock = 0;
    *gpio_latch = 1;

    // Shift out the pattern
    for (int i = 0; i < 8; i++) {
        *gpio_clock = 1;
        usleep(100);
        *gpio_clock = 0;
        usleep(100);
    }

    // Set the GPIO pins to their initial values
    *gpio_data = SEVEN_SEGMENT_PATTERN;
    *gpio_clock = 0;
    *gpio_latch = 1;

    // Blink the digit
    while (1) {
        *gpio_data = SEVEN_SEGMENT_PATTERN;
        *gpio_clock = 0;
        *gpio_latch = 1;
        usleep(500000);
        *gpio_data = 0;
        *gpio_clock = 0;
        *gpio_latch = 1;
        usleep(500000);
    }

    // Clean up
    munmap(gpio_map, 4096);
    close(fd);

    return 0;
}

