#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up and edge detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input\n");
        gpiod_line_free(button_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_set_config(button_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set button line event detection\n");
        gpiod_line_free(button_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Blink LED with 2-second period
    while (!stop) {
        gpiod_line_set_value(led_line, 1);
        usleep(1000000);
        gpiod_line_set_value(led_line, 0);
        usleep(1000000);
    }

    // Handle button press
    if (gpiod_line_event_pending(button_line)) {
        gpiod_line_event_read(button_line, NULL);
        printf("Button pressed\n");
    }

    // Clean up
    gpiod_line_free(button_line);
    gpiod_line_free(led_line);
    gpiod_chip_close(chip);

    return 0;
}

