#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_ON 1
#define LED_OFF 0
#define BUTTON_PRESSED 1
#define BUTTON_RELEASED 0

static int led_fd;
static int button_fd;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, releasing resources...\n", signum);
        gpiod_line_release(led_fd);
        gpiod_line_release(button_fd);
        exit(0);
    }
}

static void blink_led(int state) {
    gpiod_line_set_value(led_fd, state);
    usleep(500000);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Open the LED line
    led_fd = gpiod_chip_get_line(chip, LED_PIN);
    if (led_fd == NULL) {
        fprintf(stderr, "Error: unable to open LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the LED line as an output
    if (gpiod_line_request_output(led_fd, "led", 0) < 0) {
        fprintf(stderr, "Error: unable to set LED line as output\n");
        gpiod_line_release(led_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the button line
    button_fd = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (button_fd == NULL) {
        fprintf(stderr, "Error: unable to open button line\n");
        gpiod_line_release(led_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the button line as an input with pull-down
    if (gpiod_line_request_input(button_fd, "button", 0) < 0) {
        fprintf(stderr, "Error: unable to set button line as input\n");
        gpiod_line_release(button_fd);
        gpiod_line_release(led_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the LED to off initially
    gpiod_line_set_value(led_fd, LED_OFF);

    // Loop forever, monitoring the button and blinking the LED
    while (1) {
        // Read the button state
        int button_state = gpiod_line_get_value(button_fd);
        if (button_state < 0) {
            fprintf(stderr, "Error: unable to read button state\n");
            gpiod_line_release(button_fd);
            gpiod_line_release(led_fd);
            gpiod_chip_close(chip);
            return 1;
        }

        // If the button is pressed, blink the LED
        if (button_state == BUTTON_PRESSED) {
            blink_led(LED_ON);
        }

        // If the button is released, turn the LED off
        if (button_state == BUTTON_RELEASED) {
            gpiod_line_set_value(led_fd, LED_OFF);
        }
    }

    // Close the lines and chip on exit
    gpiod_line_release(button_fd);
    gpiod_line_release(led_fd);
    gpiod_chip_close(chip);

    return 0;
}

