#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define WHO_AM_I 0x0D
#define STANDBY 0x00
#define ACTIVE 0x01
#define RANGE 0x02
#define RATE 0x03
#define THRESHOLD 0.5

int main(void) {
    int fd;
    uint8_t data[6];
    double x, y, z, magnitude;
    char timestamp[20];
    char line[100];
    FILE *fp;

    // Open I2C bus
    if ((fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Verify WHO_AM_I identifier
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to select I2C device");
        return 1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read WHO_AM_I");
        return 1;
    }
    if (data[0] != WHO_AM_I) {
        fprintf(stderr, "Invalid WHO_AM_I: 0x%02X\n", data[0]);
        return 1;
    }

    // Put device in standby mode
    data[0] = STANDBY;
    if (write(fd, data, 1) != 1) {
        perror("Failed to write STANDBY");
        return 1;
    }

    // Configure sensor for ±2 g range and 200 Hz output data rate
    data[0] = RANGE;
    data[1] = 0x02;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write RANGE");
        return 1;
    }
    data[0] = RATE;
    data[1] = 0x04;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write RATE");
        return 1;
    }

    // Activate sensor
    data[0] = ACTIVE;
    if (write(fd, data, 1) != 1) {
        perror("Failed to write ACTIVE");
        return 1;
    }

    // Open impact log file
    if ((fp = fopen("impact_log.txt", "a")) == NULL) {
        perror("Failed to open impact log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        if (read(fd, data, 6) != 6) {
            perror("Failed to read acceleration data");
            continue;
        }

        // Compute acceleration magnitude
        x = (double)data[0] / 1000.0;
        y = (double)data[1] / 1000.0;
        z = (double)data[2] / 1000.0;
        magnitude = sqrt(x * x + y * y + z * z);

        // Check for impact
        if (magnitude > THRESHOLD) {
            // Get current timestamp
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            // Write impact log line
            snprintf(line, sizeof(line), "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
            fputs(line, fp);
        }
    }

    // Close I2C bus
    close(fd);

    // Close impact log file
    fclose(fp);

    return 0;
}

