#define ACCEL_Y_REG 0x34
#define ACCEL_Z_REG 0x36
#define ACCEL_ID_REG 0x00

#define ACCEL_ID_VAL 0xE5

#define ACCEL_THRESHOLD 2.0

int main(void) {
    // Initialize I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE);
