        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO
    int gpio_fd = gpio_open(GPIO_LED, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        return 1;
