#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000

#define ACCEL_REG_X_LSB 0x08
#define ACCEL_REG_X_MSB 0x09
#define ACCEL_REG_Y_LSB 0x0A
#define ACCEL_REG_Y_MSB 0x0B
#define ACCEL_REG_Z_LSB 0x0C
#define ACCEL_REG_Z_MSB 0x0D

#define MAG_REG_X_LSB 0x0E
#define MAG_REG_X_MSB 0x0F
#define MAG_REG_Y_LSB 0x10
#define MAG_REG_Y_MSB 0x11
#define MAG_REG_Z_LSB 0x12
#define MAG_REG_Z_MSB 0x13

#define ACCEL_SCALE 0.00006103515625
#define MAG_SCALE 0.0000001

#define TILT_COMPENSATION_THRESHOLD 0.5

#define LOG_FILE "compass_log.txt"

struct accel_data {
    int16_t x;
    int16_t y;
    int16_t z;
};

struct mag_data {
    int16_t x;
    int16_t y;
    int16_t z;
};

struct sample {
    time_t timestamp;
    float heading;
    struct accel_data accel;
    struct mag_data mag;
};

void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpiod_close(i2c_handle);
    pigpio_stop(pi);
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    gpiod_close(i2c_handle);
    pigpio_stop(pi);
    exit(0);
}

int main(void) {
    // Initialize I2C bus
    int i2c_handle = gpiod_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (i2c_handle < 0) {
        printf("Error opening I2C bus: %s\n", gpiod_errmsg(i2c_handle));
        return 1;
    }

    // Initialize PIGPIO
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        printf("Error starting PIGPIO: %s\n", pigpio_errmsg(pi));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");

    // Main loop
    while (true) {
        // Read accelerometer data
        struct accel_data accel;
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_X_LSB, &accel.x) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_Y_LSB, &accel.y) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_Z_LSB, &accel.z) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }

        // Read magnetometer data
        struct mag_data mag;
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_X_LSB, &mag.x) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_Y_LSB, &mag.y) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_Z_LSB, &mag.z) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }

        // Compute tilt compensation
        float tilt_compensation = 0.0;
        if (accel.x > TILT_COMPENSATION_THRESHOLD || accel.x < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.y, accel.z);
        } else if (accel.y > TILT_COMPENSATION_THRESHOLD || accel.y < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.x, accel.z);
        } else if (accel.z > TILT_COMPENSATION_THRESHOLD || accel.z < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.x, accel.y);
        }

        // Compute heading
        float heading = atan2(mag.y, mag.x) - tilt_compensation;

        // Write sample to log file
        struct sample sample;
        sample.timestamp = time(NULL);
        sample.heading = heading;
        sample.accel.x = accel.x * ACCEL_SCALE;
        sample.accel.y = accel.y * ACCEL_SCALE;
        sample.accel.z = accel.z * ACCEL_SCALE;
        sample.mag.x = mag.x * MAG_SCALE;
        sample.mag.y = mag.y * MAG_SCALE;
        sample.mag.z = mag.z * MAG_SCALE;
        fprintf(log_file, "%ld,%f,%f,%f,%f,%f,%f,%f\n", sample.timestamp, sample.heading, sample.accel.x, sample.accel.y, sample.accel.z, sample.mag.x, sample.mag.y, sample.mag.z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    gpiod_close(i2c_handle);

    // Close PIGPIO
    pigpio_stop(pi);

    return 0;
}

