        printf("Error starting PIGPIO: %s\n", pigpio_errmsg(pi));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n");

    // Main loop
    while (true) {
        // Read accelerometer data
        struct accel_data accel;
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_X_LSB, &accel.x) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_Y_LSB, &accel.y) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, ACCEL_REG_Z_LSB, &accel.z) < 0) {
            printf("Error reading accelerometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }

        // Read magnetometer data
        struct mag_data mag;
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_X_LSB, &mag.x) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_Y_LSB, &mag.y) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }
        if (gpiod_read_i2c_word_data(i2c_handle, MAG_REG_Z_LSB, &mag.z) < 0) {
            printf("Error reading magnetometer data: %s\n", gpiod_errmsg(i2c_handle));
            return 1;
        }

        // Compute tilt compensation
        float tilt_compensation = 0.0;
        if (accel.x > TILT_COMPENSATION_THRESHOLD || accel.x < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.y, accel.z);
        } else if (accel.y > TILT_COMPENSATION_THRESHOLD || accel.y < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.x, accel.z);
        } else if (accel.z > TILT_COMPENSATION_THRESHOLD || accel.z < -TILT_COMPENSATION_THRESHOLD) {
            tilt_compensation = atan2(accel.x, accel.y);
        }

        // Compute heading
        float heading = atan2(mag.y, mag.x) - tilt_compensation;

        // Write sample to log file
        struct sample sample;
        sample.timestamp = time(NULL);
        sample.heading = heading;
        sample.accel.x = accel.x * ACCEL_SCALE;
        sample.accel.y = accel.y * ACCEL_SCALE;
        sample.accel.z = accel.z * ACCEL_SCALE;
        sample.mag.x = mag.x * MAG_SCALE;
        sample.mag.y = mag.y * MAG_SCALE;
        sample.mag.z = mag.z * MAG_SCALE;
        fprintf(log_file, "%ld,%f,%f,%f,%f,%f,%f,%f\n", sample.timestamp, sample.heading, sample.accel.x, sample.accel.y, sample.accel.z, sample.mag.x, sample.mag.y, sample.mag.z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    gpiod_close(i2c_handle);

    // Close PIGPIO
    pigpio_stop(pi);

    return 0;
}
```
This code uses the `libgpiod` and `pigpio` libraries to communicate with the GY-51 LSM303DLHC accelerometer and magnetometer over I2C bus 1. It reads the accelerometer and magnetometer data every 100 ms and computes a tilt-compensated heading. The heading, accelerometer, and magnetometer data are then logged to a file named `compass_log.txt` with a CSV header. The program also sets up signal handlers for SIGINT and SIGTERM to perform a graceful shutdown.

