#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <vl6180x_api.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define FILENAME "distance_log.txt"
#define SAMPLE_RATE 100 // ms

// Sensor initialization sequence
static void init_sensor(void) {
    // Initialize I2C bus
    if (gpiod_init(I2C_BUS) < 0) {
        perror("gpiod_init");
        exit(1);
    }

    // Initialize sensor
    if (vl6180x_init(I2C_ADDR) < 0) {
        perror("vl6180x_init");
        exit(1);
    }
}

// Sensor read function
static int read_sensor(void) {
    // Read distance from sensor
    int distance = vl6180x_read_distance(I2C_ADDR);

    // Check for errors
    if (distance < 0) {
        perror("vl6180x_read_distance");
        return -1;
    }

    return distance;
}

// SIGINT handler
static void sigint_handler(int signum) {
    // Release resources
    gpiod_release(I2C_BUS);
    vl6180x_release(I2C_ADDR);

    // Exit program
    exit(0);
}

int main(void) {
    // Initialize sensor
    init_sensor();

    // Open file for logging
    int fd = open(FILENAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read distance from sensor
        int distance = read_sensor();

        // Check for errors
        if (distance < 0) {
            perror("read_sensor");
            continue;
        }

        // Log distance and timestamp
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char buf[100];
        snprintf(buf, sizeof(buf), "%ld.%06ld %d\n", tv.tv_sec, tv.tv_usec, distance);
        write(fd, buf, strlen(buf));

        // Check for door state
        if (distance < 100) {
            write(fd, "DOOR_OPEN\n", 9);
        } else {
            write(fd, "DOOR_CLOSED\n", 10);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_RATE * 1000);
    }

    // Close file
    close(fd);

    // Release resources
    gpiod_release(I2C_BUS);
    vl6180x_release(I2C_ADDR);

    return 0;
}

