#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_1 0x10
#define I2C_ADDR_2 0x11
#define SAMPLE_INTERVAL 10

#define CSV_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize I2C devices
    int i2c_addr_1 = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR_1);
    if (i2c_addr_1 < 0) {
        perror("Failed to initialize I2C device 1");
        close(i2c_fd);
        return 1;
    }

    int i2c_addr_2 = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR_2);
    if (i2c_addr_2 < 0) {
        perror("Failed to initialize I2C device 2");
        close(i2c_fd);
        return 1;
    }

    // Initialize CSV file
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (running) {
        // Read samples from both sensors
        uint16_t sample_1 = 0;
        uint16_t sample_2 = 0;
        if (read(i2c_fd, &sample_1, sizeof(sample_1)) != sizeof(sample_1)) {
            perror("Failed to read sample from sensor 1");
            continue;
        }

        if (read(i2c_fd, &sample_2, sizeof(sample_2)) != sizeof(sample_2)) {
            perror("Failed to read sample from sensor 2");
            continue;
        }

        // Compute TDOA
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        int64_t tdoa = (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec - (int64_t)ts.tv_sec * 1000000000;

        // Write to CSV file
        fprintf(csv_file, "%ld,%ld,%d,%d,%ld\n", ts.tv_sec, ts.tv_nsec, sample_1, sample_2, tdoa);
    }

    // Clean up
    fclose(csv_file);
    close(i2c_fd);
    return 0;
}

