#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_BUS 0
#define SPI_CS 8
#define SPI_MODE 3
#define SPI_SPEED 1000000

#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

#define GYRO_X_REG 0x00
#define GYRO_Y_REG 0x01
#define GYRO_Z_REG 0x02
#define ACCEL_X_REG 0x03
#define ACCEL_Y_REG 0x04
#define ACCEL_Z_REG 0x05

#define SPI_READ_SINGLE_REG(reg) (((reg) << 8) | 0x80)

int spi_fd;

void sigint_handler(int signum) {
    close(spi_fd);
    exit(0);
}

int main(void) {
    // Initialize SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(1);
    }

    // Set chip select pin
    if (ioctl(spi_fd, SPI_IOC_WR_CS, &SPI_CS) < 0) {
        perror("Failed to set chip select pin");
        close(spi_fd);
        exit(1);
    }

    // Register signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Read gyroscope and accelerometer registers
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    while (1) {
        // Read gyroscope registers
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(GYRO_X_REG)) < 0) {
            perror("Failed to read gyroscope X register");
            close(spi_fd);
            exit(1);
        }
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(GYRO_Y_REG)) < 0) {
            perror("Failed to read gyroscope Y register");
            close(spi_fd);
            exit(1);
        }
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(GYRO_Z_REG)) < 0) {
            perror("Failed to read gyroscope Z register");
            close(spi_fd);
            exit(1);
        }

        // Read accelerometer registers
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(ACCEL_X_REG)) < 0) {
            perror("Failed to read accelerometer X register");
            close(spi_fd);
            exit(1);
        }
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(ACCEL_Y_REG)) < 0) {
            perror("Failed to read accelerometer Y register");
            close(spi_fd);
            exit(1);
        }
        if (ioctl(spi_fd, SPI_IOC_RD_SINGLE_REG, &SPI_READ_SINGLE_REG(ACCEL_Z_REG)) < 0) {
            perror("Failed to read accelerometer Z register");
            close(spi_fd);
            exit(1);
        }

        // Scale and print values
        gyro_x = (uint16_t)(((float)gyro_x) * GYRO_SCALE);
        gyro_y = (uint16_t)(((float)gyro_y) * GYRO_SCALE);
        gyro_z = (uint16_t)(((float)gyro_z) * GYRO_SCALE);
        accel_x = (uint16_t)(((float)accel_x) * ACCEL_SCALE);
        accel_y = (uint16_t)(((float)accel_y) * ACCEL_SCALE);
        accel_z = (uint16_t)(((float)accel_z) * ACCEL_SCALE);
        printf("Gyroscope X: %d, Y: %d, Z: %d\n", gyro_x, gyro_y, gyro_z);
        printf("Accelerometer X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close SPI device and exit
    close(spi_fd);
    return 0;
}

