#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_CE0 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

#define GYRO_X_REG 0x00
#define GYRO_Y_REG 0x02
#define GYRO_Z_REG 0x04
#define ACCEL_X_REG 0x06
#define ACCEL_Y_REG 0x08
#define ACCEL_Z_REG 0x0A

#define READ_CMD 0x80
#define DUMMY_VAL 0x00

int main(void) {
    // Initialize the pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open the SPI channel
    int spi_handle = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return 1;
    }

    // Set the GPIO pin for CE0
    if (pigpio_gpio_write(GPIO_CE0, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d\n", GPIO_CE0);
        return 1;
    }

    // Set up the signal handler for Ctrl-C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the gyroscope and accelerometer data
        int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        if (read_data(spi_handle, GYRO_X_REG, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Failed to read data\n");
            return 1;
        }

        // Print the data to the console
        printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d, Accel X: %d, Accel Y: %d, Accel Z: %d\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_spi_close(spi_handle);
    pigpio_stop();

    return 0;
}

int read_data(int spi_handle, int reg, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    // Send the read command
    uint16_t cmd = READ_CMD | reg;
    if (pigpio_spi_xfer(spi_handle, &cmd, 1) < 0) {
        return -1;
    }

    // Wait for the stall time
    usleep(40000);

    // Send the dummy value
    uint16_t dummy = DUMMY_VAL;
    if (pigpio_spi_xfer(spi_handle, &dummy, 1) < 0) {
        return -1;
    }

    // Read the data
    uint16_t data[6];
    if (pigpio_spi_xfer(spi_handle, data, 6) < 0) {
        return -1;
    }

    // Scale the data
    *gyro_x = data[0] * GYRO_SCALE;
    *gyro_y = data[1] * GYRO_SCALE;
    *gyro_z = data[2] * GYRO_SCALE;
    *accel_x = data[3] * ACCEL_SCALE;
    *accel_y = data[4] * ACCEL_SCALE;
    *accel_z = data[5] * ACCEL_SCALE;

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    pigpio_spi_close(spi_handle);
    pigpio_stop();

    // Exit
    exit(0);
}

