#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LED_GPIO 17
#define THRESHOLD 256

int main(int argc, char *argv[]) {
    // Initialize I2C bus
    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize LED GPIO
    int led_fd = gpio_open(LED_GPIO, GPIO_OUTPUT);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        return 1;
    }

    // Initialize log file
    FILE *log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        uint8_t data[6];
        if (i2c_read(i2c_fd, data, 6) != 6) {
            perror("Failed to read accelerometer data");
            return 1;
        }

        // Verify device ID
        if (data[0] != 0xE5) {
            perror("Invalid device ID");
            return 1;
        }

        // Compute total acceleration magnitude
        int16_t x = (data[1] << 8) | data[2];
        int16_t y = (data[3] << 8) | data[4];
        int16_t z = (data[5] << 8) | data[6];
        int16_t magnitude = sqrt(x * x + y * y + z * z);

        // Check for impact
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpio_write(led_fd, 1);

            // Log impact event
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%ld.%06ld, %d, %d, %d\n", tv.tv_sec, tv.tv_usec, x, y, z);

            // Wait for 500 ms
            usleep(500000);

            // Turn off LED
            gpio_write(led_fd, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up on exit
    i2c_close(i2c_fd);
    gpio_close(led_fd);
    fclose(log_file);

    return 0;
}

void signal_handler(int signal) {
    // Clean up on signal
    i2c_close(i2c_fd);
    gpio_close(led_fd);
    fclose(log_file);

    exit(0);
}

