#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_BUS 1
#define IMU_ADDR 0x68
#define ACCEL_REG 0x28
#define GYRO_REG 0x20
#define ACCEL_X_OFFSET 0
#define ACCEL_Y_OFFSET 2
#define ACCEL_Z_OFFSET 4
#define GYRO_X_OFFSET 6
#define GYRO_Y_OFFSET 8
#define GYRO_Z_OFFSET 10

#define SAMPLE_RATE 10
#define SAMPLE_PERIOD 100

#define CSV_FILE "imu_log.csv"

int main(int argc, char **argv) {
    // Initialize the I2C bus
    int i2c_fd = i2c_open(I2C_BUS, IMU_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the CSV file
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the signal handler for Ctrl+C
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigemptyset(&sigint_handler.sa_mask);
    sigaction(SIGINT, &sigint_handler, NULL);

    // Main loop
    while (1) {
        // Read the accelerometer and gyroscope data
        uint8_t accel_data[6];
        uint8_t gyro_data[6];
        if (i2c_read(i2c_fd, ACCEL_REG, accel_data, 6) != 6) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            return 1;
        }
        if (i2c_read(i2c_fd, GYRO_REG, gyro_data, 6) != 6) {
            fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
            return 1;
        }

        // Convert the data to signed integers
        int16_t accel_x = (int16_t)((accel_data[ACCEL_X_OFFSET] << 8) | accel_data[ACCEL_X_OFFSET + 1]);
        int16_t accel_y = (int16_t)((accel_data[ACCEL_Y_OFFSET] << 8) | accel_data[ACCEL_Y_OFFSET + 1]);
        int16_t accel_z = (int16_t)((accel_data[ACCEL_Z_OFFSET] << 8) | accel_data[ACCEL_Z_OFFSET + 1]);
        int16_t gyro_x = (int16_t)((gyro_data[GYRO_X_OFFSET] << 8) | gyro_data[GYRO_X_OFFSET + 1]);
        int16_t gyro_y = (int16_t)((gyro_data[GYRO_Y_OFFSET] << 8) | gyro_data[GYRO_Y_OFFSET + 1]);
        int16_t gyro_z = (int16_t)((gyro_data[GYRO_Z_OFFSET] << 8) | gyro_data[GYRO_Z_OFFSET + 1]);

        // Print the data to the CSV file
        fprintf(csv_file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
            time(NULL), accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD * 1000);
    }

    // Clean up on exit
    i2c_close(i2c_fd);
    fclose(csv_file);
    return 0;
}

void sigint_handler_func(int signum) {
    // Close the I2C handle and CSV file
    i2c_close(i2c_fd);
    fclose(csv_file);

    // Terminate the driver library
    pigpio_terminate();

    // Exit the program
    exit(0);
}

