        int16_t accel_y = (int16_t)((accel_data[ACCEL_Y_OFFSET] << 8) | accel_data[ACCEL_Y_OFFSET + 1]);
        int16_t accel_z = (int16_t)((accel_data[ACCEL_Z_OFFSET] << 8) | accel_data[ACCEL_Z_OFFSET + 1]);
        int16_t gyro_x = (int16_t)((gyro_data[GYRO_X_OFFSET] << 8) | gyro_data[GYRO_X_OFFSET + 1]);
        int16_t gyro_y = (int16_t)((gyro_data[GYRO_Y_OFFSET] << 8) | gyro_data[GYRO_Y_OFFSET + 1]);
        int16_t gyro_z = (int16_t)((gyro_data[GYRO_Z_OFFSET] << 8) | gyro_data[GYRO_Z_OFFSET + 1]);

        // Print the data to the CSV file
        fprintf(csv_file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
            time(NULL), accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD * 1000);
    }

    // Clean up on exit
    i2c_close(i2c_fd);
    fclose(csv_file);
    return 0;
}

void sigint_handler_func(int signum) {
    // Close the I2C handle and CSV file
    i2c_close(i2c_fd);
    fclose(csv_file);

    // Terminate the driver library
    pigpio_terminate();

    // Exit the program
    exit(0);
}
