#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define GPIO_PIN 17
#define THRESHOLD 2048
#define POLL_INTERVAL 100

int main(int argc, char *argv[]) {
    int fd, gpio_fd, log_fd;
    uint8_t buf[1];
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct gpio_event_request gpio_req;
    struct gpio_event_response gpio_resp;
    struct timespec ts;
    char log_file[20] = "impact_log.txt";

    // Open I2C bus
    if ((fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open GPIO pin
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO pin");
        return 1;
    }

    // Open log file
    if ((log_fd = open(log_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up I2C message
    msg.addr = I2C_ADDR;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = buf;

    // Set up I2C read/write ioctl data
    ioctl_data.msgs = &msg;
    ioctl_data.nmsgs = 1;

    // Set up GPIO event request
    gpio_req.lineoffset = GPIO_PIN;
    gpio_req.event_request = GPIO_EVENT_REQUEST_RISING_EDGE;
    gpio_req.consumer_label = "accelerometer";

    // Set up GPIO event response
    gpio_resp.lineoffset = GPIO_PIN;
    gpio_resp.event_response = GPIO_EVENT_RESPONSE_NONE;

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Verify sensor identity
    if (i2c_smbus_read_byte_data(fd, I2C_ADDR, 0x0D) != 0x1A) {
        fprintf(stderr, "Invalid sensor ID\n");
        return 1;
    }

    // Set up GPIO pin as input
    if (ioctl(gpio_fd, GPIO_SET_LINE_DIRECTION, GPIO_PIN, GPIO_DIRECTION_IN) < 0) {
        perror("Failed to set GPIO pin direction");
        return 1;
    }

    // Set up GPIO pin as interrupt-driven
    if (ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, &gpio_req) < 0) {
        perror("Failed to set GPIO pin request");
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        if (i2c_smbus_read_i2c_block_data(fd, I2C_ADDR, 0x00, 6, buf) < 0) {
            perror("Failed to read acceleration data");
            return 1;
        }

        // Check if any axis exceeds threshold
        if (buf[0] > THRESHOLD || buf[1] > THRESHOLD || buf[2] > THRESHOLD) {
            // Turn on LED
            if (ioctl(gpio_fd, GPIO_SET_LINE_VALUE, GPIO_PIN, GPIO_VALUE_HIGH) < 0) {
                perror("Failed to set GPIO pin value");
                return 1;
            }

            // Log reading
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_fd, "%ld.%ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, buf[0], buf[1], buf[2]);

            // Wait for 500 ms
            usleep(500000);

            // Turn off LED
            if (ioctl(gpio_fd, GPIO_SET_LINE_VALUE, GPIO_PIN, GPIO_VALUE_LOW) < 0) {
                perror("Failed to set GPIO pin value");
                return 1;
            }
        }

        // Wait for poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(fd);
    close(gpio_fd);
    close(log_fd);

    return 0;
}

void sigint_handler(int signum) {
    // Release I2C bus
    if (ioctl(fd, I2C_RELEASE, I2C_ADDR) < 0) {
        perror("Failed to release I2C bus");
    }

    // Release GPIO lines
    if (ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, &gpio_req) < 0) {
        perror("Failed to release GPIO lines");
    }

    // Close log file
    close(log_fd);

    exit(0);
}

void sigterm_handler(int signum) {
    // Release I2C bus
    if (ioctl(fd, I2C_RELEASE, I2C_ADDR) < 0) {
        perror("Failed to release I2C bus");
    }

    // Release GPIO lines
    if (ioctl(gpio_fd, GPIO_SET_LINE_REQUEST, &gpio_req) < 0) {
        perror("Failed to release GPIO lines");
    }

    // Close log file
    close(log_fd);

    exit(0);
}

