#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000

#define CSV_FILE "magnetic_field_log.csv"
#define CSV_HEADER "timestamp,x,y,z\n"

int i2c_fd;
FILE *csv_file;

void sigint_handler(int signum) {
    printf("Caught signal %d\n", signum);
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

int main(void) {
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_device_id i2c_id;
    struct timespec timestamp;
    int ret;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C speed and timeout
    ret = ioctl(i2c_fd, I2C_SPEED, I2C_SPEED);
    if (ret < 0) {
        perror("Failed to set I2C speed");
        close(i2c_fd);
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_TIMEOUT, I2C_TIMEOUT);
    if (ret < 0) {
        perror("Failed to set I2C timeout");
        close(i2c_fd);
        return 1;
    }

    // Set I2C slave address
    i2c_id.addr = I2C_ADDR;
    i2c_id.flags = I2C_M_RD;
    ret = ioctl(i2c_fd, I2C_SLAVE, &i2c_id);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if file does not exist
    if (fseek(csv_file, 0, SEEK_END) == 0) {
        fprintf(csv_file, CSV_HEADER);
    }

    // Set signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read magnetic field data
        i2c_msg.addr = I2C_ADDR;
        i2c_msg.flags = I2C_M_RD;
        i2c_msg.len = 6;
        i2c_msg.buf = malloc(i2c_msg.len);
        if (i2c_msg.buf == NULL) {
            perror("Failed to allocate memory for I2C message");
            close(i2c_fd);
            fclose(csv_file);
            return 1;
        }

        i2c_data.msgs = &i2c_msg;
        i2c_data.nmsgs = 1;

        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read I2C data");
            free(i2c_msg.buf);
            close(i2c_fd);
            fclose(csv_file);
            return 1;
        }

        // Write magnetic field data to CSV file
        clock_gettime(CLOCK_REALTIME, &timestamp);
        fprintf(csv_file, "%ld.%ld,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, i2c_msg.buf[0], i2c_msg.buf[1], i2c_msg.buf[2]);

        // Free memory
        free(i2c_msg.buf);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

