#define SAMPLE_SIZE 3

#define CSV_HEADER "YYYY-MM-DD HH:MM:SS.mmm,X,Y,Z\n"

int main(int argc, char **argv) {
    int i2c_fd, gpio_fd, csv_fd;
    uint8_t buf[SAMPLE_SIZE];
    char csv_buf[SAMPLE_SIZE * 2 + 1];
    struct i2c_msg i2c_msg;
    struct gpio_event_request gpio_req;
    struct gpio_event_response gpio_resp;
    struct gpio_event_data gpio_data;
    struct timespec ts;
    int ret;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO device
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(i2c_fd);
        return 1;
