    // Set GPIO pin edge trigger
    ret = ioctl(gpio_fd, GPIO_SET_EDGE, INT1_PIN, GPIO_EDGE_FALLING);
    if (ret < 0) {
        perror("Failed to set GPIO pin edge trigger");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

