        perror("Failed to open CSV file");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Write CSV header
    ret = write(csv_fd, CSV_HEADER, strlen(CSV_HEADER));
    if (ret < 0) {
