#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_CS 8
#define WHO_AM_I_REG 0x00
#define ANGULAR_RATE_REG 0x02
#define SCALE_FACTOR 0.0305

#define CSV_FILE "gyro_log.csv"
#define CSV_HEADER "timestamp,angular_rate\n"

static int spi_fd;
static int spi_handle;
static int spi_cs;

static void sigint_handler(int signum) {
    printf("Received SIGINT, closing SPI handle and terminating driver\n");
    spi_close(spi_handle);
    spi_terminate();
    close(spi_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize SPI driver
    if (spi_init() < 0) {
        printf("Failed to initialize SPI driver\n");
        return 1;
    }

    // Open SPI channel
    spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CS);
    if (spi_fd < 0) {
        printf("Failed to open SPI channel\n");
        spi_terminate();
        return 1;
    }

    // Set SPI handle
    spi_handle = spi_get_handle(spi_fd);
    if (spi_handle < 0) {
        printf("Failed to get SPI handle\n");
        spi_close(spi_fd);
        spi_terminate();
        return 1;
    }

    // Set SPI CS
    spi_cs = spi_get_cs(spi_handle);
    if (spi_cs < 0) {
        printf("Failed to get SPI CS\n");
        spi_close(spi_handle);
        spi_terminate();
        return 1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i = 0;
    if (spi_transfer(spi_handle, SPI_CS, WHO_AM_I_REG, &who_am_i, 1) < 0) {
        printf("Failed to read WHO_AM_I register\n");
        spi_close(spi_handle);
        spi_terminate();
        return 1;
    }
    if (who_am_i != 0x12) {
        printf("Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        spi_close(spi_handle);
        spi_terminate();
        return 1;
    }

    // Open CSV file
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        printf("Failed to open CSV file\n");
        spi_close(spi_handle);
        spi_terminate();
        return 1;
    }

    // Write CSV header
    fprintf(csv_file, CSV_HEADER);

    // Set SIGINT handler
    signal(SIGINT, sigint_handler);

    // Sample angular rate at 10 ms interval
    while (1) {
        uint16_t angular_rate = 0;
        if (spi_transfer(spi_handle, SPI_CS, ANGULAR_RATE_REG, &angular_rate, 2) < 0) {
            printf("Failed to read ANGULAR_RATE register\n");
            spi_close(spi_handle);
            spi_terminate();
            fclose(csv_file);
            return 1;
        }

        // Convert raw value to degrees per second
        double angular_rate_deg_per_sec = angular_rate * SCALE_FACTOR;

        // Get current timestamp
        time_t timestamp = time(NULL);

        // Write timestamped reading to CSV file
        fprintf(csv_file, "%ld,%.2f\n", timestamp, angular_rate_deg_per_sec);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close SPI handle and terminate driver
    spi_close(spi_handle);
    spi_terminate();

    // Close CSV file
    fclose(csv_file);

    return 0;
}
