#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLL_INTERVAL 500

static volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main(void) {
    int fd;
    int gpio_handle;
    int gpio_value;
    char timestamp[20];
    char message[50];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up the GPIO pin as an input with an internal pull-up resistor
    gpio_handle = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    // Open the log file in append mode
    fd = open("flame_events.log", O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Poll the GPIO pin every POLL_INTERVAL milliseconds
    while (!stop_flag) {
        gpio_value = gpioRead(gpio_handle);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO pin\n");
            break;
        }

        // Check if a flame is detected
        if (gpio_value == PI_LOW) {
            // Get the current timestamp
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            // Write the log message to the file
            snprintf(message, sizeof(message), "%s – Flame detected: YES\n", timestamp);
            write(fd, message, strlen(message));

            // Print the message to the console
            printf("FLAME DETECTED!\n");
        }

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    close(fd);
    gpioTerminate();

    return 0;
}

