#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define VIBRATION_LOG "vibration_log.csv"

int main(void) {
    int fd;
    int ret;
    char buf[10];
    char timestamp[20];
    FILE *fp;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open CSV file for writing
    fp = fopen(VIBRATION_LOG, "w");
    if (fp == NULL) {
        perror("Failed to open CSV file");
        close(fd);
        return 1;
    }

    // Write header line to CSV file
    fprintf(fp, "Timestamp,X,Y,Z\n");

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read acceleration data from sensor
        ret = read(fd, buf, 10);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            close(fd);
            fclose(fp);
            return 1;
        }

        // Check for sensor-absent condition
        if (buf[0] == 0xFF) {
            fprintf(stderr, "Sensor is absent\n");
            continue;
        }

        // Convert acceleration data to integers
        int x = (buf[1] << 8) | buf[2];
        int y = (buf[3] << 8) | buf[4];
        int z = (buf[5] << 8) | buf[6];

        // Get current timestamp
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&t));

        // Write data to CSV file
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    }

    // Close I2C device and CSV file
    close(fd);
    fclose(fp);

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C device and CSV file
    close(fd);
    fclose(fp);

    // Exit program
    exit(0);
}

