#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_HALL1 17
#define GPIO_HALL2 27
#define BIAS_FLAGS (PI_BIAS_PULL_UP | PI_BIAS_PULL_DOWN)
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL 50

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void log_state(int hall1, int hall2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%ld %d %d\n", ts.tv_sec, ts.tv_nsec, hall1, hall2);
    write(LOG_FILE, buf, strlen(buf));
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open GPIO chip
    int chip = pigpio_open(0);
    if (chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    int hall1 = pigpio_gpio_request(chip, GPIO_HALL1, BIAS_FLAGS);
    int hall2 = pigpio_gpio_request(chip, GPIO_HALL2, BIAS_FLAGS);
    if (hall1 < 0 || hall2 < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        return 1;
    }

    // Open log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read GPIO values
        int hall1_val = pigpio_gpio_read(chip, hall1);
        int hall2_val = pigpio_gpio_read(chip, hall2);
        if (hall1_val < 0 || hall2_val < 0) {
            fprintf(stderr, "Failed to read GPIO values\n");
            return 1;
        }

        // Log state
        log_state(hall1_val, hall2_val);

        // Check for halt condition
        if (hall1_val && hall2_val) {
            printf("Halt condition detected, halting conveyor\n");
            break;
        }

        // Sleep for LOG_INTERVAL milliseconds
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up
    pigpio_gpio_release(chip, hall1);
    pigpio_gpio_release(chip, hall2);
    pigpio_close(chip);
    close(log_fd);

    return 0;
}

