                perror("Failed to read Y_MSB_REG");
                close(i2c_fd);
                fclose(fall_log_file);
                return 1;
            }
            y_msb = ret;

            ret = i2c_smbus_read_byte_data(i2c_fd, Y_LSB_REG);
            if (ret < 0) {
                perror("Failed to read Y_LSB_REG");
                close(i2c_fd);
                fclose(fall_log_file);
                return 1;
            }
            y_lsb = ret;

            ret = i2c_smbus_read_byte_data(i2c_fd, Z_MSB_REG);
            if (ret < 0) {
                perror("Failed to read Z_MSB_REG");
                close(i2c_fd);
                fclose(fall_log_file);
                return 1;
            }
            z_msb = ret;

            ret = i2c_smbus_read_byte_data(i2c_fd, Z_LSB_REG);
            if (ret < 0) {
                perror("Failed to read Z_LSB_REG");
                close(i2c_fd);
                fclose(fall_log_file);
                return 1;
            }
            z_lsb = ret;

            // Combine MSB and LSB
            x_raw = (x_msb << 8) | x_lsb;
            y_raw = (y_msb << 8) | y_lsb;
            z_raw = (z_msb << 8) | z_lsb;

            // Compute tilt
            tilt_deg = (int16_t)((atan2(y_raw, x_raw) * 180.0) / M_PI);

            // Check for tilt exceeding threshold
            if (tilt_deg > TILT_THRESHOLD) {
                // Append fall log entry
                fprintf(fall_log_file, "%ld,%d,%d,%d\n", time(NULL), x_raw, y_raw, z_raw);
                fflush(fall_log_file);
            }
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    close(i2c_fd);
    fclose(fall_log_file);

    return 0;
}

void signal_handler(int signal) {
    close(i2c_fd);
    fclose(fall_log_file);
    exit(0);
}

