#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define ADXL354B_PARTID 0xE5
#define ADXL354B_RESET 0x00
#define ADXL354B_POWER_CTRL 0x2D
#define ADXL354B_STATUS 0x00
#define ADXL354B_X_DATA 0x08
#define ADXL354B_Y_DATA 0x09
#define ADXL354B_Z_DATA 0x0A

#define SPI_CHANNEL 0
#define SPI_CE0_GPIO 8
#define SPI_SPEED 1000000
#define SPI_MODE 0

#define LOG_FILE "vibration_log.txt"

#define RETRY_COUNT 5

static int spi_fd;
static int log_fd;

static void sigint_handler(int signum)
{
    printf("Caught signal %d, shutting down...\n", signum);
    close(spi_fd);
    close(log_fd);
    exit(0);
}

static void init_spi(void)
{
    spi_fd = pigpio_spi_open(SPI_CHANNEL, SPI_CE0_GPIO, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        printf("Failed to open SPI device: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_log(void)
{
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }
}

static void reset_sensor(void)
{
    uint8_t reset_reg = ADXL354B_RESET;
    uint8_t reset_val = 0x52;
    uint8_t status_reg = ADXL354B_STATUS;
    uint8_t status_val = 0x00;

    pigpio_spi_write(spi_fd, &reset_reg, 1);
    pigpio_spi_write(spi_fd, &reset_val, 1);
    usleep(1000);
    pigpio_spi_write(spi_fd, &status_reg, 1);
    pigpio_spi_read(spi_fd, &status_val, 1);
    while ((status_val & 0x01) == 0) {
        usleep(1000);
        pigpio_spi_write(spi_fd, &status_reg, 1);
        pigpio_spi_read(spi_fd, &status_val, 1);
    }
}

static void verify_sensor(void)
{
    uint8_t partid_reg = ADXL354B_PARTID;
    uint8_t partid_val = 0x00;

    pigpio_spi_write(spi_fd, &partid_reg, 1);
    pigpio_spi_read(spi_fd, &partid_val, 1);
    if (partid_val != ADXL354B_PARTID) {
        printf("Sensor not present or not responding\n");
        exit(1);
    }
}

static void read_acceleration(void)
{
    uint8_t x_reg = ADXL354B_X_DATA;
    uint8_t y_reg = ADXL354B_Y_DATA;
    uint8_t z_reg = ADXL354B_Z_DATA;
    int16_t x_val = 0;
    int16_t y_val = 0;
    int16_t z_val = 0;

    pigpio_spi_write(spi_fd, &x_reg, 1);
    pigpio_spi_read(spi_fd, &x_val, 2);
    pigpio_spi_write(spi_fd, &y_reg, 1);
    pigpio_spi_read(spi_fd, &y_val, 2);
    pigpio_spi_write(spi_fd, &z_reg, 1);
    pigpio_spi_read(spi_fd, &z_val, 2);

    printf("X: %d, Y: %d, Z: %d\n", x_val, y_val, z_val);
}

int main(void)
{
    struct sigaction sa;
    struct timespec ts;

    init_spi();
    init_log();
    reset_sensor();
    verify_sensor();

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        read_acceleration();
        clock_gettime(CLOCK_REALTIME, &ts);
        dprintf(log_fd, "%ld.%ld\n", ts.tv_sec, ts.tv_nsec);
        usleep(100000);
    }

    return 0;
}

