#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 3
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025
#define SAMPLE_RATE 100
#define LOG_FILE "imu_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the driver library
    if (libgpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open the SPI device
    int spi_fd = pigpio_spi_open(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the gyroscope and accelerometer data
        uint8_t addr = 0x00;
        uint8_t dummy = 0x00;
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        if (pigpio_spi_transfer(spi_fd, &addr, &dummy, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Failed to read data from SPI device\n");
            continue;
        }

        // Scale the gyroscope and accelerometer data
        gyro_x *= GYRO_SCALE;
        gyro_y *= GYRO_SCALE;
        gyro_z *= GYRO_SCALE;
        accel_x *= ACCEL_SCALE;
        accel_y *= ACCEL_SCALE;
        accel_z *= ACCEL_SCALE;

        // Get the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write the data to the log file
        fprintf(log_file, "%ld.%ld,%d,%d,%d,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Wait for the next sample
        usleep(10000);
    }

    // Clean up
    pigpio_spi_close(spi_fd);
    fclose(log_file);
    libgpiod_cleanup();

    return 0;
}

