#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_27 27

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct timespec ts;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO_17);
    line2 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line1 || !line2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up lines for input
    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for line 1\n");
        gpiod_line_free(line1);
        gpiod_line_free(line2);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_input(line2, "sensor2");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for line 2\n");
        gpiod_line_free(line1);
        gpiod_line_free(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up bulk read
    struct gpiod_line_bulk bulk;
    bulk.lines = (struct gpiod_line**)malloc(2 * sizeof(struct gpiod_line*));
    bulk.lines[0] = line1;
    bulk.lines[1] = line2;
    bulk.num_lines = 2;
    bulk.consumer = "sensor_reader";

    // Main loop
    while (!stop) {
        // Read lines
        ret = gpiod_line_bulk_read(chip, &bulk);
        if (ret < 0) {
            fprintf(stderr, "Failed to read lines\n");
            break;
        }

        // Print detection status
        printf("Sensor 1: %s\n", bulk.values[0] ? "Obstacle detected" : "Path clear");
        printf("Sensor 2: %s\n", bulk.values[1] ? "Obstacle detected" : "Path clear");

        // Sleep for 100ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpiod_line_bulk_free(chip, &bulk);
    gpiod_line_free(line1);
    gpiod_line_free(line2);
    gpiod_chip_close(chip);

    return 0;
}

