#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_DELAY 100

#define GPIO_CE0 8

#define ADIS16266_ADDRESS 0x48
#define ADIS16266_X_RATE 0x00
#define ADIS16266_Y_RATE 0x02
#define ADIS16266_Z_RATE 0x04

#define SCALE_FACTOR 0.02

int main(void) {
    int spi_fd;
    int gpio_fd;
    int ret;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    float x_rate, y_rate, z_rate;

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Initialize GPIO
    gpio_fd = pigpio_start(NULL, NULL);
    if (gpio_fd < 0) {
        perror("Failed to start pigpio");
        return 1;
    }

    ret = pigpio_gpio_export(gpio_fd, GPIO_CE0);
    if (ret < 0) {
        perror("Failed to export GPIO");
        return 1;
    }

    ret = pigpio_gpio_set_mode(gpio_fd, GPIO_CE0, PI_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO mode");
        return 1;
    }

    // Main loop
    while (1) {
        // Set CE0 low
        ret = pigpio_gpio_write(gpio_fd, GPIO_CE0, PI_LOW);
        if (ret < 0) {
            perror("Failed to set CE0 low");
            return 1;
        }

        // Read X, Y, and Z rates
        tx_buf[0] = ADIS16266_ADDRESS | 0x80;
        tx_buf[1] = ADIS16266_X_RATE;
        tx_buf[2] = ADIS16266_Y_RATE;
        tx_buf[3] = ADIS16266_Z_RATE;

        ret = write(spi_fd, tx_buf, 4);
        if (ret < 0) {
            perror("Failed to write to SPI");
            return 1;
        }

        ret = read(spi_fd, rx_buf, 6);
        if (ret < 0) {
            perror("Failed to read from SPI");
            return 1;
        }

        x_rate = (rx_buf[1] << 8) | rx_buf[0];
        y_rate = (rx_buf[3] << 8) | rx_buf[2];
        z_rate = (rx_buf[5] << 8) | rx_buf[4];

        x_rate *= SCALE_FACTOR;
        y_rate *= SCALE_FACTOR;
        z_rate *= SCALE_FACTOR;

        printf("X: %f Y: %f Z: %f\n", x_rate, y_rate, z_rate);

        // Set CE0 high
        ret = pigpio_gpio_write(gpio_fd, GPIO_CE0, PI_HIGH);
        if (ret < 0) {
            perror("Failed to set CE0 high");
            return 1;
        }

        usleep(SPI_DELAY);
    }

    // Clean up
    close(spi_fd);
    pigpio_stop(gpio_fd);

    return 0;
}

