#include <linux/i2c.h>
#include <libgpiod/libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define I2C_SDA 2
#define I2C_SCL 3

#define ACCEL_X_OFFSET 0
#define ACCEL_Y_OFFSET 2
#define ACCEL_Z_OFFSET 4
#define MAG_X_OFFSET 6
#define MAG_Y_OFFSET 8
#define MAG_Z_OFFSET 10

#define ACCEL_X_MASK 0x0FFF
#define ACCEL_Y_MASK 0x0FFF
#define ACCEL_Z_MASK 0x0FFF
#define MAG_X_MASK 0xFFFF
#define MAG_Y_MASK 0xFFFF
#define MAG_Z_MASK 0xFFFF

#define ACCEL_X_SHIFT 4
#define ACCEL_Y_SHIFT 4
#define ACCEL_Z_SHIFT 4
#define MAG_X_SHIFT 4
#define MAG_Y_SHIFT 4
#define MAG_Z_SHIFT 4

#define ACCEL_X_SCALE 0.00006103515625
#define ACCEL_Y_SCALE 0.00006103515625
#define ACCEL_Z_SCALE 0.00006103515625
#define MAG_X_SCALE 0.000000152587890625
#define MAG_Y_SCALE 0.000000152587890625
#define MAG_Z_SCALE 0.000000152587890625

#define I2C_RETRY_COUNT 5

int i2c_fd;
int i2c_addr;

void cleanup(void) {
    close(i2c_fd);
    libgpiod_release(i2c_addr);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main(void) {
    // Initialize the I2C bus
    i2c_fd = libgpiod_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("libgpiod_open");
        exit(1);
    }

    // Initialize the I2C address
    i2c_addr = libgpiod_get_addr(i2c_fd);
    if (i2c_addr < 0) {
        perror("libgpiod_get_addr");
        exit(1);
    }

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Read the identification register
    uint8_t id_reg;
    if (libgpiod_read(i2c_fd, i2c_addr, 0x00, &id_reg, 1) != 1) {
        perror("libgpiod_read");
        exit(1);
    }

    // Check the identification register
    if (id_reg != 0xC7) {
        fprintf(stderr, "Invalid identification register value: 0x%02X\n", id_reg);
        exit(1);
    }

    // Initialize the sensor
    uint8_t init_reg = 0x01;
    if (libgpiod_write(i2c_fd, i2c_addr, 0x0A, &init_reg, 1) != 1) {
        perror("libgpiod_write");
        exit(1);
    }

    // Enter the main loop
    while (1) {
        // Read the combined block
        uint8_t block[12];
        if (libgpiod_read(i2c_fd, i2c_addr, 0x00, block, 12) != 12) {
            perror("libgpiod_read");
            exit(1);
        }

        // Extract the accelerometer data
        int16_t accel_x = (block[ACCEL_X_OFFSET] << ACCEL_X_SHIFT) | (block[ACCEL_X_OFFSET + 1] >> ACCEL_X_SHIFT);
        int16_t accel_y = (block[ACCEL_Y_OFFSET] << ACCEL_Y_SHIFT) | (block[ACCEL_Y_OFFSET + 1] >> ACCEL_Y_SHIFT);
        int16_t accel_z = (block[ACCEL_Z_OFFSET] << ACCEL_Z_SHIFT) | (block[ACCEL_Z_OFFSET + 1] >> ACCEL_Z_SHIFT);

        // Extract the magnetometer data
        int16_t mag_x = (block[MAG_X_OFFSET] << MAG_X_SHIFT) | (block[MAG_X_OFFSET + 1] >> MAG_X_SHIFT);
        int16_t mag_y = (block[MAG_Y_OFFSET] << MAG_Y_SHIFT) | (block[MAG_Y_OFFSET + 1] >> MAG_Y_SHIFT);
        int16_t mag_z = (block[MAG_Z_OFFSET] << MAG_Z_SHIFT) | (block[MAG_Z_OFFSET + 1] >> MAG_Z_SHIFT);

        // Print the data
        printf("Accelerometer: X = %f, Y = %f, Z = %f\n", accel_x * ACCEL_X_SCALE, accel_y * ACCEL_Y_SCALE, accel_z * ACCEL_Z_SCALE);
        printf("Magnetometer: X = %f, Y = %f, Z = %f\n", mag_x * MAG_X_SCALE, mag_y * MAG_Y_SCALE, mag_z * MAG_Z_SCALE);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

