#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define I2C_ADDR 0x53
#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define TILT_THRESHOLD 30.0
#define SAMPLE_PERIOD 100

int main(int argc, char **argv) {
  // Initialize I2C bus
  int i2c_fd = open(I2C_DEVICE, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Initialize ADXL345 accelerometer
  uint8_t reg_addr = 0x00;
  uint8_t reg_data = 0x00;
  if (i2c_smbus_write_byte_data(i2c_fd, I2C_ADDR, reg_addr, reg_data) < 0) {
    perror("Failed to initialize ADXL345 accelerometer");
    return 1;
  }

  // Set up signal handler for Ctrl+C interrupt
  struct sigaction sigint_handler;
  sigint_handler.sa_handler = sigint_handler_func;
  sigint_handler.sa_flags = 0;
  sigemptyset(&sigint_handler.sa_mask);
  sigaction(SIGINT, &sigint_handler, NULL);

  // Main loop
  while (1) {
    // Read acceleration data from ADXL345
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, I2C_ADDR, 6, data) < 0) {
      perror("Failed to read acceleration data from ADXL345");
      return 1;
    }

    // Calculate tilt angle
    float x = (data[0] << 8) | data[1];
    float y = (data[2] << 8) | data[3];
    float z = (data[4] << 8) | data[5];
    float tilt_angle = atan2(y, x) * 180 / M_PI;

    // Check if tilt angle exceeds threshold
    if (tilt_angle > TILT_THRESHOLD) {
      // Write timestamped entry to log file
      time_t now = time(NULL);
      struct tm *tm = localtime(&now);
      char timestamp[20];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
      char log_entry[100];
      snprintf(log_entry, sizeof(log_entry), "%s: Tilt angle exceeded threshold (%f degrees)", timestamp, tilt_angle);
      int log_fd = open("/var/log/tilt_events.log", O_WRONLY | O_APPEND | O_CREAT, 0644);
      if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
      }
      write(log_fd, log_entry, strlen(log_entry));
      close(log_fd);
    }

    // Sleep for sampling period
    usleep(SAMPLE_PERIOD * 1000);
  }

  // Clean up resources
  close(i2c_fd);
  return 0;
}

void sigint_handler_func(int signum) {
  // Clean up resources
  close(i2c_fd);
  exit(0);
}

