#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL 1
#define WINDOW_SIZE 5
#define THRESHOLD 10

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", argv[1]);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(GPIO_PIN);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "sound_sensor") != 0) {
        fprintf(stderr, "Failed to request input\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        int count = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (clock_gettime(CLOCK_MONOTONIC, &end) < start.tv_sec + WINDOW_SIZE) {
            int value = gpiod_line_get_value(line);
            if (value == 1) {
                count++;
            }
            usleep(SAMPLE_INTERVAL * 1000);
        }

        if (count > threshold) {
            printf("ALERT\n");
        } else {
            printf("Status: %d\n", count);
        }

        usleep(1000000);
    }

    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

