#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define BH1750FVI_ADDR 0x23
#define BH1750FVI_CONV_TIME 180
#define BH1750FVI_CONV_HIGH 0x10
#define BH1750FVI_CONV_LOW 0x11
#define BH1750FVI_ONE_TIME_HIGH 0x20
#define BH1750FVI_ONE_TIME_LOW 0x21
#define BH1750FVI_POWER_DOWN 0x00

#define I2C_BUS 1
#define I2C_DEV "/dev/i2c-1"

int main(void) {
    int fd;
    uint8_t buf[2];
    uint16_t lux;
    struct timespec ts;
    FILE *fp;

    // Open I2C bus
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, BH1750FVI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    if ((fp = fopen("light_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set conversion time
    buf[0] = BH1750FVI_CONV_TIME;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to set conversion time");
        close(fd);
        fclose(fp);
        return 1;
    }

    // Start conversion
    buf[0] = BH1750FVI_CONV_HIGH;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to start conversion");
        close(fd);
        fclose(fp);
        return 1;
    }

    // Wait for conversion to complete
    usleep(BH1750FVI_CONV_TIME * 1000);

    // Read lux value
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read lux value");
        close(fd);
        fclose(fp);
        return 1;
    }

    // Convert lux value to integer
    lux = (buf[0] << 8) | buf[1];

    // Print lux value to log file
    fprintf(fp, "Timestamp: %ld, Lux: %d\n", time(NULL), lux);

    // Close log file
    fclose(fp);

    // Close I2C bus
    close(fd);

    return 0;
}

