#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <mpr121.h>

#define PWM_PIN 18
#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define SAMPLE_RATE 20
#define FREQUENCY_LOG "frequency_log.txt"
#define SECRET_KEY "MySecretKey"

int main(int argc, char *argv[]) {
    // Initialize the MPR121 driver
    if (mpr121_init(I2C_BUS, I2C_ADDR) != 0) {
        fprintf(stderr, "Failed to initialize MPR121 driver\n");
        return 1;
    }

    // Initialize the PWM output
    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM output\n");
        return 1;
    }

    // Set up the PWM output
    pigpio_set_mode(PWM_PIN, PI_OUTPUT);
    pigpio_set_PWM_frequency(PWM_PIN, 1000);

    // Set up the I2C interface
    if (i2c_init(I2C_BUS) != 0) {
        fprintf(stderr, "Failed to initialize I2C interface\n");
        return 1;
    }

    // Set up the TCP server
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create socket\n");
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        return 1;
    }

    if (listen(sock, 1) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Accept a new connection
        int client_sock = accept(sock, NULL, NULL);
        if (client_sock < 0) {
            fprintf(stderr, "Failed to accept connection\n");
            continue;
        }

        // Read the TCP message
        char buffer[1024];
        int bytes_read = read(client_sock, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            fprintf(stderr, "Failed to read TCP message\n");
            close(client_sock);
            continue;
        }

        // Check if the message is authenticated
        if (strncmp(buffer, "MOTION_DETECTED:", 15) != 0 || strcmp(buffer + 15, SECRET_KEY) != 0) {
            fprintf(stderr, "Invalid authentication\n");
            close(client_sock);
            continue;
        }

        // Play the PWM tone
        pigpio_set_PWM_dutycycle(PWM_PIN, 5000);
        usleep(5000000);
        pigpio_set_PWM_dutycycle(PWM_PIN, 0);

        // Sample the touch values
        int touch_values[12];
        for (int i = 0; i < 12; i++) {
            touch_values[i] = mpr121_get_touch_value(i);
        }

        // Log the played frequency
        FILE *f = fopen(FREQUENCY_LOG, "a");
        if (f == NULL) {
            fprintf(stderr, "Failed to open frequency log file\n");
            close(client_sock);
            continue;
        }
        fprintf(f, "%d\n", touch_values[0]);
        fclose(f);

        // Close the connection
        close(client_sock);
    }

    // Clean up
    pigpio_set_PWM_dutycycle(PWM_PIN, 0);
    pigpio_close();
    i2c_close(I2C_BUS);
    mpr121_close();

    return 0;
}

void sigint_handler(int signum) {
    // Stop the PWM output
    pigpio_set_PWM_dutycycle(PWM_PIN, 0);

    // Close the I2C interface
    i2c_close(I2C_BUS);

    // Close the MPR121 driver
    mpr121_close();

    // Terminate the program
    exit(0);
}

void sigterm_handler(int signum) {
    // Stop the PWM output
    pigpio_set_PWM_dutycycle(PWM_PIN, 0);

    // Close the I2C interface
    i2c_close(I2C_BUS);

    // Close the MPR121 driver
    mpr121_close();

    // Terminate the program
    exit(0);
}

