#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>
#include <linux/pwm.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define MAG_REG 0x03
#define MAG_LEN 6
#define GPIO_PIN 17
#define PWM_FREQ 1000
#define PWM_DUTY 100

int i2c_fd;
int gpio_fd;
int pwm_fd;

void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    close(gpio_fd);
    close(pwm_fd);
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Open GPIO pin
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO pin");
        close(i2c_fd);
        exit(1);
    }

    // Set GPIO pin direction
    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_PIN, GPIO_OUT) < 0) {
        perror("Failed to set GPIO pin direction");
        close(i2c_fd);
        close(gpio_fd);
        exit(1);
    }

    // Open PWM device
    pwm_fd = open("/dev/pwm0", O_RDWR);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        close(i2c_fd);
        close(gpio_fd);
        exit(1);
    }

    // Set PWM frequency and duty cycle
    if (ioctl(pwm_fd, PWM_SET_FREQ, PWM_FREQ) < 0) {
        perror("Failed to set PWM frequency");
        close(i2c_fd);
        close(gpio_fd);
        close(pwm_fd);
        exit(1);
    }
    if (ioctl(pwm_fd, PWM_SET_DUTY, PWM_DUTY) < 0) {
        perror("Failed to set PWM duty cycle");
        close(i2c_fd);
        close(gpio_fd);
        close(pwm_fd);
        exit(1);
    }

    // Enable PWM
    if (ioctl(pwm_fd, PWM_ENABLE, 1) < 0) {
        perror("Failed to enable PWM");
        close(i2c_fd);
        close(gpio_fd);
        close(pwm_fd);
        exit(1);
    }

    // Read data from magnetometer
    uint8_t data[MAG_LEN];
    if (read(i2c_fd, data, MAG_LEN) != MAG_LEN) {
        perror("Failed to read data from magnetometer");
        close(i2c_fd);
        close(gpio_fd);
        close(pwm_fd);
        exit(1);
    }

    // Extract Z-axis field magnitude
    int16_t z_axis = (data[1] << 8) | data[0];

    // Set PWM duty cycle based on Z-axis field magnitude
    if (ioctl(pwm_fd, PWM_SET_DUTY, z_axis) < 0) {
        perror("Failed to set PWM duty cycle");
        close(i2c_fd);
        close(gpio_fd);
        close(pwm_fd);
        exit(1);
    }

    // Close all resources
    close(i2c_fd);
    close(gpio_fd);
    close(pwm_fd);

    return 0;
}

