        x_raw_offset_avg = (x_raw_offset_avg * (SAMPLE_COUNT - 1) + x_raw_offset) / SAMPLE_COUNT;
        y_raw_offset_avg = (y_raw_offset_avg * (SAMPLE_COUNT - 1) + y_raw_offset) / SAMPLE_COUNT;
        z_raw_offset_avg = (z_raw_offset_avg * (SAMPLE_COUNT - 1) + z_raw_offset) / SAMPLE_COUNT;

        // Apply offsets to offset-corrected data
        x_raw_offset_corrected = x_raw_offset - x_offset;
        y_raw_offset_corrected = y_raw_offset - y_offset;
        z_raw_offset_corrected = z_raw_offset - z_offset;

        // Compute running average of last 100 offset-corrected samples
        x_raw_offset_avg_corrected = (x_raw_offset_avg_corrected * (SAMPLE_COUNT - 1) + x_raw_offset_corrected) / SAMPLE_COUNT;
        y_raw_offset_avg_corrected = (y_raw_offset_avg_corrected * (SAMPLE_COUNT - 1) + y_raw_offset_corrected) / SAMPLE_COUNT;
        z_raw_offset_avg_corrected = (z_raw_offset_avg_corrected * (SAMPLE_COUNT - 1) + z_raw_offset_corrected) / SAMPLE_COUNT;

        // Print offset-corrected X, Y, and Z components
        printf("X: %d\n", x_raw_offset_avg_corrected);
        printf("Y: %d\n", y_raw_offset_avg_corrected);
        printf("Z: %d\n", z_raw_offset_avg_corrected);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    hmc5883l_close();
    pi_close();

    return 0;
}

