#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define LSM303D_I2C_ADDR 0x1D
#define LSM303D_REG_WHO_AM_I 0x0F
#define LSM303D_REG_CTRL_REG1 0x20
#define LSM303D_REG_CTRL_REG2 0x21
#define LSM303D_REG_CTRL_REG3 0x22
#define LSM303D_REG_CTRL_REG4 0x23
#define LSM303D_REG_CTRL_REG5 0x24
#define LSM303D_REG_INT_CFG 0x30
#define LSM303D_REG_INT_SRC 0x31
#define LSM303D_REG_INT_THS 0x32
#define LSM303D_REG_STATUS_REG 0x33
#define LSM303D_REG_OUT_X_L 0x28
#define LSM303D_REG_OUT_X_H 0x29
#define LSM303D_REG_OUT_Y_L 0x2A
#define LSM303D_REG_OUT_Y_H 0x2B
#define LSM303D_REG_OUT_Z_L 0x2C
#define LSM303D_REG_OUT_Z_H 0x2D

#define LSM303D_WHO_AM_I 0x40
#define LSM303D_CTRL_REG1_DEFAULT 0x57
#define LSM303D_CTRL_REG2_DEFAULT 0x00
#define LSM303D_CTRL_REG3_DEFAULT 0x00
#define LSM303D_CTRL_REG4_DEFAULT 0x00
#define LSM303D_CTRL_REG5_DEFAULT 0x00
#define LSM303D_INT_CFG_DEFAULT 0x00
#define LSM303D_INT_SRC_DEFAULT 0x00
#define LSM303D_INT_THS_DEFAULT 0x00
#define LSM303D_STATUS_REG_DEFAULT 0x00

#define LSM303D_SENSITIVITY 0.061
#define LSM303D_INT_THRESHOLD 2000

#define LSM303D_BUFFER_SIZE 64

struct lsm303d_sample {
    int16_t x;
    int16_t y;
    int16_t z;
};

struct lsm303d_buffer {
    struct lsm303d_sample samples[LSM303D_BUFFER_SIZE];
    int head;
    int tail;
};

int lsm303d_init(int fd) {
    uint8_t reg_val;

    // Check device identity
    if (ioctl(fd, I2C_SLAVE, LSM303D_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return -1;
    }

    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read device identity register\n");
        return -1;
    }

    if (reg_val != LSM303D_WHO_AM_I) {
        fprintf(stderr, "Invalid device identity: 0x%02X\n", reg_val);
        return -1;
    }

    // Configure control registers
    if (write(fd, LSM303D_REG_CTRL_REG1, LSM303D_CTRL_REG1_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 1\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_CTRL_REG2, LSM303D_CTRL_REG2_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 2\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_CTRL_REG3, LSM303D_CTRL_REG3_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 3\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_CTRL_REG4, LSM303D_CTRL_REG4_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 4\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_CTRL_REG5, LSM303D_CTRL_REG5_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 5\n");
        return -1;
    }

    // Configure interrupt registers
    if (write(fd, LSM303D_REG_INT_CFG, LSM303D_INT_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt configuration register\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_INT_SRC, LSM303D_INT_SRC_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt source register\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_INT_THS, LSM303D_INT_THS_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt threshold register\n");
        return -1;
    }

    // Configure status register
    if (write(fd, LSM303D_REG_STATUS_REG, LSM303D_STATUS_REG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to status register\n");
        return -1;
    }

    return 0;
}

int lsm303d_read_sample(int fd, struct lsm303d_sample *sample) {
    uint8_t reg_val;

    // Read X axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read X axis\n");
        return -1;
    }

    sample->x = (int16_t)reg_val;

    // Read Y axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read Y axis\n");
        return -1;
    }

    sample->y = (int16_t)reg_val;

    // Read Z axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read Z axis\n");
        return -1;
    }

    sample->z = (int16_t)reg_val;

    return 0;
}

int lsm303d_read_buffer(int fd, struct lsm303d_buffer *buffer) {
    struct lsm303d_sample sample;

    // Read sample
    if (lsm303d_read_sample(fd, &sample) < 0) {
        fprintf(stderr, "Failed to read sample\n");
        return -1;
    }

    // Add sample to buffer
    buffer->samples[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % LSM303D_BUFFER_SIZE;

    return 0;
}

int lsm303d_dump_buffer(struct lsm303d_buffer *buffer) {
    struct lsm303d_sample sample;
    int i;

    // Dump last ten samples
    for (i = 0; i < 10; i++) {
        sample = buffer->samples[(buffer->head - i - 1) % LSM303D_BUFFER_SIZE];
        printf("%d %d %d\n", sample.x, sample.y, sample.z);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int fd;
    struct lsm303d_buffer buffer;
    struct timespec ts;
    int i;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    // Initialize LSM303D
    if (lsm303d_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303D\n");
        return -1;
    }

    // Initialize buffer
    buffer.head = 0;
    buffer.tail = 0;

    // Main loop
    while (1) {
        // Read sample
        if (lsm303d_read_buffer(fd, &buffer) < 0) {
            fprintf(stderr, "Failed to read sample\n");
            return -1;
        }

        // Dump buffer
        if (lsm303d_dump_buffer(&buffer) < 0) {
            fprintf(stderr, "Failed to dump buffer\n");
            return -1;
        }

        // Sleep for 10 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000;
        nanosleep(&ts, NULL);
    }

    // Close I2C device
    close(fd);

    return 0;
}

