        return -1;
    }

    if (write(fd, LSM303D_REG_CTRL_REG5, LSM303D_CTRL_REG5_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to control register 5\n");
        return -1;
    }

    // Configure interrupt registers
    if (write(fd, LSM303D_REG_INT_CFG, LSM303D_INT_CFG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt configuration register\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_INT_SRC, LSM303D_INT_SRC_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt source register\n");
        return -1;
    }

    if (write(fd, LSM303D_REG_INT_THS, LSM303D_INT_THS_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to interrupt threshold register\n");
        return -1;
    }

    // Configure status register
    if (write(fd, LSM303D_REG_STATUS_REG, LSM303D_STATUS_REG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to write to status register\n");
        return -1;
    }

    return 0;
}

int lsm303d_read_sample(int fd, struct lsm303d_sample *sample) {
    uint8_t reg_val;

    // Read X axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read X axis\n");
        return -1;
    }

    sample->x = (int16_t)reg_val;

    // Read Y axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read Y axis\n");
        return -1;
    }

    sample->y = (int16_t)reg_val;

    // Read Z axis
    if (read(fd, &reg_val, 1) < 0) {
        fprintf(stderr, "Failed to read Z axis\n");
        return -1;
    }

    sample->z = (int16_t)reg_val;

    return 0;
}

int lsm303d_read_buffer(int fd, struct lsm303d_buffer *buffer) {
    struct lsm303d_sample sample;

    // Read sample
    if (lsm303d_read_sample(fd, &sample) < 0) {
        fprintf(stderr, "Failed to read sample\n");
        return -1;
    }

    // Add sample to buffer
    buffer->samples[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % LSM303D_BUFFER_SIZE;

    return 0;
}

int lsm303d_dump_buffer(struct lsm303d_buffer *buffer) {
    struct lsm303d_sample sample;
    int i;

    // Dump last ten samples
    for (i = 0; i < 10; i++) {
        sample = buffer->samples[(buffer->head - i - 1) % LSM303D_BUFFER_SIZE];
        printf("%d %d %d\n", sample.x, sample.y, sample.z);
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int fd;
    struct lsm303d_buffer buffer;
    struct timespec ts;
    int i;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return -1;
    }

    // Initialize LSM303D
    if (lsm303d_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303D\n");
        return -1;
    }

    // Initialize buffer
    buffer.head = 0;
    buffer.tail = 0;

    // Main loop
    while (1) {
        // Read sample
        if (lsm303d_read_buffer(fd, &buffer) < 0) {
            fprintf(stderr, "Failed to read sample\n");
            return -1;
        }

        // Dump buffer
        if (lsm303d_dump_buffer(&buffer) < 0) {
            fprintf(stderr, "Failed to dump buffer\n");
            return -1;
        }

        // Sleep for 10 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000;
        nanosleep(&ts, NULL);
    }

    // Close I2C device
    close(fd);

    return 0;
}
