    gpio_write(GPIO_SOLENOID_1, 0);
    gpio_write(GPIO_SOLENOID_2, 0);
    gpio_close(GPIO_SOLENOID_1);
    gpio_close(GPIO_SOLENOID_2);
    exit(0);
}

