    int gpio_solenoid_1, gpio_solenoid_2;

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize GPIO pins
    gpio_solenoid_1 = gpio_open(GPIO_SOLENOID_1, GPIO_OUTPUT);
    gpio_solenoid_2 = gpio_open(GPIO_SOLENOID_2, GPIO_OUTPUT);

    // Set both lines LOW to avoid any initial solenoid activation
    gpio_write(gpio_solenoid_1, 0);
    gpio_write(gpio_solenoid_2, 0);

