#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define BUF_SIZE 6
#define TIMEOUT 5
#define RELAY_1 17
#define RELAY_2 27
#define EXPECTED_CODE "123456"

static int gpio_fd;
static int uart_fd[2];
static struct gpiod_line *relay_1, *relay_2;

static void cleanup(void) {
    gpiod_line_release(relay_1);
    gpiod_line_release(relay_2);
    close(uart_fd[0]);
    close(uart_fd[1]);
    gpiod_chip_close(gpio_fd);
}

static void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

static void sigterm_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

int main(void) {
    // Initialize the GPIO chip
    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the relay lines
    relay_1 = gpiod_line_request(gpio_fd, RELAY_1, "relay_1", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    relay_2 = gpiod_line_request(gpio_fd, RELAY_2, "relay_2", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (!relay_1 || !relay_2) {
        fprintf(stderr, "Failed to request relay lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Open the UART ports
    uart_fd[0] = open("/dev/serial0", O_RDONLY | O_NONBLOCK);
    uart_fd[1] = open("/dev/serial1", O_RDONLY | O_NONBLOCK);
    if (uart_fd[0] < 0 || uart_fd[1] < 0) {
        fprintf(stderr, "Failed to open UART ports: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read from both UART ports
        char buf[BUF_SIZE];
        int nread = read(uart_fd[0], buf, BUF_SIZE);
        if (nread < 0) {
            fprintf(stderr, "Failed to read from UART port 0: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        nread = read(uart_fd[1], buf, BUF_SIZE);
        if (nread < 0) {
            fprintf(stderr, "Failed to read from UART port 1: %s\n", strerror(errno));
            cleanup();
            return 1;
        }

        // Check if both codes match
        if (strncmp(buf, EXPECTED_CODE, BUF_SIZE) == 0) {
            // Both codes match, unlock the door
            gpiod_line_set_value(relay_1, 1);
            gpiod_line_set_value(relay_2, 1);
            usleep(2000000);
            gpiod_line_set_value(relay_1, 0);
            gpiod_line_set_value(relay_2, 0);
        } else {
            // Codes don't match, reset the input buffer
            tcflush(uart_fd[0], TCIFLUSH);
            tcflush(uart_fd[1], TCIFLUSH);
        }
    }

    return 0;
}

