#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL 50
#define FAILSAFE_TIMEOUT 10

static volatile sig_atomic_t running = 1;

void handle_signal(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    // Request the PIR and relay GPIO lines
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!pir_line || !relay_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the PIR line as an input
    if (gpiod_line_request_input(pir_line, "pir") != 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input");
        gpiod_line_free(pir_line);
        gpiod_line_free(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the relay line as an output
    if (gpiod_line_request_output(relay_line, "relay") != 0) {
        syslog(LOG_ERR, "Failed to request relay line as output");
        gpiod_line_free(pir_line);
        gpiod_line_free(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (running) {
        // Read the PIR line
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR line");
            continue;
        }

        // If the PIR line is high, activate the relay
        if (pir_value) {
            // Activate the relay
            if (gpiod_line_set_value(relay_line, 1) != 0) {
                syslog(LOG_ERR, "Failed to activate relay");
                continue;
            }

            // Log the relay on event
            syslog(LOG_INFO, "Relay on");

            // Wait for the relay to be deactivated
            sleep(1);

            // Deactivate the relay
            if (gpiod_line_set_value(relay_line, 0) != 0) {
                syslog(LOG_ERR, "Failed to deactivate relay");
                continue;
            }

            // Log the relay off event
            syslog(LOG_INFO, "Relay off");
        }

        // Check for failsafe
        if (pir_value && (time(NULL) - pir_line->last_event) > FAILSAFE_TIMEOUT) {
            // Deactivate the relay
            if (gpiod_line_set_value(relay_line, 0) != 0) {
                syslog(LOG_ERR, "Failed to deactivate relay");
                continue;
            }

            // Log the failsafe event
            syslog(LOG_WARNING, "Failsafe triggered");

            // Log the shutdown event
            syslog(LOG_INFO, "Shutting down");

            // Close the GPIO lines
            gpiod_line_free(pir_line);
            gpiod_line_free(relay_line);

            // Close the GPIO chip
            gpiod_chip_close(chip);

            // Exit
            return 0;
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean shutdown
    gpiod_line_free(pir_line);
    gpiod_line_free(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

