#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define RELAY_CYCLE_TIME 300
#define RELAY_PAUSE_TIME 60

#define SIGINT_SIGTERM_EXIT_CODE 1

static volatile sig_atomic_t sigint_sigterm_flag = 0;

static void sigint_sigterm_handler(int signal) {
    sigint_sigterm_flag = 1;
}

static void init_relays(void) {
    int ret;

    ret = gpiod_init(RELAY_1_PIN, GPIOD_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize relay 1: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_init(RELAY_2_PIN, GPIOD_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize relay 2: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_init(RELAY_3_PIN, GPIOD_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize relay 3: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }

