#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLLING_INTERVAL 100
#define ACTIVATION_DURATION 3000

static bool is_relay_active = false;
static bool is_shutting_down = false;

static void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        is_shutting_down = true;
    }
}

static void activate_relay() {
    if (!is_relay_active) {
        gpio_write(RELAY_PIN, 1);
        is_relay_active = true;
    }
}

static void deactivate_relay() {
    if (is_relay_active) {
        gpio_write(RELAY_PIN, 0);
        is_relay_active = false;
    }
}

static void log_timestamp(const char *message) {
    time_t now = time(NULL);
    struct tm *local = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", local);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

int main(int argc, char **argv) {
    // Initialize the GPIO library
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the sound sensor pin as an input
    if (gpio_set_direction(SOUND_SENSOR_PIN, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to set sound sensor pin as input\n");
        return 1;
    }

    // Set up the relay pin as an output
    if (gpio_set_direction(RELAY_PIN, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the log file
    FILE *log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (!is_shutting_down) {
        // Read the sound sensor pin
        int value = gpio_read(SOUND_SENSOR_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read sound sensor pin\n");
            return 1;
        }

        // If the sound sensor is triggered, activate the relay
        if (value == 1) {
            activate_relay();
            log_timestamp("Sound detected");
        }

        // If the relay is active, wait for the activation duration
        if (is_relay_active) {
            usleep(ACTIVATION_DURATION * 1000);
            deactivate_relay();
            log_timestamp("Relay deactivated");
        }

        // Wait for the polling interval
        usleep(POLLING_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpio_deinit();

    return 0;
}

