#define CO2_ERROR_TIMEOUT 0x02
#define CO2_ERROR_RETRIES 0x03

struct co2_data {
    uint64_t timestamp;
    uint16_t ppm;
    uint8_t error;
};

void co2_log_write(struct co2_data *data) {
    FILE *fp = fopen(CO2_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for writing\n", CO2_LOG_FILE);
        return;
    }

    fprintf(fp, "{\"timestamp\": %llu, \"ppm\": %u, \"error\": %u}\n", data->timestamp, data->ppm, data->error);
    fclose(fp);
}

void co2_error_log(uint8_t error) {
    FILE *fp = fopen(CO2_ERROR_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for writing\n", CO2_ERROR_FILE);
        return;
    }

    fprintf(fp, "{\"timestamp\": %llu, \"error\": %u}\n", get_timestamp(), error);
    fclose(fp);
}

void co2_read_response(int fd, struct co2_data *data) {
    uint8_t resp[CO2_RESP_LEN];
    int ret = read(fd, resp, CO2_RESP_LEN);
    if (ret != CO2_RESP_LEN) {
        co2_error_log(CO2_ERROR_TIMEOUT);
        return;
    }

    if (resp[0] != CO2_RESP_HEADER || resp[1] != CO2_RESP_ID || resp[2] != CO2_RESP_DATA || resp[3] != CO2_RESP_CHECKSUM) {
        co2_error_log(CO2_ERROR_CHECKSUM);
        return;
    }

    data->timestamp = get_timestamp();
    data->ppm = (resp[4] << 8) | resp[5];
    data->error = resp[6];
}

void co2_read_data(int fd, struct co2_data *data) {
    uint8_t cmd[CO2_CMD_LEN] = {CO2_CMD_HEADER, CO2_CMD_ID, CO2_CMD_DATA, CO2_CMD_CHECKSUM};
    int ret = write(fd, cmd, CO2_CMD_LEN);
    if (ret != CO2_CMD_LEN) {
        co2_error_log(CO2_ERROR_TIMEOUT);
        return;
    }

    for (int i = 0; i < CO2_READ_RETRIES; i++) {
        co2_read_response(fd, data);
        if (data->error == 0) {
            break;
        }
        usleep(CO2_READ_TIMEOUT * 1000);
    }
}

void co2_monitor(int fd) {
    struct co2_data data;
    while (1) {
        co2_read_data(fd, &data);
        co2_log_write(&data);
        printf("{\"timestamp\": %llu, \"ppm\": %u, \"error\": %u}\n", data.timestamp, data.ppm, data.error);
        usleep(CO2_READ_INTERVAL * 1000);
    }
}

int main(int argc, char *argv[]) {
    int fd = open(CO2_UART_DEV, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s\n", CO2_UART_DEV);
        return 1;
    }

    struct termios tty;
    tcgetattr(fd, &tty);
    cfsetospeed(&tty, CO2_UART_BAUD);
    cfsetispeed(&tty, CO2_UART_BAUD);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;
    tcsetattr(fd, TCSANOW, &tty);

    gpio_init();
    gpio_set_mode(CO2_UART_TXD, GPIO_MODE_OUTPUT);
    gpio_set_mode(CO2_UART_RXD, GPIO_MODE_INPUT);

    signal(SIGINT, co2_monitor_stop);
    signal(SIGTERM, co2_monitor_stop);

    co2_monitor(fd);

    gpio_cleanup();
    close(fd);

    return 0;
}

