#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void set_gpio_state(int gpio, bool state) {
    if (state) {
        gpio_write(gpio, 1);
    } else {
        gpio_write(gpio, 0);
    }
}

static void read_heading(int fd, float *heading) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        exit(1);
    }
    *heading = (data[0] << 8) | data[1];
}

static void apply_hard_iron_compensation(float *heading, float x_offset, float y_offset) {
    *heading += x_offset;
    *heading -= y_offset;
}

static void store_heading(float *heading, float *buffer, int *buffer_index) {
    buffer[*buffer_index] = *heading;
    *buffer_index = (*buffer_index + 1) % BUFFER_SIZE;
}

static void check_deviation(float *heading, float *buffer, int *buffer_index) {
    float average = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        average += buffer[i];
    }
    average /= BUFFER_SIZE;
    float deviation = *heading - average;
    if (deviation > DEVIATION_THRESHOLD) {
        set_gpio_state(17, true);
    } else {
        set_gpio_state(17, false);
    }
}

int main(int argc, char *argv[]) {
    int fd;
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        exit(1);
    }

    float heading;
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        read_heading(fd, &heading);
        apply_hard_iron_compensation(&heading, 100.0, -50.0);
        store_heading(&heading, buffer, &buffer_index);
        check_deviation(&heading, buffer, &buffer_index);
        usleep(100000);
    }

    close(fd);
    return 0;
}

