#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>
#include <linux/gpio/gpiolib.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_START 0x10
#define BH1750_CMD_READ 0x11
#define BH1750_CMD_STOP 0x13

#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22

#define LIGHT_THRESHOLD_RED 50
#define LIGHT_THRESHOLD_GREEN 150
#define LIGHT_THRESHOLD_BLUE 300

int main(void) {
    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO lines
    int red_fd = open("/dev/gpiochip0", O_RDWR);
    if (red_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    int green_fd = open("/dev/gpiochip0", O_RDWR);
    if (green_fd < 0) {
        perror("Failed to open GPIO chip");
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    int blue_fd = open("/dev/gpiochip0", O_RDWR);
    if (blue_fd < 0) {
        perror("Failed to open GPIO chip");
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO directions
    if (ioctl(red_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(green_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(blue_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO values
    if (ioctl(red_fd, GPIO_SET_VAL, 0) < 0) {
        perror("Failed to set GPIO value");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(green_fd, GPIO_SET_VAL, 0) < 0) {
        perror("Failed to set GPIO value");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(blue_fd, GPIO_SET_VAL, 0) < 0) {
        perror("Failed to set GPIO value");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("lighting_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (true) {
        // Start measurement
        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(log_file);
            close(blue_fd);
            close(green_fd);
            close(red_fd);
            close(i2c_fd);
            return 1;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_CMD_START) < 0) {
            perror("Failed to start measurement");
            close(log_file);
            close(blue_fd);
            close(green_fd);
            close(red_fd);
            close(i2c_fd);
            return 1;
        }

        // Wait for measurement to complete
        usleep(120000);

        // Read measurement
        uint16_t lux;
        if (read(i2c_fd, &lux, sizeof(lux)) < 0) {
            perror("Failed to read measurement");
            close(log_file);
            close(blue_fd);
            close(green_fd);
            close(red_fd);
            close(i2c_fd);
            return 1;
        }

        // Set GPIO values based on lux level
        if (lux < LIGHT_THRESHOLD_RED) {
            if (ioctl(red_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        } else if (lux < LIGHT_THRESHOLD_GREEN) {
            if (ioctl(green_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        } else if (lux < LIGHT_THRESHOLD_BLUE) {
            if (ioctl(blue_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        } else {
            if (ioctl(red_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }

            if (ioctl(green_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }

            if (ioctl(blue_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        }

        // Log measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d, %d lux, %d, %d, %d\n", tm->tm_hour, tm->tm_min, tm->tm_sec, lux, red_fd, green_fd, blue_fd);

        // Wait for next measurement
        sleep(1);
    }

    // Clean up
    close(log_file);
    close(blue_fd);
    close(green_fd);
    close(red_fd);
    close(i2c_fd);

    return 0;
}

