    if (green_fd < 0) {
        perror("Failed to open GPIO chip");
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    int blue_fd = open("/dev/gpiochip0", O_RDWR);
    if (blue_fd < 0) {
        perror("Failed to open GPIO chip");
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO directions
    if (ioctl(red_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(green_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(blue_fd, GPIO_SET_DIR, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO direction");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO values
    if (ioctl(red_fd, GPIO_SET_VAL, 0) < 0) {
        perror("Failed to set GPIO value");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(green_fd, GPIO_SET_VAL, 0) < 0) {
        perror("Failed to set GPIO value");
        close(blue_fd);
        close(green_fd);
        close(red_fd);
        close(i2c_fd);
        return 1;
    }

    if (ioctl(blue_fd, GPIO_SET_VAL, 0) < 0) {
