            close(log_file);
            close(blue_fd);
            close(green_fd);
            close(red_fd);
            close(i2c_fd);
            return 1;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_CMD_START) < 0) {
            perror("Failed to start measurement");
            close(log_file);
            close(blue_fd);
            close(green_fd);
            close(red_fd);
            close(i2c_fd);
            return 1;
        }

        // Wait for measurement to complete
        usleep(120000);

        // Read measurement
