        } else if (lux < LIGHT_THRESHOLD_GREEN) {
            if (ioctl(green_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        } else if (lux < LIGHT_THRESHOLD_BLUE) {
            if (ioctl(blue_fd, GPIO_SET_VAL, 1) < 0) {
