                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }

            if (ioctl(green_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }

            if (ioctl(blue_fd, GPIO_SET_VAL, 1) < 0) {
                perror("Failed to set GPIO value");
                close(log_file);
                close(blue_fd);
                close(green_fd);
                close(red_fd);
                close(i2c_fd);
                return 1;
            }
        }

        // Log measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d, %d lux, %d, %d, %d\n", tm->tm_hour, tm->tm_min, tm->tm_sec, lux, red_fd, green_fd, blue_fd);

        // Wait for next measurement
        sleep(1);
    }

    // Clean up
    close(log_file);
    close(blue_fd);
    close(green_fd);
    close(red_fd);
    close(i2c_fd);

    return 0;
}
