      // Drive forward
      gpioWrite(MOTOR_A_IN1, 1);
      gpioWrite(MOTOR_A_IN2, 0);
      gpioPWM(MOTOR_A_IN2, PWM_RANGE * (motor_a_distance / 100.0));
    } else {
      // Drive backward
      gpioWrite(MOTOR_A_IN1, 0);
      gpioWrite(MOTOR_A_IN2, 1);
      gpioPWM(MOTOR_A_IN2, PWM_RANGE * (motor_a_distance / 100.0));
    }

    if (motor_b_distance < DISTANCE_THRESHOLD) {
      // Drive forward
      gpioWrite(MOTOR_B_IN3, 1);
      gpioWrite(MOTOR_B_IN4, 0);
      gpioPWM(MOTOR_B_IN4, PWM_RANGE * (motor_b_distance / 100.0));
    } else {
      // Drive backward
      gpioWrite(MOTOR_B_IN3, 0);
      gpioWrite(MOTOR_B_IN4, 1);
      gpioPWM(MOTOR_B_IN4, PWM_RANGE * (motor_b_distance / 100.0));
    }

    // Sleep for 100 ms
    usleep(100000);
  }

  // Clean up on exit
  gpioTerminate();

  return 0;
}

// Signal handler
void signal_handler(int signal) {
  // Stop the motors
  gpioWrite(MOTOR_A_IN1, 0);
  gpioWrite(MOTOR_A_IN2, 0);
  gpioWrite(MOTOR_B_IN3, 0);
  gpioWrite(MOTOR_B_IN4, 0);

  // Clean up
  gpioTerminate();

  exit(0);
}

// Read the distance value
int read_distance(int pin) {
  // Read the distance value
  int distance = 0;
  if (gpioRead(pin) < 0) {
    fprintf(stderr, "Failed to read distance value\n");
    return -1;
  }

  // Convert the distance value to cm
  distance = (distance * 100) / 255;

  return distance;
}

