#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define TRIG_PULSE_US 10
#define MIN_MEASUREMENT_GAP_MS 60
#define BUZZER_FREQ_MIN 200
#define BUZZER_FREQ_MAX 2000

#define TIMEOUT_US 10000

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        exit(1);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        exit(1);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        exit(1);
    }
}

static void deinit_gpio(void) {
    gpioTerminate();
}

static void set_buzzer_freq(uint16_t freq) {
    if (freq < BUZZER_FREQ_MIN || freq > BUZZER_FREQ_MAX) {
        return;
    }

    gpioPWM(BUZZER_PIN, freq);
}

static void trigger_echo(void) {
    gpioWrite(TRIG_PIN, PI_HIGH);
    usleep(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, PI_LOW);
}

static uint32_t get_echo_time(void) {
    uint32_t start_time = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            return 0;
        }
    }

    uint32_t end_time = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - end_time > TIMEOUT_US) {
            return 0;
        }
    }

    return end_time - start_time;
}

int main(void) {
    signal(SIGINT, sigint_handler);

    init_gpio();

    set_buzzer_freq(0);

    while (running) {
        trigger_echo();
        uint32_t echo_time = get_echo_time();
        if (echo_time == 0) {
            fprintf(stderr, "Timeout while waiting for echo\n");
            continue;
        }

        uint16_t freq = (echo_time * 1000) / 2;
        set_buzzer_freq(freq);

        usleep(MIN_MEASUREMENT_GAP_MS * 1000);
    }

    set_buzzer_freq(0);

    deinit_gpio();

    return 0;
}

