#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_XOUT_L 0x44
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_YOUT_L 0x46
#define MPU6050_REG_GYRO_ZOUT_H 0x47
#define MPU6050_REG_GYRO_ZOUT_L 0x48

#define GYRO_SAMPLE_RATE 100

int fd;
int gyro_fd;

void sigint_handler(int sig) {
    close(fd);
    close(gyro_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(1);
    }

    gyro_fd = open("gyro_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (gyro_fd < 0) {
        perror("Failed to open gyro log file");
        close(fd);
        exit(1);
    }

    while (1) {
        uint8_t reg_addr = MPU6050_REG_GYRO_XOUT_H;
        uint8_t data[6];
        if (write(fd, &reg_addr, 1) != 1) {
            perror("Failed to write register address");
            close(fd);
            close(gyro_fd);
            exit(1);
        }

        if (read(fd, data, 6) != 6) {
            perror("Failed to read gyro data");
            close(fd);
            close(gyro_fd);
            exit(1);
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        char buf[100];
        snprintf(buf, sizeof(buf), "%ld %d %d %d\n", time(NULL), x, y, z);
        if (write(gyro_fd, buf, strlen(buf)) != strlen(buf)) {
            perror("Failed to write to gyro log file");
            close(fd);
            close(gyro_fd);
            exit(1);
        }

        usleep(GYRO_SAMPLE_RATE * 1000);
    }

    close(fd);
    close(gyro_fd);
    return 0;
}

