    if (pigpio_gpio_set_isr(BUTTON_PIN, button_isr) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", BUTTON_PIN);
        return 1;
    }

    while (true) {
        if (button_pressed) {
            play_melody();
            button_pressed = false;
        }
