volatile bool button_pressed = false;

void button_isr(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        button_pressed = true;
    }
}

void play_melody() {
    for (int i = 0; i < MEL_LENGTH; i++) {
        pigpio_gpio_write(BUZZER_PIN, 1);
        usleep(melody[i][1] * 1000);
        pigpio_gpio_write(BUZZER_PIN, 0);
        usleep(melody[i][1] * 1000);
    }
}

void cleanup() {
    pigpio_gpio_write(BUZZER_PIN, 0);
    pigpio_gpio_close(BUZZER_PIN);
    pigpio_gpio_close(BUTTON_PIN);
    pigpio_close();
}

int main() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (pigpio_gpio_open(BUTTON_PIN, PI_INPUT, PI_PULL_UP) < 0) {
        fprintf(stderr, "Failed to open GPIO %d for input\n", BUTTON_PIN);
        return 1;
    }

    if (pigpio_gpio_open(BUZZER_PIN, PI_OUTPUT, PI_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to open GPIO %d for output\n", BUZZER_PIN);
        return 1;
    }

    if (pigpio_gpio_set_glitch_filter(BUTTON_PIN, DEBOUNCE_TIME) < 0) {
        fprintf(stderr, "Failed to set glitch filter on GPIO %d\n", BUTTON_PIN);
        return 1;
    }

    if (pigpio_gpio_set_isr(BUTTON_PIN, button_isr) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", BUTTON_PIN);
        return 1;
    }

    while (true) {
        if (button_pressed) {
            play_melody();
            button_pressed = false;
        }
    }

    cleanup();
    return 0;
}
```
This program uses the `pigpio` library to interact with the GPIO pins on the Raspberry Pi. It sets up the button pin as an input with a pull-up resistor, and the buzzer pin as an output with a pull-down resistor. It also sets up a glitch filter on the button pin to debounce the signal.

The `button_isr` function is called whenever the button pin changes state. It sets the `button_pressed` flag to `true` if the button is pressed.

The `play_melody` function plays the stored melody through the buzzer pin using the `pigpio_gpio_write` function.

The `cleanup` function is called when the program exits to release the resources used by the `pigpio` library.

The `main` function sets up the GPIO pins and sets up the ISR for the button pin. It then enters an infinite loop that checks the `button_pressed` flag and plays the melody if it is set.

This program is designed to be non-blocking, so it will not block the main loop while the melody is playing. It will also handle SIGINT and SIGTERM signals to perform a clean shutdown by stopping the PWM, releasing resources, and calling the `pigpio_close` function.

