#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE 17
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define DEFAULT_POLL_TIMEOUT 1000

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    // Initialize GPIO line
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_input(line, "vibration_sensor");

    // Initialize log file
    FILE *log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: unable to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!sigint_flag) {
        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            break;
        }

        // Log event
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file);

        // Check for earthquake
        static int window[WINDOW_SIZE];
        static int window_index = 0;
        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        int count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (window[i] == 1) {
                count++;
            }
        }
        if (count >= EARTHQUAKE_THRESHOLD) {
            printf("EARTHQUAKE ALERT\n");
        }

        // Sleep for poll timeout
        usleep(poll_timeout * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

