#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_TIME 200

static bool relay_state = false;
static bool touch_state = false;
static bool touch_debounce = false;
static time_t last_touch_time = 0;

static void sigint_handler(int signum) {
    // Force relay off
    gpio_write(RELAY_GPIO, 0);

    // Append final OFF entry to log
    FILE *log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        exit(1);
    }
    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", ctime(&last_touch_time));
    fclose(log_file);

    // Clean up library
    gpiod_cleanup();
    pigpio_cleanup();

    // Exit
    exit(0);
}

static void touch_interrupt(int gpio, int level, uint32_t tick) {
    // Check if touch is valid
    if (level == 1) {
        // Check if debounce time has elapsed
        if (tick - last_touch_time > DEBOUNCE_TIME) {
            // Toggle relay state
            relay_state = !relay_state;
            gpio_write(RELAY_GPIO, relay_state);

            // Log state change
            FILE *log_file = fopen("relay_log.json", "a");
            if (log_file == NULL) {
                perror("Error opening log file");
                exit(1);
            }
            fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", ctime(&last_touch_time), relay_state ? "ON" : "OFF");
            fclose(log_file);

            // Update last touch time
            last_touch_time = tick;
        }
    }
}

int main(void) {
    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Set up GPIO
    gpiod_init();
    pigpio_init();

    // Set up touch sensor
    gpio_set_mode(TOUCH_GPIO, GPIO_INPUT);
    gpio_set_pull(TOUCH_GPIO, GPIO_PULL_DOWN);
    gpio_set_interrupt(TOUCH_GPIO, GPIO_INT_EDGE_RISING, touch_interrupt);

    // Set up relay
    gpio_set_mode(RELAY_GPIO, GPIO_OUTPUT);
    gpio_write(RELAY_GPIO, 0);

    // Main loop
    while (true) {
        // Check for touch
        if (gpio_read(TOUCH_GPIO) == 1) {
            // Check if debounce time has elapsed
            if (gpio_get_tick() - last_touch_time > DEBOUNCE_TIME) {
                // Toggle relay state
                relay_state = !relay_state;
                gpio_write(RELAY_GPIO, relay_state);

                // Log state change
                FILE *log_file = fopen("relay_log.json", "a");
                if (log_file == NULL) {
                    perror("Error opening log file");
                    exit(1);
                }
                fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", ctime(&last_touch_time), relay_state ? "ON" : "OFF");
                fclose(log_file);

                // Update last touch time
                last_touch_time = gpio_get_tick();
            }
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up library
    gpiod_cleanup();
    pigpio_cleanup();

    // Exit
    return 0;
}

