    gpiod_line_set_value(RELAY_2, 1);
    gpiod_line_set_value(RELAY_3, 1);
    gpiod_line_set_value(RELAY_4, 1);
    gpiod_line_release(RELAY_1);
    gpiod_line_release(RELAY_2);
    gpiod_line_release(RELAY_3);
    gpiod_line_release(RELAY_4);
    close(log_fd);
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, deactivating all relays\n");
    gpiod_line_set_value(RELAY_1, 1);
    gpiod_line_set_value(RELAY_2, 1);
    gpiod_line_set_value(RELAY_3, 1);
    gpiod_line_set_value(RELAY_4, 1);
    gpiod_line_release(RELAY_1);
    gpiod_line_release(RELAY_2);
    gpiod_line_release(RELAY_3);
    gpiod_line_release(RELAY_4);
    close(log_fd);
    exit(0);
}

int main() {
    // Initialize the GPIO lines
    gpiod_line_request_output(RELAY_1, "relay1", 0);
    gpiod_line_request_output(RELAY_2, "relay2", 0);
    gpiod_line_request_output(RELAY_3, "relay3", 0);
    gpiod_line_request_output(RELAY_4, "relay4", 0);

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open the log file
    log_fd = open(IRRIGATION_LOG, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        exit(1);
    }

    // Seed the random number generator
    srand(time(NULL));

    while (1) {
        // Get a new moisture reading
        int moisture = rand() % 100;

        // Check if the moisture is below the threshold
        if (moisture < MOISTURE_THRESHOLD) {
            // Activate the relays
            gpiod_line_set_value(RELAY_1, 0);
            gpiod_line_set_value(RELAY_2, 0);
            gpiod_line_set_value(RELAY_3, 0);
            gpiod_line_set_value(RELAY_4, 0);

            // Wait for 5 seconds
            sleep(5);

            // Deactivate the relays
            gpiod_line_set_value(RELAY_1, 1);
            gpiod_line_set_value(RELAY_2, 1);
            gpiod_line_set_value(RELAY_3, 1);
            gpiod_line_set_value(RELAY_4, 1);

            // Write to the log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
            char log_entry[100];
            sprintf(log_entry, "%s, %d, %d\n", timestamp, moisture, RELAY_1);
            write(log_fd, log_entry, strlen(log_entry));
            fflush(log_fd);
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Clean up
    gpiod_line_release(RELAY_1);
    gpiod_line_release(RELAY_2);
    gpiod_line_release(RELAY_3);
    gpiod_line_release(RELAY_4);
    close(log_fd);
    return 0;
}
```
This code uses the `libgpiod` library to control the GPIO lines on the Raspberry Pi. It initializes the GPIO lines as outputs and sets them to the inactive state (high level). It then sets up signal handlers for `SIGINT` and `SIGTERM` to deactivate the relays and release the GPIO lines when the program is interrupted.

The program then enters a loop where it generates a random moisture reading and checks if it is below the threshold. If it is, it activates the relays and waits for 5 seconds before deactivating them. It then writes a log entry to a file with the timestamp, moisture level, and relay number.

The program then waits for 10 seconds before repeating the process.

Finally, the program cleans up by releasing the GPIO lines and closing the log file before exiting.

