#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define STEPS 512
#define DELAY 3

bool lock_pressed = false;
bool unlock_pressed = false;

void handle_lock_button(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        lock_pressed = true;
    }
}

void handle_unlock_button(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        unlock_pressed = true;
    }
}

void handle_sigint(int signal) {
    printf("Received SIGINT, de-energizing coils and exiting\n");
    gpio_write(IN1, 0);
    gpio_write(IN2, 0);
    gpio_write(IN3, 0);
    gpio_write(IN4, 0);
    exit(0);
}

int main(void) {
    int ret;

    // Initialize GPIO
    if ((ret = gpio_init()) < 0) {
        printf("Failed to initialize GPIO: %s\n", gpio_error(ret));
        return 1;
    }

    // Set up GPIO pins
    if ((ret = gpio_set_mode(IN1, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", IN1, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_mode(IN2, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", IN2, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_mode(IN3, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", IN3, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_mode(IN4, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", IN4, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_mode(LOCK_BUTTON, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", LOCK_BUTTON, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_mode(UNLOCK_BUTTON, PI_INPUT)) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", UNLOCK_BUTTON, gpio_error(ret));
        return 1;
    }

    // Set up button interrupts
    if ((ret = gpio_set_ISR(LOCK_BUTTON, handle_lock_button)) < 0) {
        printf("Failed to set GPIO %d ISR: %s\n", LOCK_BUTTON, gpio_error(ret));
        return 1;
    }
    if ((ret = gpio_set_ISR(UNLOCK_BUTTON, handle_unlock_button)) < 0) {
        printf("Failed to set GPIO %d ISR: %s\n", UNLOCK_BUTTON, gpio_error(ret));
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (true) {
        if (lock_pressed) {
            printf("Locking door...\n");
            for (int i = 0; i < STEPS; i++) {
                gpio_write(IN1, 1);
                gpio_write(IN2, 0);
                gpio_write(IN3, 0);
                gpio_write(IN4, 0);
                usleep(DELAY * 1000);
                gpio_write(IN1, 0);
                gpio_write(IN2, 0);
                gpio_write(IN3, 0);
                gpio_write(IN4, 0);
                usleep(DELAY * 1000);
            }
            lock_pressed = false;
        } else if (unlock_pressed) {
            printf("Unlocking door...\n");
            for (int i = 0; i < STEPS; i++) {
                gpio_write(IN1, 0);
                gpio_write(IN2, 1);
                gpio_write(IN3, 0);
                gpio_write(IN4, 0);
                usleep(DELAY * 1000);
                gpio_write(IN1, 0);
                gpio_write(IN2, 0);
                gpio_write(IN3, 0);
                gpio_write(IN4, 0);
                usleep(DELAY * 1000);
            }
            unlock_pressed = false;
        }
    }

    // Clean up
    gpio_write(IN1, 0);
    gpio_write(IN2, 0);
    gpio_write(IN3, 0);
    gpio_write(IN4, 0);
    gpio_close();

    return 0;
}

