#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define RELAY_PIN 18

int main(int argc, char **argv) {
    int i2c_fd, relay_fd;
    struct vl53l1x_dev_s dev;
    struct vl53l1x_measurement_s meas;
    int distance;

    // Initialize the I2C interface
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C interface");
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (vl53l1x_init(&dev, i2c_fd, I2C_ADDR) < 0) {
        perror("Failed to initialize VL53L1X sensor");
        return 1;
    }

    // Initialize the relay pin
    if ((relay_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Set the relay pin as output
    if (gpio_direction_output(relay_fd, RELAY_PIN, 0) < 0) {
        perror("Failed to set relay pin as output");
        return 1;
    }

    // Set the relay pin to low
    if (gpio_set_value(relay_fd, RELAY_PIN, 0) < 0) {
        perror("Failed to set relay pin to low");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Take a measurement
        if (vl53l1x_measure(&dev, &meas) < 0) {
            perror("Failed to take measurement");
            return 1;
        }

        // Get the distance
        distance = meas.distance;

        // Print the distance
        printf("Distance: %d\n", distance);

        // Set the relay pin based on the distance
        if (distance <= 50) {
            if (gpio_set_value(relay_fd, RELAY_PIN, 1) < 0) {
                perror("Failed to set relay pin to high");
                return 1;
            }
        } else {
            if (gpio_set_value(relay_fd, RELAY_PIN, 0) < 0) {
                perror("Failed to set relay pin to low");
                return 1;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    close(relay_fd);
    vl53l1x_cleanup(&dev);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    close(i2c_fd);
    close(relay_fd);
    vl53l1x_cleanup(&dev);

    // Exit
    exit(0);
}

