#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY_1 17
#define RELAY_2 18
#define RELAY_3 27
#define RELAY_4 22

#define RELAY_ON 0
#define RELAY_OFF 1

#define WATERING_LOG "watering_log.txt"

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request all four lines as outputs with active-low semantics
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, RELAY_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, RELAY_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, RELAY_3);
    struct gpiod_line *line4 = gpiod_chip_get_line(chip, RELAY_4);
    if (line1 == NULL || line2 == NULL || line3 == NULL || line4 == NULL) {
        fprintf(stderr, "Error: unable to request GPIO lines\n");
        return 1;
    }

    // Set all lines HIGH (inactive) at startup
    gpiod_line_set_value(line1, RELAY_ON);
    gpiod_line_set_value(line2, RELAY_ON);
    gpiod_line_set_value(line3, RELAY_ON);
    gpiod_line_set_value(line4, RELAY_ON);

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Activate each relay in turn for exactly 5 seconds
        gpiod_line_set_value(line1, RELAY_OFF);
        sleep(5);
        gpiod_line_set_value(line1, RELAY_ON);

        gpiod_line_set_value(line2, RELAY_OFF);
        sleep(5);
        gpiod_line_set_value(line2, RELAY_ON);

        gpiod_line_set_value(line3, RELAY_OFF);
        sleep(5);
        gpiod_line_set_value(line3, RELAY_ON);

        gpiod_line_set_value(line4, RELAY_OFF);
        sleep(5);
        gpiod_line_set_value(line4, RELAY_ON);

        // Log the start time of each full cycle
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        FILE *fp = fopen(WATERING_LOG, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error: unable to open watering log file\n");
            return 1;
        }
        fprintf(fp, "%s\n", time_str);
        fclose(fp);

        // Sleep for 86400 seconds (24 hours)
        sleep(86400);
    }

    // Release all GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_line_release(line4);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

