#define PWM_DUTY_CYCLE_MAX 255

#define LOG_FILE "smart_lighting.log"

static bool g_running = true;
static int g_pwm_fd = -1;
static int g_gpio_fd = -1;

static void sigint_handler(int signum) {
    g_running = false;
}

static void init_gpio() {
    g_gpio_fd = gpio_init();
    if (g_gpio_fd < 0) {
        printf("Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpio_set_mode(g_gpio_fd, GPIO_PIN_17, GPIO_OUTPUT) < 0) {
        printf("Failed to set GPIO mode for pin 17\n");
        exit(1);
    }

    if (gpio_set_mode(g_gpio_fd, GPIO_PIN_18, GPIO_OUTPUT) < 0) {
        printf("Failed to set GPIO mode for pin 18\n");
        exit(1);
    }

    if (gpio_set_mode(g_gpio_fd, GPIO_PIN_27, GPIO_OUTPUT) < 0) {
        printf("Failed to set GPIO mode for pin 27\n");
        exit(1);
    }

    if (gpio_set_mode(g_gpio_fd, GPIO_PIN_22, GPIO_OUTPUT) < 0) {
        printf("Failed to set GPIO mode for pin 22\n");
        exit(1);
    }
}

static void init_pwm() {
    g_pwm_fd = pwm_init(PWM_FREQ, PWM_DUTY_CYCLE_STEP);
    if (g_pwm_fd < 0) {
        printf("Failed to initialize PWM\n");
        exit(1);
    }
}

static void set_pwm_duty_cycle(int duty_cycle) {
    if (pwm_set_duty_cycle(g_pwm_fd, duty_cycle) < 0) {
        printf("Failed to set PWM duty cycle\n");
        exit(1);
    }
}

static void set_gpio_state(int pin, bool state) {
    if (gpio_set_state(g_gpio_fd, pin, state) < 0) {
        printf("Failed to set GPIO state for pin %d\n", pin);
        exit(1);
    }
}

static void log_event(const char *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld %s\n", tv.tv_sec, tv.tv_usec, event);
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        printf("Failed to open log file\n");
        exit(1);
    }
    write(fd, buf, strlen(buf));
    close(fd);
}

int main() {
    signal(SIGINT, sigint_handler);

    init_gpio();
    init_pwm();

    set_pwm_duty_cycle(0);
    set_gpio_state(GPIO_PIN_17, false);
    set_gpio_state(GPIO_PIN_18, false);
    set_gpio_state(GPIO_PIN_27, false);
    set_gpio_state(GPIO_PIN_22, false);

    log_event("Starting smart lighting sunrise effect");

    while (g_running) {
        for (int i = 0; i <= PWM_DUTY_CYCLE_MAX; i += PWM_DUTY_CYCLE_STEP) {
            set_pwm_duty_cycle(i);
            set_gpio_state(GPIO_PIN_17, true);
            set_gpio_state(GPIO_PIN_18, true);
            set_gpio_state(GPIO_PIN_27, true);
            set_gpio_state(GPIO_PIN_22, true);
            sleep(1);
        }

        set_pwm_duty_cycle(0);
        set_gpio_state(GPIO_PIN_17, false);
        set_gpio_state(GPIO_PIN_18, false);
        set_gpio_state(GPIO_PIN_27, false);
        set_gpio_state(GPIO_PIN_22, false);

        sleep(30);
    }

    log_event("Stopping smart lighting sunrise effect");

    pwm_close(g_pwm_fd);
    gpio_close(g_gpio_fd);

    return 0;
}

