#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_BUS "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_ORDER MSBFIRST
#define GPIO_CHIP 0
#define GPIO_LINE 8
#define GPIO_POLARITY ACTIVE_LOW
#define GPIO_VALUE 0
#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL 10
#define RETRY_COUNT 3

int main(void) {
    // Open the SPI device
    int spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set the SPI speed, mode, and bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Set the SPI order
    if (ioctl(spi_fd, SPI_IOC_WR_ORDER, &SPI_ORDER) < 0) {
        perror("Failed to set SPI order");
        close(spi_fd);
        return 1;
    }

    // Open the GPIO line
    int gpio_fd = gpiod_open_chip(GPIO_CHIP);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }
    int gpio_line = gpiod_get_line(gpio_fd, GPIO_LINE);
    if (gpio_line < 0) {
        perror("Failed to get GPIO line");
        gpiod_close_chip(gpio_fd);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line, GPIO_POLARITY, GPIO_VALUE) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_free(gpio_line);
        gpiod_close_chip(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_free(gpio_line);
        gpiod_close_chip(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set the GPIO line to low
    if (gpiod_line_set_value(gpio_line, GPIO_VALUE) < 0) {
        perror("Failed to set GPIO line value");
        fclose(log_file);
        gpiod_line_free(gpio_line);
        gpiod_close_chip(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Read the X, Y, and Z angular rates from the MPU-9250 gyroscope
    uint8_t tx_buf[3] = {0x43, 0x00, 0x00};
    uint8_t rx_buf[3];
    int retries = 0;
    while (1) {
        // Set the GPIO line to high
        if (gpiod_line_set_value(gpio_line, GPIO_VALUE) < 0) {
            perror("Failed to set GPIO line value");
            fclose(log_file);
            gpiod_line_free(gpio_line);
            gpiod_close_chip(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Perform the SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx_buf) < 0) {
            perror("Failed to perform SPI transfer");
            if (retries++ < RETRY_COUNT) {
                continue;
            }
            fclose(log_file);
            gpiod_line_free(gpio_line);
            gpiod_close_chip(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Set the GPIO line to low
        if (gpiod_line_set_value(gpio_line, GPIO_VALUE) < 0) {
            perror("Failed to set GPIO line value");
            fclose(log_file);
            gpiod_line_free(gpio_line);
            gpiod_close_chip(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Read the X, Y, and Z angular rates from the MPU-9250 gyroscope
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &rx_buf) < 0) {
            perror("Failed to read MPU-9250 gyroscope");
            if (retries++ < RETRY_COUNT) {
                continue;
            }
            fclose(log_file);
            gpiod_line_free(gpio_line);
            gpiod_close_chip(gpio_fd);
            close(spi_fd);
            return 1;
        }

        // Write the X, Y, and Z angular rates to the log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%N", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, rx_buf[0], rx_buf[1], rx_buf[2]);

        // Sleep for the specified interval
        usleep(LOG_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_free(gpio_line);
    gpiod_close_chip(gpio_fd);
    close(spi_fd);

    return 0;
}

