#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define GPIO_LED 21

#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

#define ACCEL_SCALE 16384.0
#define GYRO_SCALE 131.0

#define TILT_THRESHOLD 45.0

int main(void) {
    int i2c_fd;
    int gpio_fd;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    float roll, pitch;
    char timestamp[20];
    char tilt_log[100];

    // Initialize the I2C bus
    if ((i2c_fd = pigpio_i2c_open(I2C_BUS, MPU6050_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the GPIO pin for the LED
    if ((gpio_fd = pigpio_gpio_open(GPIO_LED)) < 0) {
        fprintf(stderr, "Failed to open GPIO pin\n");
        return 1;
    }

    // Initialize the sensor
    if (pigpio_i2c_write(i2c_fd, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return 1;
    }

    // Set the sampling rate to 100 Hz
    if (pigpio_i2c_write(i2c_fd, 0x19, 0x0A) < 0) {
        fprintf(stderr, "Failed to set sampling rate\n");
        return 1;
    }

    // Set the LED to off
    pigpio_gpio_write(gpio_fd, 0);

    // Main loop
    while (1) {
        // Read the sensor data
        if (pigpio_i2c_read(i2c_fd, ACCEL_XOUT_H, 6, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            return 1;
        }

        // Compute the roll and pitch
        roll = atan2(accel_y, accel_z) * 180.0 / M_PI;
        pitch = atan2(accel_x, accel_z) * 180.0 / M_PI;

        // Print the roll and pitch to the console
        printf("Roll: %f, Pitch: %f\n", roll, pitch);

        // Check if the tilt threshold is exceeded
        if (abs(roll) > TILT_THRESHOLD || abs(pitch) > TILT_THRESHOLD) {
            // Set the LED to on
            pigpio_gpio_write(gpio_fd, 1);
        } else {
            // Set the LED to off
            pigpio_gpio_write(gpio_fd, 0);
        }

        // Write the data to the log file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        snprintf(tilt_log, sizeof(tilt_log), "%s, %f, %f\n", timestamp, roll, pitch);
        pigpio_i2c_write(i2c_fd, 0x00, tilt_log, strlen(tilt_log));

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    pigpio_gpio_close(gpio_fd);
    pigpio_i2c_close(i2c_fd);
    pigpio_stop();

    return 0;
}

