#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define I2C_ADDR 0x60
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define LED_GPIO 17

int main(void) {
    int i2c_fd, log_fd, gpio_fd;
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_device_id i2c_id;
    struct gpio_event_request gpio_req;
    struct gpio_event_data gpio_data;
    char buf[10];
    int ret, i, j;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    i2c_id.addr = I2C_ADDR;
    i2c_id.flags = I2C_M_RD;
    ret = ioctl(i2c_fd, I2C_SLAVE, &i2c_id);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO device
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(i2c_fd);
        close(log_fd);
        return 1;
    }

    // Set GPIO direction
    gpio_req.lineoffsets = LED_GPIO;
    gpio_req.flags = GPIO_LINE_REQUEST_OUTPUT;
    ret = ioctl(gpio_fd, GPIO_LINE_REQUEST, &gpio_req);
    if (ret < 0) {
        perror("Failed to set GPIO direction");
        close(i2c_fd);
        close(log_fd);
        close(gpio_fd);
        return 1;
    }

    // Set GPIO value
    gpio_data.line_values = 0;
    ret = ioctl(gpio_fd, GPIO_LINE_SET_VALUES, &gpio_data);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        close(i2c_fd);
        close(log_fd);
        close(gpio_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ambient light and proximity values
        i2c_msg.addr = I2C_ADDR;
        i2c_msg.flags = I2C_M_RD;
        i2c_msg.len = 2;
        i2c_msg.buf = buf;
        i2c_data.msgs = &i2c_msg;
        i2c_data.nmsgs = 1;
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read I2C data");
            close(i2c_fd);
            close(log_fd);
            close(gpio_fd);
            return 1;
        }

        // Parse ambient light and proximity values
        int ambient_light = (buf[0] << 8) | buf[1];
        int proximity = (buf[2] << 8) | buf[3];

        // Write to log file
        char line[100];
        snprintf(line, sizeof(line), "%s,AmbientLight:%d,Proximity:%d\n",
                 get_timestamp(), ambient_light, proximity);
        write(log_fd, line, strlen(line));

        // Check proximity value
        if (proximity > 100) {
            // Turn on LED
            gpio_data.line_values = 1;
            ret = ioctl(gpio_fd, GPIO_LINE_SET_VALUES, &gpio_data);
            if (ret < 0) {
                perror("Failed to set GPIO value");
                close(i2c_fd);
                close(log_fd);
                close(gpio_fd);
                return 1;
            }
        } else {
            // Turn off LED
            gpio_data.line_values = 0;
            ret = ioctl(gpio_fd, GPIO_LINE_SET_VALUES, &gpio_data);
            if (ret < 0) {
                perror("Failed to set GPIO value");
                close(i2c_fd);
                close(log_fd);
                close(gpio_fd);
                return 1;
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);
    close(gpio_fd);

    return 0;
}

void sigint_handler(int signum) {
    // Gracefully close I2C file descriptor
    close(i2c_fd);

    // Close log file
    close(log_fd);

    // Turn off LED
    gpio_data.line_values = 0;
    ioctl(gpio_fd, GPIO_LINE_SET_VALUES, &gpio_data);

    // Close GPIO device
    close(gpio_fd);

    // Exit program
    exit(0);
}

void sigterm_handler(int signum) {
    // Gracefully close I2C file descriptor
    close(i2c_fd);

    // Close log file
    close(log_fd);

    // Turn off LED
    gpio_data.line_values = 0;
    ioctl(gpio_fd, GPIO_LINE_SET_VALUES, &gpio_data);

    // Close GPIO device
    close(gpio_fd);

    // Exit program
    exit(0);
}

char* get_timestamp() {
    time_t t = time(NULL);
    struct tm* tm = localtime(&t);
    char* timestamp = asctime(tm);
    timestamp[strlen(timestamp) - 1] = '\0';
    return timestamp;
}

