#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO17 11
#define GPIO18 12
#define GPIO27 13

#define PWM_FREQ 100
#define PWM_RANGE 255

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration>\n", argv[0]);
        return 1;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration: %d\n", duration);
        return 1;
    }

    // Initialize the PWM driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize PWM driver\n");
        return 1;
    }

    // Set up the PWM channels
    int pwm1 = gpioPWM(GPIO17, PWM_FREQ, PWM_RANGE);
    int pwm2 = gpioPWM(GPIO18, PWM_FREQ, PWM_RANGE);
    int pwm3 = gpioPWM(GPIO27, PWM_FREQ, PWM_RANGE);

    if (pwm1 < 0 || pwm2 < 0 || pwm3 < 0) {
        fprintf(stderr, "Failed to set up PWM channels\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Start the PWM channels
    gpioPWM(pwm1, 0);
    gpioPWM(pwm2, 0);
    gpioPWM(pwm3, 0);

    // Fade the lamps
    for (int i = 0; i < duration; i++) {
        if (!running) {
            break;
        }

        // Fade lamp 1
        gpioPWM(pwm1, i * 255 / duration);
        printf("Lamp 1: %d%%\n", i * 100 / duration);

        // Fade lamp 2
        gpioPWM(pwm2, i * 255 / duration);
        printf("Lamp 2: %d%%\n", i * 100 / duration);

        // Fade lamp 3
        gpioPWM(pwm3, i * 255 / duration);
        printf("Lamp 3: %d%%\n", i * 100 / duration);

        // Sleep for 1 second
        sleep(1);
    }

    // Turn off the lamps
    gpioPWM(pwm1, 0);
    gpioPWM(pwm2, 0);
    gpioPWM(pwm3, 0);

    // Release resources
    gpioTerminate();

    return 0;
}

