    if (pwm1 < 0 || pwm2 < 0 || pwm3 < 0) {
        fprintf(stderr, "Failed to set up PWM channels\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Start the PWM channels
    gpioPWM(pwm1, 0);
    gpioPWM(pwm2, 0);
    gpioPWM(pwm3, 0);

    // Fade the lamps
    for (int i = 0; i < duration; i++) {
        if (!running) {
            break;
        }

        // Fade lamp 1
        gpioPWM(pwm1, i * 255 / duration);
        printf("Lamp 1: %d%%\n", i * 100 / duration);

        // Fade lamp 2
        gpioPWM(pwm2, i * 255 / duration);
        printf("Lamp 2: %d%%\n", i * 100 / duration);

        // Fade lamp 3
        gpioPWM(pwm3, i * 255 / duration);
        printf("Lamp 3: %d%%\n", i * 100 / duration);

        // Sleep for 1 second
        sleep(1);
    }

    // Turn off the lamps
    gpioPWM(pwm1, 0);
    gpioPWM(pwm2, 0);
    gpioPWM(pwm3, 0);

    // Release resources
    gpioTerminate();

    return 0;
}
