#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define ELECTRODE 0
#define DEBOUNCE_DELAY 100
#define RELAY_PIN 17
#define LOG_FILE "touch_relay.log"

static bool running = true;
static bool relay_state = false;
static int i2c_fd;
static int gpio_fd;
static int log_fd;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SLAVE);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d with address 0x%02X: %s", I2C_BUS, I2C_ADDR, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_fd = gpio_open(RELAY_PIN, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO pin %d: %s", RELAY_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void init_log() {
    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void log_error(const char *msg) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld: %s\n", tv.tv_sec, tv.tv_usec, msg);
    write(log_fd, buf, strlen(buf));
}

static void read_touch_status() {
    uint8_t data[2];
    if (i2c_read(i2c_fd, data, 2) != 2) {
        log_error("Failed to read touch status from I2C bus");
        return;
    }
    if (data[0] & (1 << ELECTRODE)) {
        if (!relay_state) {
            relay_state = true;
            gpio_write(gpio_fd, 1);
        }
    } else {
        if (relay_state) {
            relay_state = false;
            gpio_write(gpio_fd, 0);
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_i2c();
    init_gpio();
    init_log();

    while (running) {
        read_touch_status();
        usleep(10000);
    }

    gpio_close(gpio_fd);
    i2c_close(i2c_fd);
    close(log_fd);

    return 0;
}

