#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define FLAME_DETECTED_THRESHOLD 3
#define FLAME_DETECTED_INTERVAL 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the log file
    int log_fd = open("flame_log.txt", O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize the GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    struct gpiod_line *flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor) {
        perror("Error getting flame sensor line");
        return 1;
    }

    struct gpiod_line *buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        perror("Error getting buzzer line");
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("Error getting LED line");
        return 1;
    }

    // Set the GPIO pins to input mode
    gpiod_line_set_direction(flame_sensor, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_set_direction(buzzer, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(led, GPIOD_LINE_DIRECTION_OUTPUT);

    // Set the buzzer and LED to off
    gpiod_line_set_value(buzzer, 0);
    gpiod_line_set_value(led, 0);

    // Main loop
    while (running) {
        // Read the flame sensor
        int flame_sensor_value = gpiod_line_get_value(flame_sensor);
        if (flame_sensor_value < 0) {
            perror("Error reading flame sensor");
            return 1;
        }

        // If the flame sensor is low, check if it has been low for at least 3 consecutive reads spaced 50ms apart
        if (flame_sensor_value == 0) {
            static int flame_detected_count = 0;
            flame_detected_count++;

            if (flame_detected_count >= FLAME_DETECTED_THRESHOLD) {
                // Flame detected, log the timestamp and message
                time_t now = time(NULL);
                char *timestamp = ctime(&now);
                char *message = "Flame Detected\n";
                write(log_fd, timestamp, strlen(timestamp));
                write(log_fd, message, strlen(message));

                // Turn on the buzzer and LED
                gpiod_line_set_value(buzzer, 1);
                gpiod_line_set_value(led, 1);
            }
        } else {
            // Flame not detected, reset the counter
            flame_detected_count = 0;

            // Turn off the buzzer and LED
            gpiod_line_set_value(buzzer, 0);
            gpiod_line_set_value(led, 0);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Clean up
    gpiod_line_release(flame_sensor);
    gpiod_line_release(buzzer);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(log_fd);

    return 0;
}

