#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define MOTOR_SPEED_MAX 255
#define MOTOR_SPEED_MIN -255

#define TILT_ERROR_MAX 10.0
#define TILT_ERROR_MIN -10.0

#define DISTANCE_MAX 400.0
#define DISTANCE_MIN 2.0

#define OBSTACLE_DISTANCE 20.0

#define PID_KP 0.5
#define PID_KI 0.01
#define PID_KD 0.01

#define PID_ERROR_MAX 10.0
#define PID_ERROR_MIN -10.0

