            motor_b_speed = (int) (PID_KP * pid_error + PID_KI * pid_integral + PID_KD * pid_derivative);

            // Clamp the motor speeds to the maximum and minimum values
            motor_a_speed = clamp(motor_a_speed, MOTOR_SPEED_MAX, MOTOR_SPEED_MIN);
            motor_b_speed = clamp(motor_b_speed, MOTOR_SPEED_MAX, MOTOR_SPEED_MIN);

            // Check if the distance is below the obstacle distance
            if (distance < OBSTACLE_DISTANCE) {
                // Reverse both motors at 50% speed
                motor_a_speed = -motor_a_speed / 2;
                motor_b_speed = -motor_b_speed / 2;
