#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 50

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Initialize the GPIO driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up the sensor pin as an input with a pull-down resistor
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin as input\n");
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on sensor pin\n");
        return 1;
    }

    // Set up the relay pin as an output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            return 1;
        }

        // If the sensor is touched, toggle the relay
        if (sensor_value == 1) {
            // Debounce delay
            usleep(DEBOUNCE_DELAY * 1000);

            // Read the sensor value again to ensure it's still touched
            sensor_value = gpioRead(SENSOR_PIN);
            if (sensor_value < 0) {
                fprintf(stderr, "Failed to read sensor value\n");
                return 1;
            }

            // If the sensor is still touched, toggle the relay
            if (sensor_value == 1) {
                gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            }
        }
    }

    // Clean up
    gpioTerminate();

    return 0;
}

