#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <tcs34725.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define INTEGRATION_TIME 154
#define SAMPLE_PERIOD 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int fd;
    int ret;
    uint8_t reg;
    uint8_t data[4];
    uint32_t timestamp;
    FILE *fp;

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Initialize TCS34725
    reg = TCS34725_ENABLE | TCS34725_AIEN | TCS34725_WEN;
    ret = write(fd, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to TCS34725: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Set integration time
    reg = TCS34725_ATIME;
    ret = write(fd, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to TCS34725: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Set wait time
    reg = TCS34725_WTIME;
    ret = write(fd, &reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to TCS34725: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Open CSV file
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,C,R,G,B\n");

    // Main loop
    while (running) {
        // Read data from TCS34725
        ret = read(fd, data, 4);
        if (ret < 0) {
            fprintf(stderr, "Error reading from TCS34725: %s\n", strerror(errno));
            close(fd);
            fclose(fp);
            return 1;
        }

        // Get timestamp
        timestamp = time(NULL);

        // Write data to CSV file
        fprintf(fp, "%lu,%u,%u,%u,%u\n", timestamp, data[0], data[1], data[2], data[3]);

        // Sleep for SAMPLE_PERIOD ms
        usleep(SAMPLE_PERIOD * 1000);
    }

    // Close I2C bus
    close(fd);

    // Close CSV file
    fclose(fp);

    // Clean up
    tcs34725_close();

    return 0;
}

