#define RELAY_1_PIN 11
#define RELAY_2_PIN 13
#define RELAY_3_PIN 15
#define RELAY_4_PIN 17

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 5400

#define PWM_FREQUENCY 1000
#define PWM_RESOLUTION 1000

#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 100

#define SUNRISE_DUTY_CYCLE 0
#define DAYTIME_DUTY_CYCLE 50
#define SUNSET_DUTY_CYCLE 100
#define NIGHTTIME_DUTY_CYCLE 0

#define SUNRISE_PHASE 0
#define DAYTIME_PHASE 1
#define SUNSET_PHASE 2
#define NIGHTTIME_PHASE 3

#define NUM_PHASES 4

int main(int argc, char **argv) {
  // Initialize the GPIO library
  if (gpiod_init() != 0) {
    fprintf(stderr, "Error initializing GPIO library\n");
    return 1;
  }

  // Set up the GPIO pins for the relays
  gpiod_handle_t relay_1 = gpiod_open_pin(RELAY_1_PIN, GPIOD_OUTPUT);
  gpiod_handle_t relay_2 = gpiod_open_pin(RELAY_2_PIN, GPIOD_OUTPUT);
  gpiod_handle_t relay_3 = gpiod_open_pin(RELAY_3_PIN, GPIOD_OUTPUT);
  gpiod_handle_t relay_4 = gpiod_open_pin(RELAY_4_PIN, GPIOD_OUTPUT);

  if (relay_1 == NULL || relay_2 == NULL || relay_3 == NULL || relay_4 == NULL) {
    fprintf(stderr, "Error opening GPIO pins for relays\n");
    return 1;
  }

  // Set up the PWM timer
  struct timespec pwm_period = {
    .tv_sec = 0,
    .tv_nsec = 1000000000 / PWM_FREQUENCY
  };

  // Set up the duty cycle
  int duty_cycle = MIN_DUTY_CYCLE;

  // Set up the phase
  int phase = SUNRISE_PHASE;

  // Set up the time
  struct timespec current_time = {
    .tv_sec = 0,
    .tv_nsec = 0
  };

  // Set up the signal handler
  struct sigaction sigint_action = {
    .sa_handler = handle_sigint,
    .sa_flags = 0
  };

  sigaction(SIGINT, &sigint_action, NULL);

  // Main loop
  while (1) {
    // Get the current time
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Check if it's time to change the phase
    if (current_time.tv_sec >= SUNRISE_DURATION && phase == SUNRISE_PHASE) {
      phase = DAYTIME_PHASE;
      duty_cycle = DAYTIME_DUTY_CYCLE;
    } else if (current_time.tv_sec >= SUNRISE_DURATION + DAYTIME_DURATION && phase == DAYTIME_PHASE) {
      phase = SUNSET_PHASE;
      duty_cycle = SUNSET_DUTY_CYCLE;
    } else if (current_time.tv_sec >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION && phase == SUNSET_PHASE) {
      phase = NIGHTTIME_PHASE;
      duty_cycle = NIGHTTIME_DUTY_CYCLE;
    }

    // Set the duty cycle for the relays
    gpiod_set_duty_cycle(relay_1, duty_cycle);
    gpiod_set_duty_cycle(relay_2, duty_cycle);
    gpiod_set_duty_cycle(relay_3, duty_cycle);
    gpiod_set_duty_cycle(relay_4, duty_cycle);

    // Sleep for the PWM period
    nanosleep(&pwm_period, NULL);
  }

  // Clean up
  gpiod_close_pin(relay_1);
  gpiod_close_pin(relay_2);
  gpiod_close_pin(relay_3);
  gpiod_close_pin(relay_4);

  gpiod_cleanup();

  return 0;
}

void handle_sigint(int signal) {
  // Turn off all relays
  gpiod_set_duty_cycle(relay_1, 0);
  gpiod_set_duty_cycle(relay_2, 0);
  gpiod_set_duty_cycle(relay_3, 0);
  gpiod_set_duty_cycle(relay_4, 0);

  // Clean up
  gpiod_close_pin(relay_1);
  gpiod_close_pin(relay_2);
  gpiod_close_pin(relay_3);
  gpiod_close_pin(relay_4);

  gpiod_cleanup();

  exit(0);
}

