    if (current_time.tv_sec >= SUNRISE_DURATION && phase == SUNRISE_PHASE) {
      phase = DAYTIME_PHASE;
      duty_cycle = DAYTIME_DUTY_CYCLE;
    } else if (current_time.tv_sec >= SUNRISE_DURATION + DAYTIME_DURATION && phase == DAYTIME_PHASE) {
      phase = SUNSET_PHASE;
      duty_cycle = SUNSET_DUTY_CYCLE;
    } else if (current_time.tv_sec >= SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION && phase == SUNSET_PHASE) {
      phase = NIGHTTIME_PHASE;
      duty_cycle = NIGHTTIME_DUTY_CYCLE;
    }

    // Set the duty cycle for the relays
    gpiod_set_duty_cycle(relay_1, duty_cycle);
    gpiod_set_duty_cycle(relay_2, duty_cycle);
    gpiod_set_duty_cycle(relay_3, duty_cycle);
    gpiod_set_duty_cycle(relay_4, duty_cycle);

    // Sleep for the PWM period
    nanosleep(&pwm_period, NULL);
  }

  // Clean up
  gpiod_close_pin(relay_1);
  gpiod_close_pin(relay_2);
  gpiod_close_pin(relay_3);
  gpiod_close_pin(relay_4);

  gpiod_cleanup();

  return 0;
}

void handle_sigint(int signal) {
