#define GPIO_PIN 17
#define DEBOUNCE_TIME 200
#define VIDEO_DURATION 5

static int gpio_fd;
static int log_fd;
static int video_fd;

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(gpio_fd);
    close(log_fd);
    close(video_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize GPIO pin
    gpio_fd = gpiod_open_device(GPIO_PIN);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Initialize log file
    log_fd = open("/home/pi/logs/motion_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read GPIO pin
        int value = gpiod_read_pin(gpio_fd);
        if (value < 0) {
            perror("Failed to read GPIO pin");
            return 1;
        }

        // Check for motion event
        if (value == 0) {
            // Debounce the event
            usleep(DEBOUNCE_TIME * 1000);

            // Check if the event is still valid
            value = gpiod_read_pin(gpio_fd);
            if (value < 0) {
                perror("Failed to read GPIO pin");
                return 1;
            }

            if (value == 0) {
                // Get current timestamp
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);

                // Create video file name
                char filename[20];
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", tm);

                // Start video capture
                video_fd = raspivid_start(filename, VIDEO_DURATION);
                if (video_fd < 0) {
                    perror("Failed to start video capture");
                    return 1;
                }

                // Write to log file
                char log_entry[100];
                strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%SZ", tm);
                write(log_fd, log_entry, strlen(log_entry));

                // Wait for video capture to finish
                raspivid_wait(video_fd);

                // Close video file
                close(video_fd);
            }
        }
    }

    return 0;
}

