#define GYRO_INTERVAL 10

#define LOG_FILE "gyro_log.csv"

static int gpio_fd;
static int i2c_fd;
static int gyro_fd;

static void sigint_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    close(gyro_fd);
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

static void init_gpio() {
    gpio_fd = gpiod_open_device(I2C_BUS);
    if (gpio_fd < 0) {
        printf("Failed to open GPIO device: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        printf("Failed to open I2C device: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_gyro() {
    gyro_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (gyro_fd < 0) {
        printf("Failed to open gyro device: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_gyro() {
    uint8_t buf[6];
    int ret;

    ret = i2c_read(gyro_fd, GYRO_X_REG, buf, 6);
    if (ret < 0) {
        printf("Failed to read gyro data: %s\n", strerror(errno));
        exit(1);
    }

    uint16_t x = (buf[0] << 8) | buf[1];
    uint16_t y = (buf[2] << 8) | buf[3];
    uint16_t z = (buf[4] << 8) | buf[5];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_gpio();
    init_i2c();
    init_gyro();

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }

    while (1) {
        read_gyro();
        fprintf(fp, "%ld, %d, %d, %d\n", time(NULL), x, y, z);
        usleep(GYRO_INTERVAL * 1000);
    }

    fclose(fp);
    close(gyro_fd);
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

