void handle_sigint(int signal) {
    // Deactivate all relays by driving them HIGH
    gpiod_set_value(RELAY_1_PIN, 1);
    gpiod_set_value(RELAY_2_PIN, 1);
    gpiod_set_value(RELAY_3_PIN, 1);
    gpiod_set_value(RELAY_4_PIN, 1);

    // Close the log file
    fclose(log_file);

    // Terminate the driver library
    gpiod_terminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the driver library
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize the driver library\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open the log file\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Set up the GPIO pins for the relays
    gpiod_set_direction(RELAY_1_PIN, GPIOD_OUTPUT);
    gpiod_set_direction(RELAY_2_PIN, GPIOD_OUTPUT);
    gpiod_set_direction(RELAY_3_PIN, GPIOD_OUTPUT);
    gpiod_set_direction(RELAY_4_PIN, GPIOD_OUTPUT);

    // Main loop
    while (1) {
        // Generate a random moisture value seeded with time(NULL)
        int moisture = rand() % 100;

        // Treat any reading below 30 as dry soil and activate the corresponding relay by driving the pin LOW
        if (moisture < 30) {
            gpiod_set_value(RELAY_1_PIN, 0);
            gpiod_set_value(RELAY_2_PIN, 0);
            gpiod_set_value(RELAY_3_PIN, 0);
            gpiod_set_value(RELAY_4_PIN, 0);
        }

        // Treat readings of 30 or above as wet and deactivate the relay by driving the pin HIGH
        if (moisture >= 30) {
            gpiod_set_value(RELAY_1_PIN, 1);
            gpiod_set_value(RELAY_2_PIN, 1);
            gpiod_set_value(RELAY_3_PIN, 1);
            gpiod_set_value(RELAY_4_PIN, 1);
        }

        // Append the sensor reading, the resulting ON/OFF state of each relay, and a timestamp to the log file
        fprintf(log_file, "%d, %d, %d, %d, %d\n", moisture, gpiod_get_value(RELAY_1_PIN), gpiod_get_value(RELAY_2_PIN), gpiod_get_value(RELAY_3_PIN), gpiod_get_value(RELAY_4_PIN));

        // Sleep for 5 seconds
        sleep(5);
