    gpiod_set_value(RELAY_2_PIN, 1);
    gpiod_set_value(RELAY_3_PIN, 1);
    gpiod_set_value(RELAY_4_PIN, 1);

    // Close the log file
    fclose(log_file);

    // Terminate the driver library
    gpiod_terminate();

    // Exit the program
    return 0;
}

