#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <signal.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000
#define TIMEOUT_MS 200
#define TRIG_PULSE_US 10
#define TRIG_PULSE_NS (TRIG_PULSE_US * 1000)
#define TIMEOUT_NS (TIMEOUT_MS * 1000 * 1000)

static int gpio_fd;
static int trig_pin;
static int echo_pin;
static int trig_pulse_ns;
static int timeout_ns;
static int max_distance;
static int log_fd;
static pthread_mutex_t mutex;

static void sigint_handler(int signum) {
    pthread_mutex_lock(&mutex);
    gpio_write(gpio_fd, trig_pin, 0);
    gpio_write(gpio_fd, echo_pin, 0);
    pthread_mutex_unlock(&mutex);
    close(log_fd);
    gpio_terminate(gpio_fd);
    pthread_mutex_destroy(&mutex);
    exit(0);
}

static void trig_callback(int pin, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    gpio_write(gpio_fd, trig_pin, 1);
    usleep(trig_pulse_ns);
    gpio_write(gpio_fd, trig_pin, 0);
    pthread_mutex_unlock(&mutex);
}

static void echo_callback(int pin, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    uint32_t pulse_width = gpio_pulse_width(gpio_fd, echo_pin);
    if (pulse_width > timeout_ns) {
        printf("Timeout error\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    int distance = pulse_width / 58;
    if (distance > max_distance) {
        printf("Out of range\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    char buf[100];
    snprintf(buf, sizeof(buf), "%lu,%d\n", tick, distance);
    write(log_fd, buf, strlen(buf));
    pthread_mutex_unlock(&mutex);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    trig_pin = gpio_get_pin(gpio_fd, TRIG_PIN);
    echo_pin = gpio_get_pin(gpio_fd, ECHO_PIN);
    if (trig_pin < 0 || echo_pin < 0) {
