#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY 1000
#define GEAR_RATIO 64
#define STEPS_PER_REV 2048
#define SQUARE_SIZE 50

int main() {
    // Initialize GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *lines[4];
    lines[0] = gpiod_chip_get_line(chip, MOTOR1_IN1);
    lines[1] = gpiod_chip_get_line(chip, MOTOR1_IN2);
    lines[2] = gpiod_chip_get_line(chip, MOTOR1_IN3);
    lines[3] = gpiod_chip_get_line(chip, MOTOR1_IN4);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    // Set GPIO pins as outputs
    for (int i = 0; i < 4; i++) {
        gpiod_line_request_output(lines[i], "motor", 0);
    }

    // Calculate steps for square
    int steps = SQUARE_SIZE * STEPS_PER_REV / GEAR_RATIO;

    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Drive motors
    for (int i = 0; i < steps; i++) {
        // Drive motor 1
        gpiod_line_set_value(lines[0], 1);
        gpiod_line_set_value(lines[1], 0);
        gpiod_line_set_value(lines[2], 0);
        gpiod_line_set_value(lines[3], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[0], 0);
        gpiod_line_set_value(lines[1], 1);
        gpiod_line_set_value(lines[2], 0);
        gpiod_line_set_value(lines[3], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[0], 0);
        gpiod_line_set_value(lines[1], 0);
        gpiod_line_set_value(lines[2], 1);
        gpiod_line_set_value(lines[3], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[0], 0);
        gpiod_line_set_value(lines[1], 0);
        gpiod_line_set_value(lines[2], 0);
        gpiod_line_set_value(lines[3], 1);
        usleep(STEP_DELAY);

        // Drive motor 2
        gpiod_line_set_value(lines[4], 1);
        gpiod_line_set_value(lines[5], 0);
        gpiod_line_set_value(lines[6], 0);
        gpiod_line_set_value(lines[7], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[4], 0);
        gpiod_line_set_value(lines[5], 1);
        gpiod_line_set_value(lines[6], 0);
        gpiod_line_set_value(lines[7], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[4], 0);
        gpiod_line_set_value(lines[5], 0);
        gpiod_line_set_value(lines[6], 1);
        gpiod_line_set_value(lines[7], 0);
        usleep(STEP_DELAY);

        gpiod_line_set_value(lines[4], 0);
        gpiod_line_set_value(lines[5], 0);
        gpiod_line_set_value(lines[6], 0);
        gpiod_line_set_value(lines[7], 1);
        usleep(STEP_DELAY);
    }

    // Release resources
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int signum) {
    // Set all GPIO pins low
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], 0);
    }

    // Release resources
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    exit(0);
}

