#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>
#include <libgpiod.h>

#define I2C_ADDR 0x19
#define I2C_BUS 1
#define I2C_SPEED 100000
#define I2C_TIMEOUT 1000
#define AXIS_THRESHOLD 2.0

static int i2c_fd;
static int gpio_fd;

static void sigint_handler(int signum) {
    printf("Received SIGINT, shutting down...\n");
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

static void init_i2c(void) {
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED, I2C_TIMEOUT);
    if (i2c_fd < 0) {
        printf("Error opening I2C bus: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_gpio(void) {
    gpio_fd = gpiod_open(I2C_BUS, I2C_ADDR, GPIOD_OUT);
    if (gpio_fd < 0) {
        printf("Error opening GPIO: %s\n", strerror(errno));
        exit(1);
    }
}

static void configure_sensor(void) {
    uint8_t reg_addr = 0x20;
    uint8_t reg_val = 0x08;
    if (i2c_write(i2c_fd, &reg_addr, 1, &reg_val, 1) < 0) {
        printf("Error writing to I2C register: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_sensor(void) {
    uint8_t reg_addr = 0x28;
    uint8_t reg_val[6];
    if (i2c_read(i2c_fd, &reg_addr, 1, reg_val, 6) < 0) {
        printf("Error reading from I2C register: %s\n", strerror(errno));
        exit(1);
    }
    int16_t x = (reg_val[0] << 8) | reg_val[1];
    int16_t y = (reg_val[2] << 8) | reg_val[3];
    int16_t z = (reg_val[4] << 8) | reg_val[5];
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

static void check_threshold(void) {
    if (abs(x) > AXIS_THRESHOLD || abs(y) > AXIS_THRESHOLD || abs(z) > AXIS_THRESHOLD) {
        printf("High acceleration detected, shutting down...\n");
        close(i2c_fd);
        close(gpio_fd);
        system("sudo shutdown -h now");
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);

    if (argc > 1) {
        if (strcmp(argv[1], "-a") == 0) {
            if (argc > 2) {
                I2C_ADDR = strtol(argv[2], NULL, 16);
            } else {
                printf("Invalid I2C address\n");
                exit(1);
            }
        } else if (strcmp(argv[1], "-t") == 0) {
            if (argc > 2) {
                AXIS_THRESHOLD = strtod(argv[2], NULL);
            } else {
                printf("Invalid threshold\n");
                exit(1);
            }
        } else {
            printf("Invalid argument\n");
            exit(1);
        }
    }

    if (I2C_ADDR < 0x19 || I2C_ADDR > 0x1F) {
        printf("Invalid I2C address\n");
        exit(1);
    }

    if (AXIS_THRESHOLD <= 0) {
        printf("Invalid threshold\n");
        exit(1);
    }

    init_i2c();
    init_gpio();
    configure_sensor();

    while (1) {
        read_sensor();
        check_threshold();
        usleep(100000);
    }

    return 0;
}

