#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/libgpiod.h>

#define RELAY_GPIO 18
#define TCP_PORT 5000
#define BUF_SIZE 1024

void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    // Close the socket
    close(sock);
    // Close the log file
    fclose(log_file);
    // Turn off the relay
    gpiod_line_set_value(relay_line, 0);
    // Terminate the driver library
    gpiod_line_release(relay_line);
    exit(0);
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM, shutting down...\n");
    // Close the socket
    close(sock);
    // Close the log file
    fclose(log_file);
    // Turn off the relay
    gpiod_line_set_value(relay_line, 0);
    // Terminate the driver library
    gpiod_line_release(relay_line);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize the driver library
    gpiod_chip_iter *chip_iter = gpiod_chip_iter_new();
    gpiod_chip *chip = gpiod_chip_iter_next(chip_iter);
    gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    gpiod_line_request_output(relay_line, "relay", 0);

    // Create a socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // Bind the socket to the specified port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(TCP_PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        perror("listen");
        exit(1);
    }

    // Open the log file
    FILE *log_file = fopen("relay_log.txt", "w");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Accept an incoming connection
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            perror("accept");
            continue;
        }

        // Read the command from the client
        char buf[BUF_SIZE];
        int n = read(client_sock, buf, BUF_SIZE);
        if (n < 0) {
            perror("read");
            close(client_sock);
            continue;
        }

        // Trim the trailing whitespace
        buf[n] = '\0';
        char *cmd = strtok(buf, " ");
        if (cmd == NULL) {
            close(client_sock);
            continue;
        }

        // Check the command
        if (strcasecmp(cmd, "ON") == 0) {
            // Turn on the relay
            gpiod_line_set_value(relay_line, 1);
            fprintf(log_file, "Relay turned on at %s\n", ctime(&time(NULL)));
        } else if (strcasecmp(cmd, "OFF") == 0) {
            // Turn off the relay
            gpiod_line_set_value(relay_line, 0);
            fprintf(log_file, "Relay turned off at %s\n", ctime(&time(NULL)));
        } else {
            // Invalid command
            fprintf(log_file, "Invalid command received at %s\n", ctime(&time(NULL)));
        }

        // Close the client socket
        close(client_sock);
    }

    // Close the socket
    close(sock);
    // Close the log file
    fclose(log_file);
    // Turn off the relay
    gpiod_line_set_value(relay_line, 0);
    // Terminate the driver library
    gpiod_line_release(relay_line);
    return 0;
}

