        fprintf(stderr, "Error setting GPIO 18 direction: %s\n", strerror(errno));
        return 1;
    }

    // Set up I2C addresses for sensors
    if (i2c_set_slave_address(fd1, SENSOR1_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address for sensor 1: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_set_slave_address(fd2, SENSOR2_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    // Set up I2C read and write functions
    if (i2c_set_read_func(fd1, i2c_read) < 0) {
        fprintf(stderr, "Error setting I2C read function for sensor 1: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_set_read_func(fd2, i2c_read) < 0) {
        fprintf(stderr, "Error setting I2C read function for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_set_write_func(fd1, i2c_write) < 0) {
        fprintf(stderr, "Error setting I2C write function for sensor 1: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_set_write_func(fd2, i2c_write) < 0) {
        fprintf(stderr, "Error setting I2C write function for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    // Start measurement command for both sensors
    if (i2c_write(fd1, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error starting measurement for sensor 1: %s\n", strerror(errno));
        return 1;
    }

    if (i2c_write(fd2, 0x00, 0x00) < 0) {
        fprintf(stderr, "Error starting measurement for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    // Open flow log file
    fp = fopen(FLOW_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flow log file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Read flow rates from both sensors
        if (i2c_read(fd1, buf1, 3) < 0) {
            fprintf(stderr, "Error reading flow rate from sensor 1: %s\n", strerror(errno));
            continue;
        }

        if (i2c_read(fd2, buf2, 3) < 0) {
            fprintf(stderr, "Error reading flow rate from sensor 2: %s\n", strerror(errno));
            continue;
        }

        // Validate CRC
        crc1 = crc8(buf1, 2, 0x07, 0x00, 0x00);
        crc2 = crc8(buf2, 2, 0x07, 0x00, 0x00);

        if (crc1 != buf1[2] || crc2 != buf2[2]) {
            fprintf(stderr, "CRC check failed for sensor %d\n", (buf1[2] == crc1) ? 1 : 2);
            continue;
        }

        // Extract flow rates
        flow1 = (buf1[0] << 8) | buf1[1];
        flow2 = (buf2[0] << 8) | buf2[1];

        // Log flow rates
        gettimeofday(&tv, NULL);
        fprintf(fp, "%ld.%06ld, %d, %d\n", tv.tv_sec, tv.tv_usec, flow1, flow2);
        fflush(fp);

        // Control relay
        if (flow1 < 500 || flow2 < 500) {
            gpio_write(relay_fd, 1);
        } else {
            gpio_write(relay_fd, 0);
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    fclose(fp);
    gpio_close(relay_fd);
    i2c_close(fd1);
    i2c_close(fd2);
    gpio_cleanup();

    return 0;
}
