#define UNLOCK_PULSE_WIDTH 1000

int main(void) {
    // Initialize the GPIO pins
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set the GPIO pins as output
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        return 1;
    }
    if (gpioSetMode(LOCK_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LOCK_PIN);
        return 1;
    }
    if (gpioSetMode(UNLOCK_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", UNLOCK_PIN);
        return 1;
    }

    // Enable internal pull-up resistors for the buttons
    if (gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor for GPIO %d\n", LOCK_PIN);
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor for GPIO %d\n", UNLOCK_PIN);
        return 1;
    }

    // Set the initial state of the servo to 0
    if (gpioWrite(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set initial state of servo\n");
        return 1;
    }

    // Install signal handler for SIGINT/SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the state of the buttons
        int lock_state = gpioRead(LOCK_PIN);
        int unlock_state = gpioRead(UNLOCK_PIN);

        // Debounce the buttons
        usleep(DEBOUNCE_DELAY);

        // Check if the lock button was pressed
        if (lock_state == 1) {
            // Send a pulse width of 2000 µs to lock the door
            if (gpioPulse(SERVO_PIN, PI_OUTPUT, LOCK_PULSE_WIDTH) < 0) {
                fprintf(stderr, "Failed to send pulse width to lock the door\n");
                return 1;
            }
            printf("Door locked\n");
        }

        // Check if the unlock button was pressed
        if (unlock_state == 1) {
            // Send a pulse width of 1000 µs to unlock the door
            if (gpioPulse(SERVO_PIN, PI_OUTPUT, UNLOCK_PULSE_WIDTH) < 0) {
                fprintf(stderr, "Failed to send pulse width to unlock the door\n");
                return 1;
            }
            printf("Door unlocked\n");
        }

        // Sleep for a short period to keep CPU usage low
        usleep(10000);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

void signal_handler(int signal) {
    // Stop the servo by sending a pulse width of 0
    if (gpioPulse(SERVO_PIN, PI_OUTPUT, 0) < 0) {
        fprintf(stderr, "Failed to stop the servo\n");
        return;
    }

    // Call the API one final time to ensure the servo is stopped
    if (gpioPulse(SERVO_PIN, PI_OUTPUT, 0) < 0) {
        fprintf(stderr, "Failed to stop the servo\n");
        return;
    }

    // Clean up and exit
    gpioTerminate();
    exit(0);
}

