#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL 100
#define ACTIVATION_DURATION 60

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize the GPIO driver
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the PIR motion sensor pin as an input
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR motion sensor line\n");
        return 1;
    }
    gpiod_line_request_input(pir_line, "pir");

    // Set up the LED pin as an output
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        return 1;
    }
    gpiod_line_request_output(led_line, "led", 0);

    // Set up the SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the security log file
    FILE *log_file = fopen("security_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open security log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the PIR motion sensor
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR motion sensor\n");
            return 1;
        }

        // If the PIR motion sensor is triggered, turn on the LED
        if (pir_value) {
            gpiod_line_set_value(led_line, 1);
            fprintf(log_file, "%s - Activated\n", get_iso_8601_timestamp());
        }

        // Wait for the polling interval
        usleep(POLL_INTERVAL * 1000);

        // If the PIR motion sensor is still triggered, turn off the LED after the activation duration
        if (pir_value) {
            gpiod_line_set_value(led_line, 0);
            fprintf(log_file, "%s - Deactivated (%d seconds)\n", get_iso_8601_timestamp(), ACTIVATION_DURATION);
        }
    }

    // Clean up
    gpiod_line_release(pir_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

char *get_iso_8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);
    timestamp[strlen(timestamp) - 1] = '\0';

    return timestamp;
}

