#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQ 50
#define PWM_WIDTH 1
#define PWM_DUTY_CYCLE 2

#define LOG_FILE "security.log"

int main(int argc, char *argv[]) {
    // Initialize the GPIO pins
    if (gpioInitialise() < 0) {
        syslog(LOG_USER, "Failed to initialize GPIO");
        exit(1);
    }

    // Set up the servo motor
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ);
    gpioSetPWMrange(SERVO_PIN, PWM_WIDTH);
    gpioSetPWMdutycycle(SERVO_PIN, PWM_DUTY_CYCLE);

    // Set up the PIR sensor
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Create a socket for listening for TCP connections
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_USER, "Failed to create socket");
        exit(1);
    }

    // Bind the socket to port 5000
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(5000);
    addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_USER, "Failed to bind socket");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, 1) < 0) {
        syslog(LOG_USER, "Failed to listen on socket");
        exit(1);
    }

    // Accept incoming connections
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len);
    if (client_sock < 0) {
        syslog(LOG_USER, "Failed to accept incoming connection");
        exit(1);
    }

    // Set up the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_USER, "Failed to open log file");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the PIR sensor
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            syslog(LOG_USER, "Failed to read PIR sensor");
            exit(1);
        }

        // If the PIR sensor is triggered, send a response over the socket
        if (pir_value == 1) {
            char response[10];
            sprintf(response, "PIR:1");
            if (send(client_sock, response, strlen(response), 0) < 0) {
                syslog(LOG_USER, "Failed to send response over socket");
                exit(1);
            }
        }

