#define BH1750_REG_CONTROL 0x01
#define BH1750_CONTROL_ON 0x10
#define BH1750_CONTROL_OFF 0x00
#define BH1750_CONTROL_HIGH_RES 0x04
#define BH1750_CONTROL_LOW_RES 0x00
#define BH1750_CONTROL_120MS 0x00
#define BH1750_CONTROL_240MS 0x01
#define BH1750_CONTROL_480MS 0x02
#define BH1750_CONTROL_960MS 0x03
#define BH1750_CONTROL_1920MS 0x04
#define BH1750_CONTROL_3840MS 0x05
#define BH1750_CONTROL_7680MS 0x06
#define BH1750_CONTROL_15360MS 0x07

