        return 1;
    }

    // Initialize GPIO for relay
    int gpio_fd = gpio_open(GPIO_RELAY, "out");
    if (gpio_fd < 0) {
        perror("gpio_open");
        return 1;
    }

    // Initialize log file
    int log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up BH1750 sensor
    uint8_t control_reg = BH1750_CONTROL_ON | BH1750_CONTROL_HIGH_RES | BH1750_CONTROL_120MS;
    if (i2c_write(i2c_fd, BH1750_ADDR, BH1750_REG_CONTROL, &control_reg, 1) < 0) {
        perror("i2c_write");
        return 1;
    }

    // Main loop
    while (1) {
        // Read lux value
        uint8_t data_reg[2];
        if (i2c_read(i2c_fd, BH1750_ADDR, BH1750_REG_DATA, data_reg, 2) < 0) {
            perror("i2c_read");
            return 1;
        }
        uint16_t lux = (data_reg[0] << 8) | data_reg[1];

        // Log lux value
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char buf[100];
