            gpio_write(gpio_fd, GPIO_RELAY_OFF);
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up on exit
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);
    close(log_fd);
    return 0;
}

void sigint_handler(int signum) {
    // Clean up on SIGINT
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);
    close(log_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    // Clean up on SIGTERM
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);
    close(log_fd);
    exit(0);
}

