#include <pigpio/pigpio.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN 24
#define LOCK_PIN 25

#define TARE_READINGS 10
#define MEASURE_READINGS 5
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 500

static bool running = true;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;

static void handle_sigint(int signal) {
    running = false;
}

static void handle_sigterm(int signal) {
    running = false;
}

static void handle_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
    exit(EXIT_FAILURE);
}

static void tare_hx711() {
    int i;
    uint32_t reading = 0;
    for (i = 0; i < TARE_READINGS; i++) {
        if (gpiod_line_wait_for_value(HX711_DOUT_PIN, GPIOD_LINE_WAIT_FOR_LOW, 1000) != 0) {
            handle_error("Timeout waiting for HX711 DOUT to go low");
        }
        if (gpiod_line_clock_in(HX711_SCK_PIN, 24, &reading) != 0) {
            handle_error("Error reading HX711 data");
        }
        reading >>= 8;
    }
    reading >>= 8;
    syslog(LOG_INFO, "Tare reading: %u", reading);
}

static void measure_hx711() {
    int i;
    uint32_t reading = 0;
    for (i = 0; i < MEASURE_READINGS; i++) {
        if (gpiod_line_wait_for_value(HX711_DOUT_PIN, GPIOD_LINE_WAIT_FOR_LOW, 1000) != 0) {
            handle_error("Timeout waiting for HX711 DOUT to go low");
        }
        if (gpiod_line_clock_in(HX711_SCK_PIN, 24, &reading) != 0) {
            handle_error("Error reading HX711 data");
        }
        reading >>= 8;
    }
    reading >>= 8;
    syslog(LOG_INFO, "Measure reading: %u", reading);
}

static void lock_solenoid() {
    if (gpiod_line_set_value(LOCK_PIN, GPIOD_LINE_VALUE_HIGH) != 0) {
        handle_error("Error setting solenoid lock");
    }
    usleep(duration * 1000);
    if (gpiod_line_set_value(LOCK_PIN, GPIOD_LINE_VALUE_LOW) != 0) {
        handle_error("Error clearing solenoid lock");
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:t:d:")) != -1) {
        switch (opt) {
            case 's':
                scale_factor = atof(optarg);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale_factor] [-t threshold] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (gpiod_init() != 0) {
        handle_error("Error initializing GPIO");
    }

    if (pigpio_init() != 0) {
        handle_error("Error initializing PIGPIO");
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    tare_hx711();

    while (running) {
        measure_hx711();
        if (reading > threshold) {
            lock_solenoid();
        }
        usleep(duration * 1000);
    }

    gpiod_line_release(HX711_DOUT_PIN);
    gpiod_line_release(HX711_SCK_PIN);
    gpiod_line_release(LOCK_PIN);
    pigpio_close();
    gpiod_close();

    return 0;
}

