#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_CLEAN_SESSION 1

static void handle_sigint(int signum) {
    // Set GPIO17 LOW and disconnect from MQTT broker
    gpiod_set_value(GPIO_PIN, 0);
    mqtt_disconnect();

    // Clean up the driver library and close syslog
    gpiod_cleanup();
    closelog();

    // Exit the program
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize the GPIO driver
    gpiod_init();

    // Set GPIO17 as an output and drive it LOW (relay OFF)
    gpiod_set_direction(GPIO_PIN, GPIOD_OUTPUT);
    gpiod_set_value(GPIO_PIN, 0);

    // Connect to the MQTT broker
    mqtt_connect("localhost", 1883, MQTT_CLIENT_ID, MQTT_CLEAN_SESSION);

    // Subscribe to the MQTT topic
    mqtt_subscribe(MQTT_TOPIC, MQTT_QOS);

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Run the MQTT client loop
    while (1) {
        // Check for incoming messages
        mqtt_loop();

        // Handle incoming messages
        if (mqtt_message_arrived()) {
            // Get the message payload
            char *payload = mqtt_get_payload();

            // Check if the payload is valid
            if (payload != NULL && strlen(payload) > 0) {
                // Check if the payload is "ON" or "OFF"
                if (strcmp(payload, "ON") == 0) {
                    // Set GPIO17 HIGH (relay energized)
                    gpiod_set_value(GPIO_PIN, 1);
                } else if (strcmp(payload, "OFF") == 0) {
                    // Set GPIO17 LOW (relay de-energized)
                    gpiod_set_value(GPIO_PIN, 0);
                } else {
                    // Log an error if the payload is invalid
                    syslog(LOG_ERR, "Invalid payload: %s", payload);
                }
            }
        }

        // Check for connection, subscription, disconnection, or error events
        if (mqtt_connection_lost() || mqtt_subscription_lost() || mqtt_disconnected()) {
            // Log the details of the event
            syslog(LOG_INFO, "MQTT event: %s", mqtt_get_event_string());

            // Wait five seconds before attempting to reconnect
            sleep(5);

            // Attempt to reconnect to the MQTT broker
            mqtt_connect("localhost", 1883, MQTT_CLIENT_ID, MQTT_CLEAN_SESSION);

            // Subscribe to the MQTT topic
            mqtt_subscribe(MQTT_TOPIC, MQTT_QOS);
        }
    }

    // Clean up the driver library and close syslog
    gpiod_cleanup();
    closelog();

    // Exit the program
    return 0;
}
