#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

#define PWM_FREQ 10000
#define PWM_RES 255
#define TICKS_PER_REV 64
#define TARGET_RPM 50
#define ANGLE_PER_TICK (360.0 / TICKS_PER_REV)
#define ANGLE_PER_SEC (ANGLE_PER_TICK / PWM_FREQ)
#define ANGLE_PER_SEC_TO_RPM (ANGLE_PER_SEC * 60)

#define ENCODER_STALL_TIMEOUT 2000

volatile uint32_t encoder_a_ticks = 0;
volatile uint32_t encoder_b_ticks = 0;

void encoder_a_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        encoder_a_ticks++;
    } else {
        encoder_a_ticks--;
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        encoder_b_ticks++;
    } else {
        encoder_b_ticks--;
    }
}

void motor_a_pwm(int duty_cycle) {
    gpio_pwm(MOTOR_A_PWM, duty_cycle);
}

void motor_b_pwm(int duty_cycle) {
    gpio_pwm(MOTOR_B_PWM, duty_cycle);
}

void motor_a_forward() {
    gpio_write(MOTOR_A_DIR, 1);
    motor_a_pwm(PWM_RES);
}

void motor_a_backward() {
    gpio_write(MOTOR_A_DIR, 0);
    motor_a_pwm(PWM_RES);
}

void motor_b_forward() {
    gpio_write(MOTOR_B_DIR, 1);
    motor_b_pwm(PWM_RES);
}

void motor_b_backward() {
    gpio_write(MOTOR_B_DIR, 0);
    motor_b_pwm(PWM_RES);
}

void motor_stop() {
    motor_a_pwm(0);
    motor_b_pwm(0);
}

void encoder_stall_check() {
    if (encoder_a_ticks == 0 && encoder_b_ticks == 0) {
        printf("Encoder stall detected!\n");
        motor_stop();
    }
}

