#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define BH1750_ADDR 0x23
#define BH1750_MODE_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MODE_CONTINUOUS_LOW_RES_MODE 0x11
#define BH1750_MODE_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_MODE_ONE_TIME_LOW_RES_MODE 0x21
#define BH1750_MODE_POWER_DOWN 0x00

#define GPIO_PIN 17
#define GPIO_PIN_ACTIVE_HIGH 1

#define LOG_FILE "chicken_coop_log.txt"

#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS 10

#define I2C_DEV "/dev/i2c-1"

int main(int argc, char **argv) {
    // Initialize I2C bus
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO pin
    int gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Set GPIO pin to output mode
    if (ioctl(gpio_fd, GPIO_SET_OUTPUT, GPIO_PIN) < 0) {
        perror("Failed to set GPIO pin to output mode");
        return 1;
    }

    // Set GPIO pin to low
    if (ioctl(gpio_fd, GPIO_SET_LOW, GPIO_PIN) < 0) {
        perror("Failed to set GPIO pin to low");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Set I2C mode to continuous high resolution mode
    if (ioctl(i2c_fd, I2C_SET_MODE, BH1750_MODE_CONTINUOUS_HIGH_RES_MODE) < 0) {
        perror("Failed to set I2C mode");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigint_action.sa_flags = 0;
    sigemptyset(&sigint_action.sa_mask);
    sigaction(SIGINT, &sigint_action, NULL);

    struct sigaction sigterm_action;
    sigterm_action.sa_handler = sigterm_handler;
    sigterm_action.sa_flags = 0;
    sigemptyset(&sigterm_action.sa_mask);
    sigaction(SIGTERM, &sigterm_action, NULL);

    // Main loop
    while (true) {
        // Read lux value from sensor
        uint16_t lux = read_lux(i2c_fd);
        if (lux == 0) {
            fprintf(log_file, "Failed to read lux value\n");
            continue;
        }

        // Check if lux value is below dusk threshold
        if (lux < LUX_THRESHOLD_DUSK) {
            // Turn on relay
            if (ioctl(gpio_fd, GPIO_SET_HIGH, GPIO_PIN) < 0) {
                perror("Failed to turn on relay");
                return 1;
            }
        }

        // Check if lux value is above dawn threshold
        if (lux > LUX_THRESHOLD_DAWN) {
            // Turn off relay
            if (ioctl(gpio_fd, GPIO_SET_LOW, GPIO_PIN) < 0) {
                perror("Failed to turn off relay");
                return 1;
            }
        }

        // Log lux value and relay state
        fprintf(log_file, "%s: Lux = %d, Relay = %s\n",
                get_timestamp(), lux,
                lux < LUX_THRESHOLD_DUSK ? "ON" : "OFF");

        // Wait for next measurement
        usleep(5000000);
    }

    // Clean up
    close(i2c_fd);
    close(gpio_fd);
    fclose(log_file);

    return 0;
}

uint16_t read_lux(int i2c_fd) {
    uint16_t lux;
    if (read(i2c_fd, &lux, sizeof(lux)) < 0) {
        perror("Failed to read lux value");
        return 0;
    }
    return lux;
}

char *get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);
    timestamp[strlen(timestamp) - 1] = '\0';

    return timestamp;
}

void sigint_handler(int signal) {
    // Clean up
    close(i2c_fd);
    close(gpio_fd);
    fclose(log_file);

    // Exit
    exit(0);
}

void sigterm_handler(int signal) {
    // Clean up
    close(i2c_fd);
    close(gpio_fd);
    fclose(log_file);

    // Exit
    exit(0);
}

