#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50

static bool relay_state = false;
static bool touch_state = false;
static bool debounce_state = false;

static void sigint_handler(int signum) {
    printf("Received SIGINT, turning relay off and releasing resources\n");
    gpiod_line_release(relay_line);
    gpiod_line_release(touch_line);
    exit(0);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *relay_line, *touch_line;
    struct timespec ts;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open GPIO chip and lines
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay line\n");
        return 1;
    }
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch line\n");
        return 1;
    }

    // Set up relay and touch lines
    gpiod_line_request_output(relay_line, "relay", 0);
    gpiod_line_request_input(touch_line, "touch");

    // Main loop
    while (true) {
        // Read touch sensor
        gpiod_line_get_value(touch_line, &touch_state);

        // Debounce touch sensor
        if (touch_state) {
            if (!debounce_state) {
                debounce_state = true;
                clock_gettime(CLOCK_MONOTONIC, &ts);
            } else if (ts.tv_sec + DEBOUNCE_DELAY < clock_gettime(CLOCK_MONOTONIC, &ts).tv_sec) {
                // Toggle relay state
                relay_state = !relay_state;
                gpiod_line_set_value(relay_line, relay_state);
                printf("%s: Relay state changed to %s\n", asctime(localtime(&ts)), relay_state ? "ON" : "OFF");
                debounce_state = false;
            }
        } else {
            debounce_state = false;
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    gpiod_line_release(relay_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);

    return 0;
}

