#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LPM_THRESHOLD 5.0
#define HYSTERESIS 0.5

static volatile int flow_count = 0;
static pthread_mutex_t flow_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file;

void handle_sigint(int signum) {
    printf("Received SIGINT\n");
    pthread_mutex_lock(&flow_mutex);
    flow_count = 0;
    pthread_mutex_unlock(&flow_mutex);
    fclose(log_file);
    pthread_mutex_destroy(&flow_mutex);
    exit(1);
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM\n");
    pthread_mutex_lock(&flow_mutex);
    flow_count = 0;
    pthread_mutex_unlock(&flow_mutex);
    fclose(log_file);
    pthread_mutex_destroy(&flow_mutex);
    exit(1);
}

void *flow_sensor_thread(void *arg) {
