#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 50

static bool relay_state = false;
static bool touch_state = false;
static bool touch_debounce = false;
static struct timespec last_touch_time;

static void handle_sigint(int signum) {
    relay_state = false;
    gpiod_set_value(RELAY_PIN, relay_state);
    gpiod_release(RELAY_PIN);
    gpiod_release(TOUCH_PIN);
    exit(0);
}

static void handle_sigterm(int signum) {
    relay_state = false;
    gpiod_set_value(RELAY_PIN, relay_state);
    gpiod_release(RELAY_PIN);
    gpiod_release(TOUCH_PIN);
    exit(0);
}

static void handle_touch_event(int pin, int value) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (value == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (now.tv_sec - last_touch_time.tv_sec >= DEBOUNCE_MS / 1000) {
            relay_state = !relay_state;
            gpiod_set_value(RELAY_PIN, relay_state);
            printf("%s Relay: %s\n", ctime(&now.tv_sec), relay_state ? "ON" : "OFF");
            last_touch_time = now;
        }
    }
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS;

    if (argc > 1 && strcmp(argv[1], "-d") == 0) {
        debounce_ms = atoi(argv[2]);
    }

