#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <termios.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_DEFAULT_PULSE_WIDTH 1500
#define SERVO_ANGLE_STEP 10

int main(int argc, char *argv[]) {
    int servo_fd;
    int servo_angle = 90;
    int servo_pulse_width;
    struct termios old_termios;
    struct termios new_termios;

    // Open the GPIO pin for PWM output
    servo_fd = open("/dev/gpiochip0", O_WRONLY);
    if (servo_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Set the terminal to raw mode
    tcgetattr(STDIN_FILENO, &old_termios);
    new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    // Set the servo pulse width to the default value
    servo_pulse_width = SERVO_DEFAULT_PULSE_WIDTH;
    if (pigpio_set_servo_pulsewidth(servo_fd, SERVO_PIN, servo_pulse_width) < 0) {
        perror("Failed to set servo pulse width");
        return 1;
    }

    // Set the servo angle to the default value
    servo_angle = 90;
    printf("Servo angle: %d\n", servo_angle);

    // Loop until the user presses 'q' or Ctrl+C
    while (1) {
        int c = getchar();
        if (c == 'q' || c == EOF) {
            break;
        }

        // Adjust the servo angle based on the user input
        if (c == '+') {
            servo_angle += SERVO_ANGLE_STEP;
            if (servo_angle > 180) {
                servo_angle = 180;
            }
        } else if (c == '-') {
            servo_angle -= SERVO_ANGLE_STEP;
            if (servo_angle < 0) {
                servo_angle = 0;
            }
        }

        // Calculate the new servo pulse width based on the angle
        servo_pulse_width = (servo_angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH;

        // Set the new servo pulse width
        if (pigpio_set_servo_pulsewidth(servo_fd, SERVO_PIN, servo_pulse_width) < 0) {
            perror("Failed to set servo pulse width");
            return 1;
        }

        // Print the current servo angle
        printf("Servo angle: %d\n", servo_angle);
    }

    // Stop the PWM pulses on the GPIO pin
    if (pigpio_set_servo_pulsewidth(servo_fd, SERVO_PIN, 0) < 0) {
        perror("Failed to stop servo pulse width");
        return 1;
    }

    // Restore the terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);

    // Close the GPIO pin
    close(servo_fd);

    return 0;
}

