#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define MOTOR_RPM_LOG_FILE "motor_rpm.log"
#define MOTOR_RPM_SAMPLE_INTERVAL 5
#define MOTOR_RPM_DEBOUNCE_WINDOW 2

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int signum) {
    stop_flag = 1;
}

static void sigterm_handler(int signum) {
    stop_flag = 1;
}

int main(int argc, char *argv[]) {
    // Initialize the GPIO line
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(line, "motor-rpm");
    if (ret < 0) {
        fprintf(stderr, "Error: unable to request GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    // Open the log file
    int log_fd = open(MOTOR_RPM_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error: unable to open log file\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    uint64_t start_time = 0;
    uint64_t end_time = 0;
    uint64_t pulse_count = 0;
    uint64_t rpm = 0;
    while (!stop_flag) {
        // Wait for the rising edge
        ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE);
        if (ret < 0) {
            fprintf(stderr, "Error: unable to wait for GPIO line event\n");
            break;
        }

        // Debounce the pulse
        if (ret > MOTOR_RPM_DEBOUNCE_WINDOW) {
            pulse_count++;
        }

        // Compute the RPM
        end_time = clock_gettime(CLOCK_MONOTONIC, NULL);
        if (start_time == 0) {
            start_time = end_time;
        }
        if (end_time - start_time >= MOTOR_RPM_SAMPLE_INTERVAL) {
            rpm = (pulse_count * 60) / (end_time - start_time);
            pulse_count = 0;
            start_time = end_time;
        }

        // Write to the log file
        char log_line[100];
        snprintf(log_line, sizeof(log_line), "%s,%.2f\n",
                 ctime(&end_time), rpm);
        write(log_fd, log_line, strlen(log_line));
        fsync(log_fd);

        // Print to stdout
        printf("RPM: %.2f\n", rpm);
    }

    // Clean up
    close(log_fd);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

