#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define GPIO_RELAY 17
#define POLL_INTERVAL 50
#define LONG_PRESS_TIME 10000

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    int sensor_value, relay_value;
    bool long_press = false;
    struct timespec ts;

    // Initialize the GPIO pins
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set up the GPIO pins
    if (gpioSetMode(GPIO_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_SENSOR);
        return 1;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        return 1;
    }

    // Set the initial relay state
    relay_value = 0;
    if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
        return 1;
    }

    // Main loop
    while (!stop) {
        // Read the sensor value
        sensor_value = gpioRead(GPIO_SENSOR);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_SENSOR);
            return 1;
        }

        // Check for a long press
        if (sensor_value && !long_press) {
            long_press = true;
            ts.tv_sec = 0;
            ts.tv_nsec = LONG_PRESS_TIME * 1000000;
            nanosleep(&ts, NULL);
            if (sensor_value) {
                // Force the relay off
                relay_value = 0;
                if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
                    fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
                    return 1;
                }
                // Ignore further toggles until the sensor is released
                long_press = false;
            }
        }

        // Toggle the relay state on each rising edge of the sensor
        if (sensor_value && !long_press) {
            relay_value = !relay_value;
            if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
                fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
                return 1;
            }
        }

        // Sleep for the poll interval
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL * 1000000;
        nanosleep(&ts, NULL);
    }

    // Release the relay
    relay_value = 0;
    if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
        return 1;
    }

    // Clean up
    gpioTerminate();

    return 0;
}

