                long_press = false;
            }
        }

        // Toggle the relay state on each rising edge of the sensor
        if (sensor_value && !long_press) {
            relay_value = !relay_value;
            if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
                fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
                return 1;
            }
        }

        // Sleep for the poll interval
        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL * 1000000;
        nanosleep(&ts, NULL);
    }

    // Release the relay
    relay_value = 0;
    if (gpioWrite(GPIO_RELAY, relay_value) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d\n", GPIO_RELAY, relay_value);
        return 1;
    }

    // Clean up
    gpioTerminate();

    return 0;
}
