    speeds.motor_1_speed = (counts.count_a - counts.count_b) * 60 / PID_SAMPLE_TIME;
    speeds.motor_2_speed = (counts.count_a - counts.count_b) * 60 / PID_SAMPLE_TIME;
    return speeds;
}

// Function to log motor speeds and PID output
void log_motor_speeds(motor_speeds_t speeds, pid_output_t output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(1);
    }
    fprintf(fp, "%d,%d,%d,%d,%d,%d,%d,%d\n", speeds.motor_1_speed, speeds.motor_2_speed, output.p, output.i, output.d, MOTOR_1_DUTY_CYCLE, MOTOR_2_DUTY_CYCLE);
    fclose(fp);
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Stop motors
        gpiod_set_value(MOTOR_1_ENA, 0);
        gpiod_set_value(MOTOR_2_ENB, 0);
        // Release GPIO lines
        gpiod_release_line(MOTOR_1_ENA);
        gpiod_release_line(MOTOR_1_IN1);
        gpiod_release_line(MOTOR_1_IN2);
        gpiod_release_line(MOTOR_2_ENB);
        gpiod_release_line(MOTOR_2_IN3);
        gpiod_release_line(MOTOR_2_IN4);
        // Close log file
        fclose(LOG_FILE);
        // Exit program
        exit(0);
    }
}

// Function to run encoder monitoring in separate thread
void *encoder_monitoring_thread(void *arg) {
    while (true) {
        // Read encoder counts
        encoder_counts_t counts = read_encoder_counts();
        // Compute motor speeds
        motor_speeds_t speeds = compute_motor_speeds(counts);
        // Log motor speeds and PID output
        log_motor_speeds(speeds, pid_output_t{0, 0, 0});
        // Sleep for PID sample time
        usleep(PID_SAMPLE_TIME * 1000);
    }
}

int main() {
    // Initialize GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        exit(1);
    }

    // Request GPIO lines
    gpiod_line_t *line_ena = gpiod_chip_get_line(chip, MOTOR_1_ENA);
    gpiod_line_t *line_in1 = gpiod_chip_get_line(chip, MOTOR_1_IN1);
    gpiod_line_t *line_in2 = gpiod_chip_get_line(chip, MOTOR_1_IN2);
    gpiod_line_t *line_enb = gpiod_chip_get_line(chip, MOTOR_2_ENB);
    gpiod_line_t *line_in3 = gpiod_chip_get_line(chip, MOTOR_2_IN3);
    gpiod_line_t *line_in4 = gpiod_chip_get_line(chip, MOTOR_2_IN4);
    if (line_ena == NULL || line_in1 == NULL || line_in2 == NULL || line_enb == NULL || line_in3 == NULL || line_in4 == NULL) {
        perror("Error requesting GPIO lines");
        exit(1);
    }

    // Set edge events
    gpiod_line_set_edge_event(line_ena, GPIOD_LINE_EVENT_RISING);
    gpiod_line_set_edge_event(line_in1, GPIOD_LINE_EVENT_RISING);
    gpiod_line_set_edge_event(line_in2, GPIOD_LINE_EVENT_RISING);
    gpiod_line_set_edge_event(line_enb, GPIOD_LINE_EVENT_RISING);
    gpiod_line_set_edge_event(line_in3, GPIOD_LINE_EVENT_RISING);
    gpiod_line_set_edge_event(line_in4, GPIOD_LINE_EVENT_RISING);

    // Open log file
    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening log file");
        exit(1);
    }
    fprintf(fp, "Motor 1 Speed (RPM),Motor 2 Speed (RPM),P,I,D,Motor 1 Duty Cycle,Motor 2 Duty Cycle\n");
    fclose(fp);

    // Create encoder monitoring thread
    pthread_t thread;
    pthread_create(&thread, NULL, encoder_monitoring_thread, NULL);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (true) {
        // Read encoder counts
        encoder_counts_t counts = read_encoder_counts();
        // Compute motor speeds
        motor_speeds_t speeds = compute_motor_speeds(counts);
        // Compute PID output
        pid_output_t output = compute_pid_output(MOTOR_SPEED - speeds.motor_1_speed, MOTOR_SPEED);
        // Compute motor duty cycles
        compute_motor_duty_cycles(output);
        // Set motor duty cycles
        gpiod_set_value(MOTOR_1_ENA, MOTOR_1_DUTY_CYCLE);
        gpiod_set_value(MOTOR_2_ENB, MOTOR_2_DUTY_CYCLE);
        // Sleep for PID sample time
        usleep(PID_SAMPLE_TIME * 1000);
    }

    // Clean up
    gpiod_chip_close(chip);
    return 0;
}
