#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define VALVE_1_RELAY_GPIO 17
#define VALVE_2_RELAY_GPIO 18

#define VALVE_1_OPEN_DURATION 500
#define VALVE_2_OPEN_DURATION 1000

#define VALVE_1_PAUSE_DURATION 5
#define VALVE_2_PAUSE_DURATION 10

#define LOG_FILE "valve_log.txt"

static bool g_running = true;

static void sigint_handler(int signum) {
    g_running = false;
}

static void sigterm_handler(int signum) {
    g_running = false;
}

static void log_event(const char *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    char line[128];
    snprintf(line, sizeof(line), "%s %s\n", timestamp, event);
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (write(fd, line, strlen(line)) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    close(fd);
}

int main(void) {
    // Initialize GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Request lines for valve 1 and valve 2
    struct gpiod_line *valve_1_line = gpiod_chip_get_line(chip, VALVE_1_RELAY_GPIO);
    if (!valve_1_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    struct gpiod_line *valve_2_line = gpiod_chip_get_line(chip, VALVE_2_RELAY_GPIO);
    if (!valve_2_line) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (g_running) {
        // Activate valve 1
        gpiod_line_set_value(valve_1_line, 1);
        log_event("Valve 1 activated");
        usleep(VALVE_1_OPEN_DURATION * 1000);
        gpiod_line_set_value(valve_1_line, 0);
        log_event("Valve 1 deactivated");
        usleep(VALVE_1_PAUSE_DURATION * 1000);

        // Activate valve 2
        gpiod_line_set_value(valve_2_line, 1);
        log_event("Valve 2 activated");
        usleep(VALVE_2_OPEN_DURATION * 1000);
        gpiod_line_set_value(valve_2_line, 0);
        log_event("Valve 2 deactivated");
        usleep(VALVE_2_PAUSE_DURATION * 1000);
    }

    // Clean up
    gpiod_line_release(valve_1_line);
    gpiod_line_release(valve_2_line);
    gpiod_chip_close(chip);

    return 0;
}

