#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define GPIO_PIN 17

#define TOUCH_THRESHOLD 10
#define RELEASE_THRESHOLD 5
#define FILTER 1
#define CHARGE_TIME 10
#define ELECTRODE_CURRENT 10

#define STOP_MODE 0
#define RUN_MODE 1

#define TOGGLE_ON 1
#define TOGGLE_OFF 0

int i2c_fd;
int gpio_fd;

void init_i2c(void) {
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
}

void init_gpio(void) {
    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_PIN, GPIO_OUT) < 0) {
        perror("Failed to set GPIO pin direction");
        exit(1);
    }
}

void set_mpr121_mode(int mode) {
    uint8_t reg_addr = 0x5E;
    uint8_t reg_val = mode;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void set_mpr121_thresholds(void) {
    uint8_t reg_addr = 0x41;
    uint8_t reg_val = TOUCH_THRESHOLD;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    reg_addr = 0x42;
    reg_val = RELEASE_THRESHOLD;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void set_mpr121_filter(void) {
    uint8_t reg_addr = 0x5D;
    uint8_t reg_val = FILTER;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void set_mpr121_charge_time(void) {
    uint8_t reg_addr = 0x5B;
    uint8_t reg_val = CHARGE_TIME;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void set_mpr121_electrode_current(void) {
    uint8_t reg_addr = 0x5C;
    uint8_t reg_val = ELECTRODE_CURRENT;

    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }

    if (write(i2c_fd, &reg_val, 1) != 1) {
        perror("Failed to write to I2C register");
        exit(1);
    }
}

void toggle_relay(int state) {
    uint8_t reg_addr = GPIO_PIN;
    uint8_t reg_val = state;

    if (write(gpio_fd, &reg_addr, 1) != 1) {
        perror("Failed to write to GPIO pin");
        exit(1);
    }

    if (write(gpio_fd, &reg_val, 1) != 1) {
        perror("Failed to write to GPIO pin");
        exit(1);
    }
}

void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

int main(void) {
    signal(SIGINT, handle_sigint);

    init_i2c();
    init_gpio();

    set_mpr121_mode(STOP_MODE);
    set_mpr121_thresholds();
    set_mpr121_filter();
    set_mpr121_charge_time();
    set_mpr121_electrode_current();

    set_mpr121_mode(RUN_MODE);

    while (1) {
        uint8_t touch_status;
        if (read(i2c_fd, &touch_status, 1) != 1) {
            perror("Failed to read from I2C");
            exit(1);
        }

        if (touch_status > 0) {
            toggle_relay(TOGGLE_ON);
            printf("Relay toggled on\n");
        } else {
            toggle_relay(TOGGLE_OFF);
            printf("Relay toggled off\n");
        }

        usleep(100000);
    }

    return 0;
}

