#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define RATE_LIMIT_MS 2000

static bool rate_limited = false;
static time_t last_unlock_time = 0;

static void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        libgpiod_close(PIR_PIN);
        libgpiod_close(RELAY_PIN);
        fclose(log_file);
        exit(0);
    }
}

static void handle_motion(void) {
    if (rate_limited) {
        printf("Rate limited, ignoring motion event\n");
        return;
    }

    time_t now = time(NULL);
    if (now - last_unlock_time < RATE_LIMIT_MS) {
        printf("Rate limited, ignoring motion event\n");
        return;
    }

    printf("Motion detected, unlocking door strike for 500ms\n");
    libgpiod_set_value(RELAY_PIN, 1);
    usleep(500000);
    libgpiod_set_value(RELAY_PIN, 0);
    last_unlock_time = now;
    rate_limited = true;
}

int main(void) {
    signal(SIGINT, handle_signal);

    if (libgpiod_init() != 0) {
        printf("Failed to initialize GPIO driver\n");
        return 1;
    }

    if (libgpiod_set_direction(PIR_PIN, GPIOD_IN) != 0) {
        printf("Failed to set PIR pin direction\n");
        return 1;
    }

    if (libgpiod_set_direction(RELAY_PIN, GPIOD_OUT) != 0) {
        printf("Failed to set relay pin direction\n");
        return 1;
    }

    FILE *log_file = fopen("door_events.log", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    while (true) {
        int value = libgpiod_get_value(PIR_PIN);
        if (value == 1) {
            handle_motion();
        }

        fprintf(log_file, "%ld\n", time(NULL));
        usleep(50000);
    }

    return 0;
}

