#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>
#include <hx711.h>

#define GPIO_DATA 4
#define GPIO_CLOCK 17
#define GPIO_LOCK 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"
#define TIMEOUT_MS 500
#define THRESHOLD_KG 10.0

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    // Initialize GPIO driver
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_DATA, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO data pin mode\n");
        return 1;
    }
    if (gpioSetMode(GPIO_CLOCK, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO clock pin mode\n");
        return 1;
    }
    if (gpioSetMode(GPIO_LOCK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO lock pin mode\n");
        return 1;
    }

    // Set up HX711 sensor
    hx711_t hx711;
    hx711.data_pin = GPIO_DATA;
    hx711.clock_pin = GPIO_CLOCK;
    hx711.scale_factor = 1.0;
    hx711.offset = 0.0;

    // Load calibration data from file
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file != NULL) {
        if (fscanf(calibration_file, "%lf %lf", &hx711.scale_factor, &hx711.offset) != 2) {
            fprintf(stderr, "Failed to read calibration data from file\n");
            return 1;
        }
        fclose(calibration_file);
    } else {
        fprintf(stderr, "Calibration file not found, using default values\n");
    }

    // Perform one-time startup calibration
    double offset = 0.0;
    for (int i = 0; i < 100; i++) {
        double weight = hx711_read(&hx711);
        offset += weight;
    }
    offset /= 100.0;
    hx711.offset = offset;

    // Open weight log file
    FILE *weight_log_file = fopen(WEIGHT_LOG_FILE, "a");
    if (weight_log_file == NULL) {
        fprintf(stderr, "Failed to open weight log file\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read weight from HX711 sensor
        double weight = hx711_read(&hx711);

        // Compute weight using loaded or default scale and offset
        double computed_weight = weight * hx711.scale_factor + hx711.offset;

        // Engage solenoid if weight exceeds threshold
        if (computed_weight > THRESHOLD_KG) {
            gpioWrite(GPIO_LOCK, 1);
        } else {
            gpioWrite(GPIO_LOCK, 0);
        }

        // Log weight reading to file
        fprintf(weight_log_file, "%.3f\n", computed_weight);

        // Wait for next iteration
        usleep(TIMEOUT_MS * 1000);
    }

    // Clean up
    gpioTerminate();
    fclose(weight_log_file);

    return 0;
}

