#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define GPIO_DT 23
#define GPIO_SCK 24
#define GPIO_LOCK 17
#define WEIGHT_THRESHOLD 100
#define LOCK_DURATION 5

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s: %s\n", timestamp, event);
    FILE *fp = fopen("stock_events.txt", "a");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(fp, log_entry);
    fclose(fp);
}

static void read_weight(void) {
    int fd = open("/dev/hx711", O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    uint8_t data[2];
    ssize_t n = read(fd, data, sizeof(data));
    if (n == -1) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    close(fd);
    uint16_t weight = (data[0] << 8) | data[1];
    log_event(weight < WEIGHT_THRESHOLD ? "Weight below threshold" : "Weight above threshold");
    if (weight < WEIGHT_THRESHOLD) {
        int gpio_fd = gpiod_open(GPIO_LOCK, "lock", GPIOD_OUTPUT);
        if (gpio_fd == -1) {
            perror("gpiod_open");
            exit(EXIT_FAILURE);
        }
        gpiod_set_value(gpio_fd, 1);
        sleep(LOCK_DURATION);
        gpiod_set_value(gpio_fd, 0);
        gpiod_close(gpio_fd);
    }
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    while (running) {
        read_weight();
        sleep(1);
    }
    return 0;
}

