// Global variables
struct gpiod_chip *chip;
struct gpiod_line *data_line;
struct gpiod_line *clock_line;
struct gpiod_line *solenoid_line;
uint32_t calibration_factor;
uint32_t weight;
bool timeout;

int main(void) {
    // Initialize GPIO
    init_gpio();

    // Read calibration factor
    read_calibration();

    // Main loop
    while (true) {
        // Read weight
        read_weight();

        // Check if weight exceeds threshold
        if (weight > THRESHOLD_WEIGHT) {
            // Engage solenoid
            engage_solenoid();

            // Log weight
            log_weight();

            // Disengage solenoid
            disengage_solenoid();
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_chip_close(chip);
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(solenoid_line);

    return 0;
}

void init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        exit(1);
    }

    // Request lines
    data_line = gpiod_chip_get_line(chip, 4);
    clock_line = gpiod_chip_get_line(chip, 17);
    solenoid_line = gpiod_chip_get_line(chip, 27);
    if (data_line == NULL || clock_line == NULL || solenoid_line == NULL) {
        fprintf(stderr, "Error: Failed to request GPIO lines\n");
        exit(1);
    }

    // Set line directions
    gpiod_line_set_direction(data_line, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_set_direction(clock_line, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(solenoid_line, GPIOD_LINE_DIRECTION_OUTPUT);
}

void read_calibration(void) {
    // Open calibration file
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open calibration file\n");
        exit(1);
    }

    // Read calibration factor
    if (fscanf(fp, "%u", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Failed to read calibration factor\n");
        exit(1);
    }

    // Close calibration file
    fclose(fp);
}

void read_weight(void) {
    // Set clock line low
    gpiod_line_set_value(clock_line, 0);

    // Read data line
    gpiod_line_get_value(data_line, &weight);

    // Set clock line high
    gpiod_line_set_value(clock_line, 1);

    // Apply calibration factor
    weight = weight * calibration_factor;
}

void engage_solenoid(void) {
    // Set solenoid line high
    gpiod_line_set_value(solenoid_line, 1);

    // Wait for 5 seconds
    sleep(5);

    // Set solenoid line low
    gpiod_line_set_value(solenoid_line, 0);
}

void disengage_solenoid(void) {
    // Set solenoid line low
    gpiod_line_set_value(solenoid_line, 0);
}

void log_weight(void) {
    // Open security log file
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open security log file\n");
        exit(1);
    }

    // Get current time
    struct timeval tv;
    gettimeofday(&tv, NULL);

    // Log weight
    fprintf(fp, "%ld.%06ld %f\n", tv.tv_sec, tv.tv_usec, weight);

    // Close security log file
    fclose(fp);
}

void handle_sigint(int signal) {
    // Disengage solenoid
    disengage_solenoid();

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close data and clock lines
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);

    // Close solenoid line
    gpiod_line_release(solenoid_line);

    // Exit program
    exit(0);
}

