void handle_sigint(int signal) {
    printf("Received SIGINT, turning off buzzer and closing log file\n");
    gpio_write(BUZZER_PIN, 0);
    close(log_file);
    gpio_close(PIR_PIN);
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, turning off buzzer and closing log file\n");
    gpio_write(BUZZER_PIN, 0);
    close(log_file);
    gpio_close(PIR_PIN);
    exit(0);
}

int main(void) {
    int log_file;
    int pir_value;
    struct timespec ts;

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open log file
    log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file == -1) {
        perror("Error opening log file");
        exit(1);
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        perror("Error initializing GPIO");
        exit(1);
    }

    // Set up PIR pin as input
    if (gpio_set_mode(PIR_PIN, GPIO_INPUT) < 0) {
        perror("Error setting PIR pin as input");
        exit(1);
    }

    // Set up buzzer pin as output
    if (gpio_set_mode(BUZZER_PIN, GPIO_OUTPUT) < 0) {
        perror("Error setting buzzer pin as output");
        exit(1);
    }

    // Loop indefinitely
    while (1) {
        // Read PIR value
        pir_value = gpio_read(PIR_PIN);
        if (pir_value < 0) {
            perror("Error reading PIR value");
            exit(1);
        }

        // If motion detected, turn on buzzer and log timestamp
        if (pir_value == 1) {
            gpio_write(BUZZER_PIN, 1);
            clock_gettime(CLOCK_REALTIME, &ts);
            dprintf(log_file, "%s %d:%d:%d\n", ctime(&ts.tv_sec), ts.tv_nsec / 1000000, ts.tv_nsec % 1000000);
            usleep(2000000); // 2 seconds
            gpio_write(BUZZER_PIN, 0);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(log_file);
    gpio_close(PIR_PIN);
    gpio_close(BUZZER_PIN);
    gpio_deinit();

    return 0;
}

