#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define GPIO_CHIP 0
#define GPIO_LINE 0

volatile sig_atomic_t sig_flag = 0;

void sigint_handler(int signum) {
    sig_flag = 1;
}

int main(int argc, char *argv[]) {
    int fd;
    char buf[1024];
    int duration;
    int ret;

    // Open the configuration file
    fd = open("watering.conf", O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Read the duration from the configuration file
    ret = read(fd, buf, sizeof(buf));
    if (ret < 0) {
        perror("read");
        close(fd);
        return 1;
    }
    close(fd);

    // Parse the duration from the configuration file
    duration = atoi(buf);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration: %d\n", duration);
        return 1;
    }

    // Initialize the GPIO line as an output with active-low = 0 and a default low value (valve off)
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Activate the valve by setting the line high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("Valve on\n");

    // Wait the configured duration using a signal-safe interruptible sleep
    struct timespec ts;
    ts.tv_sec = duration;
    ts.tv_nsec = 0;
    ret = nanosleep(&ts, NULL);
    if (ret < 0) {
        perror("nanosleep");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the line low to turn the valve off
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("Valve off\n");

    // Release the GPIO line and close the chip
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

