#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <pigpio/pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define RIGHT_MOTOR_PWM_PIN 23
#define LEFT_MOTOR_DIR_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

#define BASE_SPEED 150
#define TURN_SPEED 127

#define SAMPLE_PERIOD 10
#define PWM_FREQUENCY 1000

#define LOG_FILE "trace_log.txt"

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void init_gpio(void) {
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (pigpio_init() != 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        exit(1);
    }
}

static void set_motor_speed(int left_speed, int right_speed) {
    pigpio_set_pwm_frequency(PWM_FREQUENCY);
    pigpio_set_pwm_dutycycle(LEFT_MOTOR_PWM_PIN, left_speed);
    pigpio_set_pwm_dutycycle(RIGHT_MOTOR_PWM_PIN, right_speed);
}

static void set_motor_direction(int left_dir, int right_dir) {
    gpiod_set_value(LEFT_MOTOR_DIR_PIN, left_dir);
    gpiod_set_value(RIGHT_MOTOR_DIR_PIN, right_dir);
}

static void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    fprintf(fp, "%s, %d, %d, %d, %d, %d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fclose(fp);
}

int main(void) {
    init_gpio();

    signal(SIGINT, sigint_handler);

    int left_sensor = 0;
    int middle_sensor = 0;
    int right_sensor = 0;
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    while (running) {
        left_sensor = gpiod_get_value(LEFT_SENSOR_PIN);
        middle_sensor = gpiod_get_value(MIDDLE_SENSOR_PIN);
        right_sensor = gpiod_get_value(RIGHT_SENSOR_PIN);

        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            set_motor_speed(0, 0);
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 1) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, TURN_SPEED);
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            set_motor_speed(BASE_SPEED, TURN_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 1) {
            set_motor_speed(TURN_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 1) {
            set_motor_speed(TURN_SPEED, TURN_SPEED);
        }

        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        usleep(SAMPLE_PERIOD * 1000);
    }

    set_motor_speed(0, 0);
    gpiod_close();
    pigpio_close();

    return 0;
}

