    int right_speed = BASE_SPEED;

    while (running) {
        left_sensor = gpiod_get_value(LEFT_SENSOR_PIN);
        middle_sensor = gpiod_get_value(MIDDLE_SENSOR_PIN);
        right_sensor = gpiod_get_value(RIGHT_SENSOR_PIN);

        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            set_motor_speed(0, 0);
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 1) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
            set_motor_speed(BASE_SPEED, TURN_SPEED);
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            set_motor_speed(BASE_SPEED, TURN_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 1) {
            set_motor_speed(TURN_SPEED, BASE_SPEED);
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 1) {
            set_motor_speed(TURN_SPEED, TURN_SPEED);
        }

        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        usleep(SAMPLE_PERIOD * 1000);
    }

    set_motor_speed(0, 0);
    gpiod_close();
    pigpio_close();

    return 0;
}
