#include <pigpio.h>
#include <bh1750.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150

static int i2c_fd;
static int relay_fd;
static int log_fd;

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    close(i2c_fd);
    close(relay_fd);
    close(log_fd);
    pigpio_stop();
    exit(0);
}

static void log_lux(int lux) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld.%06ld %d\n", tv.tv_sec, tv.tv_usec, lux);
    write(log_fd, buf, strlen(buf));
}

static void set_relay(int state) {
    if (state) {
        printf("Turning on relay...\n");
        pigpio_write(relay_fd, 1);
    } else {
        printf("Turning off relay...\n");
        pigpio_write(relay_fd, 0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <log_file>\n", argv[0]);
        return 1;
    }

    // Initialize I2C bus
    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize relay
    relay_fd = pigpio_gpio_open(RELAY_GPIO, PI_OUTPUT);
    if (relay_fd < 0) {
        printf("Failed to open relay: %s\n", strerror(errno));
        return 1;
    }

    // Initialize log file
    log_fd = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read lux value
        int lux = bh1750_read(i2c_fd);
        if (lux < 0) {
            printf("Failed to read lux value: %s\n", strerror(errno));
            continue;
        }

        // Log lux value
        log_lux(lux);

        // Turn on relay if lux is below threshold
        if (lux < LUX_THRESHOLD) {
            set_relay(1);
        } else {
            set_relay(0);
        }

        // Sleep for 180 ms
        usleep(180000);
    }

    return 0;
}

