int main(int argc, char *argv[]) {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize servo
    servo_fd = servo_init(SERVO_PIN);
    if (servo_fd < 0) {
        printf("Failed to initialize servo\n");
        return 1;
    }

    // Initialize push buttons
    lock_fd = gpio_init(LOCK_PIN, GPIO_INPUT);
    if (lock_fd < 0) {
        printf("Failed to initialize lock button\n");
        return 1;
    }
    unlock_fd = gpio_init(UNLOCK_PIN, GPIO_INPUT);
    if (unlock_fd < 0) {
        printf("Failed to initialize unlock button\n");
        return 1;
    }

    // Set up debounce delay
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY * 1000};

    // Main loop
    while (1) {
        // Read push button states
        int lock_state = gpio_read(lock_fd);
        int unlock_state = gpio_read(unlock_fd);

        // Debounce push buttons
        nanosleep(&debounce_delay, NULL);

        // Check if lock button is pressed
        if (lock_state == 0) {
            // Set servo pulse width to 1000 µs
            servo_set_pulse_width(servo_fd, SERVO_PULSE_WIDTH_LOCK);
            printf("Locked\n");
        }

        // Check if unlock button is pressed
        if (unlock_state == 0) {
            // Set servo pulse width to 2000 µs
            servo_set_pulse_width(servo_fd, SERVO_PULSE_WIDTH_UNLOCK);
            printf("Unlocked\n");
        }
    }

    // Clean up
    gpio_close(gpio_fd);
    servo_close(servo_fd);
    gpio_close(lock_fd);
    gpio_close(unlock_fd);

    return 0;
}

