#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <zmq.h>

#define GPIO_BASE 0x20000000
#define GPIO_ALARM 27
#define GPIO_SOUND 17

#define SOUND_ALERTS "SOUND_ALERTS"

void *gpio_map;

void *gpio_init() {
    int fd;
    if ((fd = open("/dev/mem", O_RDWR|O_SYNC) < 0)) {
        perror("Failed to open /dev/mem");
        exit(1);
    }

    gpio_map = mmap(NULL, 4096, PROT_READ|PROT_WRITE, MAP_SHARED, fd, GPIO_BASE);
    if (gpio_map == MAP_FAILED) {
        perror("Failed to mmap GPIO registers");
        exit(1);
    }

    return gpio_map;
}

void gpio_set_mode(int pin, int mode) {
    int offset = pin / 10;
    int shift = (pin % 10) * 3;
    int value = (mode & 0x7) << shift;
    int mask = ~(0x7 << shift);
    int reg = gpio_map[offset];
    reg &= mask;
    reg |= value;
    gpio_map[offset] = reg;
}

void gpio_set_value(int pin, int value) {
    int offset = pin / 10;
    int shift = (pin % 10) * 3;
    int mask = ~(0x1 << shift);
    int reg = gpio_map[offset];
    reg &= mask;
    reg |= (value & 0x1) << shift;
    gpio_map[offset] = reg;
}

void gpio_cleanup() {
    munmap(gpio_map, 4096);
    close(fd);
}

void *zmq_init() {
    void *context;
    void *socket;

    context = zmq_ctx_new();
    if (!context) {
        perror("Failed to create ZeroMQ context");
        exit(1);
    }

    socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        perror("Failed to create ZeroMQ socket");
        exit(1);
    }

    if (zmq_connect(socket, "tcp://*:5555") < 0) {
        perror("Failed to connect to ZeroMQ socket");
        exit(1);
    }

    if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, SOUND_ALERTS, strlen(SOUND_ALERTS)) < 0) {
        perror("Failed to set ZeroMQ subscription");
        exit(1);
    }

    return socket;
}

void zmq_cleanup(void *socket) {
    zmq_close(socket);
    zmq_ctx_destroy(socket);
}

void *alarm_node(void *arg) {
    void *socket = arg;
    int value;

    while (1) {
        if (zmq_recv(socket, &value, sizeof(value), 0) < 0) {
            perror("Failed to receive ZeroMQ message");
            exit(1);
        }

        if (value == 1) {
            gpio_set_value(GPIO_ALARM, 1);
            sleep(1);
            gpio_set_value(GPIO_ALARM, 0);
        }
    }

    return NULL;
}

void *sound_sensor(void *arg) {
    void *socket = arg;
    int value;

    while (1) {
        value = gpio_get_value(GPIO_SOUND);
        if (value == 0) {
            zmq_send(socket, SOUND_ALERTS, strlen(SOUND_ALERTS), 0);
        }
        usleep(10000);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    void *gpio_map;
    void *socket;
    pthread_t thread;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        exit(1);
    }

    gpio_map = gpio_init();
    gpio_set_mode(GPIO_ALARM, 0);
    gpio_set_mode(GPIO_SOUND, 0);

    socket = zmq_init();

    if (strcmp(argv[1], "sound_sensor") == 0) {
        pthread_create(&thread, NULL, sound_sensor, socket);
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        pthread_create(&thread, NULL, alarm_node, socket);
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        exit(1);
    }

    pthread_join(thread, NULL);

    zmq_cleanup(socket);
    gpio_cleanup();

    return 0;
}

