#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x20
#define I2C_REG 0x00
#define I2C_LEN 0
#define I2C_RETRIES 3
#define I2C_DELAY 100

#define SLPM_FACTOR 1000

int main(void) {
    int fd;
    int ret;
    int i;
    uint8_t buf[2];
    uint16_t flow;
    float slpm;
    struct timespec ts;
    FILE *logfile;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    logfile = fopen("airflow_log.txt", "a");
    if (logfile == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Issue zero-length I2C write to generate start condition
        ret = write(fd, NULL, 0);
        if (ret < 0) {
            perror("Failed to issue I2C write");
            close(fd);
            fclose(logfile);
            return 1;
        }

        // Read two bytes from Honeywell AWM7300V mass airflow sensor
        ret = read(fd, buf, 2);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            close(fd);
            fclose(logfile);
            return 1;
        }

        // Mask 14-bit flow value from first two bytes according to sensor documentation
        flow = (buf[0] << 8) | buf[1];
        flow &= 0x3FFF;

        // Convert flow value to SLPM
        slpm = flow * SLPM_FACTOR;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log flow rate to log file
        fprintf(logfile, "%ld.%ld, %f\n", ts.tv_sec, ts.tv_nsec, slpm);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(fd);
    fclose(logfile);

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C file descriptor
    close(fd);

    // Flush and close log file
    fflush(logfile);
    fclose(logfile);

    // Exit program
    exit(0);
}

