#define BH1750_ADDR 0x23
#define BH1750_REG_DATA 0x00
#define BH1750_REG_CONTROL 0x01
#define BH1750_CONTROL_ON 0x01
#define BH1750_CONTROL_OFF 0x00

#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

int main(int argc, char *argv[]) {
    int i2c_fd, sock_fd;
    struct sockaddr_in mcast_addr;
    struct i2c_msg msg;
    uint8_t data[2];
    float lux;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Set I2C control register
    msg.addr = BH1750_REG_CONTROL;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &BH1750_CONTROL_ON;
    if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
        perror("Failed to set I2C control register");
        close(i2c_fd);
        return 1;
    }

    // Open UDP socket
    if ((sock_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to open UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set UDP multicast address
    memset(&mcast_addr, 0, sizeof(mcast_addr));
    mcast_addr.sin_family = AF_INET;
    mcast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    mcast_addr.sin_port = htons(MULTICAST_PORT);
    if (bind(sock_fd, (struct sockaddr *)&mcast_addr, sizeof(mcast_addr)) < 0) {
        perror("Failed to set UDP multicast address");
        close(i2c_fd);
        close(sock_fd);
        return 1;
    }

    // Set TTL for UDP multicast
    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set TTL for UDP multicast");
        close(i2c_fd);
        close(sock_fd);
        return 1;
    }

    // Install signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read ambient light from BH1750
        msg.addr = BH1750_REG_DATA;
        msg.flags = I2C_M_RD;
        msg.len = 2;
        msg.buf = data;
        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            perror("Failed to read ambient light from BH1750");
            close(i2c_fd);
            close(sock_fd);
            return 1;
        }

        // Convert raw value to lux
        lux = (data[0] << 8) | data[1];
        lux = lux / 1.2;

        // Broadcast lux value as a floating-point string
        char buf[32];
        sprintf(buf, "%f", lux);
        if (sendto(sock_fd, buf, strlen(buf), 0, (struct sockaddr *)&mcast_addr, sizeof(mcast_addr)) < 0) {
            perror("Failed to broadcast lux value");
            close(i2c_fd);
            close(sock_fd);
            return 1;
        }

        // Sleep for one second
        sleep(1);
    }

    return 0;
}

void sigint_handler(int signum) {
    close(i2c_fd);
    close(sock_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    close(i2c_fd);
    close(sock_fd);
    exit(0);
}

