#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <pigpio.h>

#define BUF_SIZE 1024
#define MAGIC_WORD 0x12345678
#define TLV_TYPE_RANGE 0x01
#define TLV_TYPE_VELOCITY 0x02

int main(int argc, char *argv[]) {
    // Open the UART device
    int fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set the UART baud rate
    if (cfsetispeed(&tty, B921600) < 0) {
        perror("cfsetispeed");
        return 1;
    }
    if (cfsetospeed(&tty, B921600) < 0) {
        perror("cfsetospeed");
        return 1;
    }

    // Set the UART options
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE);
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    // Set the UART timeout
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = 100000;
    if (setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
        perror("setsockopt");
        return 1;
    }

    // Open the CSV file
    FILE *fp = fopen("radar_data.csv", "a");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // Initialize the pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        perror("pigpio_start");
        return 1;
    }

    // Set the GPIO pin for the radar sensor
    int gpio = 18;
    if (pigpio_gpio_export(gpio) < 0) {
        perror("pigpio_gpio_export");
        return 1;
    }
    if (pigpio_gpio_set_mode(gpio, PI_OUTPUT) < 0) {
        perror("pigpio_gpio_set_mode");
        return 1;
    }
    if (pigpio_gpio_write(gpio, 1) < 0) {
        perror("pigpio_gpio_write");
        return 1;
    }

    // Read data from the UART
    char buf[BUF_SIZE];
    int n;
    while ((n = read(fd, buf, BUF_SIZE)) > 0) {
        // Check for the magic word
        if (memcmp(buf, &MAGIC_WORD, sizeof(MAGIC_WORD)) == 0) {
            // Parse the TLV payload
            uint8_t *ptr = buf + sizeof(MAGIC_WORD);
            while (ptr < buf + n) {
                uint8_t type = *ptr++;
                uint16_t length = *ptr++;
                uint8_t *data = ptr;

                // Validate the TLV payload
                if (type == TLV_TYPE_RANGE || type == TLV_TYPE_VELOCITY) {
                    // Extract the range and velocity
                    uint16_t range = *(uint16_t *)data;
                    uint16_t velocity = *(uint16_t *)(data + 2);

                    // Write the data to the CSV file
                    struct timeval tv;
                    gettimeofday(&tv, NULL);
                    fprintf(fp, "%ld.%06ld,%d,%d,%d\n", tv.tv_sec, tv.tv_usec, type, range, velocity);
                }

                // Advance the pointer
                ptr += length;
            }
        }
    }

    // Clean up
    fclose(fp);
    pigpio_gpio_write(gpio, 0);
    pigpio_gpio_unexport(gpio);
    pigpio_stop();
    close(fd);

    return 0;
}

