#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define BUF_SIZE 1024
#define TIMEOUT 2

void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    close(fd);
    exit(0);
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM, shutting down...\n");
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int fd;
    char buf[BUF_SIZE];
    char *line;
    int nread;
    int nparsed;
    int nlines;
    struct timeval tv;
    struct sigaction sa;

    // Open the UART device
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        printf("Error opening UART device: %s\n", strerror(errno));
        return 1;
    }

    // Set the UART attributes
    struct termios tio;
    tcgetattr(fd, &tio);
    cfsetispeed(&tio, B115200);
    cfsetospeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cflag &= ~(PARENB | PARODD);
    tio.c_cflag &= ~CSTOPB;
    tio.c_cflag &= ~CRTSCTS;
    tio.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tio.c_oflag &= ~OPOST;
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = 5;
    tcsetattr(fd, TCSANOW, &tio);

    // Set up signal handlers
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = handle_sigterm;
    sigaction(SIGTERM, &sa, NULL);

    // Read data from the UART
    while (1) {
        // Set up the select() call
        tv.tv_sec = TIMEOUT;
        tv.tv_usec = 0;
        FD_ZERO(&fdset);
        FD_SET(fd, &fdset);
