#include <fcntl.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define EMERGENCY_STOP_STRING "EMERGENCY STOP!\n"

#define UART_DEVICE "/dev/ttyAMA0"
#define UART_BAUD 115200
#define UART_DATA_BITS 8
#define UART_STOP_BITS 1
#define UART_PARITY 0

#define TIMEOUT_MS 100

static volatile bool running = true;

static void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = false;
    }
}

static void close_uart(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

static void close_driver(pi_t *pi) {
    if (pi != NULL) {
        pi_stop(pi);
    }
}

static void cleanup(int fd, pi_t *pi) {
    close_uart(fd);
    close_driver(pi);
}

int main(int argc, char *argv[]) {
    int fd = -1;
    pi_t *pi = NULL;

    // Initialize the driver library
    if (pi_init(NULL, NULL, 0) != 0) {
        fprintf(stderr, "Failed to initialize the driver library\n");
        return 1;
    }

    // Open the UART device
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open the UART device\n");
        return 1;
    }

    // Set the UART configuration
    if (pi_uart_set_config(fd, UART_BAUD, UART_DATA_BITS, UART_STOP_BITS, UART_PARITY) != 0) {
        fprintf(stderr, "Failed to set the UART configuration\n");
        return 1;
    }

    // Set the signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set the GPIO pins as inputs with pull-up resistors enabled
    if (pi_gpio_set_mode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set the left sensor pin as input\n");
        return 1;
    }
    if (pi_gpio_set_mode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set the middle sensor pin as input\n");
        return 1;
    }
    if (pi_gpio_set_mode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set the right sensor pin as input\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read the sensor states
        int left_state = pi_gpio_read(LEFT_SENSOR_PIN);
        int middle_state = pi_gpio_read(MIDDLE_SENSOR_PIN);
        int right_state = pi_gpio_read(RIGHT_SENSOR_PIN);

        // Check if all sensors are clear
        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            // Send the emergency stop string
            if (pi_uart_write(fd, EMERGENCY_STOP_STRING, strlen(EMERGENCY_STOP_STRING)) != 0) {
                fprintf(stderr, "Failed to write the emergency stop string\n");
            }
        }

        // Log the sensor states
        printf("Left sensor: %d\n", left_state);
        printf("Middle sensor: %d\n", middle_state);
        printf("Right sensor: %d\n", right_state);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    cleanup(fd, pi);

    return 0;
}

